/*
 * Soil Moisture Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - DFRobot Soil Moisture Sensor v2.0 (analog resistive) wired to
 *     MCP3008 channel 0 (CH0).
 *   - MCP3008 connected to Pi SPI0:
 *       MCP3008 VDD  -> Pi 3.3 V (Pin 1)
 *       MCP3008 VREF -> Pi 3.3 V (Pin 1)
 *       MCP3008 AGND -> Pi GND  (Pin 6)
 *       MCP3008 DGND -> Pi GND  (Pin 6)
 *       MCP3008 CLK  -> Pi GPIO11 (SCLK, Pin 23)
 *       MCP3008 DOUT -> Pi GPIO9  (MISO, Pin 21)
 *       MCP3008 DIN  -> Pi GPIO10 (MOSI, Pin 19)
 *       MCP3008 CS   -> Pi GPIO8  (CE0,  Pin 24)
 *       MCP3008 CH0  -> Sensor analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c -lpigpio -lrt
 * Run:
 *   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define MAX_CONSEC_ERR 10         /* abort after this many consecutive SPI failures */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* tell main loop to exit cleanly */
}

/* --------------------------- MCP3008 Read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI Mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (low 8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;          /* 0-1023 */
}

/* ------------------------------ Timestamp -------------------------------- */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1 || !buf || len == 0) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil Moisture Monitoring Started (MCP3008 CH0, SPI0 CE0)\n");
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);

        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: ADC read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Error: %d consecutive SPI failures — aborting.\n",
                        consecutive_errors);
                break;
            }
        } else {
            consecutive_errors = 0;
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("[%s] ADC Value: %4d  (Moisture: %s)\n",
                   ts, adc_value,
                   (adc_value > 700) ? "DRY" :
                   (adc_value > 300) ? "WET" : "VERY WET");
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nSoil Moisture Monitoring Stopped.\n");
    return EXIT_SUCCESS;
}

