#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_SINGLE   (1 << 15)
#define ADS1115_CFG_MUX_AIN0   (0x04 << 12)  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096V (0x01 << 9)   /* PGA = ±4.096 V */
#define ADS1115_CFG_MODE_SS   (0x01 << 8)   /* Single-shot */
#define ADS1115_CFG_DR_128SPS (0x04 << 5)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x03 << 0)   /* Disable comparator */

#define MLX91219_SENSITIVITY 0.040f   /* 40 mV/A */
#define MLX91219_VZERO       2.5f     /* Zero-current offset at mid-supply */
#define PGA_FULLSCALE        4.096f   /* ±4.096 V */
#define ADC_MAX_COUNT        32767.0f /* 16-bit signed, single-ended */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (MSB first). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0)
        return -1;
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (MSB first). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Trigger a single-shot conversion and read the result. */
static int ads1115_read_conversion(int handle, int16_t *raw)
{
    uint16_t config = ADS1115_CFG_OS_SINGLE | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t cfg;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0)
        return -1;

    if (!(cfg & ADS1115_CFG_OS_SINGLE))
        return -1; /* Conversion not ready */

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

static float calculate_current(int16_t raw)
{
    float voltage = ((float)raw / ADC_MAX_COUNT) * PGA_FULLSCALE;
    return (voltage - MLX91219_VZERO) / MLX91219_SENSITIVITY;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (err=%d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register. */
    uint16_t cfg_check;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding on I2C bus %d at 0x%02X.\n",
                I2C_BUS, ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_conversion(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read error from ADS1115.\n");
        } else {
            float current = calculate_current(raw);
            printf("Current: %.3f A\n", current);
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

