#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_OS_SINGLE 0x8000
#define ADS1115_MUX_AIN0 0x4000
#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;
static volatile sig_atomic_t flame_event = 0;
static volatile uint32_t last_flame_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        uint32_t elapsed;
        if (tick >= last_flame_tick) {
            elapsed = tick - last_flame_tick;
        } else {
            elapsed = (0xFFFFFFFF - last_flame_tick) + tick + 1;
        }
        if (elapsed >= DEBOUNCE_MS * 1000) {
            flame_event = 1;
            last_flame_tick = tick;
        }
    }
}

static int read_temperature(float *temp_out) {
    char config[3];
    char reg[2];
    char data[2];
    int16_t raw;
    float voltage, temperature;

    config[0] = (ADS1115_OS_SINGLE | ADS1115_MUX_AIN0 |
                 ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                 ADS1115_DR_128SPS) >> 8;
    config[1] = (ADS1115_OS_SINGLE | ADS1115_MUX_AIN0 |
                 ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                 ADS1115_DR_128SPS) & 0xFF;
    config[2] = 0x03;

    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }

    gpioDelay(10000);

    reg[0] = ADS1115_REG_CONVERSION;
    reg[1] = 0x00;
    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, reg, 2) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion pointer.\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion.\n");
        return -1;
    }

    raw = (data[0] << 8) | data[1];
    voltage = (raw * 4.096) / 32768.0;
    temperature = (voltage / 3.3) * 60.0 + 20.0;

    *temp_out = temperature;
    return 0;
}

static void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION_US);
    gpioWrite(BUZZER_PIN, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X.\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open fire_log.txt.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register flame sensor ISR.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        int flame_detected = (flame_event == 1);
        flame_event = 0;

        if (read_temperature(&temperature) == 0) {
            if (flame_detected && temperature > TEMP_THRESHOLD) {
                log_event("Fire detected!");
                activate_buzzer();
            } else if (flame_detected) {
                log_event("Flame detected!");
            } else if (temperature > TEMP_THRESHOLD) {
                char msg[64];
                snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
                log_event(msg);
            }
        } else {
            log_event("Error reading temperature sensor.");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

