#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.1
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000
#define FAN_GPIO_LINE 18
#define LOG_FILE "current_log.txt"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value == 0 || value == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor may be absent or disconnected\n", value);
    }
    return value;
}

static double adc_to_current(int adc_value, double sensitivity) {
    double voltage = (adc_value / 1023.0) * 3.3;
    return voltage / sensitivity;
}

static void log_data(double current, double threshold, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.3f A, Threshold: %.3f A, Fan: %s\n",
