#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define READ_INTERVAL_SEC 5

/* Simulated raw 16-bit ADC reading for the CO element.
 * In a real deployment, this would be read from an ADS1115 or similar ADC
 * connected to the MICS-4514 analog output. */
#define RAW_CO_VALUE 1000

/* Global flag for signal handling */
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Function to read raw 16-bit ADC value from the MICS-4514 via I2C.
 * Returns 0 on success, -1 on error. */
static int read_raw_co(int i2c_handle, int *raw_value) {
    /* Write a dummy byte to trigger a conversion or poll the sensor.
     * For a real ADS1115, this would configure the conversion register. */
    char dummy = 0x00;
    if (i2cWriteDevice(i2c_handle, &dummy, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed (sensor absent or bus error).\n");
        return -1;
    }

    /* Read 2 bytes of data */
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d).\n", bytes_read);
        return -1;
    }

    /* Combine bytes into 16-bit value (big-endian) */
    *raw_value = ((buf[0] << 8) | buf[1]) & 0xFFFF;
    return 0;
}

/* Function to convert raw ADC value to CO concentration in PPM.
 * Uses a calibrated logarithmic curve. */
static float raw_to_ppm(int raw_value) {
    if (raw_value <= 0) {
        return 0.0f;
    }

    /* Example calibration curve: CO concentration (PPM) = 10 * log10(raw_value) + 10 */
    float ppm = 10.0f * log10f((float)raw_value) + 10.0f;

    /* Clamp to a reasonable range (0 to 1000 PPM) */
    if (ppm < 0.0f) {
        ppm = 0.0f;
    }
    if (ppm > 1000.0f) {
        ppm = 1000.0f;
    }

    return ppm;
}

/* Function to log CO concentration to a file */
static int log_co_data(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handling for Ctrl+C and termination */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not set SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not set SIGTERM handler.\n");
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int raw_value = 0;

        /* Read raw CO value from the sensor */
        if (read_raw_co(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error: Failed to read raw CO value. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        /* Convert raw value to PPM */
        float ppm = raw_to_ppm(raw_value);

        /* Log the data */
        if (log_co_data(ppm) != 0) {
            fprintf(stderr, "Error: Failed to log CO data.\n");
        }

        printf("CO: %.2f PPM (Raw: %d)\n", ppm, raw_value);

        /* Wait for the next reading interval */
        sleep(READ_INTERVAL_SEC);
    }

    /* Clean up resources */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

