int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *co_raw, uint16_t *no2_raw);
float calculate_co_ppm(uint16_t co_raw);
int log_data(float co_ppm);
int check_threshold(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initializes the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads raw sensor data from the MICS-4514
int read_sensor_data(uint16_t *co_raw, uint16_t *no2_raw) {
    char buf[4];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 4);
        if (bytes_read == 4) {
            *co_raw = (buf[0] << 8) | buf[1];
            *no2_raw = (buf[2] << 8) | buf[3];
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(100000); // 100ms delay before retry
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1;
}

// Calculates CO level in PPM from raw ADC value
float calculate_co_ppm(uint16_t co_raw) {
    // Placeholder linear conversion; replace with actual sensor calibration curve
    return (float)co_raw * 0.1;
}

// Logs CO data to a file
int log_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

// Checks if CO level exceeds the threshold and logs an alert
int check_threshold(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
            return -1;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, CO_THRESHOLD);
        fclose(fp);
        return 0;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("MICS-4514 CO/NO2 Sensor Monitoring Started\n");

    while (program_running) {
        uint16_t co_raw, no2_raw;

        // Read sensor data
        if (read_sensor_data(&co_raw, &no2_raw) == 0) {
            // Calculate CO level
            float co_ppm = calculate_co_ppm(co_raw);

            // Log data
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log CO data\n");
            }

            // Check threshold
            if (check_threshold(co_ppm) != 0) {
                fprintf(stderr, "Failed to check CO threshold\n");
            }

            printf("CO: %.2f PPM, NO2: %.2f PPM\n", co_ppm, (float)no2_raw * 0.1);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next reading interval
        gpioDelay(READ_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    cleanup();
    printf("MICS-4514 CO/NO2 Sensor Monitoring Stopped\n");

    return 0;
}

