#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define ADC_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "audio_log.txt"
#define REFERENCE_PRESSURE 20e-6
#define SENSITIVITY_DBV_PER_PA -38.0

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_i2c_word(int handle, int reg, int16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_spl(int16_t raw) {
    double voltage = (double)raw * 0.000030517578125;
    double pressure = pow(10.0, (voltage - SENSITIVITY_DBV_PER_PA) / 20.0);
    double spl = 20.0 * log10(pressure / REFERENCE_PRESSURE);
    return spl;
}

static void log_data(double spl) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, spl);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MIC1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MIC2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t raw1 = 0, raw2 = 0;
        int r1 = read_i2c_word(i2c_handle1, ADC_REG, &raw1);
        int r2 = read_i2c_word(i2c_handle2, ADC_REG, &raw2);

        double spl;
        if (r1 != 0 || r2 != 0) {
            fprintf(stderr, "I2C read error (h1=%d, h2=%d)\n", r1, r2);
            spl = -999.0;
        } else {
            double s1 = calculate_spl(raw1);
            double s2 = calculate_spl(raw2);
            spl = (s1 + s2) / 2.0;
        }

        log_data(spl);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

