#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define MIC1_ADC_CHANNEL 0
#define MIC2_ADC_CHANNEL 1
#define LED_PIN 27

// Define constants
#define SAMPLE_RATE_MS 1
#define WINDOW_SIZE_MS 100
#define THRESHOLD 0.7
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 3) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
