#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: Single-shot, A0 single-ended, +/-4.096V, 128 SPS, no comparator
#define ADS1115_CONFIG_BASE 0x8000 // OS bit
#define ADS1115_CONFIG_MUX_A0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

// Global variables
static int i2c_handle = -1;
static double current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
static int initialize(void);
static int read_ads1115_raw(int16_t *raw_value);
static double convert_to_current(int16_t raw_value);
static void add_to_buffer(double current);
static double calculate_average_current(void);
static void control_led(double average_current);
static void signal_handler(int signal);
static void cleanup(void);

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Initialize pigpio and I2C
static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d)\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    return 0;
}

// Read raw 16-bit value from ADS1115 channel A0
static int read_ads1115_raw(int16_t *raw_value) {
    char config[3];
    char reg[1];
    char read_buf[2];
    int16_t val;
    int ret;

    // Write config: single-shot conversion on A0
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | 
                 ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | 
                 ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    ret = i2cWriteDevice(i2c_handle, config, 3);
    if (ret < 0) {
        fprintf(stderr, "Error: I2C write config failed (code %d)\n", ret);
        return -1;
    }

    // Wait for conversion to complete (~8ms for 128 SPS)
    gpioDelay(10000);

    // Point to conversion register
    reg[0] = ADS1115_REG_CONVERSION;
    ret = i2cWriteDevice(i2c_handle, reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: I2C write pointer failed (code %d)\n", ret);
        return -1;
    }

    // Read 2 bytes
    ret = i2cReadDevice(i2c_handle, read_buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: I2C read conversion failed (code %d)\n", ret);
        return -1;
    }

    val = (read_buf[0] << 8) | read_buf[1];
    *raw_value = val;
    return 0;
}

// Convert raw ADC value to current (MLX91204: 0.5V to 4.5V for 0-100A, 5V supply)
static double convert_to_current(int16_t raw_value) {
    // ADS1115 at +/-4.096V: 1 bit = 125 uV
    double voltage = raw_value * 0.000125;
    // MLX91204: 0.5V to 4.5V for 0-100A
    double current = (voltage - 0.5) / 4.0 * 100.0;
    return current;
}

// Add current reading to circular buffer
static void add_to_buffer(double current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate average current from buffer
static double calculate_average_current(void) {
    if (buffer_count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

// Control LED based on average current
static void control_led(double average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t raw_value;
        if (read_ads1115_raw(&raw_value) == 0) {
            double current = convert_to_current(raw_value);
            add_to_buffer(current);
            double avg_current = calculate_average_current();
            control_led(avg_current);

            // Log to console
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Current: %.2f A, Avg: %.2f A, LED: %s\n", 
                   timestamp, current, avg_current, 
                   (avg_current > OVERCURRENT_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

