#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TCS34725 I2C address (ADDR pin tied to GND) */
#define TCS34725_I2C_ADDR 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x00
#define TCS34725_ATIME   0x01
#define TCS34725_ID      0x12
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

/* ENABLE register bits */
#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02

/* Expected ID value (lower 4 bits) */
#define TCS34725_ID_VALUE 0x44

/* Integration time: 0xFF = 2.4 ms (ATIME = 255) */
#define ATIME_2_4MS 0xFF

/* Gain: 0x01 = 4x */
#define GAIN_4X 0x01

#define CSV_FILENAME "color_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_csv_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register; returns 0 on success, -1 on  */
/* I2C error.                                                           */
/* ------------------------------------------------------------------ */
static int tcs_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register; returns 0 on success, -1 on */
/* I2C error.                                                           */
/* ------------------------------------------------------------------ */
static int tcs_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
