        perror("Failed to set signal handlers");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, MCP3008_CS_LINE);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    unsigned char mode = SPI_MODE;
    unsigned char bits = SPI_BITS;
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("Failed to create log file");
            close(spi_fd);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            return 1;
        }
        fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    printf("Starting moisture monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int adc1 = read_mcp3008(spi_fd, cs_line, 0);
        int adc2 = read_mcp3008(spi_fd, cs_line, 1);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture1 = map_adc_to_moisture(adc1);
        float moisture2 = map_adc_to_moisture(adc2);

        if (log_data(moisture1, moisture2) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Moisture 1: %.2f%%, Moisture 2: %.2f%%\n", moisture1, moisture2);
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nExiting gracefully.\n");
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    return 0;
}

