#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* ADS1115 config bits */
#define ADS1115_CFG_OS_BEGIN   0x8000  /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_MUX_AIN1  0x5000  /* AIN1 vs GND */
#define ADS1115_CFG_PGA_2_3   0x0200  /* Gain +/-6.144V */
#define ADS1115_CFG_MODE_SS   0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128    0x0080  /* 128 SPS */

/* GPIO pin for warning LED */
#define WARNING_LED_PIN 17

/* Pressure thresholds (kPa) */
#define PRESSURE_THRESHOLD 105.0f
#define PRESSURE_MIN 0.0f
#define PRESSURE_MAX 400.0f

/* Temperature range (°C) */
#define TEMP_MIN 0.0f
#define TEMP_MAX 100.0f

/* ADC full-scale range for PGA 2/3 (+/-6.144V) */
#define ADC_VREF 6.144f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000  /* 10 ms */

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register                         */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register                        */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed for 0x%02X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended sample from the ADS1115                         */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int ads1115_read_channel(int handle, uint16_t mux, int16_t *raw) {
    uint16_t config = ADS1115_CFG_OS_BEGIN | mux | ADS1115_CFG_PGA_2_3 |
                      ADS1115_CFG_MODE_SS | ADS1115_CFG_DR_128;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Poll OS bit (bit 15) to confirm conversion finished */
    uint16_t cfg_val;
    for (int i = 0; i < 10; i++) {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg_val) < 0) {
            return -1;
        }
        if (cfg_val & 0x8000) {
            break;
        }
        gpioDelay(2000);
    }

    if (!(cfg_val & 0x8000)) {
        fprintf(stderr, "Error: ADS1115 conversion timeout\n");
        return -1;
    }

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0) {
        return -1;
    }

    *raw = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC value to voltage                                    */
/* ------------------------------------------------------------------ */
static float raw_to_voltage(int16_t raw) {
    return (float)raw * ADC_VREF / 32768.0f;
}

/* ------------------------------------------------------------------ */
/* Convert voltage to pressure (kPa)                                   */
/* ------------------------------------------------------------------ */
static float voltage_to_pressure(float v) {
    return (v / 5.0f) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

/* ------------------------------------------------------------------ */
/* Convert voltage to temperature (°C)                                 */
/* ------------------------------------------------------------------ */
static float voltage_to_temperature(float v) {
    return (v / 5.0f) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
}

/* ------------------------------------------------------------------ */
/* Read pressure and temperature with retry                            */
/* ------------------------------------------------------------------ */
static int read_sensor(float *pressure, float *temperature) {
    int16_t raw_pressure = 0, raw_temp = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (ads1115_read_channel(i2c_handle, ADS1115_CFG_MUX_AIN0, &raw_pressure) == 0 &&
            ads1115_read_channel(i2c_handle, ADS1115_CFG_MUX_AIN1, &raw_temp) == 0) {
            float v_p = raw_to_voltage(raw_pressure);
            float v_t = raw_to_voltage(raw_temp);

            *pressure = voltage_to_pressure(v_p);
            *temperature = voltage_to_temperature(v_t);
            return 0;
        }

        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Error: Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Control warning LED                                                 */
/* ------------------------------------------------------------------ */
static void control_led(float pressure) {
    int level = (pressure > PRESSURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(WARNING_LED_PIN, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", WARNING_LED_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Configure warning LED pin */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", WARNING_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent.\n", i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(i2c_handle, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding on address 0x%02X\n", ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting pressure monitoring...\n", cfg_check);

    /* Main loop */
    while (running) {
        float pressure, temperature;

        if (read_sensor(&pressure, &temperature) == 0) {
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
            control_led(pressure);
        } else {
            fprintf(stderr, "Error: Sensor read failed. Check wiring and I2C address.\n");
            gpioWrite(WARNING_LED_PIN, 0);
        }

        /* Sleep 1 second (microseconds) */
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

