#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define OVERCURRENT_THRESHOLD 10.0 /* Amperes */
#define OVERCURRENT_GPIO 27       /* Motor shutdown output */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_DELAY_US 100000    /* 100 ms */

/* MLX91209 sensor parameters (analog output) */
#define VCC            3.3        /* Supply voltage */
#define ZERO_CURRENT_V (VCC / 2.0) /* Midpoint at 0A */
#define SENSITIVITY_V_PER_A 0.066 /* 66 mV/A */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                         (start bit)
     *   Byte 1: (0x08 | channel) << 4        (single-ended + channel)
     *   Byte 2: 0x00                         (don't care, clocks out low bits)
     * Response: bits 9-8 in rx[1] (masked 0x03), bits 7-0 in rx[2]
