#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

// ADS1115 Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous mode
#define ADS1115_CONFIG_BASE 0x8000 // OS bit set to start conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // +/-4.096V
#define ADS1115_CONFIG_MODE_CONT 0x0000 // Continuous conversion mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Disable comparator

#define VREF 4.096
#define ADC_MAX 32767.0 // 16-bit signed, positive range
#define PRESSURE_OFFSET 0.5 // kPa
#define PRESSURE_SENSITIVITY 0.1 // V/kPa
#define MIN_PRESSURE 0.0 // kPa
#define MAX_PRESSURE 100.0 // kPa
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_ads1115_raw(int16_t *raw_value);
float convert_to_pressure(int16_t raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initializes the I2C bus and configures the ADS1115
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115: AIN0 single-ended, +/-4.096V, 128 SPS, continuous mode
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | 
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_CONT | 
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    // Write config to register 0x01
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    // Wait for first conversion to complete (128 SPS -> ~7.8ms, wait 20ms)
    gpioDelay(20000);

    return 0;
}

// Reads the raw ADC value from the ADS1115
int read_ads1115_raw(int16_t *raw_value) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Point to conversion register
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Failed to set ADS1115 conversion register pointer: %s\n", strerror(errno));
        return -1;
    }

    // Read 2 bytes of conversion data
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Failed to read ADS1115 conversion data: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

// Converts the raw ADC value to pressure in kPa
float convert_to_pressure(int16_t raw_value) {
    float voltage = ((float)raw_value / ADC_MAX) * VREF;
    float pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SENSITIVITY;
    return pressure;
}

// Logs the pressure reading to a file with an ISO-8601 timestamp
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C and ADC
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t raw_value;
        if (read_ads1115_raw(&raw_value) == 0) {
            float pressure = convert_to_pressure(raw_value);

            if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure reading.\n");
                }
            } else {
                fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

