#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define SUPPLY_VOLTAGE 5.0
#define ADC_RESOLUTION 4095.0
#define THERMISTOR_BETA 3950.0
#define THERMISTOR_R0 10000.0
#define THERMISTOR_T0 298.15

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / ADC_RESOLUTION) * SUPPLY_VOLTAGE;
}

static float calculate_humidity(float v_humidity) {
    float rh = (v_humidity - 0.824f) / 0.0315f;
    if (rh < 0.0f) rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static float calculate_temperature(float v_thermistor) {
    float r_thermistor = (THERMISTOR_R0 * v_thermistor) / (SUPPLY_VOLTAGE - v_thermistor);
    float inv_t = (1.0f / THERMISTOR_T0) + (1.0f / THERMISTOR_BETA) * logf(r_thermistor / THERMISTOR_R0);
    return (1.0f / inv_t) - 273.15f;
}

static void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold at %s: %.2f%%\" | ssmtp %s",
             timestamp, humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error sending email alert (exit code %d).\n", result);
    }
}

static void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d.\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_humidity = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int adc_thermistor = read_mcp3208(MCP3208_CHANNEL_THERMISTOR);

        if (adc_humidity < 0 || adc_thermistor < 0) {
            fprintf(stderr, "SPI transfer error.\n");
            gpioDelay(1000000);
            continue;
        }

        float v_humidity = adc_to_voltage(adc_humidity);
        float v_thermistor = adc_to_voltage(adc_thermistor);
        float humidity = calculate_humidity(v_humidity);
        float temperature = calculate_temperature(v_thermistor);

        printf("Humidity: %.2f%%, Temperature: %.2fC\n", humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        log_data(humidity, temperature);

        gpioDelay(5000000);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

