#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define ADC_CHANNELS 3
#define ADC_RESOLUTION 1023.0
#define VREF 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 0.3
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE 100
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(CS_PIN, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double calculate_acceleration(int adc_value) {
    double voltage = (adc_value / ADC_RESOLUTION) * VREF;
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

static void log_data(int x_adc, int y_adc, int z_adc, double x_g, double y_g, double z_g) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f\n",
            timestamp, x_adc, y_adc, z_adc, x_g, y_g, z_g);
    fflush(log_file);
}

static void detect_impact(double x_g, double y_g, double z_g) {
    double magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
    if (magnitude > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,IMPACT DETECTED,%.3f g\n", timestamp, magnitude);
        fflush(log_file);
        printf("Impact detected! Magnitude: %.3f g\n", magnitude);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting data acquisition at %d Hz...\n", SAMPLE_RATE);

    while (!terminate) {
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double x_g = calculate_acceleration(x_adc);
        double y_g = calculate_acceleration(y_adc);
        double z_g = calculate_acceleration(z_adc);

        log_data(x_adc, y_adc, z_adc, x_g, y_g, z_g);
        detect_impact(x_g, y_g, z_g);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

