/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio I2C on bus 1, address 0x49.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw
 * photoplethysmography (PPG) samples to heart rate (HR) and SpO2.
 * This program reads the raw 16-bit IR and RED ADC values from the
 * FIFO as proxy values and logs them as HR (IR) and SpO2 (RED).
 * For a production-quality HR/SpO2 reading, use the Si1172 SDK
 * or a certified medical-grade sensor.
 *
 * Build: gcc -Wall -Wextra -O2 -o si1172_log si1172_log.c -lpigpio -lrt
 * Run:   sudo ./si1172_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 constants (command-based register access) ---- */
#define SI1172_I2C_ADDR        0x49
#define SI1172_BUS             1

#define SI1172_REG_COMMAND     0xC0  /* command register */
#define SI1172_REG_DATA0       0xC1  /* FIFO data registers */
#define SI1172_REG_DATA1       0xC2
#define SI1172_REG_DATA2       0xC3
#define SI1172_REG_DATA3       0xC4

/* Commands */
#define SI1172_CMD_RESET       0x01
#define SI1172_CMD_START       0x02  /* start measurement */
#define SI1172_CMD_STOP        0x03
#define SI1172_CMD_READ_FIFO   0x04

/* Error flags */
#define ERR_NONE               0
#define ERR_I2C_READ           1
#define ERR_SENSOR_ABSENT      2

/* ---- Globals ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %d\n",
                reg, val, rc);
    }
    return rc;
}

static int i2c_read_byte(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ---- Sensor init ---- */
static int sensor_init(void)
{
    /* Reset the device */
    if (i2c_write_byte(SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Start measurement */
    if (i2c_write_byte(SI1172_REG_COMMAND, SI1172_CMD_START) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ---- Read raw 16-bit IR + RED from FIFO ---- */
static int read_sensor_data(uint16_t *ir, uint16_t *red)
{
    uint8_t d0, d1, d2, d3;

    if (i2c_read_byte(SI1172_REG_DATA0, &d0) < 0) return -1;
    if (i2c_read_byte(SI1172_REG_DATA1, &d1) < 0) return -1;
    if (i2c_read_byte(SI1172_REG_DATA2, &d2) < 0) return -1;
    if (i2c_read_byte(SI1172_REG_DATA3, &d3) < 0) return -1;

    /* Si1172 FIFO: DATA0=IR_LSB, DATA1=IR_MSB, DATA2=RED_LSB, DATA3=RED_MSB */
    *ir  = (uint16_t)((d1 << 8) | d0);
    *red = (uint16_t)((d3 << 8) | d2);
    return 0;
}

/* ---- Log one row ---- */
static void log_data(time_t ts, uint16_t hr, uint16_t spo2, int err)
{
    fprintf(log_file, "%ld,%u,%u,%d\n", (long)ts, hr, spo2, err);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2c_write_byte(SI1172_REG_COMMAND, SI1172_CMD_STOP);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at 0x49 */
    i2c_handle = i2cOpen(SI1172_BUS, SI1172_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                SI1172_BUS, SI1172_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init() < 0) {
        fprintf(stderr, "Sensor initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("biometric_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(log_file);
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1172 logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        time_t now = time(NULL);
        uint16_t ir = 0, red = 0;
        int err = ERR_NONE;

        if (read_sensor_data(&ir, &red) < 0) {
            err = ERR_I2C_READ;
            /* Log error row with sentinel values */
            log_data(now, 0xFFFF, 0xFFFF, err);
        } else {
            /* Proxy: IR = HR, RED = SpO2 (see NOTE above) */
            log_data(now, ir, red, err);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

