#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define VREF 3.3
#define FLOW_MAX 5.0
#define ADC_MAX 1023.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float adc_to_flow(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_MAX;
    return (voltage / VREF) * FLOW_MAX;
}

static int log_flow_rate(float flow_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value == 0 || adc_value >= 1023) {
            fprintf(stderr, "Warning: ADC value at extreme (%d) - sensor absent or wiring fault\n", adc_value);
        }

        float flow_rate = adc_to_flow(adc_value);

        if (flow_rate < 0.0f || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Warning: Flow rate out of range: %.2f L/min\n", flow_rate);
        }

        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Error: Failed to log flow rate\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

