#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP_10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        return -1;
    }
    usleep(100000); // 100ms wait for conversion
    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }
    return 0;
}

void convert_data(const uint8_t *data, float *temperature, float *pressure) {
    // Raw values (big-endian, 16-bit)
    uint16_t raw_p = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    // ICP-10125 calibration (simplified linear approximation)
    // For real deployment, use the full calibration coefficients from the datasheet
    *temperature = (raw_t - 32768.0) * 100.0 / 65535.0;
    *pressure = (raw_p - 32768.0) * 100000.0 / 65535.0;
}

void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(fp);
}

void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint8_t sensor_data[6];
        float temperature, pressure;

        if (read_sensor_data(i2c_fd, sensor_data) == 0) {
            convert_data(sensor_data, &temperature, &pressure);
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            fprintf(log_file, "Error reading sensor data: %s\n", strerror(errno));
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

