#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define SAMPLE_RATE 1000
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    float gain = 1.0f;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0f) {
            fprintf(stderr, "Error: Gain must be greater than 0\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle: %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio from MCP3008 channels %d and %d...\n", MCP3008_CHANNEL_0, MCP3008_CHANNEL_1);
    printf("Gain: %.2f\n", gain);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int mic1 = read_mcp3008(MCP3008_CHANNEL_0);
        int mic2 = read_mcp3008(MCP3008_CHANNEL_1);

        if (mic1 < 0 || mic2 < 0) {
            fprintf(stderr, "Error: Failed to read from MCP3008. Exiting.\n");
            break;
        }

        int diff = mic1 - mic2;
        int output = (int)(diff * gain);

        printf("%d,%d,%d\n", mic1, mic2, output);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return 0;
}

