#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LED_PIN     17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW  70.0
#define SAMPLE_INTERVAL_US 5000000
#define SLEEP_INCREMENT_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_water_level(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void control_led(double water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_PIN, 1);
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_PIN, 0);
    }
}

static void log_water_level(double water_level) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(json_file, "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f},\n",
            timestamp, ts.tv_nsec / 1000000, water_level);
    fflush(json_file);
}

