    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (json_file) {
        fclose(json_file);
        json_file = NULL;
    }
}

