    gpioWrite(LED_PIN, 0);

    json_file = fopen("water_levels.json", "w");
    if (!json_file) {
        perror("Failed to open water_levels.json");
        cleanup();
        return 1;
    }
    fprintf(json_file, "[\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            double water_level = calculate_water_level(adc_value);
            control_led(water_level);
            log_water_level(water_level);
            printf("Water Level: %.2f%%\n", water_level);
        }

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(SLEEP_INCREMENT_US);
        }
    }

    fprintf(json_file, "\b\b]\n");
    fclose(json_file);
    json_file = NULL;

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    spi_handle = -1;
    gpioTerminate();

    return 0;
}

