#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0          // SPI0 CE0 (physical pin 24)
#define SPI_SPEED 1000000      // 1 MHz
#define ADC_CHANNEL 0          // MCP3008 channel 0
#define SAMPLE_INTERVAL_MS 100 // 100 milliseconds
#define LOG_FILE "airflow_log.csv"

// Global variables for signal handling
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_lpm(int adc_value);
void log_data(float lpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended + channel selection)
    // Byte 2: 0x00 (Don't care)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to LPM (example linear conversion)
float convert_to_lpm(int adc_value) {
    // Example: 0-1023 ADC range maps to 0-100 LPM
    // Replace with actual sensor calibration curve
    return (float)adc_value * 100.0 / 1023.0;
}

// Function to log data to CSV file
void log_data(float lpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, lpm) < 0) {
