#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MOISTURE_THRESHOLD 30.0
#define LOGGING_FREQUENCY 60
#define RECIPIENT_EMAIL "recipient@example.com"
#define MSMTP_CONFIG_FILE "/etc/msmtprc"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Error: Invalid calibration values (max_raw <= min_raw)\n");
        return -1.0f;
    }
    float moisture = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0f);
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

static int log_data(float moisture) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open plant_data.txt for appending\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error: localtime() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error: localtime() failed for email\n");
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char command[512];
    snprintf(command, sizeof(command),
             "msmtp -C %s -t", MSMTP_CONFIG_FILE);

    FILE *fp = popen(command, "w");
    if (!fp) {
        fprintf(stderr, "Error: Failed to execute msmtp\n");
        return -1;
    }

    fprintf(fp, "To: %s\n", RECIPIENT_EMAIL);
    fprintf(fp, "Subject: Plant Moisture Alert\n\n");
    fprintf(fp, "Plant moisture level is critically low: %.2f%%\n", moisture);
    fprintf(fp, "Timestamp: %s\n", timestamp);

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose() failed\n");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int spi_channel = SPI_CHANNEL;
    int adc_channel = ADC_CHANNEL;
    int min_raw = MIN_RAW_VALUE;
    int max_raw = MAX_RAW_VALUE;
    float moisture_threshold = MOISTURE_THRESHOLD;
    int logging_frequency = LOGGING_FREQUENCY;
    char recipient_email[256] = RECIPIENT_EMAIL;
    char msmtp_config_file[512] = MSMTP_CONFIG_FILE;

    if (argc > 1) {
        spi_channel = atoi(argv[1]);
        if (spi_channel < 0 || spi_channel > 1) {
            fprintf(stderr, "Error: SPI channel must be 0 or 1\n");
            return 1;
        }
    }
    if (argc > 2) {
        adc_channel = atoi(argv[2]);
        if (adc_channel < 0 || adc_channel > 7) {
            fprintf(stderr, "Error: ADC channel must be 0-7\n");
            return 1;
        }
    }
    if (argc > 3) {
        min_raw = atoi(argv[3]);
    }
    if (argc > 4) {
        max_raw = atoi(argv[4]);
    }
    if (argc > 5) {
        moisture_threshold = atof(argv[5]);
    }
    if (argc > 6) {
        logging_frequency = atoi(argv[6]);
        if (logging_frequency <= 0) {
            fprintf(stderr, "Error: Logging frequency must be positive\n");
            return 1;
        }
    }
    if (argc > 7) {
        strncpy(recipient_email, argv[7], sizeof(recipient_email) - 1);
        recipient_email[sizeof(recipient_email) - 1] = '\0';
    }
    if (argc > 8) {
        strncpy(msmtp_config_file, argv[8], sizeof(msmtp_config_file) - 1);
        msmtp_config_file[sizeof(msmtp_config_file) - 1] = '\0';
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI channel: %d, ADC channel: %d, Min raw: %d, Max raw: %d, Threshold: %.1f%%, Frequency: %ds, Recipient: %s, MSMTP config: %s\n",
           spi_channel, adc_channel, min_raw, max_raw, moisture_threshold, logging_frequency, recipient_email, msmtp_config_file);

    while (program_running) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        float moisture = calculate_moisture(raw_value, min_raw, max_raw);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error: Invalid moisture calculation, retrying in %d seconds\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        if (log_data(moisture) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        if (moisture < moisture_threshold) {
            if (send_email_alert(moisture) != 0) {
                fprintf(stderr, "Warning: Failed to send email alert\n");
            }
        }

        sleep(logging_frequency);
    }

    printf("\nShutting down gracefully...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

