    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx_buffer, (char *)rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits
    // rx_buffer[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * VREF;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    // Clamp voltage to valid range to prevent out-of-bounds errors
    if (voltage < VOLTAGE_MIN) voltage = VOLTAGE_MIN;
    if (voltage > VOLTAGE_MAX) voltage = VOLTAGE_MAX;

    return ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

// Function to log pressure data with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0, MCP3008 CH0, 1 Hz sampling\n");
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read ADC value (consecutive: %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: Max consecutive errors reached. Aborting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Sensor-absent detection: voltage stuck at 0V or VREF
        if (voltage < 0.01 && voltage > 0.0) {
            fprintf(stderr, "Warning: Sensor may be disconnected (0V reading)\n");
        } else if (voltage > VREF - 0.01 && voltage < VREF) {
            fprintf(stderr, "Warning: Sensor may be disconnected (VREF reading)\n");
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log pressure data
        log_pressure(pressure);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

