#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define LOG_BUFFER_SIZE 20
#define SAMPLE_INTERVAL_MS 5000

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[LOG_BUFFER_SIZE];
static int log_index = 0;
static int log_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    if (!running) return;

    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return;
    }

    int moisture_level = ((rx[1] & 0x03) << 8) | rx[2];

    time_t now = time(NULL);
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
    if (log_count < LOG_BUFFER_SIZE) log_count++;

    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to turn pump ON\n");
        }
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to turn pump OFF\n");
        }
    }

    printf("Moisture: %d, Pump: %s\n", moisture_level, pump_state ? "ON" : "OFF");

    for (int i = 0; i < log_count; i++) {
        int idx = (log_index - log_count + i + LOG_BUFFER_SIZE) % LOG_BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[idx].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", ts, log_buffer[idx].moisture_level, log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

