#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVERFLOW_CTR 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_RATE 100
#define ADC_RANGE 4096
#define PULSE_WIDTH_411US 0x03
#define LED_CURRENT_24MA 0x24

#define HR_THRESHOLD 100
#define SPO2_THRESHOLD 95

#define WINDOW_SIZE 100
#define PEAK_THRESHOLD 0.5

typedef struct {
    int red;
    int ir;
} sensor_data_t;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(i2c_handle, reg);
    if (r < 0) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_reg(REG_MODE_CONFIG, 0x40) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (write_reg(REG_INTR_ENABLE_2, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (write_reg(REG_OVERFLOW_CTR, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (write_reg(REG_FIFO_CONFIG, 0x4F) < 0) return -1;
    if (write_reg(REG_MODE_CONFIG, 0x03) < 0) return -1;
    if (write_reg(REG_SPO2_CONFIG, (SAMPLE_RATE << 5) | (PULSE_WIDTH_411US << 2) | 0x03) < 0) return -1;
    if (write_reg(REG_LED1_PA, LED_CURRENT_24MA) < 0) return -1;
    if (write_reg(REG_LED2_PA, LED_CURRENT_24MA) < 0) return -1;

    return 0;
}

