    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_buzzer(int state) {
    if (gpioWrite(BUZZER_PIN, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

