        } else {
            if (set_buzzer(0) != 0) break;
        }

        gpioDelay(SAMPLE_US);
    }

    set_buzzer(0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

