#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS115_REG_CONFIG 0x01
#define ADS115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

#define RELAY_LINE     17
#define REED_LINE      27
#define LOG_FILE       "/var/log/door_events.log"
#define NUM_BASELINE   10
#define POLL_MS        200
#define RELAY_MS       3000
#define BASELINE_MS    50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void sigh(int sig) { (void)sig; running = 0; }

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm; localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t cfg = 0x8000 | (0x4000) | (0x0100) | (0x0080) | (0x0000) | (0x0003);
    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    return 0;
}

static int ads1115_read(int fd) {
    uint16_t val;
    if (i2c_read16(fd, ADS1115_REG_CONV, &val) < 0) return -1;
    return (int16_t)val;
}

static int calibrate_baseline(int fd, float *threshold) {
    long sum = 0;
    int ok = 0;
    for (int i = 0; i < NUM_BASELINE; i++) {
        int v = ads1115_read(fd);
        if (v < 0) { log_event("Baseline read failed"); continue; }
        sum += v; ok++;
        usleep(BASELINE_MS * 1000);
    }
    if (ok == 0) return -1;
    *threshold = 0.8f * (float)sum / ok;
    return 0;
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (reed_line)  gpiod_line_release(reed_line);
    if (chip)       gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
