int main(void) {
    struct sigaction sa = { .sa_handler = sigh };
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); return 1; }
    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    reed_line  = gpiod_chip_get_line(chip, REED_LINE);
    if (!relay_line || !reed_line) { perror("gpiod_get_line"); cleanup(); return 1; }
    if (gpiod_line_request_output(relay_line, "door-relay", 0) < 0) {
        perror("relay request"); cleanup(); return 1;
    }
    if (gpiod_line_request_input(reed_line, "reed-door") < 0) {
        perror("reed request"); cleanup(); return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); cleanup(); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); cleanup(); return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        log_event("ADS1115 init failed"); cleanup(); return 1;
    }

    float threshold;
    if (calibrate_baseline(i2c_fd, &threshold) < 0) {
        log_event("Calibration failed"); cleanup(); return 1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Calibration complete, threshold=%.2f", threshold);
    log_event(msg);

    while (running) {
        int v = ads1115_read(i2c_fd);
        if (v < 0) { log_event("ADC read error"); usleep(POLL_MS * 1000); continue; }
        if ((float)v < threshold) {
            log_event("Proximity detected, releasing lock");
            if (gpiod_line_set_value(relay_line, 1) < 0) log_event("Relay on failed");
            for (int ms = 0; ms < RELAY_MS && running; ms += 100) usleep(100000);
            if (gpiod_line_set_value(relay_line, 0) < 0) log_event("Relay off failed");
            int r = gpiod_line_get_value(reed_line);
            if (r == 0) log_event("Door opened");
            else if (r < 0) log_event("Reed read error");
            else log_event("Door not opened");
        }
        usleep(POLL_MS * 1000);
    }
    log_event("Shutting down");
    cleanup();
    return 0;
}

