    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("fprintf header");
            fclose(fp);
            goto cleanup_chip;
        }
        fflush(fp);
    }

    printf("Logging soil moisture data to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        int s1 = read_mcp3008(spi_fd, cs_lines[0], 0);
        int s2 = read_mcp3008(spi_fd, cs_lines[1], 0);
        int s3 = read_mcp3008(spi_fd, cs_lines[2], 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");

    if (fclose(fp) != 0) {
        perror("fclose");
    }

cleanup_chip:
    for (int i = 0; i < 3; i++) {
        if (cs_lines[i]) {
            gpiod_line_release(cs_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

