#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static int spi_handle = -1;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        log_message("SPI transfer failed, retrying...");
        gpioDelay(100000);
    }
    log_message("SPI transfer failed after max retries.");
    return -1;
}

static int calculate_moisture(int raw) {
    if (raw < 0) return -1;
    if (raw <= DRY_RAW) return 100;
    if (raw >= WET_RAW) return 0;
    int span = WET_RAW - DRY_RAW;
    int diff = raw - DRY_RAW;
    int pct = 100 - (int)(((float)diff / span) * 100.0f);
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_message(state ? "Pump activated" : "Pump deactivated");
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_s] [-s interval_s]\n", argv[0]);
                return 1;
        }
    }
    if (threshold < 0 || threshold > 100 || duration <= 0 || sleep_interval <= 0) {
        fprintf(stderr, "Invalid arguments.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started.");

    while (running) {
        int raw = read_mcp3008(0);
        if (raw < 0) {
            log_message("Sensor read failed; skipping cycle.");
            sleep(sleep_interval);
            continue;
        }
        int moisture = calculate_moisture(raw);
        char buf[128];
        snprintf(buf, sizeof(buf), "Raw: %d, Moisture: %d%%", raw, moisture);
        log_message(buf);

        if (moisture < threshold) {
            log_message("Moisture below threshold; activating pump.");
            control_pump(1);
            for (int i = 0; i < duration && running; i++) {
                sleep(1);
            }
            control_pump(0);
        }
        for (int i = 0; i < sleep_interval && running; i++) {
            sleep(1);
        }
    }

    log_message("Shutting down.");
    cleanup();
    return 0;
}

