#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define PCF8591_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* Control byte: bit7=0 (single-ended), bit6=0 (AIN0), bit5=0 (disable analog output) */
#define PCF8591_CTRL_SINGLE_ENDED_AIN0 0x00

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 device */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 returns the result of the *previous* conversion on the
     * first read after a control-byte write.  Perform a dummy read
     * to discard the stale byte so the next read reflects AIN0.
     */
    uint8_t dummy;
    ssize_t n = read(fd, &dummy, 1);
    if (n < 0) {
        fprintf(stderr, "Initial dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (n == 0) {
        fprintf(stderr, "Initial dummy read returned 0 bytes (device absent?)\n");
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        uint8_t ctrl = PCF8591_CTRL_SINGLE_ENDED_AIN0;

        /* Write control byte to select AIN0 single-ended */
        if (write(fd, &ctrl, 1) != 1) {
            fprintf(stderr, "write(control) failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Read the conversion result (previous conversion) */
        uint8_t value;
        n = read(fd, &value, 1);
        if (n < 0) {
            fprintf(stderr, "read(sample) failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (n == 0) {
            fprintf(stderr, "read(sample) returned 0 bytes\n");
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

