#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

/* Config: single-shot, AIN0 single-ended, PGA +/-4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE     0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* MUX[14:12] = 100 */
#define ADS1115_CFG_PGA_4096 0x0200  /* PGA[11:9] = 001 */
#define ADS1115_CFG_DR_128   0x0080  /* DR[7:5] = 100 */
#define ADS115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

#define MOTOR_SHUTDOWN_PIN   27
#define THRESHOLD_GAUSS      500.0f
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     1000000  /* 1 Hz */
#define ADC_PGA_V            4.096f
#define ADC_MAX_COUNT        32767.0f
#define SS49E_VCC            3.3f
#define SS49E_ZERO_FIELD_V   2.5f
#define SS49E_SENSITIVITY_V_PER_G 0.0014f  /* 1.4 mV/Gauss */

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static float gauss_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;
static bool  motor_armed  = true;

/* ---- Prototypes ---- */
static int  ads1115_read_raw(int handle, int16_t *raw);
static float raw_to_voltage(int16_t raw);
static float voltage_to_gauss(float v);
static float buffer_add(float gauss);
static float buffer_average(void);
static void  shutdown_motor(void);
static void  signal_handler(int sig);
static void  cleanup(void);

/* ---- ADS1115 helpers ---- */
static int ads1115_read_raw(int handle, int16_t *raw) {
    char cfg[3];
    char conv[2];
    int  cfg_val = ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 |
                   ADS1115_CFG_PGA_4096 | ADS1115_CFG_DR_128 |
                   ADS1115_CFG_CQUE_NONE;

    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (cfg_val >> 8) & 0xFF;
    cfg[2] = cfg_val & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed");
        return -1;
    }

    /* Wait for conversion (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register */
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115 reg select failed");
        return -1;
    }

    if (i2cReadDevice(handle, conv, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 read conversion failed");
        return -1;
    }

    *raw = (int16_t)((conv[0] << 8) | (conv[1] & 0xFF));
    return 0;
}

static float raw_to_voltage(int16_t raw) {
    return ((float)raw / ADC_MAX_COUNT) * ADC_PGA_V;
}

static float voltage_to_gauss(float v) {
    /* SS49E: B(Gauss) = (V - V_zero) / sensitivity */
    return (v - SS49E_ZERO_FIELD_V) / SS49E_SENSITIVITY_V_PER_G;
}

/* ---- Circular buffer ---- */
static float buffer_add(float gauss) {
    gauss_buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    return buffer_average();
}

static float buffer_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += gauss_buffer[i];
    return sum / (float)buffer_count;
}

/* ---- Motor shutdown ---- */
static void shutdown_motor(void) {
    if (motor_armed) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1);
        motor_armed = false;
        syslog(LOG_CRIT, "Motor shutdown triggered (threshold exceeded)");
    }
}

/* ---- Signal / cleanup ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (motor_armed) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
        motor_armed = false;
    }
    gpioTerminate();
    closelog();
}

/* ---- Main ---- */
int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall sensor monitoring started (threshold %.1f Gauss)", THRESHOLD_GAUSS);

    while (!terminate) {
        int16_t raw;
        if (ads1115_read_raw(i2c_handle, &raw) != 0) {
            syslog(LOG_WARNING, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        if (voltage < 0.0f || voltage > SS49E_VCC) {
            syslog(LOG_WARNING, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        float avg   = buffer_add(gauss);

        syslog(LOG_INFO, "Gauss: %.2f | Avg: %.2f", gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            shutdown_motor();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

