#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10
#define WATERING_INTERVAL 60
#define LOG_FILE "watering_events.txt"
#define MAX_SPI_RETRIES 3
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
                fprintf(stderr, "Warning: ADC value out of range: %d\n", adc_value);
                return -1;
            }
            return adc_value;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d), ret=%d\n", attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(100000);
    }
    fprintf(stderr, "Error: SPI communication failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
    }
}

static void log_event(int moisture_level, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", timestamp, moisture_level, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring and Automated Watering System\n");

    while (running) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_event(-1, 0);
            gpioDelay(WATERING_INTERVAL * 1000000);
            continue;
        }

        printf("Moisture Level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold. Activating pump.\n");
            control_pump(1);
            log_event(moisture_level, 1);

            for (int i = 0; i < PUMP_DURATION && running; i++) {
                gpioDelay(1000000);
            }

            control_pump(0);
            log_event(moisture_level, 0);
            printf("Pump deactivated.\n");
        }

        for (int i = 0; i < WATERING_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

