#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define PWM_PIN     18
#define PWM_FREQ    1000
#define PWM_RANGE   1024
#define ADC_CHANNEL 0
#define SAMPLE_US  100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reading MCP3008 channel %d via SPI%d, controlling PWM on GPIO%d.\n",
           ADC_CHANNEL, SPI_CHANNEL, PWM_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, continuing...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (gpioPWM(PWM_PIN, adc_value) != 0) {
            fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, adc_value);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

