#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_GPIO 17
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADC_MAX_VALUE 32767.0
#define ADC_VREF 4.096
#define SENSOR_SENSITIVITY 0.001
#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL_US 100000
#define BLINK_ON_US 50000
#define BLINK_OFF_US 50000
#define BLINK_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, int16_t *raw) {
    char config[3];
    char conv[2];
    int16_t val;

    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }

    gpioDelay(10000);

    config[0] = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, config, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion pointer\n");
        return -1;
    }

    if (i2cReadDevice(handle, conv, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
        return -1;
    }

    val = (int16_t)((conv[0] << 8) | conv[1]);
    *raw = val;
    return 0;
}

static double calculate_gauss(int16_t raw) {
    double voltage = (raw / ADC_MAX_VALUE) * ADC_VREF;
    double gauss = (voltage - 1.65) / SENSOR_SENSITIVITY;
    return gauss;
}

static void blink_led(int gpio, int duration_us) {
    uint32_t start = gpioTick();
    while (running && (gpioTick() - start) < (uint32_t)duration_us) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_ON_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_OFF_US);
    }
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E Hall sensor (ADS1115 on I2C bus %d, addr 0x%02X)...\n", I2C_BUS, ADS1115_ADDR);
    printf("Threshold: %.2f Gauss, LED on GPIO%d\n", threshold, LED_GPIO);

    while (running) {
        int16_t raw;
        if (read_ads1115(i2c_handle, &raw) == 0) {
            double gauss = calculate_gauss(raw);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                blink_led(LED_GPIO, BLINK_DURATION_US);
            }
        } else {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

