#define ADC_MAX 1023
#define ADC_MIN 0
#define MOISTURE_MIN 0.0
#define MOISTURE_MAX 100.0
#define ADC_ERROR_SENTINEL -1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static MQTTClient mqtt_client;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        syslog(LOG_ERR, "ADC value %d out of range", adc_value);
        return -1.0;
    }
    float moisture = MOISTURE_MIN + (float)(adc_value - ADC_MIN) *
                     (MOISTURE_MAX - MOISTURE_MIN) / (ADC_MAX - ADC_MIN);
    if (moisture < MOISTURE_MIN) moisture = MOISTURE_MIN;
    if (moisture > MOISTURE_MAX) moisture = MOISTURE_MAX;
    return moisture;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int rc = MQTTClient_publish(mqtt_client, MQTT_TOPIC_SOIL, strlen(payload), payload, 0, 0, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    }
}

