        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    int rc = MQTTClient_create(&mqtt_client, MQTT_SERVER, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT create failed: %s", MQTTClient_strerror(rc));
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    MQTTClient_setCallbacks(mqtt_client, NULL, connection_lost, message_arrived, NULL);

