    usleep(BH1750_MEASUREMENT_TIME_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -2;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | (channel & 0x07)) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, float sound_db, float light_lux, int err_code) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, err_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open " SPI_DEVICE);
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float sound_db = 0.0f;
        float light_lux = 0.0f;
        int err_code = 0;

        int adc = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc < 0) {
            err_code = -3;
        } else {
            sound_db = (float)adc * 100.0f / 1023.0f;
        }

        if (read_bh1750(i2c_fd, &light_lux) != 0) {
            err_code = -4;
        }

        log_data(fp, sound_db, light_lux, err_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

