#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_valve_position(int position) {
    if (position < 0 || position > 100) {
        fprintf(stderr, "Invalid valve position: %d\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(const int readings[NUM_SENSORS], int avg, int valve_pos) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n",
            ts, readings[0], readings[1], readings[2], avg, valve_pos);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("irrigation.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int readings[NUM_SENSORS];
        int valid = 0;
        long sum = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(i);
            if (v < 0) {
                fprintf(stderr, "Sensor %d read error, skipping\n", i);
                continue;
            }
            readings[i] = v;
            sum += v;
            valid++;
        }

        int avg = (valid > 0) ? (int)(sum / valid) : 0;
        int valve_pos = 100 - (int)(((float)avg / 1023.0f) * 100.0f);
        if (valve_pos < 0) valve_pos = 0;
        if (valve_pos > 100) valve_pos = 100;

        if (set_valve_position(valve_pos) != 0) {
            fprintf(stderr, "Valve set error, continuing\n");
        }

        log_data(readings, avg, valve_pos);
        printf("Avg: %d, Valve: %d\n", avg, valve_pos);

        for (int i = 0; i < LOG_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    set_valve_position(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

