    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", duty_ns);
    if (lseek(pwm_fd, 0, SEEK_SET) < 0) return -1;
    if (write(pwm_fd, buf, len) != len) return -1;
    return 0;
}

int main() {
    FILE *config_file;
    float min_distance = 2.0, max_distance = 400.0;
    float min_frequency = 220.0, max_frequency = 880.0;
    int spi_fd = -1, pwm_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL, *echo_line = NULL;
    int last_valid_distance = 0;

    signal(SIGINT, signal_handler);

    config_file = fopen(CONFIG_FILE, "r");
    if (config_file) {
        if (fscanf(config_file, "%f %f %f %f", &min_distance, &max_distance, &min_frequency, &max_frequency) != 4) {
            fprintf(stderr, "Error reading config file. Using defaults.\n");
            min_distance = 2.0; max_distance = 400.0; min_frequency = 220.0; max_frequency = 880.0;
        }
        fclose(config_file);
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) { perror("gpiod_chip_open"); goto cleanup; }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) { perror("gpiod_chip_get_line"); goto cleanup; }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) { perror("gpiod_line_request_output trig"); goto cleanup; }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) { perror("gpiod_line_request_input echo"); goto cleanup; }

