        long diff_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        float distance = (diff_us * 0.0343) / 2.0;

        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
            if (last_valid_distance > 0) distance = last_valid_distance;
