#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x08 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0) return -1;
    if (adc_value > 1023) adc_value = 1023;
    return (int)(((float)adc_value / 1023.0f) * 500.0f);
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

static void log_data(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

static int initialize_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_spi() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed after %d retries, re-initializing SPI\n", MAX_RETRIES);
            if (initialize_spi() != 0) {
                fprintf(stderr, "SPI re-initialization failed, exiting\n");
                break;
            }
            gpioDelay(1000000);
            continue;
        }

        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            gpioDelay(5000000);
            continue;
        }

        control_fan(aqi);
        log_data(aqi);

        gpioDelay(5000000);
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

