void cleanup(int signal) {
    (void)signal;
    terminate = 1;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    motor_stop(MOTOR1_ENABLE);
    motor_stop(MOTOR2_ENABLE);
