        spi_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

// Function to read the potentiometer value from the MCP3008 ADC
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // MCP3008 SPI command format for single-ended mode:
    // Byte 1: 0x01 (Start bit)
    // Byte 2: (0x08 | channel) << 4 (Single-ended + channel selection)
    // Byte 3: 0x00 (Don't care)
    tx_buffer[0] = 0x01;
    tx_buffer[1] = (0x08 | channel) << 4;
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    // rx_buffer[1] contains the two most significant bits
    // rx_buffer[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
