    // Logarithmic mapping for finer control at lower speeds
    double normalized_value = (double)potentiometer_value / 1023.0;
    double speed_factor = 1.0 - pow(1.0 - normalized_value, 2.0); // Quadratic mapping for smoothness
    int speed = (int)(speed_factor * (MAX_SPEED - MIN_SPEED)) + MIN_SPEED;

