#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define NUM_CALIBRATION_SAMPLES 500
#define DEBOUNCE_DELAY_US 10000
#define THRESHOLD_PERCENT 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, (char*)tx, (char*)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int calibrate_noise_level(int num_samples) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < num_samples; i++) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            continue;
        }
        sum += val;
        valid++;
        gpioDelay(1000);
    }
    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }
    return (int)(sum / valid);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Calibrating noise level for 5 seconds...\n");
    int ambient = calibrate_noise_level(NUM_CALIBRATION_SAMPLES);
    if (ambient < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Ambient level: %d\n", ambient);
    int threshold = ambient + (ambient * THRESHOLD_PERCENT / 100);
    printf("Threshold: %d\n", threshold);

    uint32_t last_led_toggle = 0;
    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            gpioDelay(10000);
            continue;
        }
        if (sound_level > threshold) {
            uint32_t now = gpioTick();
            if (now - last_led_toggle > DEBOUNCE_DELAY_US) {
                gpioWrite(LED_GPIO, 1);
                last_led_toggle = now;
            }
        } else {
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

