#define SPI_SPEED 1000000 // 1 MHz
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define AIRFLOW_MAX 200.0
#define TIMER_INTERVAL_MS 100
#define ADC_RESOLUTION 1024.0
#define ADC_VREF 3.3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

