#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8          /* GPIO8 = physical pin 24 */
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000ULL / SAMPLE_RATE_HZ)
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "audio_log.txt"
#define ADC_CHANNEL     0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(int *spi_fd)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    *spi_fd = fd;
    return 0;
}

static int gpio_init(struct gpiod_line_request **req)
{
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP ")");
        return -1;
    }

    struct gpiod_line_settings *settings = gpiod_line_settings_new();
    if (!settings) {
        perror("gpiod_line_settings_new");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    struct gpiod_line_config *line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        perror("gpiod_line_config_new");
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    unsigned int offset = CS_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1, settings) < 0) {
        perror("gpiod_line_config_add_line_settings");
        gpiod_line_config_free(line_cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_request_config *req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        perror("gpiod_request_config_new");
        gpiod_line_config_free(line_cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_request_config_set_consumer(req_cfg, "audio_logger");

    *req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!*req) {
        perror("gpiod_chip_request_lines");
        gpiod_request_config_free(req_cfg);
        gpiod_line_config_free(line_cfg);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_request_config_free(req_cfg);
    gpiod_line_config_free(line_cfg);
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);
    return 0;
}

static int read_adc(int spi_fd, struct gpiod_line_request *req, int channel)
{
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | (channel & 0x07)) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_request_set_value(req, CS_LINE_OFFSET, GPIOD_LINE_VALUE_ACTIVE) < 0) {
        perror("gpiod_line_request_set_value(ACTIVE)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_request_set_value(req, CS_LINE_OFFSET, GPIOD_LINE_VALUE_INACTIVE);
        return -1;
    }

    if (gpiod_line_request_set_value(req, CS_LINE_OFFSET, GPIOD_LINE_VALUE_INACTIVE) < 0) {
        perror("gpiod_line_request_set_value(INACTIVE)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, long long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%lld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_line_request *gpio_req = NULL;
    FILE *log_fp = NULL;
    int ret = 1;

    if (setup_signals() < 0)
        goto cleanup;

    if (spi_init(&spi_fd) < 0)
        goto cleanup;

    if (gpio_init(&gpio_req) < 0)
        goto cleanup;

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    struct timespec next;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &next) < 0) {
        perror("clock_gettime");
        goto cleanup;
    }

    while (g_running) {
        long long ts_ns;
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &now) < 0) {
            perror("clock_gettime");
            break;
        }
        ts_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        int adc = read_adc(spi_fd, gpio_req, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        if (log_data(log_fp, ts_ns, adc) < 0)
            break;

        next.tv_sec += (next.tv_nsec + SAMPLE_PERIOD_NS) / 1000000000ULL;
        next.tv_nsec = (next.tv_nsec + SAMPLE_PERIOD_NS) % 1000000000ULL;

        struct timespec rem;
        while (nanosleep(&next, &rem) < 0 && errno == EINTR && g_running)
            next = rem;
    }

    ret = 0;

cleanup:
    if (log_fp) {
        if (fclose(log_fp) != 0)
            perror("fclose");
    }
    if (spi_fd >= 0)
        close(spi_fd);
    if (gpio_req)
        gpiod_line_request_release(gpio_req);
    return ret;
}

