#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// ADXL335 Constants
#define ADXL335_SENSITIVITY 0.300 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5   // 1.5V

// MCP3008 Constants
#define MCP3008_CS 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Kalman Filter Parameters
#define Q 0.001
#define R 0.1

// Global Variables
static volatile int running = 1;
static int spi_handle = -1;

// Kalman Filter State
typedef struct {
    double x;
    double P;
} KalmanState;

KalmanState kalman_x = {0.0, 1.0};
KalmanState kalman_y = {0.0, 1.0};
KalmanState kalman_z = {0.0, 1.0};

// Function Prototypes
int read_mcp3008(int channel);
double kalman_filter(double measurement, double *state_x, double *state_P);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Kalman Filter Function
double kalman_filter(double measurement, double *state_x, double *state_P) {
    // Prediction Step
    *state_P = *state_P + Q;

    // Update Step
    double K = *state_P / (*state_P + R);
    *state_x = *state_x + K * (measurement - *state_x);
    *state_P = (1 - K) * *state_P;

    return *state_x;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize() != 0) {
        return 1;
    }

    printf("ADXL335 Kalman Filter Accelerometer Reading\n");
    printf("Press Ctrl+C to exit\n");

    while (running) {
        // Read ADC values
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert ADC values to voltage (3.3V reference, 10-bit ADC)
        double voltage_x = (double)adc_x / 1023.0 * 3.3;
        double voltage_y = (double)adc_y / 1023.0 * 3.3;
        double voltage_z = (double)adc_z / 1023.0 * 3.3;

        // Convert voltage to acceleration (g)
        double acceleration_x = (voltage_x - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
        double acceleration_y = (voltage_y - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
        double acceleration_z = (voltage_z - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;

        // Apply Kalman Filter
        double filtered_x = kalman_filter(acceleration_x, &kalman_x.x, &kalman_x.P);
        double filtered_y = kalman_filter(acceleration_y, &kalman_y.x, &kalman_y.P);
        double filtered_z = kalman_filter(acceleration_z, &kalman_z.x, &kalman_z.P);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        gpioDelay(100000); // 100ms delay (10 Hz)
    }

    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

