#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MAX_MAGNITUDE 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, int gpio_num, float *out_voltage) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_num, strerror(errno));
        return -1;
    }
    *out_voltage = (val == 1) ? VCC : 0.0;
    return 0;
}

static float calculate_magnetic_field(float voltage) {
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(FILE *fp, float m1, float m2, float m3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", m1, m2, m3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    line3 = gpiod_chip_get_line(chip, SENSOR3_GPIO);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "hall_sensor1") < 0 ||
        gpiod_line_request_input(line2, "hall_sensor2") < 0 ||
        gpiod_line_request_input(line3, "hall_sensor3") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        float v1 = 0.0, v2 = 0.0, v3 = 0.0;
        int err = 0;

        if (read_sensor(line1, SENSOR1_GPIO, &v1) < 0) err = 1;
        if (read_sensor(line2, SENSOR2_GPIO, &v2) < 0) err = 1;
        if (read_sensor(line3, SENSOR3_GPIO, &v3) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Sensor read error; skipping log entry.\n");
            struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
            nanosleep(&ts, NULL);
            continue;
        }

        float m1 = calculate_magnetic_field(v1);
        float m2 = calculate_magnetic_field(v2);
        float m3 = calculate_magnetic_field(v3);

        if (m1 < -MAX_MAGNITUDE || m1 > MAX_MAGNITUDE ||
            m2 < -MAX_MAGNITUDE || m2 > MAX_MAGNITUDE ||
            m3 < -MAX_MAGNITUDE || m3 > MAX_MAGNITUDE) {
            fprintf(stderr, "Warning: Magnetic field out of range: %.2f, %.2f, %.2f mT\n", m1, m2, m3);
        }

        if (log_data(log_fp, m1, m2, m3) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

