#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define LOG_FILE "watering.log"
#define CHECK_INTERVAL 60

static volatile int running = 1;
static int spi_handle = -1;

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1);
        log_event("Pump turned ON");
    } else {
        gpioWrite(PUMP_GPIO, 0);
        log_event("Pump turned OFF");
    }
}

void cleanup() {
    log_event("Cleaning up and exiting");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("Failed to open SPI channel");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_event("Failed to read moisture sensor, retrying in 60s");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d (raw), %d%%", moisture, moisture * 100 / 1023);
            log_event(msg);
            control_pump(moisture * 100 / 1023);
        }
        sleep(CHECK_INTERVAL);
    }

    cleanup();
    return 0;
}

