#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_LED 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static int reconnect_delay = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
        reconnect_delay = 1;
    } else {
        log_error("Connection failed, retrying...");
        sleep(reconnect_delay);
        if (reconnect_delay < MAX_RECONNECT_DELAY) reconnect_delay *= 2;
        mosquitto_reconnect(m);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnection, retrying...");
        sleep(reconnect_delay);
        if (reconnect_delay < MAX_RECONNECT_DELAY) reconnect_delay *= 2;
        mosquitto_reconnect(m);
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (!payload) {
            log_error("Memory allocation failed");
            return;
        }
        memcpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';

        cJSON *json = cJSON_Parse(payload);
        if (!json) {
            log_error("Invalid JSON payload");
            free(payload);
            return;
        }

        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (!cJSON_IsBool(led_state)) {
            log_error("Missing or invalid 'led_state' key");
            cJSON_Delete(json);
            free(payload);
            return;
        }

        int state = cJSON_IsTrue(led_state) ? 1 : 0;
        if (gpioWrite(GPIO_LED, state) != 0) {
            log_error("Failed to write to GPIO");
        } else {
            printf("LED set to %s\n", state ? "ON" : "OFF");
        }

        cJSON_Delete(json);
        free(payload);
    }
}

static int setup_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        return -1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    if (setup_mqtt() != 0) {
        gpioTerminate();
        return 1;
    }

    int rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to start mosquitto loop: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        sleep(1);
    }

    cleanup();
    return 0;
}

