#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER        "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_vibration_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Vibration detected on GPIO%d\n", timestamp, GPIO_LINE) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP ")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE);
    fflush(stdout);

    int ret = EXIT_SUCCESS;

    while (program_running) {
        struct timespec ts = { 1, 0 }; /* 1-second timeout */
        int rv = gpiod_line_event_wait(line, &ts);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait()");
            ret = EXIT_FAILURE;
            break;
        }

        if (rv == 0) {
            continue; /* timeout, no event */
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read()");
            ret = EXIT_FAILURE;
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (log_vibration_event() == 0) {
                printf("Vibration detected. Initiating shutdown...\n");
                fflush(stdout);
                int rc = system("sudo shutdown -h now");
                if (rc == -1) {
                    perror("system()");
                } else if (rc != 0) {
                    fprintf(stderr, "shutdown command returned %d\n", rc);
                }
            } else {
                fprintf(stderr, "Failed to log vibration event.\n");
            }
            break;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Vibration monitoring stopped.\n");
    return ret;
}

