#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    return voltage * 100.0f;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

static void write_buffer_to_file(const float *buffer, int size) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    if (fwrite(buffer, sizeof(float), size, fp) != (size_t)size) {
        perror("Error writing to log file");
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float temperature = convert_to_temperature(adc_value);
            log_temperature(temperature);

            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (buffer_index == 0) {
                write_buffer_to_file(temperature_buffer, BUFFER_SIZE);
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

