#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* MCP3008 SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   500000  /* 500 kHz */
#define SPI_FLAGS   0       /* mode 0, active-low CE */

/* MCP4725 I2C configuration */
#define I2C_BUS     1
#define DAC_ADDR    0x62
#define DAC_VREF    3.3f

/* TMP36 conversion: V = (T + 100) * 10 mV */
#define TMP36_OFFSET 100.0f
#define TMP36_SCALE  0.01f

/* Sampling */
#define SAMPLE_INTERVAL_US 500000  /* 0.5 s */
#define MAX_RETRIES        3

/* Globals for cleanup */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1 on error. */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes
     * tx[0] = 0x01 (start)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return adc;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);  /* 10 ms backoff */
    }
    return -1;
}

/* Convert ADC value (0-1023) to temperature in Celsius. */
static float adc_to_celsius(int adc) {
    float voltage = (float)adc * (DAC_VREF / 1024.0f);
    return (voltage / TMP36_SCALE) - TMP36_OFFSET;
}

/* Set MCP4725 DAC output voltage (0V to Vref). Returns 0 on success, -1 on error. */
static int set_dac_voltage(float voltage) {
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > DAC_VREF) voltage = DAC_VREF;

    /* MCP4725: 12-bit DAC, 16-bit write command + data
     * Command bits: [15:12] = 0001 (write DAC), [11:10] = 00 (normal power),
     * [9:4] = don't care, [3:0] = 0000 (no EEPROM)
     * Data bits: [11:0] = 12-bit value (0-4095)
     */
    uint16_t value = (uint16_t)((voltage / DAC_VREF) * 4095.0f);
    uint16_t command = 0x4000 | (value & 0x0FFF);  /* write DAC, normal power */

    char tx[3];
    tx[0] = (command >> 8) & 0xFF;
    tx[1] = command & 0xFF;
    tx[2] = 0x00;  /* stop bit / padding */

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, tx, 3);
        if (ret == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

/* Log data to file and stdout. */
static void log_data(int adc, float temp, float dac_v) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
            ts, adc, temp, dac_v);
    fflush(log_file);

    printf("%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n", ts, adc, temp, dac_v);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, DAC_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temp = adc_to_celsius(adc);
        float dac_v = (temp / 50.0f) * DAC_VREF;
        if (dac_v < 0.0f) dac_v = 0.0f;
        if (dac_v > DAC_VREF) dac_v = DAC_VREF;

        if (set_dac_voltage(dac_v) != 0) {
            fprintf(stderr, "DAC write failed; continuing\n");
        }

        log_data(adc, temp, dac_v);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

