    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, tx, 3);
        if (ret == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

/* Log data to file and stdout. */
static void log_data(int adc, float temp, float dac_v) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
            ts, adc, temp, dac_v);
    fflush(log_file);

    printf("%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n", ts, adc, temp, dac_v);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, DAC_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temp = adc_to_celsius(adc);
        float dac_v = (temp / 50.0f) * DAC_VREF;
        if (dac_v < 0.0f) dac_v = 0.0f;
        if (dac_v > DAC_VREF) dac_v = DAC_VREF;

        if (set_dac_voltage(dac_v) != 0) {
            fprintf(stderr, "DAC write failed; continuing\n");
        }

        log_data(adc, temp, dac_v);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

