#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60000000  /* microseconds */

static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0f;
    }
    return (1.0f - (float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(int sensor_number, float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

