    if (fprintf(log_file, "%s, Sensor %d, Moisture: %.2f%%\n", timestamp, sensor_number, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
