    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                continue;
            }

            float moisture_level = calculate_moisture(adc_value);
            if (moisture_level < 0.0f) {
                fprintf(stderr, "Error: Failed to calculate moisture for sensor %d\n", i);
                continue;
            }

            log_data(i, moisture_level);
        }

        if (program_running) {
            gpioDelay(SLEEP_INTERVAL);
        }
    }

    printf("\nCleaning up and exiting...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

