#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_DELAY_MS 1000
#define INTER_RELAY_DELAY_MS 1000

/* BCM GPIO pin numbers for the four relay control lines */
static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

/* Global pointers for cleanup in the signal handler */
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL, NULL, NULL, NULL};
static volatile sig_atomic_t keep_running = 1;

/* Signal handler: deactivate all relays and release resources */
static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

/* Deactivate all relays and release GPIO lines */
static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    int ret;

    /* Set up signal handling for clean exit */
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Request each relay line as an output, initially LOW */
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_output(relay_lines[i], "relay-sequence", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output on GPIO %u: %s\n",
                    relay_pins[i], strerror(-ret));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    /* Main sequencing loop */
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            /* Activate relay */
            ret = gpiod_line_set_value(relay_lines[i], 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO %u HIGH: %s\n",
                        relay_pins[i], strerror(-ret));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d (GPIO %u) ON\n", i + 1, relay_pins[i]);
            usleep(RELAY_DELAY_MS * 1000);

            /* Deactivate relay */
            ret = gpiod_line_set_value(relay_lines[i], 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO %u LOW: %s\n",
                        relay_pins[i], strerror(-ret));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d (GPIO %u) OFF\n", i + 1, relay_pins[i]);
            usleep(INTER_RELAY_DELAY_MS * 1000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

