#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* ---- SPI parameters ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0         /* mode 0, active-low CE */

/* ---- Rain sensor threshold ---- */
#define RAIN_THRESHOLD 5

/* ---- Motor control ---- */
#define MOTOR_SPEED 150
#define MOTOR_DURATION_SEC 3

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ---- Function prototypes ---- */
static int  read_mcp3008(int channel);
static int  adc_to_rain_level(int adc_value);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void log_rain_data(int rain_level);
static void signal_handler(int signal);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008 (0-7) via SPI.        */
/* Returns 0-1023 on success, -1 on SPI transfer failure.             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (all 8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10).                   */
/* Sensor outputs higher voltage when dry, so ADC 1023 -> rain 0,     */
/* ADC 0 -> rain 10.                                                  */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* Invert: higher ADC -> lower rain level */
    return (int)((1023 - adc_value) / 102.3f);
}

/* ------------------------------------------------------------------ */
/* Drive motor forward (close window).                                */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
}

/* ------------------------------------------------------------------ */
/* Drive motor backward (open window).                                */
/* ------------------------------------------------------------------ */
static void motor_backward(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
}

/* ------------------------------------------------------------------ */
/* Stop motor.                                                        */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Log rain level with timestamp to rain_log.txt.                     */
/* ------------------------------------------------------------------ */
static void log_rain_data(int rain_level)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown.                              */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: stop motor, close SPI, close log, terminate pigpio.       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins ---- */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for simple duty-cycle scaling */
    if (gpioSetPWMrange(MOTOR_ENA, 255) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup */
    motor_stop();

    /* ---- Open SPI bus ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open rain_log.txt\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_open = 1;  /* 1 = open, 0 = closed */

    /* ---- Main loop ---- */
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read rain sensor\n");
            sleep(1);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);
        log_rain_data(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            if (window_open) {
                printf("Rain detected (level %d) - closing window.\n", rain_level);
                motor_forward();
                sleep(MOTOR_DURATION_SEC);
                motor_stop();
                window_open = 0;
            }
        } else {
            if (!window_open) {
                printf("Rain stopped (level %d) - opening window.\n", rain_level);
                motor_backward();
                sleep(MOTOR_DURATION_SEC);
                motor_stop();
                window_open = 1;
            }
        }

        sleep(1);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

