#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define LED_ON_TIME_MS 500
#define DEBOUNCE_MS 50
#define SAMPLE_DELAY_US 1000
#define ADC_MAX 1023
#define VREF 3.3f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    int high_count = 0;
    for (int i = 0; i < 10; i++) {
        if (gpioRead(pin) == 1) {
            high_count++;
        }
        gpioDelay(SAMPLE_DELAY_US);
    }
    return high_count;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_ADC_PIN %d as input\n", MIC_ADC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int adc_value = read_adc(MIC_ADC_PIN);

        if (adc_value > THRESHOLD) {
            float voltage = (adc_value / (float)ADC_MAX) * VREF;
            printf("ADC: %d, Voltage: %.2f V\n", adc_value, voltage);
            fflush(stdout);

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on LED\n");
            }
            log_detection();

            gpioDelay(LED_ON_TIME_MS * 1000);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off LED\n");
            }

            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

