    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening direction file");
        return -1;
    }
    if (fprintf(fp, "%s", direction) < 0) {
        perror("Error writing to direction file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

