#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 21
#define THRESHOLD_MT 10.0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 1.65
#define LOG_FILE "magnetic_log.txt"
#define READ_DELAY_US 100000

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double voltage_to_magnetic_field(int adc_value) {
    double voltage = (double)adc_value * VCC / 1023.0;
    double quiescent = VCC / 2.0;
    return (voltage - quiescent) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

static void log_data(double field_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Field: %.2f mT\n", ts, field_mt);
    }
    fclose(fp);
}

static void control_led(double field_mt) {
    gpioWrite(LED_GPIO, field_mt > THRESHOLD_MT ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Magnetic field monitor started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error\n");
            break;
        }
        double field = voltage_to_magnetic_field(adc);
        log_data(field);
        control_led(field);
        gpioDelay(READ_DELAY_US);
    }
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

