    }

    if (gpiod_line_request_output(line, "mlx91209-spi", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (spi_init(&spi_fd) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

