#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define VREF        5.0        /* MCP3008 VREF tied to Pi 5V */
#define VDD_MLX     5.0        /* MLX91211 VDD = 5V */
#define VZERO_MLX   2.5        /* MLX91211 output at 0A = VDD/2 = 2.5V */
#define FULLSCALE_A 50.0       /* MLX91211 full-scale current = +50A */
#define LOG_FILE    "current_log.txt"
#define SAMPLE_US  100000      /* 100 ms between samples */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from MCP3008 channel (single-ended, 10-bit)        */
/* Returns 0 on success (stores 0-1023 in *value), -1 on SPI error     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel, int *value)
{
    unsigned char tx[3];
    unsigned char rx[3];

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + ch, then don't-care */
    tx[0] = 0x01;
    tx[1] = (unsigned char)(0x80 | (channel << 4));
    tx[2] = 0x00;

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC code to current (A) via MLX91211 ratiometric model  */
/* Returns 0 on success (stores current in *current), -1 on out-of-range */
/* ------------------------------------------------------------------ */
static int adc_to_current(int adc_value, double *current)
{
    double voltage = ((double)adc_value / 1023.0) * VREF;

    /* Sanity-check: MLX91211 output spans 2.5V..5.0V; reject out-of-range */
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "ADC voltage %.3f V out of valid range [0, %.1f]\n",
                voltage, VREF);
        return -1;
    }

    /* Ratiometric: 2.5V -> 0A, 5.0V -> +50A */
    *current = (voltage - VZERO_MLX) * (FULLSCALE_A / (VDD_MLX - VZERO_MLX));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append timestamped current reading to log file                     */
/* ------------------------------------------------------------------ */
static int log_current(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91211 current logging started. Press Ctrl+C to stop.\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 ch%d, logging to '%s'\n",
           SPI_SPEED, ADC_CHANNEL, LOG_FILE);

    /* Main sampling loop */
    while (program_running) {
        int adc_value = 0;
        double current = 0.0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            /* SPI error — skip this sample, keep running */
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (adc_to_current(adc_value, &current) != 0) {
            /* Out-of-range voltage — skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_current(current) != 0) {
            /* Log write failed — keep running but warn */
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

