        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91211 current logging started. Press Ctrl+C to stop.\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 ch%d, logging to '%s'\n",
           SPI_SPEED, ADC_CHANNEL, LOG_FILE);

    /* Main sampling loop */
    while (program_running) {
        int adc_value = 0;
        double current = 0.0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            /* SPI error — skip this sample, keep running */
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (adc_to_current(adc_value, &current) != 0) {
            /* Out-of-range voltage — skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_current(current) != 0) {
            /* Log write failed — keep running but warn */
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

