#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define CHIP_NUMBER 0
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int debounce_read(struct gpiod_line *line) {
    int ones = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) ones++;
        usleep(DEBOUNCE_DELAY_US);
    }
    return (ones > DEBOUNCE_SAMPLES / 2) ? 1 : 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(CHIP_NUMBER);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %d: %s\n", CHIP_NUMBER, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (program_running) {
        int s1 = debounce_read(line1);
        int s2 = debounce_read(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error during sensor read, exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1 (GPIO%d): %d, Sensor 2 (GPIO%d): %d\n",
               SENSOR1_PIN, s1, SENSOR2_PIN, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

