static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create directory '%s': %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        char width_str[16], height_str[16];
        snprintf(width_str, sizeof(width_str), "%d", IMAGE_WIDTH);
        snprintf(height_str, sizeof(height_str), "%d", IMAGE_HEIGHT);
        char *argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--width", width_str,
            "--height", height_str,
            "--nopreview",
            NULL
        };
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) return 0;
    syslog(LOG_ERR, "libcamera-still exited with status %d", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera application");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        syslog(LOG_ERR, "Cannot proceed without a valid capture directory");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    syslog(LOG_INFO, "Monitoring PIR sensor on GPIO%d", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_GPIO);
            break;
        }
        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead failed during debounce on GPIO%d", PIR_GPIO);
                break;
            }
            if (confirmed == current_state) {
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

                    time_t rawtime = time(NULL);
                    if (rawtime == (time_t)-1) {
                        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
                    } else {
                        struct tm timeinfo;
                        if (localtime_r(&rawtime, &timeinfo) == NULL) {
                            syslog(LOG_ERR, "localtime_r() failed");
                        } else {
                            char timestamp[32];
                            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d_%H-%M-%S", &timeinfo) == 0) {
                                syslog(LOG_ERR, "strftime() failed");
                            } else {
                                char filename[MAX_PATH_LEN];
                                char filepath[MAX_PATH_LEN];
                                snprintf(filename, sizeof(filename), "motion_%s.jpg", timestamp);
                                snprintf(filepath, sizeof(filepath), "%s/%s", CAPTURE_DIR, filename);

                                if (capture_image(filepath) == 0) {
                                    syslog(LOG_INFO, "Image captured: %s", filepath);
                                } else {
                                    syslog(LOG_ERR, "Failed to capture image");
                                }
                            }
                        }
                    }
                }
                last_state = current_state;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return 0;
}

