#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int signum) {
    (void)signum;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(const char *device_name, int *fd, struct v4l2_format *format,
                       struct v4l2_requestbuffers *reqbuf, struct v4l2_buffer *buf,
                       void **buffers, size_t *buffer_sizes) {
    *fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    memset(format, 0, sizeof(*format));
    format->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format->fmt.pix.width = IMAGE_WIDTH;
    format->fmt.pix.height = IMAGE_HEIGHT;
    format->fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    format->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, format) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(reqbuf, 0, sizeof(*reqbuf));
    reqbuf->count = NUM_BUFFERS;
    reqbuf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, reqbuf) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (reqbuf->count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    buffers[0] = NULL;
    buffer_sizes[0] = 0;

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    buffer_sizes[0] = buf->length;
    buffers[0] = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);
    if (buffers[0] == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QBUF, buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffers[0], buf->length);
        close(*fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffers[0], buf->length);
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select(): %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) return -1;
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.bytesused > buffer_size) {
        fprintf(stderr, "Buffer overflow: %u > %zu\n", buf.bytesused, buffer_size);
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        }
        return -1;
    }

    memcpy(buffer, (unsigned char *)buffer + buf.m.offset, buf.bytesused);

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, const unsigned char *image_data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    size_t written = fwrite(image_data, 1, (size_t)width * height, fp);
    if (written != (size_t)width * height) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    const char *device_name = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    int fd = -1;
    struct v4l2_format format;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    size_t buffer_sizes[NUM_BUFFERS];
    int image_count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(device_name, &fd, &format, &reqbuf, &buf, buffers, buffer_sizes) < 0) {
        return 1;
    }

    printf("Camera initialized. Capturing frames...\n");

    while (!stop_flag) {
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", image_count + 1);

        if (capture_frame(fd, buffers[0], buffer_sizes[0]) < 0) {
            if (stop_flag) break;
            continue;
        }

        if (save_image(filename, (const unsigned char *)buffers[0], IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            fprintf(stderr, "Error saving image %s\n", filename);
        } else {
            printf("Saved %s\n", filename);
            image_count++;
        }
    }

    printf("\nShutting down...\n");

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    if (buffers[0] != NULL && buffers[0] != MAP_FAILED) {
        if (munmap(buffers[0], buffer_sizes[0]) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
    }

    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        }
    }

    printf("Total images captured: %d\n", image_count);
    return 0;
}

