#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define UDP_MTU 65000
#define HEADER_SIZE 12

typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} udp_header_t;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_v4l2(int *fd, unsigned int *width, unsigned int *height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    int i;

    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open video device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto fail;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = *width;
    fmt.fmt.pix.height = *height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto fail;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    return 0;

fail:
    close(*fd);
    *fd = -1;
    return -1;
}

static int init_buffers(int fd, struct buffer *buffers) {
    struct v4l2_buffer buf;
    unsigned int i;

    for (i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd) {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned int i;

    for (i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct buffer *buffers, unsigned int *frame_index) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    (*frame_index)++;
    return (int)buf.index;
}

static int send_udp_fragment(int sockfd, const unsigned char *data, size_t size, const struct sockaddr_in *server_addr, unsigned int frame_index, unsigned int fragment_index, unsigned int total_fragments) {
    unsigned char packet[UDP_MTU];
    udp_header_t header;

    if (size + HEADER_SIZE > UDP_MTU) {
        fprintf(stderr, "Fragment too large\n");
        return -1;
    }

    header.frame_index = frame_index;
    header.fragment_index = fragment_index;
    header.total_fragments = total_fragments;
    header.payload_size = (unsigned int)size;

    memcpy(packet, &header, HEADER_SIZE);
    memcpy(packet + HEADER_SIZE, data, size);

    if (sendto(sockfd, packet, size + HEADER_SIZE, 0, (const struct sockaddr *)server_addr, sizeof(*server_addr)) < 0) {
        perror("sendto");
        return -1;
    }
    return 0;
}

static int stream_frame(int sockfd, const unsigned char *data, size_t size, const struct sockaddr_in *server_addr, unsigned int frame_index) {
    unsigned int num_fragments = (size + UDP_MTU - HEADER_SIZE - 1) / (UDP_MTU - HEADER_SIZE);
    unsigned int i;

    for (i = 0; i < num_fragments; i++) {
        size_t fragment_size = (i == num_fragments - 1) ? (size - (size_t)i * (UDP_MTU - HEADER_SIZE)) : (UDP_MTU - HEADER_SIZE);

        if (send_udp_fragment(sockfd, data + i * (UDP_MTU - HEADER_SIZE), fragment_size, server_addr, frame_index, i + 1, num_fragments) < 0) {
            return -1;
        }
    }
    return 0;
}

static void cleanup(int fd, struct buffer *buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    unsigned int i;

    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }

    if (buffers) {
        for (i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int fd = -1;
    int sockfd = -1;
    struct buffer buffers[NUM_BUFFERS];
    struct sockaddr_in server_addr;
    unsigned int frame_index = 0;
    int i;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    memset(buffers, 0, sizeof(buffers));

    for (i = 0; i < NUM_BUFFERS; i++) {
        buffers[i].start = MAP_FAILED;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_v4l2(&fd, &IMAGE_WIDTH, &IMAGE_HEIGHT) < 0) {
        fprintf(stderr, "Failed to initialize V4L2\n");
        return 1;
    }

    if (init_buffers(fd, buffers) < 0) {
        fprintf(stderr, "Failed to initialize buffers\n");
        cleanup(fd, buffers);
        return 1;
    }

    if (start_streaming(fd) < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        cleanup(fd, buffers);
        return 1;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        cleanup(fd, buffers);
        return 1;
