#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS  4
#define OUTPUT_FILE  "image.jpg"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        return -1;
    }
    return 0;
}

static int init_mmap(int fd, struct v4l2_buffer *buffers, int *n_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }
    *n_buffers = req.count;

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buffers[i], 0, sizeof(buffers[i]));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) == -1) {
            perror("VIDIOC_QUERYBUF");
            free(buffers);
            return -1;
        }
        buffers[i].start = mmap(NULL, buffers[i].length,
                                PROT_READ | PROT_WRITE,
                                MAP_SHARED, fd, buffers[i].m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            buffers[i].start = NULL;
            free(buffers);
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd, struct v4l2_buffer *buffers, int n_buffers) {
    for (int i = 0; i < n_buffers; i++) {
        memset(&buffers[i], 0, sizeof(buffers[i]));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buffers, int n_buffers,
                         unsigned char **out_data, size_t *out_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    if (buf.index >= (unsigned int)n_buffers) {
        fprintf(stderr, "Invalid buffer index %u\n", buf.index);
        return -1;
    }
    if (buf.bytesused == 0) {
        fprintf(stderr, "Frame has zero bytes\n");
        return -1;
    }

    *out_data = malloc(buf.bytesused);
    if (!*out_data) {
        perror("malloc");
        return -1;
    }
    *out_size = buf.bytesused;
    memcpy(*out_data, buffers[buf.index].start, buf.bytesused);

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        free(*out_data);
        *out_data = NULL;
        *out_size = 0;
        return -1;
    }
    return 0;
}

static int save_jpeg(const char *filename, const unsigned char *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        fprintf(stderr, "Short write: %zu of %zu bytes\n", written, size);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void cleanup(int fd, struct v4l2_buffer *buffers, int n_buffers) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffers) {
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    perror("munmap");
                }
            }
        }
        free(buffers);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    struct v4l2_buffer *buffers = NULL;
    int n_buffers = 0;
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    int ret = 1;

    install_signal_handlers();

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    if (init_device(fd) == -1) {
        goto out;
    }

    if (init_mmap(fd, buffers, &n_buffers) == -1) {
        goto out;
    }

    if (start_streaming(fd, buffers, n_buffers) == -1) {
        goto out;
    }

    if (capture_frame(fd, buffers, n_buffers, &image_data, &image_size) == -1) {
        goto out;
    }

    if (save_jpeg(OUTPUT_FILE, image_data, image_size) == -1) {
        goto out;
    }

    printf("Image saved as %s (%zu bytes)\n", OUTPUT_FILE, image_size);
    ret = 0;

out:
    if (image_data) {
        free(image_data);
    }
    cleanup(fd, buffers, n_buffers);
    return ret;
}

