#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

#define SERVO_MIN_PULSE  50   /* 1 ms   -> 5% of 20 ms period */
#define SERVO_MAX_PULSE  100  /* 2 ms   -> 10% of 20 ms period */
#define SERVO_MID_PULSE  75   /* 1.5 ms -> 7.5% of 20 ms period */
#define SERVO_RANGE      100  /* 0-100 duty values */
#define SERVO_MIN_DUTY   50
#define SERVO_MAX_DUTY   100
#define SERVO_MID_DUTY   75

#define SERVO_MIN_POS    25
#define SERVO_MAX_POS    125
#define SERVO_STEP       5
#define POLL_DELAY_MS    50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_range(int x, int in_min, int in_max, int out_min, int out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static int set_servo(struct gpiod_line *line, int position) {
    if (position < SERVO_MIN_POS) position = SERVO_MIN_POS;
    if (position > SERVO_MAX_POS) position = SERVO_MAX_POS;

    int duty = map_range(position, SERVO_MIN_POS, SERVO_MAX_POS,
                         SERVO_MIN_DUTY, SERVO_MAX_DUTY);

    /* Software PWM: drive line high for duty/1000 of the period, then low */
    int high_us  = (duty * 20000) / 1000;
    int low_us   = 20000 - high_us;

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(high)");
        return -1;
    }
    usleep(high_us);

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(low)");
        return -1;
    }
    usleep(low_us);

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *btn_lines[4] = {NULL, NULL, NULL, NULL};
    int pan_pos = SERVO_MID_PULSE;
    int tilt_pos = SERVO_MID_PULSE;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    btn_lines[0] = gpiod_chip_get_line(chip, TILT_UP_PIN);
    btn_lines[1] = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    btn_lines[2] = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    btn_lines[3] = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !btn_lines[0] || !btn_lines[1] ||
        !btn_lines[2] || !btn_lines[3]) {
        fprintf(stderr, "Failed to get one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0) {
        perror("gpiod_line_request_output(pan)");
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        perror("gpiod_line_request_output(tilt)");
        goto cleanup;
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input_flags(btn_lines[i], "button",
                                           GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
            fprintf(stderr, "Failed to request button line %d\n", i);
            goto cleanup;
        }
    }

    printf("Pan-Tilt Servo Control (libgpiod)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int tilt_up    = gpiod_line_get_value(btn_lines[0]);
        int tilt_down  = gpiod_line_get_value(btn_lines[1]);
        int pan_left   = gpiod_line_get_value(btn_lines[2]);
        int pan_right  = gpiod_line_get_value(btn_lines[3]);

        if (tilt_up == 0)   tilt_pos += SERVO_STEP;
        if (tilt_down == 0) tilt_pos -= SERVO_STEP;
        if (pan_left == 0)  pan_pos -= SERVO_STEP;
        if (pan_right == 0) pan_pos += SERVO_STEP;

        if (set_servo(pan_line, pan_pos) < 0)  break;
        if (set_servo(tilt_line, tilt_pos) < 0) break;

        usleep(POLL_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line)  gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    for (int i = 0; i < 4; i++) {
        if (btn_lines[i]) gpiod_line_release(btn_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

