#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt, struct v4l2_requestbuffers *req,
                       struct v4l2_buffer *buf, void **buffers, int *n_buffers) {
    *fd = open(CAMERA_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", CAMERA_DEVICE, strerror(errno));
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = IMAGE_WIDTH;
    fmt->fmt.pix.height = IMAGE_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(req, 0, sizeof(*req));
    req->count = 4;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    *n_buffers = req->count;
    *buffers = calloc(*n_buffers, sizeof(void *));
    if (!*buffers) {
        fprintf(stderr, "Out of memory\n");
        close(*fd);
        return -1;
    }

    for (int i = 0; i < *n_buffers; i++) {
        memset(buf, 0, sizeof(*buf));
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;
        buf->index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            for (int j = 0; j < i; j++) munmap(buffers[j], buf->length);
            free(*buffers);
            close(*fd);
            return -1;
        }

        buffers[i] = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);
        if (buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            for (int j = 0; j < i; j++) munmap(buffers[j], buf->length);
            free(*buffers);
            close(*fd);
            return -1;
        }
    }

    for (int i = 0; i < *n_buffers; i++) {
        memset(buf, 0, sizeof(*buf));
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;
        buf->index = i;
        if (xioctl(*fd, VIDIOC_QBUF, buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            for (int j = 0; j <= i; j++) munmap(buffers[j], buf->length);
            free(*buffers);
            close(*fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        for (int j = 0; j < *n_buffers; j++) munmap(buffers[j], buf->length);
        free(*buffers);
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, void **buffers, int n_buffers, unsigned char **frame_data, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_data = buffers[buf.index];
    *frame_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j += 2) {
            int y1 = yuyv[(i * width + j) * 2];
            int u = yuyv[(i * width + j) * 2 + 1];
            int y2 = yuyv[(i * width + j + 1) * 2];
            int v = yuyv[(i * width + j + 1) * 2 + 1];

            int r1 = y1 + (1402 * (v - 128)) / 1000;
            int g1 = y1 - (344 * (u - 128) + 714 * (v - 128)) / 1000;
            int b1 = y1 + (1772 * (u - 128)) / 1000;

            int r2 = y2 + (1402 * (v - 128)) / 1000;
            int g2 = y2 - (344 * (u - 128) + 714 * (v - 128)) / 1000;
            int b2 = y2 + (1772 * (u - 128)) / 1000;

            rgb[(i * width + j) * 3] = (r1 < 0) ? 0 : (r1 > 255) ? 255 : r1;
            rgb[(i * width + j) * 3 + 1] = (g1 < 0) ? 0 : (g1 > 255) ? 255 : g1;
            rgb[(i * width + j) * 3 + 2] = (b1 < 0) ? 0 : (b1 > 255) ? 255 : b1;

            rgb[(i * width + j + 1) * 3] = (r2 < 0) ? 0 : (r2 > 255) ? 255 : r2;
            rgb[(i * width + j + 1) * 3 + 1] = (g2 < 0) ? 0 : (g2 > 255) ? 255 : g2;
            rgb[(i * width + j + 1) * 3 + 2] = (b2 < 0) ? 0 : (b2 > 255) ? 255 : b2;
        }
    }
}

static void box_blur(const unsigned char *src, unsigned char *dst, int width, int height, int radius) {
    int kernel_size = 2 * radius + 1;
    int kernel_area = kernel_size * kernel_size;

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            for (int ki = -radius; ki <= radius; ki++) {
                for (int kj = -radius; kj <= radius; kj++) {
                    int x = j + kj;
                    int y = i + ki;
                    if (x < 0) x = 0;
                    if (x >= width) x = width - 1;
                    if (y < 0) y = 0;
                    if (y >= height) y = height - 1;
                    int idx = (y * width + x) * 3;
                    r_sum += src[idx];
                    g_sum += src[idx + 1];
                    b_sum += src[idx + 2];
                }
            }
            int idx = (i * width + j) * 3;
            dst[idx] = r_sum / kernel_area;
            dst[idx + 1] = g_sum / kernel_area;
            dst[idx + 2] = b_sum / kernel_area;
        }
    }
}

static int save_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
