#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_capability(const struct v4l2_capability *cap) {
    printf("Camera: %s\n", cap->card);
    printf("Driver: %s\n", cap->driver);
    printf("Bus info: %s\n", cap->bus_info);
    printf("Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
}

static void print_resolution(const struct v4l2_frmsizeenum *fs) {
    switch (fs->type) {
        case V4L2_FRMSIZE_TYPE_DISCRETE:
            printf("  %ux%u\n", fs->discrete.width, fs->discrete.height);
            break;
        case V4L2_FRMSIZE_TYPE_STEPWISE:
            printf("  %ux%u - %ux%u (step %ux%u)\n",
                   fs->stepwise.min_width, fs->stepwise.min_height,
                   fs->stepwise.max_width, fs->stepwise.max_height,
                   fs->stepwise.step_width, fs->stepwise.step_height);
            break;
        case V4L2_FRMSIZE_TYPE_CONTINUOUS:
            printf("  %ux%u - %ux%u (continuous)\n",
                   fs->stepwise.min_width, fs->stepwise.min_height,
                   fs->stepwise.max_width, fs->stepwise.max_height);
            break;
        default:
            printf("  (unknown frame size type %u)\n", fs->type);
            break;
    }
}

static void print_frame_interval(const struct v4l2_frmivalenum *fi) {
    switch (fi->type) {
        case V4L2_FRMIVAL_TYPE_DISCRETE:
            printf("    %u/%u fps\n", fi->discrete.numerator, fi->discrete.denominator);
            break;
        case V4L2_FRMIVAL_TYPE_STEPWISE:
            printf("    %u/%u - %u/%u fps (step %u/%u)\n",
                   fi->stepwise.min.numerator, fi->stepwise.min.denominator,
                   fi->stepwise.max.numerator, fi->stepwise.max.denominator,
                   fi->stepwise.step.numerator, fi->stepwise.step.denominator);
            break;
        case V4L2_FRMIVAL_TYPE_CONTINUOUS:
            printf("    %u/%u - %u/%u fps (continuous)\n",
                   fi->stepwise.min.numerator, fi->stepwise.min.denominator,
                   fi->stepwise.max.numerator, fi->stepwise.max.denominator);
            break;
        default:
            printf("    (unknown frame interval type %u)\n", fi->type);
            break;
    }
}

static int query_frame_sizes(int fd, unsigned int pixfmt) {
    struct v4l2_frmsizeenum fs;
    memset(&fs, 0, sizeof(fs));
    fs.pixel_format = pixfmt;

    printf("Supported resolutions:\n");
    for (fs.index = 0; ; fs.index++) {
        if (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs) == -1) {
            if (errno == EINVAL) {
                printf("  (no frame sizes reported for this pixel format)\n");
            } else {
                fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            }
            return -1;
        }
        print_resolution(&fs);
    }
    return 0;
}

static int query_frame_intervals(int fd, unsigned int pixfmt, unsigned int width, unsigned int height) {
    struct v4l2_frmivalenum fi;
    memset(&fi, 0, sizeof(fi));
    fi.pixel_format = pixfmt;
    fi.width = width;
    fi.height = height;

    printf("  Supported frame rates:\n");
    for (fi.index = 0; ; fi.index++) {
        if (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi) == -1) {
            if (errno == EINVAL) {
                printf("    (no frame intervals reported for %ux%u)\n", width, height);
            } else {
                fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
            }
            return -1;
        }
        print_frame_interval(&fi);
    }
    return 0;
}

static int check_autofocus(int fd) {
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &qc) == 0) {
        printf("Autofocus: supported (id=%u, type=%u)\n", qc.id, qc.type);
        return 0;
    }
    if (errno == EINVAL) {
        printf("Autofocus: not supported\n");
        return 0;
    }
    fprintf(stderr, "VIDIOC_QUERYCTRL for autofocus failed: %s\n", strerror(errno));
    return -1;
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    print_capability(&cap);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_READWRITE)) {
        fprintf(stderr, "Device does not support read/write I/O\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (check_autofocus(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Enumerate YUYV (4:2:2 packed) resolutions and intervals */
    unsigned int yuyv = V4L2_PIX_FMT_YUYV;
    if (query_frame_sizes(fd, yuyv) == -1) {
