#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000
#define SERVO_MAX_PULSE  2000
#define SERVO_CENTER     1500
#define STEP_SIZE        10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int clamp_pulse(int pulse) {
    if (pulse < SERVO_MIN_PULSE) return SERVO_MIN_PULSE;
    if (pulse > SERVO_MAX_PULSE) return SERVO_MAX_PULSE;
    return pulse;
}

static void set_servo(int pin, int pulse) {
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Warning: gpioServo(%d, %d) failed\n", pin, pulse);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    int pan_pulse  = SERVO_CENTER;
    int tilt_pulse = SERVO_CENTER;

    set_servo(PAN_SERVO_PIN, pan_pulse);
    set_servo(TILT_SERVO_PIN, tilt_pulse);

    printf("Pan-tilt control started.\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  UP   button: GPIO%d\n", UP_BUTTON_PIN);
    printf("  DOWN button: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  LEFT button: GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT button: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("  Center position: %d us\n", SERVO_CENTER);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int up    = gpioRead(UP_BUTTON_PIN);
        int down  = gpioRead(DOWN_BUTTON_PIN);
        int left  = gpioRead(LEFT_BUTTON_PIN);
        int right = gpioRead(RIGHT_BUTTON_PIN);

        if (up == 0) {
            tilt_pulse = clamp_pulse(tilt_pulse + STEP_SIZE);
            set_servo(TILT_SERVO_PIN, tilt_pulse);
        }
        if (down == 0) {
            tilt_pulse = clamp_pulse(tilt_pulse - STEP_SIZE);
            set_servo(TILT_SERVO_PIN, tilt_pulse);
        }
        if (left == 0) {
            pan_pulse = clamp_pulse(pan_pulse - STEP_SIZE);
            set_servo(PAN_SERVO_PIN, pan_pulse);
        }
        if (right == 0) {
            pan_pulse = clamp_pulse(pan_pulse + STEP_SIZE);
            set_servo(PAN_SERVO_PIN, pan_pulse);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    set_servo(PAN_SERVO_PIN, 0);
    set_servo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nPan-tilt control stopped.\n");
    return EXIT_SUCCESS;
}

