#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512

static volatile sig_atomic_t program_running = 1;
static char server_ip[64] = "";
static int server_port = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm timeinfo;
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    localtime_r(&ts.tv_sec, &timeinfo);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &timeinfo);

    snprintf(filename, filename_size, "%s/%s_%06ld.jpg", CAPTURE_DIR, timestamp, ts.tv_nsec / 1000);

    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o '%s' -w %d -h %d -q %d --nopreview 2>/dev/null",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed to execute libcamera-still: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_status) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    char json_data[MAX_JSON_LEN];
    snprintf(json_data, sizeof(json_data),
             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
             filename, timestamp, motion_status, PIR_GPIO);

    char url[128];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    strncpy(server_ip, argv[1], sizeof(server_ip) - 1);
    server_ip[sizeof(server_ip) - 1] = '\0';
    server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "curl_global_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (program_running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (motion_detected) {
            char filename[MAX_FILENAME_LEN];
            if (capture_image(filename, sizeof(filename)) == 0) {
                time_t rawtime;
                struct tm timeinfo;
                struct timespec ts;
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    localtime_r(&ts.tv_sec, &timeinfo);
                    char timestamp[32];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
                    char full_timestamp[40];
                    snprintf(full_timestamp, sizeof(full_timestamp), "%s.%06ldZ", timestamp, ts.tv_nsec / 1000);

                    if (send_data(filename, full_timestamp, 1) != 0) {
                        fprintf(stderr, "Failed to send data for %s\n", filename);
                    } else {
                        printf("Motion detected, image captured and sent: %s\n", filename);
                    }
                } else {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                }
            } else {
                fprintf(stderr, "Failed to capture image\n");
            }

            gpioDelay(DEBOUNCE_TIME_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    curl_global_cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

