#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          17
#define IMAGE_DIR        "/home/pi/images"
#define LOG_FILE         "/home/pi/motion_capture.log"
#define DEBOUNCE_MS      50
#define POLL_TIMEOUT_MS  1000
#define CAPTURE_WIDTH    640
#define CAPTURE_HEIGHT   480
#define CAPTURE_QUALITY  85
#define CAPTURE_TIMEOUT  2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown] %s\n", msg);
    }
    fclose(fp);
}

static int capture_image(const char *filename)
{
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "libcamera-still -o '%s' --width %d --height %d -q %d --timeout %d --nopreview",
                       filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY, CAPTURE_TIMEOUT);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec debounce_ts = { 0, DEBOUNCE_MS * 1000000L };
    struct timespec poll_ts = { 0, POLL_TIMEOUT_MS * 1000000L };
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(line, "pir-motion") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        goto cleanup;
    }

    log_event("Motion detection system started.");

    while (running) {
        int ev = gpiod_line_event_wait(line, &poll_ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ev == 0) continue;

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        nanosleep(&debounce_ts, NULL);

        time_t t = time(NULL);
        struct tm tm;
        if (!localtime_r(&t, &tm)) {
            log_event("localtime_r failed");
            continue;
        }

        char filename[256];
        int n = snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                         IMAGE_DIR,
                         tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                         tm.tm_hour, tm.tm_min, tm.tm_sec,
                         tm.tm_msec);
        if (n < 0 || (size_t)n >= sizeof(filename)) {
            log_event("Filename buffer too small");
            continue;
        }

        char log_msg[300];
        snprintf(log_msg, sizeof(log_msg), "Motion detected on GPIO%d, capturing image: %s", PIR_PIN, filename);
        log_event(log_msg);

        if (capture_image(filename) == 0) {
            snprintf(log_msg, sizeof(log_msg), "Image captured successfully: %s", filename);
            log_event(log_msg);
        } else {
            snprintf(log_msg, sizeof(log_msg), "Failed to capture image: %s", filename);
            log_event(log_msg);
        }
    }

    log_event("Motion detection system stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

