#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_NEUTRAL_ANGLE 90
#define ANGLE_INCREMENT 5
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / MAX_ANGLE;
}

int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) return -1;
    if (gpioServo(gpio, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    int pan_angle = SERVO_NEUTRAL_ANGLE;
    int tilt_angle = SERVO_NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_GPIO, pan_angle) != 0 || set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pan-Tilt Control (arrow keys, q to quit)\n");
    printf("Initial: Pan=%d, Tilt=%d\n", pan_angle, tilt_angle);

    while (keep_running) {
        int c = getchar();
        if (c == EOF) break;

        switch (c) {
            case 'w':
                if (tilt_angle + ANGLE_INCREMENT <= MAX_ANGLE) {
                    tilt_angle += ANGLE_INCREMENT;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        fprintf(stderr, "Failed to set tilt angle\n");
                    }
                } else {
                    fprintf(stderr, "Tilt at max (%d)\n", MAX_ANGLE);
                }
                break;
            case 's':
                if (tilt_angle - ANGLE_INCREMENT >= MIN_ANGLE) {
                    tilt_angle -= ANGLE_INCREMENT;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        fprintf(stderr, "Failed to set tilt angle\n");
                    }
                } else {
                    fprintf(stderr, "Tilt at min (%d)\n", MIN_ANGLE);
                }
                break;
            case 'a':
                if (pan_angle - ANGLE_INCREMENT >= MIN_ANGLE) {
                    pan_angle -= ANGLE_INCREMENT;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        fprintf(stderr, "Failed to set pan angle\n");
                    }
                } else {
                    fprintf(stderr, "Pan at min (%d)\n", MIN_ANGLE);
                }
                break;
            case 'd':
                if (pan_angle + ANGLE_INCREMENT <= MAX_ANGLE) {
                    pan_angle += ANGLE_INCREMENT;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        fprintf(stderr, "Failed to set pan angle\n");
                    }
                } else {
                    fprintf(stderr, "Pan at max (%d)\n", MAX_ANGLE);
                }
                break;
            case 'q':
                keep_running = 0;
                break;
            default:
                break;
        }
        usleep(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_GPIO, SERVO_NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, SERVO_NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Pan-Tilt terminated. Servos set to neutral.\n");
    return 0;
}

