#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static double total_volume = 0.0;
static int i2c_handle = -1;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    if (i2cWriteByte(i2c_handle, data | ENABLE | LCD_BACKLIGHT) < 0) {
        fprintf(stderr, "I2C write (strobe high) failed\n");
    }
    gpioDelay(500);
    if (i2cWriteByte(i2c_handle, (data & ~ENABLE) | LCD_BACKLIGHT) < 0) {
        fprintf(stderr, "I2C write (strobe low) failed\n");
    }
    gpioDelay(500);
}

static void lcd_byte(int bits, int mode) {
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    if (i2cWriteByte(i2c_handle, high) < 0) {
        fprintf(stderr, "I2C write (high nibble) failed\n");
    }
    lcd_strobe(high);
    if (i2cWriteByte(i2c_handle, low) < 0) {
        fprintf(stderr, "I2C write (low nibble) failed\n");
    }
    lcd_strobe(low);
}

static void lcd_string(const char *s) {
    while (*s) lcd_byte((uint8_t)*s++, LCD_CHR);
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    if (i2cWriteByte(i2c_handle, 0x33) < 0) return;
    lcd_strobe(0x33);
    if (i2cWriteByte(i2c_handle, 0x32) < 0) return;
    lcd_strobe(0x32);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void update_lcd(double flow_rate, double total_volume) {
    char line1[17], line2[17];
    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", total_volume);
    lcd_clear();
    lcd_string(line1);
    lcd_byte(LCD_LINE_2, LCD_CMD);
    lcd_string(line2);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
