#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define ANEMOMETER_GPIO 17
#define LCD_I2C_ADDR    0x27
#define SPI_CHANNEL     0
#define SPI_SPEED       1000000
#define SAMPLE_MS       500
#define PULSES_PER_MPS  2.0
#define ADC_MAX         1023
#define ADC_MIN         0
#define ADC_DEADZONE    10

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_i2c(int handle, uint8_t data) {
    if (i2cWriteByte(handle, data) < 0) {
        fprintf(stderr, "LCD I2C write failed\n");
        return -1;
    }
    return 0;
}

static void lcd_send_4bits(int handle, uint8_t nibble, uint8_t rs) {
    uint8_t hi = (nibble & 0xF0) | rs;
    lcd_write_i2c(handle, hi | 0x04);
    lcd_write_i2c(handle, hi & ~0x04);
    gpioDelay(1000);
}

static void lcd_send_command(int handle, uint8_t cmd) {
    lcd_send_4bits(handle, cmd & 0xF0, 0);
    lcd_send_4bits(handle, (cmd << 4) & 0xF0, 0);
    if (cmd == 0x01 || cmd == 0x02) gpioDelay(2000);
}

static void lcd_send_data(int handle, uint8_t data) {
    lcd_send_4bits(handle, data & 0xF0, 1);
    lcd_send_4bits(handle, (data << 4) & 0xF0, 1);
}

static void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_4bits(handle, 0x30, 0); gpioDelay(5000);
    lcd_send_4bits(handle, 0x30, 0); gpioDelay(1000);
    lcd_send_4bits(handle, 0x30, 0); gpioDelay(1000);
    lcd_send_4bits(handle, 0x20, 0); gpioDelay(1000);
    lcd_send_command(handle, 0x28);
    lcd_send_command(handle, 0x0C);
    lcd_send_command(handle, 0x06);
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_clear(int handle) {
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(int handle, int col, int row) {
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    lcd_send_command(handle, addr + col);
}

static void lcd_print(int handle, const char *str) {
    while (*str) {
        lcd_send_data(handle, (uint8_t)*str++);
    }
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) return -1;
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double calculate_wind_speed(int pulses) {
    return (double)pulses / PULSES_PER_MPS;
}

static double calculate_wind_direction(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) return -1.0;
    double angle = (double)adc_value / (double)ADC_MAX * 360.0;
    if (angle < 0.0) angle = 0.0;
    if (angle >= 360.0) angle = 360.0 - 1e-9;
    return angle;
}

static void display_data(int lcd_handle, double wind_speed, double wind_direction) {
    char buffer[20];
    lcd_clear(lcd_handle);
    lcd_set_cursor(lcd_handle, 0, 0);
    snprintf(buffer, sizeof(buffer), "Spd:%.1f m/s", wind_speed);
    lcd_print(lcd_handle, buffer);
    lcd_set_cursor(lcd_handle, 0, 1);
    snprintf(buffer, sizeof(buffer), "Dir:%.0f deg", wind_direction);
    lcd_print(lcd_handle, buffer);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int lcd_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", LCD_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init(lcd_handle);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        i2cClose(lcd_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", ANEMOMETER_GPIO);
        spiClose(spi_handle);
        i2cClose(lcd_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", ANEMOMETER_GPIO);
        spiClose(spi_handle);
        i2cClose(lcd_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Wind sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;

        double wind_speed = calculate_wind_speed(pulses);
        int adc_value = read_mcp3008(spi_handle, 0);
        double wind_direction = -1.0;

        if (adc_value >= 0) {
            wind_direction = calculate_wind_direction(adc_value);
            if (adc_value <= ADC_DEADZONE || adc_value >= (ADC_MAX - ADC_DEADZONE)) {
                fprintf(stderr, "Warning: ADC reading at extreme (%d), possible sensor fault\n", adc_value);
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        if (wind_direction < 0.0) {
            wind_direction = 0.0;
        }

        display_data(lcd_handle, wind_speed, wind_direction);
        printf("Wind Speed: %.1f m/s, Wind Direction: %.0f deg\n", wind_speed, wind_direction);

        gpioDelay(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    lcd_clear(lcd_handle);
    lcd_print(lcd_handle, "Shutting down");
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    spiClose(spi_handle);
    i2cClose(lcd_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

