#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define SAMPLE_INTERVAL_SEC 1
#define SENSOR_TIMEOUT_SEC 10

static volatile int pulse_count = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int lcd_write_byte(int handle, uint8_t data) {
    uint8_t buf[1] = {data};
    if (i2cWriteDevice(handle, (char *)buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }
    return 0;
}

int lcd_send_command(int handle, uint8_t cmd) {
    if (lcd_write_byte(handle, cmd & 0xF0) != 0) return -1;
    if (lcd_write_byte(handle, (cmd << 4) & 0xF0) != 0) return -1;
    gpioDelay(5000);
    return 0;
}

int lcd_send_data(int handle, uint8_t data) {
    if (lcd_write_byte(handle, (data & 0xF0) | 0x01) != 0) return -1;
    if (lcd_write_byte(handle, ((data << 4) & 0xF0) | 0x01) != 0) return -1;
    gpioDelay(5000);
    return 0;
}

int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x30) != 0) return -1;
    gpioDelay(5000);
    if (lcd_send_command(handle, 0x30) != 0) return -1;
    gpioDelay(10000);
    if (lcd_send_command(handle, 0x30) != 0) return -1;
    if (lcd_send_command(handle, 0x20) != 0) return -1;
    if (lcd_send_command(handle, 0x28) != 0) return -1;
    if (lcd_send_command(handle, 0x08) != 0) return -1;
    if (lcd_send_command(handle, 0x01) != 0) return -1;
