#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %u as output\n", col_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void display_frame(const int frame[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            gpiod_line_set_value(row_lines[row], 1);
            gpiod_line_set_value(col_lines[col], 0);
            usleep(SCAN_DELAY_US);
            gpiod_line_set_value(row_lines[row], 0);
            gpiod_line_set_value(col_lines[col], 1);
        }
    }
}

static void left_to_right_wave(int frame[NUM_ROWS][NUM_COLS], int phase) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            frame[row][col] = (col >= phase && col < phase + 3) ? 1 : 0;
        }
    }
}

static void right_to_left_wave(int frame[NUM_ROWS][NUM_COLS], int phase) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            frame[row][col] = (col >= NUM_COLS - phase - 3 && col < NUM_COLS - phase) ? 1 : 0;
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return 1;
    }

    int frame[NUM_ROWS][NUM_COLS];
    int phase = 0;
    int direction = 1;

    while (keep_running) {
        if (direction == 1) {
            left_to_right_wave(frame, phase);
        } else {
            right_to_left_wave(frame, phase);
        }

        display_frame(frame);

        phase += direction;
        if (phase >= NUM_COLS - 2) {
            direction = -1;
        } else if (phase <= 0) {
            direction = 1;
        }
    }

    cleanup();
    return 0;
}

