/*
 * VL53L3CX Multi-Target ToF Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download and a
 *       complex initialization sequence (ST ULD). This program stubs
 *       the firmware download with a descriptive comment and implements
 *       the I2C communication, error handling, and application logic.
 *       A full production implementation would require the ST ULD driver
 *       binaries (vl53l3cx_api.c/h) linked in, which are available under
 *       the ST Software License Agreement.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (I2C1 SDA)
 *   VL53L3CX SCL -> GPIO3 (I2C1 SCL)
 *   VL53L3CX VDD -> 3.3V
 *   VL53L3CX GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

/* VL53L3CX Register Addresses (ST ULD API) */
#define VL53L3CX_REG_SOFT_RESET       0x0000
#define VL53L3CX_REG_MODEL_ID         0x010F
#define VL53L3CX_REG_RANGE_START      0x0080
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_REG_RESULT_DISTANCE  0x0096

#define VL53L3CX_EXPECTED_MODEL_ID    0xEA
#define VL53L3CX_SOFT_RESET_VAL       0x00
#define VL53L3CX_RANGE_START_VAL      0x01

#define MAX_TARGETS 4

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t distance_mm;
    uint8_t  confidence;
} target_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Write a 16-bit register address followed by a 16-bit value.
 * The VL53L3CX uses 16-bit register addresses in its ULD API.
 */
static int vl53l3cx_write_reg16(uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 4);
}

/*
 * Write an 8-bit value to an 8-bit register address.
 */
static int vl53l3cx_write_reg8(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    return i2cWriteDevice(i2c_handle, buf, 2);
}

/*
 * Read a 16-bit value from a 16-bit register address.
 */
static int vl53l3cx_read_reg16(uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(i2c_handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/*
 * Read an 8-bit value from an 8-bit register address.
 */
static int vl53l3cx_read_reg8(uint8_t reg, uint8_t *value) {
    char reg_buf[1];
    char data_buf[1];
    reg_buf[0] = reg;

    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int vl53l3cx_init(void) {
    uint8_t model_id = 0;

    /* 1. Soft reset */
    if (vl53l3cx_write_reg8(VL53L3CX_REG_SOFT_RESET, VL53L3CX_SOFT_RESET_VAL) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms delay for reset to take effect */

    /* 2. Verify Model ID */
    if (vl53l3cx_read_reg8(VL53L3CX_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != VL53L3CX_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L3CX_EXPECTED_MODEL_ID);
        return -1;
    }

    /*
     * 3. Firmware Download (ST ULD)
     *    In a full implementation, this would involve downloading the
     *    proprietary firmware from the ST ULD binaries.
     *    For this stubbed version, we assume the firmware is pre-loaded.
     */

    /* 4. Start ranging */
    if (vl53l3cx_write_reg8(VL53L3CX_REG_RANGE_START, VL53L3CX_RANGE_START_VAL) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l3cx_read_data(target_data_t *targets, int *num_targets) {
    uint8_t status = 0;
    uint16_t distance = 0;
    int i;

    *num_targets = 0;

    /* Check if data is ready */
    if (vl53l3cx_read_reg8(VL53L3CX_REG_RESULT_RANGE_STATUS, &status) != 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* No new data available */
        return 0;
    }

    /* Read distance for each target */
    for (i = 0; i < MAX_TARGETS; i++) {
        if (vl53l3cx_read_reg16(VL53L3CX_REG_RESULT_DISTANCE + (i * 2), &distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance for target %d.\n", i);
            return -1;
        }
        targets[i].distance_mm = distance;
        targets[i].confidence = 0xFF; /* Placeholder confidence */
        (*num_targets)++;
    }

    return 0;
}

static void log_data(const target_data_t *targets, int num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Targets: %d\n", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("  Target %d: Distance = %u mm, Confidence = %u\n",
               i, targets[i].distance_mm, targets[i].confidence);
    }
    fflush(stdout);
}

int main(void) {
    target_data_t targets[MAX_TARGETS];
    int num_targets = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L3CX sensor */
    if (vl53l3cx_init() != 0) {
        fprintf(stderr, "Error: VL53L3CX initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L3CX sensor initialized. Reading data every 100ms...\n");

    /* Main loop */
    while (!terminate) {
        if (vl53l3cx_read_data(targets, &num_targets) == 0) {
            log_data(targets, num_targets);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }
        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

