#define SI1145_REG_IRQ_STATUS 0x31
#define SI1145_REG_COMMAND 0x18

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PS_AUTO 0x0D
#define SI1145_CMD_ALS_AUTO 0x0E

#define SI1145_PART_ID 0x45

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t vis_low, vis_high, ir_low, ir_high;

    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0, &vis_low) < 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0 + 1, &vis_high) < 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_IR_DATA0, &ir_low) < 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_IR_DATA0 + 1, &ir_high) < 0) return -1;

    *ambient_light = (uint16_t)((vis_high << 8) | vis_low);
    *proximity = (uint16_t)((ir_high << 8) | ir_low);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
