    uint8_t part_id;

    if (read_register(handle, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        return -1;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_AUTO) < 0) return -1;
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_AUTO) < 0) return -1;

    uint8_t irq_status;
    if (read_register(handle, SI1145_REG_IRQ_STATUS, &irq_status) < 0) return -1;
    if (write_register(handle, SI1145_REG_IRQ_STATUS, irq_status) < 0) return -1;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting data logging. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t proximity, ambient_light;

        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

