#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_PS_RATE      0x0A
#define SI1145_REG_PS_LED21     0x0F
#define SI1145_REG_PS1_DATA0    0x18
#define SI1145_REG_PS1_DATA1    0x19
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_CH_LIST      0x4F
#define SI1145_REG_COMMAND      0x30

#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_PS_FORCE     0x07
#define SI1145_CMD_RESET        0x01

#define SI1145_PART_ID_EXPECTED 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word_le(uint8_t reg_lsb, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg_lsb, &lo) < 0) return -1;
    if (read_reg(reg_lsb + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, 0x17) < 0) return -1;

    if (write_reg(SI1145_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_PS_RATE, 0x08) < 0) return -1;
    if (write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) return -1;

    if (write_reg(SI1145_REG_CH_LIST, 0x80) < 0) return -1;

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);
    return read_word_le(SI1145_REG_PS1_DATA0, prox);
}

static int read_ambient_light(uint16_t *als) {
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);
    return read_word_le(SI1145_REG_ALS_VIS_DATA0, als);
}

static void log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, prox, als);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        uint16_t prox, als;

        if (read_proximity(&prox) < 0) {
            fprintf(stderr, "Proximity read error\n");
        } else if (read_ambient_light(&als) < 0) {
            fprintf(stderr, "Ambient light read error\n");
        } else {
            log_data(prox, als);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

