#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define WATERING_THRESHOLD 15.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 30
#define POLL_INTERVAL_S 60
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    }
    fprintf(fp, "%s %s\n", ts, msg);
    fflush(fp);
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec ts_start, ts_rise, ts_fall;
    struct gpiod_line_event event;
    int ret;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    ret = gpiod_line_event_wait(echo, &(struct timespec){0, ECHO_TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        return -1.0;
    }
    if (ret == 0) {
        return -2.0; /* sensor absent or no echo */
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        return -1.0;
    }
    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        return -1.0;
    }
    ts_rise = event.ts;

    /* Wait for echo falling edge (timeout) */
    ret = gpiod_line_event_wait(echo, &(struct timespec){0, ECHO_TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        return -1.0;
    }
    if (ret == 0) {
        return -3.0; /* echo stuck high */
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        return -1.0;
    }
    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        return -1.0;
    }
    ts_fall = event.ts;

    double pulse_us = (ts_fall.tv_sec - ts_rise.tv_sec) * 1000000.0 +
                      (ts_fall.tv_nsec - ts_rise.tv_nsec) / 1000.0;
    double distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -4.0; /* out of range */
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    /* Enable rising and falling edge events on echo line */
    if (gpiod_line_request_both_edges_events(echo, "hc-sr04-echo-events") < 0) {
        perror("gpiod_line_request_both_edges_events");
        goto cleanup;
    }

    log_message(log_fp, "Plant watering reminder system started.");

    while (program_running) {
        double distance = measure_distance(trig, echo);

        if (distance < 0) {
            char buf[128];
            switch ((int)distance) {
                case -1: snprintf(buf, sizeof(buf), "Error: GPIO event read/write failed."); break;
                case -2: snprintf(buf, sizeof(buf), "Error: Echo rising edge timeout (sensor absent?)."); break;
                case -3: snprintf(buf, sizeof(buf), "Error: Echo falling edge timeout (stuck high?)."); break;
                case -4: snprintf(buf, sizeof(buf), "Error: Distance out of range (2-400 cm)."); break;
                default: snprintf(buf, sizeof(buf), "Error: Unknown measurement failure."); break;
            }
            log_message(log_fp, buf);
        } else {
            char buf[128];
            snprintf(buf, sizeof(buf), "Distance: %.2f cm", distance);
            log_message(log_fp, buf);
            if (distance < WATERING_THRESHOLD) {
                log_message(log_fp, "Time to water the plant!");
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && program_running; i++) {
            sleep(1);
        }
    }

    log_message(log_fp, "Plant watering reminder system stopped.");
    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return rc;
}

