#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x39
#define I2C_BUS 1

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int init_apds9960(int handle) {
    int id = i2c_read_byte(handle, APDS9960_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_color_data(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    int rc_r = i2c_read_word(handle, APDS9960_RDATAL);
    int rc_g = i2c_read_word(handle, APDS9960_GDATAL);
    int rc_b = i2c_read_word(handle, APDS9960_CDATAL);

    if (rc_r < 0 || rc_g < 0 || rc_b < 0) return -1;

    *r = (uint16_t)rc_r;
    *g = (uint16_t)rc_g;
    *b = (uint16_t)rc_b;
    return 0;
}

static int read_proximity_data(int handle, uint8_t *prox) {
    int rc = i2c_read_byte(handle, APDS9960_PDATAL);
    if (rc < 0) return -1;
    *prox = (uint8_t)rc;
    return 0;
}

static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint8_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, prox);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, APDS9960_I2C_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_apds9960(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    fflush(log_file);

    while (running) {
        uint16_t r, g, b;
        uint8_t prox;

        if (read_color_data(i2c_handle, &r, &g, &b) < 0 ||
            read_proximity_data(i2c_handle, &prox) < 0) {
            fprintf(stderr, "I2C communication error, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            usleep(1000000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C: %s\n", pigpio_error(i2c_handle));
                break;
            }
            if (init_apds9960(i2c_handle) < 0) {
                fprintf(stderr, "Failed to re-initialize APDS9960\n");
                break;
            }
            continue;
        }

        if (prox > PROXIMITY_THRESHOLD) {
            log_data(log_file, r, g, b, prox);
        }

        usleep(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

