#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A
#define CSV_FILE       "heartrate.csv"

/* Si1182 register addresses */
#define REG_PART_ID     0x00
#define REG_MEAS_RATE0  0x08
#define REG_COMMAND     0x47
#define REG_PS_DATA0    0x24
#define REG_PS_DATA1    0x25

#define EXPECTED_PART_ID 0x82
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Write one byte to an 8-bit register using SMBus-style block transfer. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian register pair. */
static int i2c_read_reg16_le(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_lo, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lo + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
