    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* Configure measurement rate for continuous proximity mode. */
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x0A) < 0)
        return -1;

    /* Issue a reset/start command to begin measurements. */
    if (i2c_write_reg8(fd, REG_COMMAND, 0x01) < 0)
        return -1;

    return 0;
