        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_sensor(fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        goto cleanup;
    }

    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging heart rate to %s. Press Ctrl+C to stop.\n", CSV_FILE);

