#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define GPIO_TRIGGER   17
#define LOG_FILE       "distance_log.txt"
#define POLL_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* Trigger a single measurement and read the 16-bit distance in mm. */
static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[14];
    int     elapsed = 0;

    /* Start a single-shot range measurement */
    if (i2c_write_reg8(handle, REG_SYSRANGE_START, 0x01) != 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until it sets (data ready) */
    do {
        if (i2c_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
        elapsed += 2;
    } while (elapsed < POLL_TIMEOUT_MS);

    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement\n");
        return -1;
    }

    /* Read the 14-byte result block */
    if (i2c_read_reg(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) != 0)
        return -1;

    /* Distance is bytes 10-11, little-endian */
    *distance_mm = (uint16_t)((data[10] << 8) | data[11]);

    /* Clear the interrupt so the next measurement can signal */
    if (i2c_write_reg8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t     rawtime;
    struct tm *timeinfo;
    char       timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L0X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor presence check --- */
    {
        uint8_t model_id = 0;
        if (i2c_read_reg(g_i2c_handle, 0x010F, &model_id, 1) != 0) {
            fprintf(stderr, "VL53L0X not responding at 0x%02X\n", VL53L0X_ADDR);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (model_id != 0xEA) {
            fprintf(stderr, "Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- GPIO setup --- */
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L0X distance logger started. GPIO %d falling edge triggers measurement.\n",
           GPIO_TRIGGER);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        /* Wait for falling edge on GPIO 17 */
        if (gpioWaitForEdge(GPIO_TRIGGER, FALLING_EDGE, 1000) == 0) {
            uint16_t distance = 0;
            if (read_distance(g_i2c_handle, &distance) == 0) {
                log_distance(g_log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Measurement failed; continuing.\n");
            }
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

