#define MEASURE_US     50000    /* 50 ms  */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0)
        return -1;
    return 0;
}

int main(void)
{
    int i2c_handle = -1;
    FILE *log_file = NULL;
    char ts[32];
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, CH101_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        goto cleanup_i2c;
    }

    while (g_running) {
        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Failed to generate timestamp\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (i2cWriteByte(i2c_handle, TRIGGER_CMD) < 0) {
            fprintf(stderr, "%s, Error triggering measurement\n", ts);
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(MEASURE_US);

        int distance = i2cReadWordData(i2c_handle, READ_CMD);
        if (distance < 0) {
            fprintf(stderr, "%s, Error reading distance: %d\n", ts, distance);
            gpioDelay(SAMPLE_US);
            continue;
        }

        fprintf(log_file, "%s, %d\n", ts, distance);
        fflush(log_file);
        printf("%s, %d\n", ts, distance);

        gpioDelay(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
cleanup_gpio:
    if (log_file != NULL)
        fclose(log_file);
    gpioTerminate();
    return rc;
}

