#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d (pigpio error %d)\n", pin, value);
        return -1;
    }
    return value;
}

static void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: failed to get current time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value >= 0 && sensor2_value >= 0) {
            log_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Warning: sensor read error, skipping log entry\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nObstacle detection stopped.\n");
    return 0;
}

