#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define READ_RETRIES 3
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    int result;
    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d): %d\n", reg, attempt + 1, result);
        gpioDelay(10000);
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Starting Si1182 sensor logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;

        if (read_register16(i2c_handle, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data after %d retries\n", READ_RETRIES);
        } else if (read_register16(i2c_handle, AMBIENT_LIGHT_REG, &ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light data after %d retries\n", READ_RETRIES);
        } else {
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

