            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
    return 0;
}

static void control_led(int gpio, int distance, int threshold) {
    gpioWrite(gpio, distance < threshold ? 1 : 0);
}

