    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance monitoring (threshold=%d mm). Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(LOG_FILE, distance);
            control_led(LED_GPIO, distance, threshold);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Read failed; continuing...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

