#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define SENSOR_ADDR     0x50
#define THRESHOLD_MM    1000
#define NUM_SAMPLES     10
#define LOG_FILE        "intrusion_log.txt"
#define SAMPLE_DELAY_US 100000
#define MEASURE_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0)
        return -1;

    usleep(MEASURE_DELAY_US);

    if (i2c_read_resp(fd, resp, sizeof(resp)) != 0)
        return -1;

    if (resp[0] != 0x50) {
        fprintf(stderr, "Sensor header mismatch: got 0x%02X, expected 0x50\n", resp[0]);
        return -1;
    }

    *distance_mm = (resp[11] << 8) | resp[12];
    return 0;
}

static float calculate_average_distance(int *distances, int num) {
    long sum = 0;
    for (int i = 0; i < num; i++)
        sum += distances[i];
    return (float)sum / num;
}

static void log_intrusion(float avg_dist) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Intrusion detected! Average distance: %.2f mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_dist);
    } else {
        fprintf(fp, "<timestamp error> - Intrusion detected! Average distance: %.2f mm\n", avg_dist);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distances[NUM_SAMPLES];
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                distances[valid++] = dist;
            } else {
                fprintf(stderr, "Read failed at sample %d\n", i + 1);
            }
            usleep(SAMPLE_DELAY_US);
        }

        if (valid > 0) {
            float avg = calculate_average_distance(distances, valid);
            printf("Average distance: %.2f mm\n", avg);
            if (avg < THRESHOLD_MM) {
                printf("Intrusion detected!\n");
                log_intrusion(avg);
            }
        } else {
            fprintf(stderr, "All samples failed in this cycle.\n");
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("Resources released. Goodbye.\n");
    return 0;
}

