#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B
#define REG_MODEL_ID                0xC0
#define EXPECTED_MODEL_ID           0xEE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns byte value (0-255) or -1 on error. */
static int vl53l0x_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return rc;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int vl53l0x_read_word(int handle, uint8_t reg)
{
    int low = i2cReadByteData(handle, reg);
    if (low < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X low): %s\n",
                reg, strerror(errno));
        return -1;
    }
    int high = i2cReadByteData(handle, reg + 1);
    if (high < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X high): %s\n",
                reg + 1, strerror(errno));
        return -1;
    }
    return (high << 8) | low;
}

/* Verify the sensor is present by reading the model ID. */
static int vl53l0x_verify(int handle)
{
    int id = vl53l0x_read_byte(handle, REG_MODEL_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read model ID register.\n");
        return -1;
    }
    if (id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X).\n",
                id, EXPECTED_MODEL_ID);
        return -1;
    }
    return 0;
}

/* Perform a single-shot ranging measurement and return distance in mm. */
static int vl53l0x_read_distance(int handle)
{
    /* Start a single measurement. */
    if (vl53l0x_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready). */
    for (int i = 0; i < 100; i++) {
        int status = vl53l0x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS);
        if (status < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    int distance = vl53l0x_read_word(handle, REG_RESULT_RANGE_STATUS);
    if (distance < 0)
        return -1;

    /* Clear the interrupt so the next measurement can be triggered. */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return distance;
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    /* Open the I2C device. */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Verify the sensor is present. */
    if (vl53l0x_verify(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X sensor not detected at address 0x%02X.\n",
                VL53L0X_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL53L0X detected. Starting distance readings every 500 ms...\n");

    /* Main loop. */
    while (g_running) {
        int distance = vl53l0x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: failed to read distance.\n");
        }

