#define SI1182_ADDR        0x39
#define REG_IRQ_STATUS     0x25
#define REG_PROX_LSB       0x2A
#define REG_PROX_MSB       0x2B
#define REG_CONFIG         0x18
#define CONFIG_PROX_EN     0x01
#define POLL_TIMEOUT_MS    1000
#define SAMPLE_PERIOD_US   500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int read_proximity(int handle, uint16_t *prox)
{
    int status = read_reg(handle, REG_IRQ_STATUS);
    if (status < 0)
        return -1;

    if ((status & 0x01) == 0) {
        fprintf(stderr, "Proximity data not ready (IRQ=0x%02X)\n", status);
        return -1;
    }

    int lsb = read_reg(handle, REG_PROX_LSB);
    if (lsb < 0)
        return -1;

    int msb = read_reg(handle, REG_PROX_MSB);
    if (msb < 0)
        return -1;

    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                SI1182_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg(g_i2c_handle, REG_CONFIG, CONFIG_PROX_EN) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (NACK / absent)\n",
                SI1182_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor initialized at 0x%02X.\n", SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t prox = 0;
        if (read_proximity(g_i2c_handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Failed to read proximity data.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

