#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_RESULT_CH0 0x00
#define REG_RESULT_CH1 0x02
#define REG_AMBIENT 0x04
#define REG_ERROR_FLAGS 0x06
#define REG_CONFIG 0x08

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_register(int handle, uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", OPT3101_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("OPT3101 sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ch0_distance, ch1_distance, ambient_light, error_flags;

        if (read_register(i2c_handle, REG_RESULT_CH0, &ch0_distance) != 0 ||
            read_register(i2c_handle, REG_RESULT_CH1, &ch1_distance) != 0 ||
            read_register(i2c_handle, REG_AMBIENT, &ambient_light) != 0 ||
            read_register(i2c_handle, REG_ERROR_FLAGS, &error_flags) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(500000);
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

