/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, not wiringPi)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm resistor (protects Pi from 5V echo)
 *   HC-SR04 VCC  -> 5V (Pi pin 2 or 4)
 *   HC-SR04 GND  -> GND (Pi pin 6)
 *
 * NOTE: The HC-SR04 outputs 5V on the echo line; a 1 kOhm series resistor
 *       limits the Pi GPIO input voltage to ~3.3V, within the 3.3V
 *       tolerance of the Raspberry Pi BCM GPIO pins.
 *
 * Build:  gcc -Wall -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo edges  */
#define MAX_PULSE_US     38000       /* 38 ms max echo (HC-SR04 400 cm) */
#define SAMPLE_PERIOD_S  1           /* seconds between readings       */

/* ------------------------------------------------------------------ */
/* Globals for signal-driven shutdown                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Wait for a GPIO level change (edge) with a microsecond timeout.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_for_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    int      v;

    for (;;) {
        v = gpioRead(pin);
        if (v == level)
            return 0;

        if (v < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %d\n", pin, v);
            return -1;
        }

        if ((gpioTick() - start) >= timeout_us)
            return -1;
    }
}

/*
 * Measure distance in cm.  Returns >= 0 on success, -1.0 on error.
 *
 * NOTE: gpioTick() returns a 32-bit microsecond counter that wraps
 *       every ~71.6 minutes.  The subtraction (end - start) is safe
 *       because pigpio guarantees the result is correct even across
 *       a single wrap (the library handles the unsigned wrap).
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;
    int      rc;

    /* --- Issue 10 us trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge --- */
    rc = wait_for_level(ECHO_PIN, 1, ECHO_TIMEOUT_US);
    if (rc < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0f;
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    rc = wait_for_level(ECHO_PIN, 0, ECHO_TIMEOUT_US);
    if (rc < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0f;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* --- Validate pulse duration --- */
    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Invalid pulse duration: %u us\n", pulse_us);
        return -1.0f;
    }

    /* --- Distance = (pulse_us * 0.0343) / 2  (cm) --- */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    printf("HC-SR04 distance reader started.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Sampling every %d second(s). Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_S);
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        float distance = measure_distance();

        if (distance >= 0.0f) {
            time_t     rawtime;
            struct tm  timeinfo;
            char       timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

