#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (NUM_RANGE_BINS * 2)
#define MAGIC_WORD_SIZE 8
#define LOG_FILE "intrusion_log.csv"
#define POLL_TIMEOUT_MS 1000

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("UART read error");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd) {
    uint8_t byte;
    int match_idx = 0;

    while (running) {
        if (read_exact(fd, &byte, 1) != 0) return -1;

        if (byte == MAGIC_WORD[match_idx]) {
            match_idx++;
            if (match_idx == MAGIC_WORD_SIZE) return 0;
        } else {
            match_idx = 0;
        }
    }
    return -1;
}

static int read_range_profile(int fd, int16_t *profile) {
    uint8_t raw[DATA_FRAME_SIZE];
    if (read_exact(fd, raw, DATA_FRAME_SIZE) != 0) return -1;

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        profile[i] = (int16_t)((raw[2 * i + 1] << 8) | raw[2 * i]);
    }
    return 0;
}

static float detect_intrusion(const int16_t *profile) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (profile[i] > 0) {
            return (float)i * RANGE_RESOLUTION;
        }
    }
    return -1.0f;
}

static void trigger_alert(float distance) {
    if (gpioWrite(GPIO_LED, 1) < 0) {
        fprintf(stderr, "Failed to turn on LED\n");
        return;
    }
    printf("Intrusion detected at %.2f meters! LED activated.\n", distance);
    time_sleep(2.0);
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED\n");
    }
}

static void log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("UART initialized on %s at 115200 baud. Waiting for radar data...\n", UART_DEVICE);

    int16_t range_profile[NUM_RANGE_BINS];

    while (running) {
        if (find_magic_word(uart_fd) != 0) {
            if (!running) break;
            fprintf(stderr, "Failed to find magic word. Retrying...\n");
            continue;
        }

        if (read_range_profile(uart_fd, range_profile) != 0) {
            if (!running) break;
            fprintf(stderr, "Failed to read range profile. Retrying...\n");
            continue;
        }

        float distance = detect_intrusion(range_profile);
        if (distance >= 0.0f) {
            if (distance <= INTRUSION_THRESHOLD) {
                trigger_alert(distance);
                log_intrusion(distance);
            }
        }
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return 0;
}

