#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_PIN      17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_PERIOD_US 100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_distance(uint16_t *distance) {
    int high = i2cReadByteData(g_i2c_handle, DISTANCE_REG_H);
    if (high < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(g_i2c_handle, DISTANCE_REG_L);
    if (low < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", low);
        return -1;
    }
    *distance = ((uint16_t)high << 8) | (uint16_t)low;
    return 0;
}

static int log_distance(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Distance: %u\n", timestamp, distance);
    fclose(fp);
    return 0;
}

static void trigger_alert(uint16_t distance) {
    if (distance < (uint16_t)(DISTANCE_THRESHOLD * 10.0f)) {
        gpioWrite(ALERT_PIN, 1);
        gpioDelay(500000);
        gpioWrite(ALERT_PIN, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_PIN, 0);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (!g_running) break;

        uint16_t distance = 0;
        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Failed to log distance.\n");
        }

        trigger_alert(distance);

        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US);
        }
    }

    printf("\nCleaning up...\n");
    gpioWrite(ALERT_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

