#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_MS  100

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0007
#define REG_SYSRANGE_START          0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0013
#define REG_RESULT_RANGE_STATUS     0x0078
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0014
#define REG_MODEL_ID                0x010F
#define EXPECTED_MODEL_ID           0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit VL53L1X register address */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read one byte from a 16-bit VL53L1X register address */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data[1];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;
    *value = (uint8_t)data[0];
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit VL53L1X register address */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = ((uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_sensor(int handle)
{
