#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE   0x0001
#define REG_STATUS     0x0002

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 4);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%04X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, RETRY_COUNT, rc);
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, reg_buf, 2);
        if (rc != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed (attempt %d/%d, rc=%d)\n",
                    reg, attempt + 1, RETRY_COUNT, rc);
            if (attempt < RETRY_COUNT - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, data_buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
            return 0;
        }

        fprintf(stderr, "I2C read from reg 0x%04X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, RETRY_COUNT, rc);
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_distance_mm(int handle, uint16_t *distance_mm)
{
    uint16_t raw;
    if (i2c_read_reg16(handle, REG_DISTANCE, &raw) != 0)
        return -1;
    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Blink frequency mapping                                             */
/* ------------------------------------------------------------------ */
static float distance_to_frequency(uint16_t distance_mm)
{
    const float min_dist_mm = 50.0f;
    const float max_dist_mm = 500.0f;
    const float min_freq_hz = 1.0f;
    const float max_freq_hz = 10.0f;

    if (distance_mm <= min_dist_mm)
        return max_freq_hz;
    if (distance_mm >= max_dist_mm)
        return min_freq_hz;

    float frac = (float)distance_mm / (max_dist_mm - min_dist_mm);
    return max_freq_hz - frac * (max_freq_hz - min_freq_hz);
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void set_led(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio, on);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    set_led(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance monitor started. I2C bus %d, addr 0x%02X, LED on GPIO %d.\n",
           I2C_BUS, I2C_ADDR, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop: one half-cycle per iteration --- */
    uint32_t next_tick = gpioTick();
    int led_state = 0;
    uint32_t half_period_us = 0;

    while (g_running) {
        uint16_t distance_mm = 0;
        if (read_distance_mm(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
            next_tick += SAMPLE_US;
            led_state = 0;
            set_led(LED_GPIO, 0);
            half_period_us = 0;
        } else {
            float freq = distance_to_frequency(distance_mm);
            half_period_us = (uint32_t)(500000.0f / freq);

            time_t now = time(NULL);
            struct tm tm_info;
            localtime_r(&now, &tm_info);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Distance: %u mm  |  Blink: %.2f Hz\n",
                   ts, distance_mm, freq);

            /* Advance LED state for this sample */
            led_state = !led_state;
            set_led(LED_GPIO, led_state);
        }

        /* Schedule next half-cycle */
        next_tick += half_period_us;
        uint32_t now_tick = gpioTick();
        if (next_tick > now_tick) {
            gpioDelay(next_tick - now_tick);
        } else {
            /* Fell behind; re-sync to current time */
            next_tick = gpioTick();
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

