/* ------------------------------------------------------------------ */
static void set_led(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio, on);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    set_led(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance monitor started. I2C bus %d, addr 0x%02X, LED on GPIO %d.\n",
           I2C_BUS, I2C_ADDR, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop: one half-cycle per iteration --- */
    uint32_t next_tick = gpioTick();
    int led_state = 0;
    uint32_t half_period_us = 0;

    while (g_running) {
        uint16_t distance_mm = 0;
        if (read_distance_mm(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
            next_tick += SAMPLE_US;
            led_state = 0;
            set_led(LED_GPIO, 0);
            half_period_us = 0;
        } else {
            float freq = distance_to_frequency(distance_mm);
            half_period_us = (uint32_t)(500000.0f / freq);

            time_t now = time(NULL);
            struct tm tm_info;
            localtime_r(&now, &tm_info);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Distance: %u mm  |  Blink: %.2f Hz\n",
                   ts, distance_mm, freq);

            /* Advance LED state for this sample */
            led_state = !led_state;
            set_led(LED_GPIO, led_state);
        }

        /* Schedule next half-cycle */
        next_tick += half_period_us;
        uint32_t now_tick = gpioTick();
        if (next_tick > now_tick) {
            gpioDelay(next_tick - now_tick);
        } else {
            /* Fell behind; re-sync to current time */
            next_tick = gpioTick();
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

