#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x5B
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MEASUREMENT_DELAY_US 5000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, MLX75030_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    char cmd[1] = {0x01};
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result == 0) {
            break;
        }
        fprintf(stderr, "Warning: I2C write failed (attempt %d/%d, pigpio error %d)\n",
                retries + 1, MAX_RETRIES, result);
        retries++;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d, got %d bytes)\n",
                retries + 1, MAX_RETRIES, result);
        retries++;
        gpioDelay(RETRY_DELAY_US);
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(uint16_t distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Starting distance logging to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (running) {
        uint16_t distance_cm;
        if (read_distance(&distance_cm) == 0) {
            if (log_data(distance_cm) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

