#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define POLL_DELAY_US     10000   /* 10 ms */
#define LOG_FILE_NAME     "proximity_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 UTC timestamp into buf (size >= 25).              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a state transition to the log file.                            */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, const char *event_type)
{
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is in kernel buffer */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor with software debounce.                              */
/* Returns 0 or 1 on success, -1 on read error.                        */
/* ------------------------------------------------------------------ */
static int read_sensor_debounced(int gpio)
{
    int first, second;

    first = gpioRead(gpio);
    if (first < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed.\n", gpio);
        return -1;
    }

    gpioDelay(DEBOUNCE_DELAY_US);

    second = gpioRead(gpio);
    if (second < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed during debounce.\n", gpio);
        return -1;
    }

    return (first == second) ? first : -1;  /* still bouncing */
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev1 = -1, prev2 = -1;
    int rc = EXIT_SUCCESS;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                SENSOR_1_GPIO);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                SENSOR_2_GPIO);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    printf("Proximity sensor logging started.\n");
    printf("  Sensor 1: GPIO %d (physical pin 11)\n", SENSOR_1_GPIO);
    printf("  Sensor 2: GPIO %d (physical pin 13)\n", SENSOR_2_GPIO);
    printf("  Log file: %s\n", LOG_FILE_NAME);
    printf("  Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int v1 = read_sensor_debounced(SENSOR_1_GPIO);
        int v2 = read_sensor_debounced(SENSOR_2_GPIO);

        if (v1 >= 0 && v1 != prev1) {
            if (v1 == 0) {
                if (log_event(1, "DETECTED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            } else {
                if (log_event(1, "CLEARED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            }
            prev1 = v1;
        }

        if (v2 >= 0 && v2 != prev2) {
            if (v2 == 0) {
                if (log_event(2, "DETECTED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            } else {
                if (log_event(2, "CLEARED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            }
            prev2 = v2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n",
                    strerror(errno));
        }
        g_log_file = NULL;
    }

cleanup_gpio:
    gpioTerminate();
    printf("\nProximity sensor logging stopped.\n");
    return rc;
}

