    /* ---- Main polling loop ---- */
    while (g_running) {
        int v1 = read_sensor_debounced(SENSOR_1_GPIO);
        int v2 = read_sensor_debounced(SENSOR_2_GPIO);

        if (v1 >= 0 && v1 != prev1) {
            if (v1 == 0) {
                if (log_event(1, "DETECTED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            } else {
                if (log_event(1, "CLEARED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            }
            prev1 = v1;
        }

        if (v2 >= 0 && v2 != prev2) {
            if (v2 == 0) {
                if (log_event(2, "DETECTED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            } else {
                if (log_event(2, "CLEARED") != 0) {
                    rc = EXIT_FAILURE;
                    break;
                }
            }
            prev2 = v2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n",
                    strerror(errno));
        }
        g_log_file = NULL;
    }

cleanup_gpio:
    gpioTerminate();
    printf("\nProximity sensor logging stopped.\n");
    return rc;
}

