/*
 * CH-101 Time-of-Flight sensor reader for Raspberry Pi 5 (smart parking).
 * Uses the Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   CH-101 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_parking ch101_parking.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- CH-101 register map (representative subset) ---- */
#define CH101_I2C_ADDR        0x49
#define CH101_REG_MEAS_TRIGGER 0x04  /* write 0x01 to start a measurement */
#define CH101_REG_MEAS_STATUS 0x06  /* bit 0 = data-ready */
#define CH101_REG_DIST_HIGH   0x08  /* distance MSB */
#define CH101_REG_DIST_LOW    0x09  /* distance LSB */

#define I2C_BUS              "/dev/i2c-1"
#define CSV_FILE             "distance_log.csv"
#define SAMPLE_PERIOD_MS     500
#define MEAS_TIMEOUT_MS      50

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success.    */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register. Returns 0 on success.   */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    /* Send register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[I2C] write reg-addr 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte back */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 16-bit distance in mm.          */
/* Returns 0 on success and stores distance in *distance_mm.          */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    /* Trigger a single-shot measurement */
    if (i2c_write_reg8(fd, CH101_REG_MEAS_TRIGGER, 0x01) != 0)
        return -1;

    /* Poll MEAS_STATUS bit 0 until data-ready or timeout */
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        uint8_t status;
        if (i2c_read_reg8(fd, CH101_REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & 0x01) {
            uint8_t hi, lo;
            if (i2c_read_reg8(fd, CH101_REG_DIST_HIGH, &hi) != 0)
                return -1;
            if (i2c_read_reg8(fd, CH101_REG_DIST_LOW, &lo) != 0)
                return -1;
            *distance_mm = ((uint16_t)hi << 8) | lo;
            return 0;
        }
        usleep(5000); /* 5 ms */
    }

    fprintf(stderr, "[CH101] measurement timeout (%d ms)\n", MEAS_TIMEOUT_MS);
    return -1;
}

/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, uint16_t distance_mm)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[INIT] sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[INIT] open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the CH-101 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "[INIT] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log (append) */
    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "[INIT] fopen %s failed: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,distance_mm\n");

    printf("CH-101 smart-parking logger started.  Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t dist;
        if (ch101_read_distance(g_i2c_fd, &dist) == 0) {
            log_distance(g_csv, dist);
            printf("Distance: %u mm\n", dist);
        } else {
            fprintf(stderr, "[MAIN] read failed; skipping sample\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

