#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L5CX_ADDR  0x29
#define NUM_ZONES      64
#define POLL_MS        500

/* VL53L5CX register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET          0x0003
#define REG_SYSTEM_START        0x0000
#define REG_RANGE_START         0x0001
#define REG_RANGE_STATUS        0x0002
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_DISTANCE     0x0016  /* first zone distance; 2 bytes per zone */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value (big-endian) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address followed by a single byte */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg8(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting from a 16-bit register address */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_reg write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_reg read(0x%04X): got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);  /* 10 ms */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(100000); /* 100 ms for boot */

    /* Start ranging */
    if (i2c_write_reg8(fd, REG_SYSTEM_START, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_RANGE_START, 0x01) < 0) return -1;
    return 0;
}

static int vl53l5cx_read_zones(int fd, uint16_t *distances)
{
    uint8_t status = 0;
    int attempts = 0;

    /* Poll range status until data ready (bit 0) */
    while (attempts < 100) {
        if (i2c_read_reg(fd, REG_RANGE_STATUS, &status, 1) < 0) return -1;
        if (status & 0x01) break;
        usleep(1000);
        attempts++;
    }
    if (attempts >= 100) {
        fprintf(stderr, "Timeout waiting for range data ready\n");
        return -1;
    }

    /* Read 64 zone distances (2 bytes each, big-endian) */
    for (int i = 0; i < NUM_ZONES; i++) {
        uint8_t buf[2];
        if (i2c_read_reg(fd, REG_RESULT_DISTANCE + (uint16_t)(i * 2), buf, 2) < 0)
            return -1;
        distances[i] = ((uint16_t)buf[0] << 8) | buf[1];
    }

    /* Clear data-ready bit by writing 0x01 to range status */
    if (i2c_write_reg8(fd, REG_RANGE_STATUS, 0x01) < 0) return -1;
    return 0;
}

int main(void)
{
    int fd = -1;
    uint16_t distances[NUM_ZONES];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("VL53L5CX initialized. Reading %d zones every %d ms. Press Ctrl+C to exit.\n",
           NUM_ZONES, POLL_MS);

    while (g_running) {
        if (vl53l5cx_read_zones(fd, distances) < 0) {
            fprintf(stderr, "Zone read failed; continuing\n");
        } else {
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %2d: %4u mm\n", i, distances[i]);
            }
            printf("---\n");
            fflush(stdout);
        }
        usleep(POLL_MS * 1000);
    }

    /* Stop ranging */
    i2c_write_reg8(fd, REG_RANGE_START, 0x00);
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

