#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define REG_DISTANCE 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define LOOP_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_distance(uint16_t *distance) {
    char reg = REG_DISTANCE;
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
            fprintf(stderr, "I2C write error (reg select): %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_US);
