#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* VL53L4CX I2C default address */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses (16-bit, big-endian on bus) */
#define VL53L4CX_SOFT_RESET_REG  0x7FFF
#define VL53L4CX_SYSTEM_START_REG 0x0009
#define VL53L4CX_INT_STATUS_REG  0x0046
#define VL53L4CX_DISTANCE_REG_H  0x0096
#define VL53L4CX_DISTANCE_REG_L  0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address followed by a single data byte     */
/* using pigpio's i2cWriteI2CBlockData.                                 */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData failed for reg 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single 8-bit register value.                                 */
/* Returns the byte value (0-255) on success, -1 on failure.           */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg8(int handle, uint16_t reg)
{
    char buf[1];
    buf[0] = (reg >> 8) & 0xFF;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 0) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData (addr phase) failed for reg 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadI2CBlockData(handle, buf[0], buf, 1) < 0) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (uint8_t)buf[0];
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian: high byte at reg, low at reg+1). */
/* Returns the 16-bit value on success, -1 on failure.                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg16(int handle, uint16_t reg)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 0) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData (addr phase) failed for reg 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadI2CBlockData(handle, buf[0], buf, 2) < 0) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor: soft reset, wait, then start ranging.*/
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_SYSTEM_START_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write system start register.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres.                                       */
/* Returns distance on success, -1 on failure.                         */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle)
{
    int status = vl53l4cx_read_reg8(handle, VL53L4CX_INT_STATUS_REG);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status register.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* No new data ready yet */
        return -2;
    }

    int distance = vl53l4cx_read_reg16(handle, VL53L4CX_DISTANCE_REG_H);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance registers.\n");
        return -1;
    }

    /* Clear interrupt by writing 0x01 to the status register */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_INT_STATUS_REG, 0x01) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt status.\n");
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Log distance with microsecond-precision timestamp.                  */
/* ------------------------------------------------------------------ */
static void log_distance(int distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s.%06ld, Distance: %d mm\n",
           time_buf, ts.tv_nsec / 1000, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: close I2C and terminate pigpio.                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L4CX default address */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l4cx_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L4CX initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX distance sensor reading started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        int distance = vl53l4cx_read_distance(g_i2c_handle);

        if (distance >= 0) {
            log_distance(distance);
        } else if (distance == -1) {
            /* I2C error: report and continue */
            fprintf(stderr, "Warning: I2C communication error, continuing...\n");
        }
        /* distance == -2 means no new data ready; just skip */

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

