/* Cleanup helper: close I2C and terminate pigpio.                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L4CX default address */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l4cx_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L4CX initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX distance sensor reading started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        int distance = vl53l4cx_read_distance(g_i2c_handle);

        if (distance >= 0) {
            log_distance(distance);
        } else if (distance == -1) {
            /* I2C error: report and continue */
            fprintf(stderr, "Warning: I2C communication error, continuing...\n");
        }
        /* distance == -2 means no new data ready; just skip */

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

