#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0001
#define VL53L1X_REG_I2C_SLAVE_ADDR 0x0001
#define VL53L1X_REG_SYSTEM_MODE_START 0x0007
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_sensor(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        return -1;
    }
    if (write_reg16(VL53L1X_REG_SOFT_RESET, 0x0001) != 0) {
        fprintf(stderr, "Error writing soft reset\n");
        return -1;
    }
    gpioDelay(10000);
    if (write_reg16(VL53L1X_REG_I2C_SLAVE_ADDR, VL53L1X_ADDR) != 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        return -1;
    }
    if (write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(uint16_t *distance) {
    return read_reg16(VL53L1X_REG_RESULT_DISTANCE, distance);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int buzzer_on = 0;
    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                if (!buzzer_on) {
                    gpioWrite(BUZZER_GPIO, 1);
                    buzzer_on = 1;
                }
            } else {
                if (buzzer_on) {
                    gpioWrite(BUZZER_GPIO, 0);
                    buzzer_on = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading distance. Re-initializing sensor.\n");
            if (init_sensor() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

