#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG   -90
#define MAX_ANGLE_DEG   90

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          50000
#define LOOP_DELAY_US            200000
#define SERVO_SETTLE_US          100000

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output.\n", SERVO_PIN);
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise servo to 0 us.\n");
        return -1;
    }

    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0;
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor not responding).\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout (stuck high).\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f].\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance_cm;
}

static int set_servo_angle(double distance_cm) {
    if (distance_cm < 0) {
        return -1;
    }

    double angle = MIN_ANGLE_DEG +
                   (distance_cm - MIN_DISTANCE_CM) *
                   (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;

    int pulse_width = (int)(1000 + (angle + 90.0) * 10.0);
    if (pulse_width < 500) pulse_width = 500;
    if (pulse_width > 2500) pulse_width = 2500;

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us.\n", pulse_width);
        return -1;
    }
    return 0;
}

static void log_data(double distance_cm) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open sensor_data.log for append.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    fclose(fp);
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        double distance = measure_distance();

        if (distance >= 0) {
            if (set_servo_angle(distance) < 0) {
                fprintf(stderr, "Warning: failed to set servo angle.\n");
            }
            log_data(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: invalid distance reading, skipping.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking assist system stopped.\n");
    return 0;
}

