        }
        retries++;
        gpioDelay(100000);
    }
    if (retries == MAX_INIT_RETRIES) {
        fprintf(stderr, "Error: Sensor model ID check failed after %d retries.\n", MAX_INIT_RETRIES);
        return -1;
    }

    if (i2c_write_reg16((REG_SOFT_RESET >> 8) & 0xFF, REG_SOFT_RESET & 0xFF, 0x00) != 0) {
        fprintf(stderr, "Error: Software reset (step 1) failed.\n");
        return -1;
