#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         400.0
#define BUZZER_THRESHOLD_CM     30.0
#define ECHO_TIMEOUT_US         300000   /* 300 ms max echo wait */
#define SAMPLE_PERIOD_US        100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 minutes.
 * tick_diff correctly handles the single wraparound.
 */
static uint32_t tick_diff(uint32_t start, uint32_t end) {
    return end - start;  /* unsigned subtraction wraps correctly */
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);       /* 10 us HIGH pulse */
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * pigpio alert callback.  Called on rising and falling edges of ECHO_PIN.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    static uint32_t start_tick = 0;
    static int      have_start = 0;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
        have_start = 1;
    } else if (level == 0 && have_start) {
        /* Falling edge: echo pulse ends */
        uint32_t pulse_us = tick_diff(start_tick, tick);
        double   distance = (pulse_us / 1000000.0) * SPEED_OF_SOUND_CM_PER_S / 2.0;

        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
            printf("Distance: %.2f cm\n", distance);
            if (distance < BUZZER_THRESHOLD_CM) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            printf("Invalid distance reading: %.2f cm (out of range)\n", distance);
            gpioWrite(BUZZER_PIN, 0);
        }
        have_start = 0;
    }
    /* level == 2 (timeout) is ignored here; handled in main loop */
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register interrupt-driven alert on ECHO_PIN */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        /* Wait for echo callback to process the pulse, or detect timeout */
        uint32_t start_wait = gpioTick();
        int      have_echo  = 0;

        while (running) {
            uint32_t elapsed = tick_diff(start_wait, gpioTick());
            if (elapsed > ECHO_TIMEOUT_US) {
                break;  /* timeout: no echo received */
            }
            if (gpioRead(ECHO_PIN) == 0) {
                have_echo = 1;
                break;
            }
            gpioDelay(1000);  /* 1 ms poll */
        }

        if (!have_echo) {
            printf("Sensor absent or no echo received (timeout).\n");
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

