#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define SERVO_OPEN_US 1500
#define SERVO_CLOSED_US 500
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate/commands"
#define MQTT_STATUS_TOPIC "gate/status"
#define MQTT_SERVER "tcp://localhost:1883"
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static MQTTClient mqtt_client;
static int gate_open = 0;
static int pigpio_initialized = 0;
static int mqtt_connected = 0;

static const char *status_str(int open) { return open ? "OPEN" : "CLOSED"; }

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (i2cWriteDevice(handle, buf, 2) == 2) return 0;
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out) {
    char reg_buf[1] = { (char)reg };
    char data[2];
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (i2cWriteDevice(handle, reg_buf, 1) != 1) { gpioDelay(I2C_RETRY_DELAY_US); continue; }
        if (i2cReadDevice(handle, data, 2) != 2) { gpioDelay(I2C_RETRY_DELAY_US); continue; }
        *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        return 0;
    }
    return -1;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg8(handle, 0x00, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg8(handle, 0x88, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x80, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, 0x00, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x91, 0x3C) < 0) return -1;
    if (i2c_write_reg8(handle, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, 0xFF, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x80, 0x00) < 0) return -1;
    return 0;
}

static int read_distance(int handle, int *distance_mm) {
    uint16_t dist;
    if (i2c_read_reg16(handle, 0x14, &dist) < 0) return -1;
    *distance_mm = (int)dist;
    return 0;
}

static void control_servo(int open) {
    int us = open ? SERVO_OPEN_US : SERVO_CLOSED_US;
    if (gpioServo(SERVO_PIN, us) < 0) {
        log_event("ERROR: gpioServo failed");
        return;
    }
    gate_open = open;
    log_event(open ? "Gate opened" : "Gate closed");
}

static void mqtt_connect(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    int rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc == MQTTCLIENT_SUCCESS) {
        mqtt_connected = 1;
        log_event("MQTT connected");
    } else {
        fprintf(stderr, "MQTT connect failed: %s\n", MQTTClient_strerror(rc));
    }
}

static void mqtt_disconnect(void) {
    if (mqtt_connected) {
        MQTTClient_disconnect(mqtt_client, 1000);
        mqtt_connected = 0;
        log_event("MQTT disconnected");
    }
}

static int mqtt_publish(const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static void mqtt_message_arrived(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicLen;
    char payload[256];
    int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
    if (strcmp(payload, "force_open") == 0) {
        control_servo(1);
        mqtt_publish(MQTT_STATUS_TOPIC, status_str(1));
    } else if (strcmp(payload, "force_close") == 0) {
        control_servo(0);
        mqtt_publish(MQTT_STATUS_TOPIC, status_str(0));
    } else if (strcmp(payload, "status_request") == 0) {
        mqtt_publish(MQTT_STATUS_TOPIC, status_str(gate_open));
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (pigpio_initialized) {
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (mqtt_connected) mqtt_disconnect();
    MQTTClient_destroy(&mqtt_client);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        cleanup();
        return 1;
