    if (MQTTClient_create(&mqtt_client, MQTT_SERVER, MQTT_CLIENT_ID,
                          MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT create failed\n");
        cleanup();
        return 1;
    }

    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, mqtt_message_arrived, NULL);
    mqtt_connect();

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int dist_mm;
        if (read_distance(i2c_handle, &dist_mm) == 0) {
            int detected = (dist_mm > 0 && dist_mm < DISTANCE_THRESHOLD * 10);
            if (detected && !gate_open) {
