                mqtt_publish(MQTT_STATUS_TOPIC, status_str(1));
            } else if (!detected && gate_open) {
                control_servo(0);
                mqtt_publish(MQTT_STATUS_TOPIC, status_str(0));
            }
        } else {
            log_event("ERROR: distance read failed");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

