/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 * Library: pigpio (C API)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM) via 5V->3.3V divider
 *   VCC  -> 5V, GND -> GND
 *
 * NOTE: The HC-SR04 ECHO output is 5V; do NOT connect it directly to
 * a Raspberry Pi GPIO pin. Use a voltage divider (e.g., 1k/2k) or a
 * dedicated 5V->3.3V logic-level converter.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define MEASURE_PERIOD_US 200000     /* 200 ms between measurements    */
#define ECHO_TIMEOUT_US  60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US     100         /* reject noise below this        */
#define MAX_PULSE_US     30000       /* reject timeout above this      */
#define SPEED_OF_SOUND   0.0343f     /* cm/us (343 m/s)                */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rising_tick  = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_got_rising   = false;
static volatile bool     g_got_falling  = false;
static volatile bool     g_echo_done    = false;

static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for ECHO pin edges                            */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_rising_tick  = tick;
        g_got_rising   = true;
        g_got_falling  = false;
        g_echo_done    = false;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        g_falling_tick = tick;
        g_got_falling  = true;
        g_echo_done    = true;
    }
    /* level == 2 (timeout) is ignored */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 min.
 * Compute (b - a) correctly across a single wraparound.
 */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static void log_line(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stdout, "%s %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s %s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Measurement cycle                                                   */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns:
 *   0  on success (distance stored in *out_cm)
 *  -1  on timeout (no echo within ECHO_TIMEOUT_US)
 *  -2  on invalid pulse width
 */
static int measure_distance(float *out_cm)
{
    g_rising_tick  = 0;
    g_falling_tick = 0;
    g_got_rising   = false;
    g_got_falling  = false;
    g_echo_done    = false;

    trigger_sensor();

    /* Wait for the falling edge or until timeout */
    uint32_t start = gpioTick();
    while (!g_echo_done && g_running) {
        if (tick_diff(start, gpioTick()) > ECHO_TIMEOUT_US)
            break;
        gpioDelay(100);  /* poll every 100 us */
    }

    if (!g_got_falling) {
        return -1;  /* timeout */
    }

    if (!g_got_rising) {
        return -2;  /* no rising edge captured */
    }

    uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        return -2;  /* out of range */
    }

    *out_cm = (float)pulse_us * SPEED_OF_SOUND / 2.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (!g_log_fp) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_line("HC-SR04 measurement started (TRIG=GPIO23, ECHO=GPIO24)");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        float distance_cm = 0.0f;
        int rc = measure_distance(&distance_cm);

        if (rc == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_line(msg);
        } else if (rc == -1) {
            log_line("Warning: echo timeout — no object detected or sensor absent");
        } else {
            log_line("Warning: invalid echo pulse width — possible noise or out-of-range");
        }

        /* Sleep for the remainder of the measurement period */
        uint32_t elapsed = tick_diff(g_rising_tick, gpioTick());
        if (elapsed < MEASURE_PERIOD_US) {
            gpioDelay(MEASURE_PERIOD_US - elapsed);
        }
    }

    /* ---- Cleanup ---- */
    log_line("Shutting down...");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

