#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18

#define OPEN_DISTANCE_CM 50
#define CLOSE_DISTANCE_CM 60
#define SERVO_OPEN_US 1000
#define SERVO_CLOSE_US 2000
#define POLL_DELAY_US 100000
#define LOG_FILE "parking_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0061
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int gate_open = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(uint8_t reg_msb, uint8_t reg_lsb, uint8_t value) {
    char buf[3] = {reg_msb, reg_lsb, value};
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_msb, uint8_t reg_lsb, uint8_t *buf, uint32_t len) {
    char reg[2] = {reg_msb, reg_lsb};
    if (i2cWriteDevice(i2c_handle, reg, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_init(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(0x01, 0x0F, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(0x00, 0x00, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(0x00, 0x00, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(0x00, 0x00, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(0x00, 0x00, 0x01) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance_mm(void) {
    uint8_t status = 0;
    if (i2c_read_reg16(0x00, 0x44, &status, 1) < 0) return -1;
    if (!(status & 0x07)) return -1;

    uint8_t data[2] = {0};
    if (i2c_read_reg16(0x00, 0x96, data, 2) < 0) return -1;
    i2c_write_reg16(0x00, 0x61, 0x01);

    int distance_mm = (data[0] << 8) | data[1];
    return distance_mm;
}

static void control_servo(int open) {
    if (open) {
        if (gpioServo(SERVO_PIN, SERVO_OPEN_US) < 0) {
            fprintf(stderr, "Warning: Failed to set servo open.\n");
        }
    } else {
        if (gpioServo(SERVO_PIN, SERVO_CLOSE_US) < 0) {
            fprintf(stderr, "Warning: Failed to set servo close.\n");
        }
    }
}

static void log_event(int distance_mm, int open) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    int distance_cm = (distance_mm >= 0) ? (distance_mm / 10) : -1;
    fprintf(log_file, "%s, Distance: %d cm, Gate: %s\n", timestamp, distance_cm, open ? "Open" : "Closed");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(100000);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at addr 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        cleanup();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance_mm = vl53l1x_read_distance_mm();
        int distance_cm = (distance_mm >= 0) ? (distance_mm / 10) : -1;

        if (distance_cm > 0) {
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= OPEN_DISTANCE_CM && !gate_open) {
                control_servo(1);
                gate_open = 1;
                log_event(distance_mm, 1);
                printf("Gate opened.\n");
            } else if (distance_cm > CLOSE_DISTANCE_CM && gate_open) {
                control_servo(0);
                gate_open = 0;
                log_event(distance_mm, 0);
                printf("Gate closed.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read error or no object detected.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

