#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

#define GPIO_OPEN 18
#define GPIO_CLOSE 19

#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E
#define VL53L1X_REG_TIMING_BUDGET 0x001C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr_buf[0], &addr_buf[1], 1) < 0) {
        return -1;
    }
    return i2cReadI2CBlockData(handle, addr_buf[0], (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_TIMING_BUDGET, 0x0031) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    return i2c_write_reg16(handle, VL53L1X_REG_RANGE_START, 0x01);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }
    uint8_t buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) < 0) {
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(log_file, "%s - %s\n", ts, event);
    fflush(log_file);
}

static void control_gate(int open) {
    gpioWrite(GPIO_OPEN, open ? 1 : 0);
    gpioWrite(GPIO_CLOSE, open ? 0 : 1);
}

