    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        int rc = vl53l1x_read_distance(i2c_handle, &distance);
        if (rc == 0) {
            int open = (distance < DISTANCE_THRESHOLD_MM);
