#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18

#define DISTANCE_THRESHOLD_1 100  /* mm (10 cm) */
#define DISTANCE_THRESHOLD_2 300  /* mm (30 cm) */

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_INT_STATUS 0x0089
#define VL53L1X_REG_DISTANCE_MSB 0x0096
#define VL53L1X_REG_DISTANCE_LSB 0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to soft-reset VL53L1X.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X measurement.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int retries = 0;
    const int max_retries = 10;

    while (retries < max_retries) {
        if (i2c_read_byte(handle, VL53L1X_REG_INT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read VL53L1X status (attempt %d).\n", retries + 1);
            gpioDelay(10000); /* 10 ms backoff */
            retries++;
            continue;
        }
        if (status & 0x01) break;
        gpioDelay(1000); /* 1 ms poll interval */
        retries++;
    }

    if (retries >= max_retries) {
        fprintf(stderr, "Error: VL53L1X data not ready after %d retries.\n", max_retries);
        return -1;
    }

    uint8_t msb = 0, lsb = 0;
    if (i2c_read_byte(handle, VL53L1X_REG_DISTANCE_MSB, &msb) < 0) {
        fprintf(stderr, "Error: Failed to read distance MSB.\n");
        return -1;
    }
    if (i2c_read_byte(handle, VL53L1X_REG_DISTANCE_LSB, &lsb) < 0) {
        fprintf(stderr, "Error: Failed to read distance LSB.\n");
        return -1;
    }

    *distance = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static void control_motor(uint16_t distance) {
    if (distance < DISTANCE_THRESHOLD_1) {
        gpioWrite(GPIO_FORWARD, 1);
        gpioWrite(GPIO_BACKWARD, 0);
        printf("Motor: Forward (distance: %u mm)\n", distance);
    } else if (distance > DISTANCE_THRESHOLD_2) {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 1);
        printf("Motor: Backward (distance: %u mm)\n", distance);
    } else {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 0);
        printf("Motor: Stopped (distance: %u mm)\n", distance);
    }
}

static void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (i2c_handle < 0) return;
    uint16_t distance = 0;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        control_motor(distance);
    } else {
        fprintf(stderr, "Error: Failed to read distance. Stopping motor.\n");
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);
    gpioWrite(GPIO_FORWARD, 0);
    gpioWrite(GPIO_BACKWARD, 0);

    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR on GPIO %d.\n", GPIO_TRIGGER);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_FORWARD, 0);
    gpioWrite(GPIO_BACKWARD, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

