    if (mpr121_write_reg(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_FDLR, 0x00) < 0) return -1;

