    if (mpr121_write_reg(fd, MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_NCLT, 0x01) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 (representative) */
    if (mpr121_write_reg(fd, MPR121_E0TTH, 0x0B) < 0) return -1;
    if (mpr121_write_reg(fd, MPR121_E0RTH, 0xC8) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA */
    if (mpr121_write_reg(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

