#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG1 0x5C
#define MPR121_AFE_CONFIG2 0x5D
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_read(uint8_t reg) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
    }
    return result;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AFE_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_AFE_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write(MPR121_TL, 0xB4) < 0) return -1;

    if (mpr121_write(MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E0RTH, 0x05) < 0) return -1;

    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(uint16_t *status) {
    int low = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen("proximity.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

static void cleanup(void) {
