#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 0.0343
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define TRIGGER_SETTLE_US 5
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", info);
}

static void log_distance(double distance) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (distance < 0.0) {
        fprintf(log_file, "%s, ERROR: %s\n", ts, "timeout or sensor absent");
    } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "%s, ERROR: distance out of range (%.2f cm)\n", ts, distance);
    } else {
        fprintf(log_file, "%s, Distance: %.2f cm\n", ts, distance);
    }
    fflush(log_file);
}

static long measure_pulse(struct gpiod_line *echo_line) {
    struct timespec start, end;
    long elapsed_us;
    int val;

    /* Wait for echo rising edge */
    for (;;) {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) break;
        if (!program_running) return -1;
        usleep(1);
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge */
    for (;;) {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) break;
        if (!program_running) return -1;
        usleep(1);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                 (end.tv_nsec - start.tv_nsec) / 1000L;
    return elapsed_us;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    gpiod_line_set_value(trigger_line, 0);
    usleep(100000);

    while (program_running) {
        /* Trigger: low for 5 us, high for 10 us, low */
        gpiod_line_set_value(trigger_line, 0);
        usleep(TRIGGER_SETTLE_US);
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        long pulse_us = measure_pulse(echo_line);
        if (pulse_us < 0) {
            log_distance(-1.0);
        } else if (pulse_us > TIMEOUT_US) {
            log_distance(-1.0);
        } else {
            double distance = (pulse_us * SPEED_OF_SOUND) / 2.0;
            log_distance(distance);
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return ret;
}

