#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000
#define ECHO_TIMEOUT_US  30000
#define MIN_PULSE_US     58
#define MAX_PULSE_US     25000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ISR state */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_pulse_us   = 0;
static volatile int      g_echo_ready = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
    } else if (level == 0) {
        uint32_t elapsed = tick - g_start_tick; /* handles 32-bit wraparound */
        g_pulse_us = elapsed;
        g_echo_ready = 1;
    }
}

static void fire_trigger(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * 343.0f / 2000000.0f;
}

static void log_distance(float distance, uint32_t pulse_us)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log, "%s, Distance: %.2f m, Pulse: %u us\n",
            timestamp, distance, pulse_us);
    fflush(g_log);
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000); /* 50 ms settle */

    /* --- ISR registration --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        g_echo_ready = 0;
        g_pulse_us   = 0;

        fire_trigger();

        /* Wait for echo or timeout */
        uint32_t waited = 0;
        while (!g_echo_ready && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_ready) {
            fprintf(stderr, "Warning: echo timeout (no object detected or sensor absent).\n");
            continue;
        }

        if (g_pulse_us < MIN_PULSE_US || g_pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse out of range (%u us).\n", g_pulse_us);
            continue;
        }

        float distance = calculate_distance(g_pulse_us);
        log_distance(distance, g_pulse_us);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

