#include <string.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define POLL_DELAY_US 100000

#define REG_SYSTEM_MODE_START 0x0018
#define REG_RANGE_STATUS 0x0016
#define REG_RANGE_RESULT 0x0014
#define REG_RANGE_CONFIG 0x0019
#define REG_RANGE_START 0x0020

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_sensor(int handle) {
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    if (write_reg16(handle, REG_RANGE_CONFIG, 0x00) < 0) return -1;
    if (write_reg16(handle, REG_RANGE_START, 0x01) < 0) return -1;
    return 0;
}

static void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s Distance: %d mm, Status: 0x%02X", ts, distance, status);
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X: %d", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) < 0) {
        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint8_t status_buf[1];
        uint8_t dist_buf[2];

        if (read_reg16(i2c_handle, REG_RANGE_STATUS, status_buf, 1) < 0) {
            syslog(LOG_ERR, "Failed to read range status");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (read_reg16(i2c_handle, REG_RANGE_RESULT, dist_buf, 2) < 0) {
            syslog(LOG_ERR, "Failed to read range result");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance = (dist_buf[1] << 8) | dist_buf[0];
        int status = status_buf[0];

        log_data(distance, status);
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

