#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GATE_GPIO      24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_MODEL_ID          0x010F
#define REG_RANGE_STATUS      0x0089
#define REG_RANGE_MM          0x0096
#define REG_SYSTEM_MODE       0x0015
#define REG_RANGE_CONFIG      0x0021
#define REG_SOFT_RESET        0x000B

#define EXPECTED_MODEL_ID     0xEA
#define RANGE_STATUS_DATA_READY 0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char wbuf[2];
    wbuf[0] = (reg >> 8) & 0xFF;
    wbuf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, wbuf, 2) < 0)
        return -1;
    char rbuf[1];
    if (i2cReadDevice(handle, rbuf, 1) != 1)
        return -1;
    *value = (uint8_t)rbuf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char wbuf[2];
    wbuf[0] = (reg >> 8) & 0xFF;
    wbuf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, wbuf, 2) < 0)
        return -1;
    char rbuf[2];
    if (i2cReadDevice(handle, rbuf, 2) != 2)
        return -1;
    *value = ((uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X sensor                                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) < 0) {
        log_event("Error: failed to read model ID from sensor");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Error: unexpected model ID 0x%02X (expected 0x%02X)",
                 model_id, EXPECTED_MODEL_ID);
        log_event(msg);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x00) < 0) {
        log_event("Error: soft reset write failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set ranging mode to short (0x00) */
    if (i2c_write_reg8(handle, REG_RANGE_CONFIG, 0x00) < 0) {
        log_event("Error: failed to set range config");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg8(handle, REG_SYSTEM_MODE, 0x01) < 0) {
        log_event("Error: failed to start ranging");
        return -1;
    }

    log_event("VL53L1X initialised successfully");
    return 0;
}

static int vl53l1x_read_distance_cm(int handle, int *distance_cm)
{
    uint8_t status = 0;
    if (i2c_read_reg8(handle, REG_RANGE_STATUS, &status) < 0) {
        log_event("Error: failed to read range status");
        return -1;
    }
    if ((status & RANGE_STATUS_DATA_READY) == 0) {
        return 1; /* not ready yet */
    }

    uint16_t distance_mm = 0;
    if (i2c_read_reg16(handle, REG_RANGE_MM, &distance_mm) < 0) {
        log_event("Error: failed to read distance register");
        return -1;
    }

    *distance_cm = (int)(distance_mm / 10);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                       */
/* ------------------------------------------------------------------ */
static void gate_set(int state)
{
    gpioWrite(GATE_GPIO, state);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_event("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("gate_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error opening I2C bus %d addr 0x%02X: %d",
                 I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        log_event(msg);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure gate GPIO */
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gate_set(0); /* start closed */

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    int gate_state = 0;

    while (g_running) {
        int distance_cm = 0;
        int rc = vl53l1x_read_distance_cm(g_i2c_handle, &distance_cm);

        if (rc == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_event(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM && gate_state == 0) {
                gate_set(1);
                gate_state = 1;
                log_event("Gate opened");
            } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_state == 1) {
                gate_set(0);
                gate_state = 0;
                log_event("Gate closed");
            }
        } else if (rc < 0) {
            log_event("Sensor read error");
        }
        /* rc == 1: data not ready yet, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gate_set(0);
    cleanup();
    return EXIT_SUCCESS;
}

