#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define TIMEOUT_US     30000
#define TRIGGER_PULSE_US 10
#define SAMPLES        5
#define LOOP_DELAY_US  100000
#define SERVO_MIN_US   500
#define SERVO_MAX_US   2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Shared state between alert callback and main thread */
static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end   = 0;
static volatile int      echo_seen   = 0;
static volatile int      reading_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start = tick;
        echo_seen = 0;
    } else if (level == 0) {
        pulse_end = tick;
        echo_seen = 1;
        reading_ready = 1;
    }
}

static double measure_distance(void) {
    pulse_start = 0;
    pulse_end   = 0;
    echo_seen   = 0;
    reading_ready = 0;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    while (!reading_ready && (gpioTick() - start_tick) < TIMEOUT_US) {
        gpioDelay(100);
    }

    if (!echo_seen) {
        return -1.0;
    }

    uint32_t pulse_width = pulse_end - pulse_start; /* handles 32-bit wrap */
    double distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static double moving_average(double new_value, double *history, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += history[i];
    }
    for (int i = size - 1; i > 0; i--) {
        history[i] = history[i - 1];
    }
    history[0] = new_value;
    return sum / size;
}

static int distance_to_angle(double distance) {
    if (distance < 0) return 90;
    if (distance < 10) return 0;
    if (distance > 300) return 180;
    double angle = (int)(180.0 * (log10(distance + 1.0) / log10(301.0)));
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return (int)angle;
}

static int angle_to_pulse_width(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_MIN_US + (int)((angle / 180.0) * (SERVO_MAX_US - SERVO_MIN_US));
}

static int set_servo_angle(int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    int rc = gpioServo(SERVO_PIN, pulse_width);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioServo failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(log_file);
}

int main(void) {
    double distance_history[SAMPLES] = {0.0};
    int servo_angle = 90;
    int rc;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (rc=%d)\n", rc);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv\n");
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurement and servo tracking...\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Warning: invalid distance reading, using default\n");
            distance = -1.0;
        } else {
            distance = moving_average(distance, distance_history, SAMPLES);
        }

        if (distance >= 0) {
            servo_angle = distance_to_angle(distance);
        } else {
            servo_angle = 90;
        }

        if (set_servo_angle(servo_angle) < 0) {
            fprintf(stderr, "Warning: failed to set servo angle\n");
        }

        log_data(distance, servo_angle);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

