#define BUFFER_SIZE 10
#define THRESHOLD_MM 200
#define POLL_DELAY_US 50000

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static int16_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
