static int write_reg16(uint8_t reg, uint16_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)(value & 0xFF) };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;
    *value = (uint16_t)((uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

