#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define INTERRUPT_GPIO 27

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static volatile uint16_t proximity_value = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    int high = i2cReadByteData(handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %d\n", low);
        return -1;
    }
    *prox = ((uint16_t)high << 8) | (uint16_t)low;
    return 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    interrupt_flag = 1;
}

static void log_proximity(uint16_t prox, bool alert) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Proximity: %u, Status: %s\n", ts, prox, alert ? "ALERT" : "SAFE");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR on GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C: 0x%02X\n", threshold, i2c_address);

    while (running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            uint16_t prox;
            if (read_proximity(i2c_handle, &prox) == 0) {
                proximity_value = prox;
                bool alert = (prox > threshold);
                log_proximity(prox, alert);
                if (alert) {
                    printf("ALERT: Proximity %u exceeds threshold %d\n", prox, threshold);
                }
            } else {
                fprintf(stderr, "Failed to read proximity\n");
            }
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

