#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND 29.1f   /* cm/us */
#define MIN_DISTANCE   2.0f    /* cm */
#define MAX_DISTANCE   400.0f  /* cm */
#define THRESHOLD      10.0f   /* cm */
#define TIMEOUT_US     50000   /* 50 ms */
#define LOOP_DELAY_US  500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the width of the echo pulse in microseconds.
 * Returns -1 on timeout or pigpio error.
 */
static long measure_echo_pulse(void) {
    uint32_t start_tick = 0;
    uint32_t end_tick = 0;
    uint32_t timeout_start = gpioTick();

    /* Wait for echo to go high (start of pulse) */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_width_us) {
    return (float)pulse_width_us / 2.0f / SPEED_OF_SOUND;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(1000); /* 1 ms settle */

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Send 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high\n");
            break;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low\n");
            break;
        }

        long pulse_width = measure_echo_pulse();

        if (pulse_width < 0) {
            printf("Invalid reading (timeout)\n");
        } else {
            float distance = calculate_distance(pulse_width);
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < THRESHOLD) {
                    printf("Too close!\n");
                }
            }
        }

        /* Sleep 500 ms; gpioDelay is non-blocking-friendly but we need a delay */
        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

