#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET   0x30
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_PART_ID      0x41
#define SI1120_RESET_CMD    0x01

#define I2C_BUS            1
#define LOG_FILE           "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_als(int handle, uint16_t *als)
{
    uint8_t lo, hi;
    if (i2c_read_reg(handle, SI1120_REG_ALS_DATA0, &lo) != 0)
        return -1;
    if (i2c_read_reg(handle, SI1120_REG_ALS_DATA1, &hi) != 0)
        return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ps1(int handle, uint16_t *ps1)
{
    uint8_t lo, hi;
    if (i2c_read_reg(handle, SI1120_REG_PS1_DATA0, &lo) != 0)
        return -1;
    if (i2c_read_reg(handle, SI1120_REG_PS1_DATA1, &hi) != 0)
        return -1;
    *ps1 = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t ps1)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, ALS: %u, PS1: %u\n", ts, als, ps1);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(g_i2c_handle, SI1120_REG_RESET, SI1120_RESET_CMD) != 0) {
        fprintf(stderr, "Sensor reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    uint8_t part_id = 0;
    if (i2c_read_reg(g_i2c_handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0, ps1 = 0;
        int als_ok = read_als(g_i2c_handle, &als);
        int ps1_ok = read_ps1(g_i2c_handle, &ps1);

        if (als_ok == 0 && ps1_ok == 0) {
            log_data(g_log_file, als, ps1);
        } else {
            fprintf(stderr, "Sensor read error (ALS: %d, PS1: %d)\n",
                    als_ok, ps1_ok);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

