#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND 0.0343f   /* cm/us */
#define DISTANCE_THRESHOLD 20.0f /* cm */
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0; /* 0=idle, 1=rising seen, 2=falling seen */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN low\n");
        return -1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on ECHO_PIN %d\n", ECHO_PIN);
        return -1;
    }
    return 0;
}

static float measure_distance(void) {
    echo_state = 0;
    start_tick = 0;
    end_tick = 0;

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low\n");
        return -1.0f;
    }

    /* Wait up to 30 ms for the falling edge (echo pulse max ~23 ms for 4 m) */
    for (int i = 0; i < 30000; i++) {
        if (echo_state == 2) {
            uint32_t diff = end_tick - start_tick;
            return (float)diff * SPEED_OF_SOUND / 2.0f;
        }
        gpioDelay(1);
    }
    return -1.0f;
}

static void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(BUZZER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set BUZZER_PIN high\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set BUZZER_PIN low\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("HC-SR04 distance monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Warning: measurement failed (timeout or error)\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

