#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define MAX_ANGLE 180.0
#define MIN_ANGLE 0.0

#define SERVO_MIN_PULSE 500
#define SERVO_MID_PULSE 1500
#define SERVO_MAX_PULSE 2500

#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff * SPEED_OF_SOUND) / 2000000.0;
    return distance;
}

float calculate_angle(float distance) {
    if (distance < 0) return -1.0;
    if (distance >= MAX_DISTANCE) return MIN_ANGLE;
    if (distance <= MIN_DISTANCE) return MAX_ANGLE;
    float angle = MAX_ANGLE - (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    return angle;
}

int set_servo_angle(float angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range\n");
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE + (int)((angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor error, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float angle = calculate_angle(distance);
        if (angle < 0) {
            fprintf(stderr, "Angle calculation error\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Servo set error\n");
        }

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Parking Assist System stopped.\n");
    return 0;
}

