#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0;
    }
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    float distance = (float)pulse_duration * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / MAX_ANGLE;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Warning: distance measurement failed, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle;
        if (distance <= 20.0) {
            angle = MIN_ANGLE;
        } else if (distance >= 200.0) {
            angle = MAX_ANGLE;
        } else {
            angle = (int)(((distance - 20.0) / (200.0 - 20.0)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
        }

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Warning: servo set failed\n");
        }

        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

