#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define REG_TEMP 0x01
#define REG_HUM 0x02
#define REG_CONFIG 0x03
#define CONFIG_INTERNAL 0x00
#define CONV_DELAY_US 10000
#define POLL_DELAY_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(void) {
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, CONFIG_INTERNAL) < 0) {
        fprintf(stderr, "Error writing CONFIG register\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return ((175.72f * (float)raw) / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    return ((125.0f * (float)raw) / 65536.0f) - 6.0f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        uint16_t raw_temp, raw_hum;

        if (read_register(REG_TEMP, &raw_temp) < 0) {
            fprintf(stderr, "Temperature read failed, re-initialising I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C: %d\n", i2c_handle);
                break;
            }
            if (init_sensor() < 0) {
                fprintf(stderr, "Sensor re-init failed\n");
                break;
            }
            continue;
        }

        if (read_register(REG_HUM, &raw_hum) < 0) {
            fprintf(stderr, "Humidity read failed, re-initialising I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C: %d\n", i2c_handle);
                break;
            }
            if (init_sensor() < 0) {
                fprintf(stderr, "Sensor re-init failed\n");
                break;
            }
            continue;
        }

        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_hum);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

