#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_EXPECTED 0x68

/* Scaling factors for default ranges */
#define ACCEL_SCALE 16384.0f  /* +/- 2g  */
#define GYRO_SCALE  131.0f    /* +/- 250 deg/s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    int status;

    /* Verify device identity */
    status = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (I2C error %d)\n", status);
        return -1;
    }
    if (status != MPU6050_WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                        status, MPU6050_WHO_AM_I_EXPECTED);
        return -1;
    }

    /* Reset the device */
    status = i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x80);
    if (status < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (reset) (I2C error %d)\n", status);
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization delay */

    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    status = i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to wake PWR_MGMT_1 (I2C error %d)\n", status);
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    status = i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x07);
    if (status < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV (I2C error %d)\n", status);
        return -1;
    }

    /* DLPF config: 0x00 -> internal 8 MHz / 1 KHz, no filter */
    status = i2cWriteByteData(handle, MPU6050_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to write CONFIG (I2C error %d)\n", status);
        return -1;
    }

    /* Gyro: +/- 250 deg/s (FS_SEL = 0) */
    status = i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG (I2C error %d)\n", status);
        return -1;
    }

    /* Accel: +/- 2g (AFS_SEL = 0) */
    status = i2cWriteByteData(handle, MPU6050_ACCEL_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG (I2C error %d)\n", status);
        return -1;
    }

    return 0;
}

static int read_mpu6050_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];
    int status;

    status = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (status < 0) {
        fprintf(stderr, "Error: I2C block read failed (I2C error %d)\n", status);
        return -1;
    }
    if (status != 14) {
        fprintf(stderr, "Error: short read: got %d bytes, expected 14\n", status);
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (I2C error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised. Logging data every 100 ms (Ctrl+C to stop).\n");

    /* Main loop */
    while (g_running) {
        if (read_mpu6050_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

