    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (I2C error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised. Logging data every 100 ms (Ctrl+C to stop).\n");

    /* Main loop */
    while (g_running) {
        if (read_mpu6050_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

