#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *temp_c) {
    uint8_t buf[3];
    ssize_t w, r;

    buf[0] = reg;
    w = write(fd, buf, 1);
    if (w != 1) {
        return -1;
    }

    usleep(10000);

    r = read(fd, buf, 3);
    if (r != 3) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[0];
    *temp_c = (float)raw * 0.02 - 273.15;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        return -1;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }

    if (fflush(log_fp) != 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        i2c_fd = -1;
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(i2c_fd);
        i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MLX90614 temperature logger started. Logging to %s every %d seconds.\n",
           LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int amb_ok = i2c_read_reg16(i2c_fd, AMBIENT_TEMP_REG, &ambient);
        int obj_ok = i2c_read_reg16(i2c_fd, OBJECT_TEMP_REG, &object);

        if (amb_ok != 0 || obj_ok != 0) {
            fprintf(stderr, "Error reading temperature data (amb_ok=%d, obj_ok=%d): %s\n",
                    amb_ok, obj_ok, strerror(errno));
        } else {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error logging temperature data: %s\n", strerror(errno));
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

