#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD_MSB 0x24
#define MEASURE_CMD_LSB 0x00
#define MEASUREMENT_DELAY_US 20000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_fp) {
        fprintf(error_fp, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
        fflush(error_fp);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
}

static int read_sts30_temperature(int handle, float *temperature) {
    char cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    char buf[3];
    int result;

    result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to STS30");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, buf, 3);
    if (result != 3) {
        log_error("Failed to read measurement data from STS30");
        return -1;
    }

    unsigned int raw_temp = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);

    return 0;
}

static void log_temperature(FILE *fp, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(fp);
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", STS30_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        fprintf(stderr, "Failed to open error log file '%s': %s\n", ERROR_LOG_FILE, strerror(errno));
        fclose(log_fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register SIGTERM handler");
    }

    printf("Starting temperature monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sts30_temperature(i2c_handle, &temperature) == 0) {
            log_temperature(log_fp, temperature);
        } else {
            log_error("Failed to read temperature from STS30");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nCleaning up and exiting...\n");
    if (log_fp) fclose(log_fp);
    if (error_fp) fclose(error_fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

