#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sht40_read(int fd, float *temp, float *hum) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read failed: expected 6 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d seconds.\n", LOG_FILE, POLL_INTERVAL_SEC);

    while (running) {
        float temp, hum;
        if (sht40_read(i2c_fd, &temp, &hum) == 0) {
            log_data(temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

