#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEASURE_US     1000     /* 1 ms  */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP31 */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp31(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {0x21, 0x96};
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc == 0)
            break;
        fprintf(stderr, "I2C write failed (attempt %d/%d), rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    if (rc != 0) {
        fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASURE_US);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc == 6)
            break;
        fprintf(stderr, "I2C read failed (attempt %d/%d), rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    if (rc != 6) {
        fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    int  handle = -1;
    FILE *fp   = NULL;
    int  rc    = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup_i2c;
    }

    while (g_running) {
        float pressure, temperature;

        if (read_sdp31(handle, &pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);
cleanup_gpio:
    if (fp != NULL)
        fclose(fp);
    gpioTerminate();
    return rc;
}

