#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MEASURE_US     20000    /* 20 ms max conversion time */
#define POLL_US        1000     /* 1 ms poll interval */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 2-byte measurement from the Si7015 using No Hold Master mode.
 * Returns 0 on success, -1 on error. */
static int read_measurement(int handle, uint8_t cmd, uint16_t *raw)
{
    int rc;
    uint8_t buf[2];

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }

    /* Poll until data is ready (up to MEASURE_US) */
    for (int waited = 0; waited < MEASURE_US; waited += POLL_US) {
        gpioDelay(POLL_US);
        rc = i2cReadDevice(handle, (char *)buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "i2cReadDevice after cmd 0x%02X failed: %s\n",
                    cmd, pigpio_error(rc));
            return -1;
        }
        /* rc == 0: no data yet, keep polling */
    }

    fprintf(stderr, "Timeout waiting for measurement after cmd 0x%02X\n", cmd);
    return -1;
}

static int read_temperature(int handle, float *temp)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_TEMP, &raw) != 0)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *hum)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_HUMID, &raw) != 0)
        return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f)   *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static void log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    } else {
        fprintf(fp, "<timestamp-error>, %.2f, %.2f\n", temp, hum);
    }

    fclose(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp, hum;

        if (read_temperature(g_i2c_handle, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }
        if (read_humidity(g_i2c_handle, &hum) != 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_data(temp, hum);
        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

