#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define MEAS_DELAY_MS  45
#define LOOP_DELAY_MS  100
#define LOG_FILE       "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP8xx */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu (%s)\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    if (i2c_write_cmd(fd, CMD_CONT_MEAS) < 0)
        return -1;

    sleep_ms(MEAS_DELAY_MS);

    uint8_t raw[9];
    if (i2c_read_bytes(fd, raw, sizeof(raw)) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&raw[i * 3], 2) != raw[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale = (int16_t)((raw[6] << 8) | raw[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / 200.0f - 45.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
