static int sht40_read(int fd, float *temp, float *hum) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY_MS * 1000);

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read failed: expected 6 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
