#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE    60
#define MAX_RETRIES    3
#define MEAS_DELAY_US  10000   /* 10 ms — Si7021 needs >= 10 ms after a measurement command */

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;
static int    i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_fan(void) {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        return -1;
    }
    if (gpioWrite(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error writing GPIO %d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

/*
 * Read a 2-byte measurement from the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int read_measurement(uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int  attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByte(i2c_handle, cmd) < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), attempt %d/%d\n",
                    cmd, attempt + 1, MAX_RETRIES);
            gpioDelay(MEAS_DELAY_US);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);

        int n = i2cReadDevice(i2c_handle, buf, 2);
        if (n == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (cmd 0x%02X, got %d bytes), attempt %d/%d\n",
                cmd, n, attempt + 1, MAX_RETRIES);
        gpioDelay(MEAS_DELAY_US);
    }
    return -1;
}

static int read_temperature(float *temperature) {
    uint16_t raw;
    if (read_measurement(0xE3, &raw) < 0) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        return -1;
    }
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *humidity) {
    uint16_t raw;
    if (read_measurement(0xE5, &raw) < 0) {
        fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
        return -1;
    }
    *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static void add_reading(float temperature, float humidity) {
    buffer[buffer_index].timestamp  = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity    = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void print_buffer(void) {
    printf("\n--- Last %d readings ---\n", buffer_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&buffer[idx].timestamp));
        printf("[%s] T=%.2f C  H=%.2f %%\n",
               ts, buffer[idx].temperature, buffer[idx].humidity);
    }
    printf("--------------------------\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0 || init_fan() < 0) {
        if (i2c_handle >= 0) i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            add_reading(temperature, humidity);
            control_fan(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
        }

        /* Sleep 2 s in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

