    if (rc < 0) {
        fprintf(stderr, "Error sending command 0x%04X: pigpio error %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_data(int handle, uint8_t *buf, int len) {
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error reading data: expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

static int is_data_ready(int handle) {
    if (send_command(handle, CMD_GET_DATA_READY_STATUS) < 0)
        return -1;
    gpioDelay(2000);  /* 2 ms processing time */
    uint8_t buf[3];
    if (read_data(handle, buf, 3) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready status\n");
        return -1;
    }
    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    return (word & 0x07FF) != 0;
