#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t command) {
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", command, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(sensor_data_t *out) {
    if (send_command(CMD_READ_MEASUREMENT) < 0) return -1;
    gpioDelay(1000);

    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error reading measurement data: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on humidity word\n");
        return -1;
    }

    out->co2 = (buf[0] << 8) | buf[1];
    out->temperature = (buf[3] << 8) | buf[4];
    out->humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_print(const circular_buffer_t *buf) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%d] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               i,
               buf->data[idx].co2,
               buf->data[idx].temperature / 100.0,
               buf->data[idx].humidity / 1000.0);
    }
    printf("--- End of Buffer ---\n\n");
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(500000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(CMD_START_PERIODIC_MEASUREMENT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);

    circular_buffer_t buffer;
    buffer_init(&buffer);

    printf("SCD40 CO2 monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        uint8_t status_buf[3];
        int status_rc = i2cReadDevice(i2c_handle, (char *)status_buf, 3);
        if (status_rc != 3) {
            fprintf(stderr, "Error reading data-ready status: %d\n", status_rc);
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }
        if (crc8(status_buf, 2) != status_buf[2]) {
            fprintf(stderr, "CRC error on data-ready status\n");
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }
        uint16_t status = (status_buf[0] << 8) | status_buf[1];
        if ((status & 0x07FF) == 0) {
            gpioDelay(100000);
            continue;
        }

        sensor_data_t sensor_data;
        if (read_measurement(&sensor_data) == 0) {
            printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
                   sensor_data.co2,
                   sensor_data.temperature / 100.0,
                   sensor_data.humidity / 1000.0);
            buffer_add(&buffer, sensor_data);
            buffer_print(&buffer);

            if (sensor_data.co2 > CO2_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

