#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000        /* 50 ms per edge wait */
#define MAX_CONSECUTIVE_ERRORS 3
#define TEMP_MIN -40.0f
#define TEMP_MAX 150.0f

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s %s\n", ts, msg);
    fflush(log_file);
}

static int wait_for_level(int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(GPIO_PIN) != level) {
        if (!program_running) return -1;
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    uint32_t t0, t1, t2;

    /* Wait for falling edge (start of high pulse) */
    if (wait_for_level(0, EDGE_TIMEOUT_US) != 0) return -1;
    t0 = gpioTick();

    /* Wait for rising edge (end of high pulse) */
    if (wait_for_level(1, EDGE_TIMEOUT_US) != 0) return -1;
    t1 = gpioTick();

    /* Wait for falling edge (end of full cycle) */
    if (wait_for_level(0, EDGE_TIMEOUT_US) != 0) return -1;
    t2 = gpioTick();

    uint32_t th = t1 - t0;  /* high pulse width in microseconds */
    uint32_t tl = t2 - t0;  /* total cycle width in microseconds */

    if (tl == 0) {
        return -1;
    }

    float ratio = (float)th / (float)tl;
    *temperature = 4215.0f - (2143.0f * ratio);

    if (*temperature < TEMP_MIN || *temperature > TEMP_MAX) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            consecutive_errors = 0;
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            fprintf(log_file, "%s Temperature: %.2f C\n", ts, temperature);
            fflush(log_file);
        } else {
            consecutive_errors++;
            log_message("ERROR: Failed to read temperature");
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

