#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEAS_CMD_HIGH_REP 0x2400
#define MEAS_DELAY_US 15000
#define LOG_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1
#define SIM_PERIOD_S 3600.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *temp_raw, uint16_t *hum_raw) {
    uint8_t cmd[2] = { (MEAS_CMD_HIGH_REP >> 8) & 0xFF, MEAS_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        *temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        *hum_raw = ((uint16_t)buf[3] << 8) | buf[4];
        return 0;
    }
    return -1;
}

static sensor_data_t convert_data(uint16_t temp_raw, uint16_t hum_raw) {
    sensor_data_t d;
    d.temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    d.humidity = 100.0f * (float)hum_raw / 65535.0f;
    return d;
}

static sensor_data_t simulate_data(sensor_data_t actual) {
    sensor_data_t sim;
    double t = time(NULL) / SIM_PERIOD_S * 2.0 * M_PI;
    sim.temperature = actual.temperature + 2.0f * sinf((float)t);
    sim.humidity = actual.humidity + 5.0f * sinf((float)t);
    return sim;
}

static void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, data.temperature, data.humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0)
        return 1;

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (!terminate) {
        uint16_t temp_raw, hum_raw;
        if (read_sensor_data(&temp_raw, &hum_raw) == 0) {
            sensor_data_t actual = convert_data(temp_raw, hum_raw);
            sensor_data_t sim = simulate_data(actual);
            log_data(sim);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
            fprintf(log_file, "NaN,NaN\n");
            fflush(log_file);
        }
        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    cleanup();
    return 0;
}

