#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000 /* 15 ms worst-case conversion time */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one measurement from the SHT35 ---- */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%04X)\n", MEASURE_CMD);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC validation */
    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Append a CSV row; write header if file is new/empty ---- */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "r");
    int need_header = 0;
    if (fp) {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) == 0)
            need_header = 1;
        fclose(fp);
    } else {
        need_header = 1;  /* file does not exist yet */
    }

    fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for append\n", filename);
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,%.2f,%.2f\n", temperature, humidity);
    }

    fclose(fp);
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35-DIS-B logger started. Bus %d, addr 0x%02X. Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "Warning: failed to log data\n");
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

