#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV     0xE0
#define CMD_RESET              0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (int)n;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw_out) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;

    for (int waited = 0; waited < MEAS_TIMEOUT_MS; waited += 5) {
        usleep(5000);
        if (cmd == CMD_READ_TEMP_PREV) {
            uint8_t buf[3];
            if (i2c_read_bytes(fd, buf, 3) == 0) {
                if (crc8(buf, 2) == buf[2]) {
                    *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
                    return 0;
                }
            }
        } else {
            uint8_t buf[3];
            if (i2c_read_bytes(fd, buf, 3) == 0) {
                if (crc8(buf, 2) == buf[2]) {
                    *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
                    return 0;
                }
            }
        }
    }
    return -1;
