#define MEASURE_CMD 0x3603
#define CONVERSION_TIME_US 45000
#define LOG_INTERVAL_S 5
#define LOG_FILE "pressure_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%04X)\n", MEASURE_CMD);
        return -1;
    }

    gpioDelay(CONVERSION_TIME_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: I2C read failed (expected 9 bytes)\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on scale factor word\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
