#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define RAW_MIN 1638
#define RAW_MAX 14745
#define FLOW_MIN 0.0f
#define FLOW_MAX 10.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, int16_t *raw_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %d\n", bytes);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t status_masked = raw & 0x3FFF;
    *raw_out = (int16_t)(status_masked >> 2);
    return 0;
}

static float convert_to_flow(int16_t raw) {
    if (raw < RAW_MIN) raw = RAW_MIN;
    if (raw > RAW_MAX) raw = RAW_MAX;
    return FLOW_MIN + ((float)(raw - RAW_MIN) / (float)(RAW_MAX - RAW_MIN)) * (FLOW_MAX - FLOW_MIN);
}

static void set_fan_speed(float flow_rate) {
    if (flow_rate < 0.0f) flow_rate = 0.0f;
    if (flow_rate > FLOW_MAX) flow_rate = FLOW_MAX;
    int duty = (int)((flow_rate / FLOW_MAX) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
    }
}

static void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", ts, flow_rate);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", FAN_GPIO);
        cleanup();
        return 1;
    }
    gpioPWM(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_sensor(i2c_handle, &raw) == 0) {
            float flow = convert_to_flow(raw);
            set_fan_speed(flow);
            log_data(flow);
            printf("Flow: %.2f SLPM, Fan: %d%%\n", flow, (int)((flow / FLOW_MAX) * 100));
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

