    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        log_error("Failed to read WHO_AM_I register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0xB1)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        log_error("Failed to write CTRL_REG1");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        float pressure, temperature;
        if (read_pressure(i2c_handle, &pressure) == 0 &&
            read_temperature(i2c_handle, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data");
        }
        gpioDelay(1000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

