#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read temperature from STLM75.
 * The sensor returns a 16-bit two's-complement word in big-endian order
 * (MSB first).  pigpio's i2cReadWordData returns the word with the low
 * byte first, so we swap the two bytes before extracting the value.
 * The STLM75 has 9-bit resolution: bits [15:8] hold the sign and 8 data
 * bits, and bits [7:0] are always 0.  We right-shift by 7 to get the
 * integer part, then divide by 2 for the 0.5 °C LSB.
 */
static int read_temperature(float *temp_out)
{
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error: I2C read failed (rc=%d)\n", raw);
        return -1;
    }

    /* Swap bytes: pigpio returns little-endian, STLM75 is big-endian */
    uint16_t swapped = (uint16_t)(((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8));
    int16_t value = (int16_t)swapped;

    /* Sign-extend from 9 bits to 16 bits */
    if (value & 0x0100) {
        value |= 0xFE00;
    }

    *temp_out = (float)(value >> 7) / 2.0f;
    return 0;
}

static float calculate_average(const float buffer[], int count)
{
    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += buffer[i];
    }
    return sum / (float)count;
}

static void control_led(float average_temp)
{
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) {
                buffer_count++;
            }

            float average_temp = calculate_average(temperature_buffer, buffer_count);
            control_led(average_temp);

            printf("Temperature: %.2f C, Average: %.2f C, LED: %s\n",
                   temperature, average_temp,
                   (average_temp > TEMP_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping iteration\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

