#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define MEASUREMENT_INTERVAL 2
#define LOG_FILE "air_quality.log"

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(int handle, uint16_t command) {
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", command, rc);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_arg(int handle, uint16_t command, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(command >> 8);
    buf[1] = (uint8_t)(command & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    int rc = i2cWriteDevice(handle, (char *)buf, 5);
    if (rc < 0) {
        fprintf(stderr, "Error writing command 0x%04X with arg 0x%04X: %d\n", command, arg, rc);
        return -1;
    }
    return 0;
}

static int scd30_read_data(int handle, uint8_t *data, int len) {
    int rc = i2cReadDevice(handle, (char *)data, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading data: %d\n", rc);
        return -1;
    }
    if (rc != len) {
        fprintf(stderr, "Short read: got %d, expected %d\n", rc, len);
        return -1;
    }
    return 0;
}

static int scd30_init(int handle) {
    if (scd30_write_command_with_arg(handle, CMD_SET_MEASUREMENT_INTERVAL, MEASUREMENT_INTERVAL) != 0) {
        fprintf(stderr, "Failed to set measurement interval\n");
        return -1;
    }
    if (scd30_write_command_with_arg(handle, CMD_START_PERIODIC_MEASUREMENT, 0x0000) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        return -1;
    }
    return 0;
}

static int scd30_data_ready(int handle) {
    if (scd30_write_command(handle, CMD_GET_DATA_READY) != 0) return -1;
    gpioDelay(3000);
    uint8_t data[3];
    if (scd30_read_data(handle, data, 3) != 0) return -1;
    if (scd30_crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on data-ready flag\n");
        return -1;
    }
    uint16_t ready = (data[0] << 8) | data[1];
    return (ready != 0) ? 1 : 0;
}

static int scd30_read_measurement(int handle, float *co2, float *temp, float *hum) {
    if (scd30_write_command(handle, CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(3000);
    uint8_t data[18];
    if (scd30_read_data(handle, data, 18) != 0) return -1;
    for (int i = 0; i < 6; i++) {
        if (scd30_crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on value %d\n", i);
            return -1;
        }
    }
    uint32_t co2_raw = ((uint32_t)data[0] << 24) | ((uint32_t)data[1] << 16) | ((uint32_t)data[3] << 8) | data[4];
    uint32_t temp_raw = ((uint32_t)data[6] << 24) | ((uint32_t)data[7] << 16) | ((uint32_t)data[9] << 8) | data[10];
    uint32_t hum_raw = ((uint32_t)data[12] << 24) | ((uint32_t)data[13] << 16) | ((uint32_t)data[15] << 8) | data[16];
    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *hum = (float)hum_raw / 100.0f;
    return 0;
}

static void log_data(float co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

static void control_ventilation(float co2) {
    if (co2 >= 1200.0f) printf("Ventilation: HIGH\n");
    else if (co2 >= 800.0f) printf("Ventilation: LOW\n");
    else printf("Ventilation: OFF\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SCD30_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (scd30_init(i2c_handle) != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        cleanup();
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 0;
    }

    while (running) {
        int ready = scd30_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error checking data-ready flag\n");
        } else if (ready == 1) {
            float co2, temp, hum;
            if (scd30_read_measurement(i2c_handle, &co2, &temp, &hum) == 0) {
                log_data(co2, temp, hum);
                control_ventilation(co2);
            } else {
                fprintf(stderr, "Error reading measurement\n");
            }
        }
        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

