#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define SDP32_CMD_CONT_MEAS_MSB 0x36
#define SDP32_CMD_CONT_MEAS_LSB 0x2F
#define SDP32_READ_LEN 9
#define SDP32_MEAS_DELAY_US 20000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
    int valid;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SDP32_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int start_continuous_measurement(void) {
    char cmd[2] = {SDP32_CMD_CONT_MEAS_MSB, SDP32_CMD_CONT_MEAS_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing continuous measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static sensor_data_t read_sdp32(void) {
    sensor_data_t data = {0.0f, 0.0f, 0};
    char buffer[SDP32_READ_LEN];

    int result = i2cReadDevice(i2c_handle, buffer, SDP32_READ_LEN);
    if (result != SDP32_READ_LEN) {
        fprintf(stderr, "Error reading from I2C device (got %d bytes, expected %d): %s\n",
                result, SDP32_READ_LEN, strerror(errno));
        return data;
    }

    uint8_t pressure_msb = (uint8_t)buffer[0];
    uint8_t pressure_lsb = (uint8_t)buffer[1];
    uint8_t pressure_crc = (uint8_t)buffer[2];
    uint8_t temperature_msb = (uint8_t)buffer[3];
    uint8_t temperature_lsb = (uint8_t)buffer[4];
    uint8_t temperature_crc = (uint8_t)buffer[5];
    uint8_t scale_factor_msb = (uint8_t)buffer[6];
    uint8_t scale_factor_lsb = (uint8_t)buffer[7];
    uint8_t scale_factor_crc = (uint8_t)buffer[8];

    uint8_t pressure_data[2] = {pressure_msb, pressure_lsb};
    uint8_t temperature_data[2] = {temperature_msb, temperature_lsb};
    uint8_t scale_factor_data[2] = {scale_factor_msb, scale_factor_lsb};

    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return data;
    }
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return data;
    }
    if (crc8(scale_factor_data, 2) != scale_factor_crc) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return data;
    }

    int16_t raw_pressure = (int16_t)((pressure_msb << 8) | pressure_lsb);
    int16_t raw_temperature = (int16_t)((temperature_msb << 8) | temperature_lsb);
    uint16_t scale_factor = (uint16_t)((scale_factor_msb << 8) | scale_factor_lsb);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return data;
    }

    data.pressure = (float)raw_pressure / (float)scale_factor;
    data.temperature = (float)raw_temperature / 256.0f;
    data.valid = 1;
    return data;
}

static void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.valid) {
        printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n",
               timestamp, data.pressure, data.temperature);
    } else {
        printf("%s - Invalid sensor data\n", timestamp);
    }
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval value. Using default: %d ms\n", DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (start_continuous_measurement() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioDelay(SDP32_MEAS_DELAY_US);

    while (!terminate) {
        sensor_data_t data = read_sdp32();
        log_data(data);
        gpioDelay(interval_ms * 1000);
    }

    cleanup();
    return 0;
}

