#define HDC1000_ADDR        0x40
#define REG_TEMP            0x00
#define REG_HUMID           0x01
#define REG_CONFIG          0x02

/* Bit 12: TRES=14 (14-bit temp), Bit 11: HRES=14 (14-bit humidity),
   Bit 10: MODE=1 (T & RH acquired sequentially), Bit 1: MEAS_TRIG=1 */
#define CONFIG_VALUE        0x1004

#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_INTERVAL_S   5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_temp, raw_humid;

    /* Trigger a measurement by writing the temperature register pointer */
    if (i2c_write_reg16(fd, REG_TEMP, 0x0000) != 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    /* Read 4 bytes: 2 bytes temperature + 2 bytes humidity */
    uint8_t reg_buf = REG_TEMP;
    uint8_t data[4];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "hdc1000_read: write pointer: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 4) != 4) {
        fprintf(stderr, "hdc1000_read: read data: %s\n", strerror(errno));
        return -1;
    }

    raw_temp  = ((uint16_t)data[0] << 8) | data[1];
    raw_humid = ((uint16_t)data[2] << 8) | data[3];

    *temperature = ((float)raw_temp  / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_humid / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) != 0) {
        fprintf(stderr, "HDC1000 not detected at 0x%02X or init failed\n", HDC1000_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at 0x%02X. Reading every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_S);

    while (g_running) {
        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

