#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define CMD_MEASURE_TEMP_HOLD 0xE3
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByte(handle, CMD_MEASURE_TEMP_HOLD);
        if (result < 0) {
            fprintf(stderr, "Error writing measurement command (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(20000); // 20ms conversion time

        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
            *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;
            return 0;
        } else {
            fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
        }
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SI7051_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7051 Temperature Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nSi7051 Temperature Logger stopped.\n");
    return EXIT_SUCCESS;
}

