#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define MLX90833_REG_PRESSURE 0x00
#define MLX90833_REG_TEMP 0x02
#define MLX90833_REG_CONFIG 0x04
#define MLX90833_REG_ID 0x0C
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mlx90833_pressure(int handle, float *pressure) {
    char reg = MLX90833_REG_PRESSURE;
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &reg, 1) != 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (i2cReadDevice(handle, buf, 3) == 3) {
            uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 16) |
                          ((uint32_t)(uint8_t)buf[1] << 8)  |
                          ((uint32_t)(uint8_t)buf[2]);
            *pressure = (float)raw * 0.01f;
            return 0;
        }
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static int read_mlx90833_temperature(int handle, float *temp) {
    char reg = MLX90833_REG_TEMP;
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &reg, 1) != 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (i2cReadDevice(handle, buf, 2) == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temp = (float)raw * 0.01f;
            return 0;
        }
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(stdout);
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (err=%d).\n", I2C_BUS, MLX90833_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90833 Pressure Sensor Reader (I2C bus %d, addr 0x%02X)\n", I2C_BUS, MLX90833_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (read_mlx90833_pressure(i2c_handle, &pressure) != 0) {
            fprintf(stderr, "Error: Failed to read pressure after %d retries.\n", MAX_RETRIES);
        } else if (read_mlx90833_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
        } else {
            log_data(pressure, temperature);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

