#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x63
#define CMD_READ_OTP   0x50
#define CMD_MEASURE_HP 0x40
#define MEASURE_DELAY_US 7000
#define POLL_DELAY_US  5000000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    uint16_t scale_factor_lut;
    uint16_t scale_factor_h;
    uint16_t scale_factor_p;
} calibration_data_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_otp(int handle, uint8_t *otp) {
    if (i2cWriteByte(handle, CMD_READ_OTP) < 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(2000);
    int n = i2cReadDevice(handle, (char *)otp, 8);
    if (n != 8) {
        fprintf(stderr, "Error: OTP read returned %d bytes (expected 8)\n", n);
        return -1;
    }
    for (int i = 0; i < 8; i++) {
        if (otp[i] != 0xFF) break;
        if (i == 7) {
            fprintf(stderr, "Error: OTP memory all 0xFF - sensor absent or not responding\n");
            return -1;
        }
    }
    return 0;
}

static int read_measurement(int handle, uint8_t *buf) {
    if (i2cWriteByte(handle, CMD_MEASURE_HP) < 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    int n = i2cReadDevice(handle, (char *)buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: measurement read returned %d bytes (expected 6)\n", n);
        return -1;
    }
    for (int i = 0; i < 6; i++) {
        if (buf[i] != 0xFF) break;
        if (i == 5) {
            fprintf(stderr, "Error: measurement data all 0xFF - sensor absent or not responding\n");
            return -1;
        }
    }
    return 0;
}

static void compute_scaling(const uint8_t *otp, calibration_data_t *cal) {
    uint32_t lut = ((uint32_t)otp[0] << 8) | otp[1];
    uint32_t h   = ((uint32_t)otp[2] << 8) | otp[3];
    uint32_t p   = ((uint32_t)otp[4] << 8) | otp[5];
    cal->scale_factor_lut = (uint16_t)lut;
    cal->scale_factor_h   = (uint16_t)h;
    cal->scale_factor_p   = (uint16_t)p;
}

static void compensate(const uint8_t *buf, const calibration_data_t *cal,
                       float *temp_c, float *press_pa) {
    int16_t raw_t = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]);
    uint32_t raw_p = ((uint32_t)buf[2] << 16) | ((uint32_t)buf[3] << 8) | buf[4];

    float t = (float)raw_t / 65536.0f;
    float p = (float)raw_p / 65536.0f;

    float t_comp = t * 100.0f;
    float p_comp = p * 100000.0f;

    *temp_c = t_comp;
    *press_pa = p_comp;
}

static void log_data(float temp_c, float press_pa) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp_c, press_pa);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t otp[8];
    if (read_otp(g_i2c_handle, otp) != 0) {
        fprintf(stderr, "Error: failed to read OTP calibration data\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    calibration_data_t cal;
    compute_scaling(otp, &cal);

    uint8_t buf[6];
    int consecutive_errors = 0;

    while (g_running) {
        if (read_measurement(g_i2c_handle, buf) == 0) {
            consecutive_errors = 0;
            float temp_c, press_pa;
            compensate(buf, &cal, &temp_c, &press_pa);
            log_data(temp_c, press_pa);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: measurement read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: %d consecutive failures, attempting re-open\n", consecutive_errors);
                i2cClose(g_i2c_handle);
                g_i2c_handle = -1;
                gpioDelay(1000000);
                g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
                if (g_i2c_handle < 0) {
                    fprintf(stderr, "Error: i2cOpen re-open failed (handle=%d)\n", g_i2c_handle);
                    break;
                }
                consecutive_errors = 0;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

