#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define REG_PRESSURE_MSB 0xAA
#define REG_PRESSURE_LSB 0xAB
#define SCALE_FACTOR     0.1f
#define POLL_INTERVAL_S  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *val) {
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_kpa) {
    uint8_t msb = 0, lsb = 0;
    int16_t raw;

    if (i2c_write_byte(fd, REG_PRESSURE_MSB) < 0) return -1;
    if (i2c_read_byte(fd, &msb) < 0) return -1;

    if (i2c_write_byte(fd, REG_PRESSURE_LSB) < 0) return -1;
    if (i2c_read_byte(fd, &lsb) < 0) return -1;

    raw = (int16_t)((msb << 8) | lsb);
    *pressure_kpa = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X)\n",
           I2C_BUS, MLX90819_ADDR);
    fflush(stdout);

    while (g_running) {
        float pressure;
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];

        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        if (read_pressure(fd, &pressure) == 0) {
            printf("%s Pressure: %.2f kPa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "%s Failed to read pressure\n", ts);
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    if (fd >= 0) close(fd);
    return EXIT_SUCCESS;
}

