            fprintf(stderr, "Attempting I2C recovery...\n");
            if (open_i2c() != 0) {
                fprintf(stderr, "Recovery failed; exiting.\n");
                break;
            }
            if (read_pressure(&pressure) != 0) {
                fprintf(stderr, "Read failed after recovery; continuing.\n");
                gpioDelay(SAMPLE_US);
                continue;
            }
        }

        log_pressure(pressure);
        check_pressure(pressure);

        gpioDelay(SAMPLE_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

