#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_nibble(int *nibble) {
    uint32_t start, end;
    int level;

    start = gpioTick();
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - start > TIMEOUT_US) return -1;
    }
    start = gpioTick();
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start > TIMEOUT_US) return -1;
    }
    end = gpioTick();

    int ticks = (int)(end - start);
    if (ticks < MIN_NIBBLE_TICKS || ticks > MAX_NIBBLE_TICKS) return -2;

    *nibble = (ticks - MIN_NIBBLE_TICKS) / 4;
    return 0;
}

static int read_sent_frame(int *raw) {
    int nibbles[4];
    int status;

    for (int i = 0; i < 4; i++) {
        int ret = read_nibble(&nibbles[i]);
        if (ret != 0) return ret;
    }

    status = nibbles[0];
    if (status & 0x08) return -3;

    int checksum = (nibbles[0] + nibbles[1] + nibbles[2]) & 0x0F;
    if (checksum != nibbles[3]) return -4;

    *raw = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
    return 0;
}

static float convert_to_pressure(int raw) {
    return (float)raw * 0.1f + 10.0f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_DOWN);

    printf("SENT pressure sensor monitoring started on GPIO %d\n", SENT_GPIO);

    while (running) {
        uint32_t start = gpioTick();
        while (gpioRead(SENT_GPIO) == 1) {
            if (gpioTick() - start > TIMEOUT_US) {
                fprintf(stderr, "Error: sensor absent (timeout waiting for falling edge)\n");
                break;
            }
        }
        start = gpioTick();
        while (gpioRead(SENT_GPIO) == 0) {
            if (gpioTick() - start > TIMEOUT_US) {
                fprintf(stderr, "Error: sensor absent (timeout waiting for rising edge)\n");
                break;
            }
        }
        start = gpioTick();
        while (gpioRead(SENT_GPIO) == 1) {
            if (gpioTick() - start > TIMEOUT_US) {
                fprintf(stderr, "Error: sensor absent (timeout waiting for falling edge after sync)\n");
                break;
            }
        }
        end = gpioTick();
        int sync_ticks = (int)(end - start);
        if (sync_ticks < SYNC_TICKS - 5 || sync_ticks > SYNC_TICKS + 5) {
            fprintf(stderr, "Error: invalid sync pulse width %d ticks\n", sync_ticks);
            continue;
        }

        int raw;
        int ret = read_sent_frame(&raw);
        if (ret == 0) {
            float pressure = convert_to_pressure(raw);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else if (ret == -1) {
            fprintf(stderr, "Error: SENT frame timeout\n");
        } else if (ret == -2) {
            fprintf(stderr, "Error: invalid nibble pulse width\n");
        } else if (ret == -3) {
            fprintf(stderr, "Error: SENT status nibble indicates error\n");
        } else if (ret == -4) {
            fprintf(stderr, "Error: SENT checksum mismatch\n");
        }
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

