#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define EXPECTED_DEVICE_ID 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define READ_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static int log_temperature(float temperature) {
    uint8_t data[4];
    memcpy(data, &temperature, sizeof(float));

    if (fwrite(data, sizeof(uint8_t), 4, log_file) != 4) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int verify_device_id(void) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading device ID register: %d\n", result);
        return -1;
    }

    uint16_t device_id = (uint16_t)((buf[0] << 8) | buf[1]);
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device_id() != 0) {
        fprintf(stderr, "TMP117 device ID verification failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL_SEC);

    while (running) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

