#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CONVERSION_DELAY_US 9000
#define LOG_FILE "environmental_data.txt"
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, SensorData *data) {
    uint8_t cmd = MEASURE_HIGH_PRECISION;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_hum = (buf[3] << 8) | buf[4];

    data->temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    data->humidity = -6.0f + 125.0f * (float)raw_hum / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, SensorData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    SensorData sensor_data;
    while (!terminate) {
        if (read_sht40(i2c_handle, &sensor_data) == 0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying next cycle\n");
        }
        gpioDelay(5000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

