#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  5
#define LOG_FILE       "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;
static int  i2c_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *out) {
    char reg = (char)TEMP_REG;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature register address.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read 2 bytes from temperature register.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    *out = (float)raw * 0.0078125f;
    return 0;
}

static void add_reading(float temp) {
    buffer[buffer_index].timestamp  = time(NULL);
    buffer[buffer_index].temperature = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int save_buffer(void) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    size_t to_write = (size_t)buffer_count;
    size_t written  = fwrite(buffer, sizeof(TemperatureReading), to_write, fp);
    if (written != to_write) {
        fprintf(stderr, "Error: wrote %zu of %zu readings to log file.\n", written, to_write);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Sampling every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD);

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            add_reading(temp);
            printf("Temperature: %.2f °C\n", temp);
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping sample.\n");
        }

        if (save_buffer() != 0) {
            fprintf(stderr, "Warning: failed to save buffer to log file.\n");
        }

        for (int i = 0; i < SAMPLE_PERIOD && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (save_buffer() != 0) {
        fprintf(stderr, "Error: failed to save buffer on exit.\n");
    }
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

