#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, SI7202_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *magnetic_field, int16_t *temperature) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", result);
        return -1;
    }
    *magnetic_field = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[2] << 8) | buf[3]);
    return 0;
}

static void convert_data(int16_t raw_magnetic_field, int16_t raw_temperature,
                         float *magnetic_field_gauss, float *temperature_celsius) {
    *magnetic_field_gauss = (float)raw_magnetic_field * 0.1f;
    *temperature_celsius = (float)raw_temperature * 0.01f - 25.0f;
}

static int log_data(float magnetic_field, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, magnetic_field, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    int16_t raw_magnetic_field, raw_temperature;
    float magnetic_field_gauss, temperature_celsius;

    while (program_running) {
        if (read_sensor_data(&raw_magnetic_field, &raw_temperature) == 0) {
            convert_data(raw_magnetic_field, raw_temperature,
                         &magnetic_field_gauss, &temperature_celsius);
            if (log_data(magnetic_field_gauss, temperature_celsius) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging NaN values\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Error logging NaN values\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

