#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *flow_raw, uint16_t *temp_raw) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *flow_raw = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
    *temp_raw = ((uint16_t)(buf[2] & 0x0F) << 8) | (uint8_t)buf[3];
    return 0;
