#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message, int status_code) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - ERROR: %s (Status Code: %d)\n", ts, message, status_code);
    }
    fclose(fp);
}

static void log_data(int temperature, int humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen data log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - Temperature: %d C, Humidity: %d %%\n", ts, temperature, humidity);
    }
    fclose(fp);
}

static int read_dht11(int *temperature, int *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = PI_HIGH;
    int bits_read = 0;
    uint32_t start_time = 0;

    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode", 1);
        return 1;
    }

    if (gpioWrite(DHT11_GPIO, PI_LOW) < 0) {
        log_error("Failed to pull GPIO low", 2);
        return 2;
    }
    gpioDelay(20000); /* 20 ms low start signal */

    if (gpioWrite(DHT11_GPIO, PI_HIGH) < 0) {
        log_error("Failed to release GPIO", 3);
        return 3;
    }
    gpioDelay(30); /* 30 us high before switching to input */

    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) {
        log_error("Failed to set GPIO to input", 4);
        return 4;
    }

    /* Wait for sensor to pull low (response signal) */
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        if (gpioTick() - start_time > 100000) {
            log_error("Timeout waiting for sensor response (stuck high)", 5);
            return 5;
        }
    }

    /* Sensor response: ~80 us low, ~80 us high */
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == PI_LOW) {
        if (gpioTick() - start_time > 100000) {
            log_error("Timeout waiting for response low", 6);
            return 6;
        }
    }
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        if (gpioTick() - start_time > 100000) {
            log_error("Timeout waiting for response high", 7);
            return 7;
        }
    }

    /* Read 40 data bits */
    for (int i = 0; i < 40; i++) {
        /* Each bit starts with ~50 us low */
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == PI_LOW) {
            if (gpioTick() - start_time > 100000) {
                log_error("Timeout waiting for bit low", 8);
                return 8;
            }
        }

        /* Measure high-pulse duration to determine bit value */
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == PI_HIGH) {
            if (gpioTick() - start_time > 100000) {
                log_error("Timeout waiting for bit high", 9);
                return 9;
            }
        }
        uint32_t high_duration = gpioTick() - start_time;

        data[i / 8] <<= 1;
        if (high_duration > 50) {
            data[i / 8] |= 1;
        }
        bits_read++;
    }

    if (bits_read != 40) {
        log_error("Incomplete data read", 10);
        return 10;
    }

    /* Checksum validation */
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        log_error("Checksum failure", 11);
        return 11;
    }

    *humidity = data[0];
    *temperature = data[2];
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    int temperature, humidity;
    while (running) {
        int rc = read_dht11(&temperature, &humidity);
        if (rc == 0) {
            log_data(temperature, humidity);
        }
        /* Sleep 2 seconds, checking running flag every 100 ms */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000);
        }
    }

    gpioTerminate();
    return 0;
}

