static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SHT31_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed, retries left: %d\n", retries - 1);
            retries--;
            usleep(RETRY_DELAY_US);
            continue;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed, retries left: %d\n", retries - 1);
            retries--;
            usleep(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch, retries left: %d\n", retries - 1);
            retries--;
            usleep(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch, retries left: %d\n", retries - 1);
            retries--;
            usleep(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw = ((uint16_t)buf[3] << 8) | buf[4];

        data->temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        data->humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1;
}

static int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

