#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_ID_VAL 0x2A
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_register_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read error on reg 0x%02X: expected %u, got %d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int initialize_adpd105(int handle) {
    uint8_t id = 0;
    if (read_register(handle, ADPD105_REG_ID, &id) != 0) {
        return -1;
    }
    if (id != ADPD105_REG_ID_VAL) {
        fprintf(stderr, "ADPD105 ID mismatch: got 0x%02X, expected 0x%02X\n", id, ADPD105_REG_ID_VAL);
        return -1;
    }
    if (write_register(handle, 0x01, 0x01) != 0) return -1;
    if (write_register(handle, 0x02, 0x02) != 0) return -1;
    if (write_register(handle, 0x03, 0x03) != 0) return -1;
    return 0;
}

static int read_adpd105_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[6];
    if (read_register_block(handle, ADPD105_REG_RED, buf, 6) != 0) {
        return -1;
    }
    *red   = (uint16_t)(buf[1] << 8 | buf[0]);
    *green = (uint16_t)(buf[3] << 8 | buf[2]);
    *blue  = (uint16_t)(buf[5] << 8 | buf[4]);
    return 0;
}

static double calculate_cct(uint16_t r, uint16_t g, uint16_t b) {
    if (r == 0 || g == 0 || b == 0) return 0.0;
    double rn = (double)r, gn = (double)g, bn = (double)b;
    double sum = rn + gn + bn;
    double r1 = rn / sum, g1 = gn / sum, b1 = bn / sum;
    double r2 = r1 * r1, g2 = g1 * g1, b2 = b1 * b1;
    double g3 = g1 * g2, r3 = r1 * r2, b3 = b1 * b2;
    double n = (r1 * g3) + (r2 * b3) - (r3 * g2) - (b2 * g3);
    double d = (r1 * g2) - (r2 * g1) - (r1 * b2) + (r2 * b1);
    double n2 = n * n, d2 = d * d;
    double x = 449.0 * n2 / (n2 + d2);
    double y = 3525.0 * n * d / (n2 + d2);
    double z = 108.0 * d2 / (n2 + d2);
    double xz = x + z;
    if (xz == 0.0) return 0.0;
    double cct = 449.0 * x * (3.0 * x + z) / (x * (3.0 * x + z));
    return cct;
}

static void log_cct_data(double avg_cct) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    if (sz == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, avg_cct);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int h1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADPD105_ADDR_1, h1);
        gpioTerminate();
        return 1;
    }

    int h2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADPD105_ADDR_2, h2);
        i2cClose(h1);
        gpioTerminate();
        return 1;
    }

    if (initialize_adpd105(h1) != 0 || initialize_adpd105(h2) != 0) {
        fprintf(stderr, "ADPD105 initialization failed\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t r1 = 0, g1 = 0, b1 = 0, r2 = 0, g2 = 0, b2 = 0;
        int ok1 = read_adpd105_data(h1, &r1, &g1, &b1);
        int ok2 = read_adpd105_data(h2, &r2, &g2, &b2);

        if (ok1 != 0 || ok2 != 0) {
            fprintf(stderr, "Sensor read error; skipping log entry\n");
        } else {
            double cct1 = calculate_cct(r1, g1, b1);
            double cct2 = calculate_cct(r2, g2, b2);
            double avg = (cct1 + cct2) / 2.0;
            log_cct_data(avg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    return 0;
}

