    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    }
    if (log_file) {
        fprintf(log_file, "%s,%s\n", ts, msg);
        fflush(log_file);
    }
    fprintf(stderr, "%s,%s\n", ts, msg);
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static float convert_pressure(uint16_t raw) {
    return ((float)raw - (float)OUTPUT_MIN) *
           (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) /
           ((float)OUTPUT_MAX - (float)OUTPUT_MIN) +
           PRESSURE_MIN_KPA;
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * 0.01f - 40.0f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_pressure = 0, raw_temperature = 0;
        int p_ok = read_register16(i2c_handle, PRESSURE_REG, &raw_pressure);
        int t_ok = read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature);

        if (p_ok != 0 || t_ok != 0) {
            char err_msg[128];
            snprintf(err_msg, sizeof(err_msg),
                     "I2C read error: pressure=%d temp=%d", p_ok, t_ok);
            log_message(err_msg);
        } else {
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            } else {
                strncpy(ts, "UNKNOWN", sizeof(ts));
            }
            fprintf(log_file, "%s,%.2f kPa,%.2f C\n", ts, pressure_kPa, temperature_C);
            fflush(log_file);
        }

        gpioSleep(PI_TIME_RELATIVE, 2, 0);
    }

    cleanup();
    return EXIT_SUCCESS;
}

