#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 26.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float read_temperature(int handle) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1000.0f;
    }
    int16_t raw = ((int16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    raw >>= 7;
    return (float)raw * 0.5f;
}

static void add_to_buffer(float temp, float buffer[], int *idx, int size) {
    buffer[*idx] = temp;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float buffer[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / (float)size;
}

static void control_fan(float avg) {
    static bool fan_on = false;
    if (avg > TEMP_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg=%.2f C)\n", avg);
        } else {
            fprintf(stderr, "Failed to set fan GPIO high\n");
        }
    } else if (avg < TEMP_HYSTERESIS && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg=%.2f C)\n", avg);
        } else {
            fprintf(stderr, "Failed to set fan GPIO low\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, LM75B_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp_buffer[BUFFER_SIZE];
    for (int i = 0; i < BUFFER_SIZE; i++) temp_buffer[i] = 0.0f;
    int buf_idx = 0;

    while (g_running) {
        float temp = read_temperature(g_i2c_handle);
        if (temp < -999.0f) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        } else {
            add_to_buffer(temp, temp_buffer, &buf_idx, BUFFER_SIZE);
            float avg = calculate_average(temp_buffer, BUFFER_SIZE);
            printf("Temp: %.2f C | Avg: %.2f C\n", temp, avg);
            control_fan(avg);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

