#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow.log"
#define PRESSURE_SCALE 60.0f
#define TEMP_SCALE     200.0f
#define PRESSURE_THRESHOLD 5.0f
#define MEAS_CMD_MSB   0x36
#define MEAS_CMD_LSB   0x2F
#define MEAS_DELAY_US  45000
#define LOOP_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_logging(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
    fflush(g_log_file);
    return 0;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sensor(float *pressure, float *temperature)
{
    uint8_t cmd[2] = { MEAS_CMD_MSB, MEAS_CMD_LSB };
    uint8_t buf[9];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    int bytes = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (bytes != 9) {
        fprintf(stderr, "Error reading sensor data: got %d bytes (expected 9)\n", bytes);
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on status word\n");
        return -2;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / PRESSURE_SCALE;
    *temperature = (float)raw_temperature / TEMP_SCALE;
    return 0;
}

static void log_data(float pressure, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(g_log_file);
}

static void check_threshold(float pressure)
{
    if (pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "WARNING: Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                pressure, PRESSURE_THRESHOLD);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_logging() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure, temperature;
    int consecutive_errors = 0;

    while (g_running) {
        int rc = read_sensor(&pressure, &temperature);
        if (rc == 0) {
            log_data(pressure, temperature);
            check_threshold(pressure);
            consecutive_errors = 0;
        } else if (rc == -2) {
            /* CRC mismatch — sensor may be absent or bus noise */
            fprintf(stderr, "Sensor CRC error — skipping sample\n");
            consecutive_errors++;
        } else {
            fprintf(stderr, "I2C read error — skipping sample\n");
            consecutive_errors++;
        }

        if (consecutive_errors >= 10) {
            fprintf(stderr, "Too many consecutive errors — aborting\n");
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

