#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float convert_temperature(int16_t raw)
{
    return (float)(raw >> 4) * 0.0625f;
}

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "stts2004-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    int led_state = 0;

    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) != 0) {
            fprintf(stderr, "Fatal I2C read error, exiting.\n");
            goto cleanup;
        }

        float temp = convert_temperature(raw);
        printf("Temperature: %.2f °C\n", temp);

        if (temp > TEMP_HIGH && led_state == 0) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n", strerror(errno));
                goto cleanup;
            }
            led_state = 1;
            printf("LED ON\n");
        } else if (temp < TEMP_LOW && led_state == 1) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n", strerror(errno));
                goto cleanup;
            }
            led_state = 0;
            printf("LED OFF\n");
        }

        sleep(POLL_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);

    printf("Exiting.\n");
    return ret;
}

