#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define CMD_RH_NOHOLD  0xF5
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP  0xE0
#define CMD_RESET      0xFE
#define CMD_ID_1       0xFA
#define CMD_ID_2       0x0F
#define CMD_FIRM_REV   0x84
#define CMD_RES        0xE7
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  60
#define LOG_FILE       "environment.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fclose(fp);
    }
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    char buf[1] = { (char)cmd };
    for (int i = 0; i < MAX_RETRIES; i++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_n(int handle, uint8_t *buf, int n) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        int rc = i2cReadDevice(handle, (char *)buf, n);
        if (rc == n) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(handle, cmd) != 0) return -1;
    gpioDelay(20000);
    uint8_t buf[3];
    if (i2c_read_n(handle, buf, 3) != 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int handle, float *temp_c) {
    uint16_t raw;
    if (read_measurement(handle, CMD_READ_TEMP, &raw) != 0) return -1;
    *temp_c = (175.72f * raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *rh) {
    uint16_t raw;
    if (read_measurement(handle, CMD_RH_NOHOLD, &raw) != 0) return -1;
    *rh = (125.0f * raw) / 65536.0f - 6.0f;
    if (*rh < 0.0f) *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static int read_electronic_id(int handle, uint8_t *id) {
    if (i2c_write_cmd(handle, CMD_ID_1) != 0) return -1;
    gpioDelay(10000);
    if (i2c_read_n(handle, id, 8) != 0) return -1;
    return 0;
}

static int read_firmware_rev(int handle, uint8_t *rev) {
    if (i2c_write_cmd(handle, CMD_FIRM_REV) != 0) return -1;
    gpioDelay(10000);
    if (i2c_read_n(handle, rev, 2) != 0) return -1;
    return 0;
}

static void log_data(float temp_c, float rh) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
        fflush(fp);
        fclose(fp);
    }
    printf("%s,%.2f,%.2f\n", ts, temp_c, rh);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
