#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x44
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    if (i2c_write_cmd(fd, 0x2C, 0xE0) != 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t raw[3];
    if (i2c_read_bytes(fd, raw, sizeof(raw)) != 0)
        return -1;

    if (sensirion_crc8(raw, 2) != raw[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t ticks = ((uint16_t)raw[0] << 8) | raw[1];
    *temp_c = -45.0f + 175.0f * (float)ticks / 65535.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temp_c)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    if (localtime_r(&now, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s, Temperature: %.2f C\n", ts, temp_c);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            log_temperature(g_log_fp, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log_fp)  { fclose(g_log_fp);  g_log_fp  = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
    return EXIT_SUCCESS;
}

