#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t data_buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(int handle, uint16_t command) {
    uint8_t buf[2] = { (command >> 8) & 0xFF, command & 0xFF };
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed for command 0x%04X: %d", command, result);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, int *co2, float *temperature, float *humidity) {
    if (send_command(handle, READ_MEASUREMENT) != 0)
        return -1;

    uint8_t buf[9];
    int result = i2cReadDevice(handle, (char *)buf, 9);
    if (result != 9) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: expected 9 bytes, got %d", result);
        log_error(msg);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2] ||
        crc8(&buf[3], 2) != buf[5] ||
        crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC mismatch on measurement data");
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    *co2 = co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

static void enqueue(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(60);
        if (!running) break;

        pthread_mutex_lock(&data_buffer.mutex);
        int count = data_buffer.count;
        sensor_data_t *data = malloc(count * sizeof(sensor_data_t));
        if (!data) {
            log_error("malloc failed in logging thread");
            pthread_mutex_unlock(&data_buffer.mutex);
            continue;
        }
        int idx = data_buffer.tail;
        for (int i = 0; i < count; i++) {
            data[i] = data_buffer.data[idx];
            idx = (idx + 1) % BUFFER_SIZE;
        }
        data_buffer.tail = (data_buffer.tail + count) % BUFFER_SIZE;
        data_buffer.count -= count;
        pthread_mutex_unlock(&data_buffer.mutex);

        if (count == 0) {
            free(data);
            continue;
        }

        char filename[256];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(filename, sizeof(filename), "%Y-%m-%d_%H-%M-%S.csv", tm);
        char filepath[512];
        snprintf(filepath, sizeof(filepath), "%s/%s", LOG_DIR, filename);

        FILE *fp = fopen(filepath, "w");
        if (!fp) {
            char msg[256];
            snprintf(msg, sizeof(msg), "Failed to open CSV file %s: %s", filepath, strerror(errno));
            log_error(msg);
            free(data);
            continue;
        }

        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        for (int i = 0; i < count; i++) {
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&data[i].timestamp));
            fprintf(fp, "%s,%d,%.2f,%.2f\n", ts, data[i].co2, data[i].temperature, data[i].humidity);
        }

        fclose(fp);
        free(data);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(i2c_handle, STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    pthread_mutex_lock(&data_buffer.mutex);
    int count = data_buffer.count;
    sensor_data_t *data = malloc(count * sizeof(sensor_data_t));
    if (data) {
        int idx = data_buffer.tail;
        for (int i = 0; i < count; i++) {
            data[i] = data_buffer.data[idx];
            idx = (idx + 1) % BUFFER_SIZE;
        }
        data_buffer.tail = (data_buffer.tail + count) % BUFFER_SIZE;
        data_buffer.count -= count;
    }
    pthread_mutex_unlock(&data_buffer.mutex);

    if (data && count > 0) {
        char filename[256];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(filename, sizeof(filename), "%Y-%m-%d_%H-%M-%S_final.csv", tm);
        char filepath[512];
        snprintf(filepath, sizeof(filepath), "%s/%s", LOG_DIR, filename);
        FILE *fp = fopen(filepath, "w");
        if (fp) {
            fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
            for (int i = 0; i < count; i++) {
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&data[i].timestamp));
                fprintf(fp, "%s,%d,%.2f,%.2f\n", ts, data[i].co2, data[i].temperature, data[i].humidity);
            }
            fclose(fp);
        } else {
            char msg[256];
            snprintf(msg, sizeof(msg), "Failed to open final CSV file: %s", strerror(errno));
            log_error(msg);
        }
        free(data);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C bus %d at addr 0x%02X: %d", I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        log_error(msg);
        gpioTerminate();
        return 1;
    }

    if (send_command(i2c_handle, START_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    init_circular_buffer(&data_buffer);

    if (mkdir(LOG_DIR, 0755) == -1 && errno != EEXIST) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to create log directory %s: %s", LOG_DIR, strerror(errno));
        log_error(msg);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int co2, ret;
        float temperature, humidity;

        ret = read_measurement(i2c_handle, &co2, &temperature, &humidity);
        if (ret == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            enqueue(&data_buffer, data);
        } else {
            log_error("Failed to read measurement data");
        }

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    pthread_join(logging_thread, NULL);
    cleanup();
    return 0;
}

