    cal->c1 = (buf[2] << 8) | buf[3];
    return 0;
}

static int read_pressure_temperature(int handle, const calibration_data_t *cal, float *pressure, float *temperature) {
    uint8_t cmd = 0x00;
    if (i2cWriteI2CBlockData(handle, MEASUREMENT_REG, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, MEASUREMENT_REG, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read measurement data\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t raw_t = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    float t = (float)raw_t / 65536.0f;
    float p = (float)raw_p / 65536.0f;

    *temperature = t * 100.0f;
    *pressure = (cal->c0 * 0.5f + cal->c1 * t + cal->c2 * p + cal->c3 * t * p) / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    calibration_data_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (!terminate) {
        float pressure, temperature;
        if (read_pressure_temperature(i2c_handle, &cal, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

