/*
 * ICP-10125 barometric pressure sensor reader with libgpiod LED warning.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: TDK ICP-10125 (I2C address 0x63, default)
 * LED:    GPIO 17 (BCM), driven via libgpiod
 *
 * Build:  gcc -O2 -Wall -o icp10125 icp10125.c -lgpiod
 *
 * Reads calibration coefficients from OTP register 0x66, triggers a
 * high-accuracy measurement (0x4011), and applies the official
 * InvenSense conversion formulas to compute pressure (Pa) and
 * temperature (°C).  Polls once per second; blinks the LED at 1 Hz
 * when pressure >= 95000 Pa and at 5 Hz when below that threshold.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x63
#define GPIO_CHIP       "gpiochip4"
#define GPIO_OFFSET     17

#define CMD_READ_OTP    0x66
#define CMD_MEASURE     0x4011
#define MEASURE_DELAY_MS 20
#define POLL_DELAY_MS   1000
#define HIGH_ALT_THRESHOLD 95000.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write16(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write16(0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu (%s)\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- CRC-8 (poly 0x31, init 0xFF) per InvenSense datasheet ---- */
static bool crc_ok(const uint8_t *data, size_t len, uint8_t crc)
{
    uint8_t c = 0xFF;
    for (size_t i = 0; i < len; i++) {
        c ^= data[i];
        for (int b = 0; b < 8; b++)
            c = (c & 0x80) ? (uint8_t)((c << 1) ^ 0x31) : (uint8_t)(c << 1);
    }
    return c == crc;
}

/* ---- Sensor read ---- */

typedef struct {
    float pressure;     /* Pa */
    float temperature;  /* °C */
} sensor_data_t;

static int read_sensor(int fd, sensor_data_t *out)
{
    uint8_t cal[8];
    uint8_t raw[6];

    /* Read 8 bytes of calibration coefficients from OTP register 0x66 */
    if (i2c_write16(fd, CMD_READ_OTP) < 0) return -1;
    if (i2c_read_block(fd, cal, 8) < 0) return -1;

    /* Trigger high-accuracy measurement */
    if (i2c_write16(fd, CMD_MEASURE) < 0) return -1;
    usleep(MEASURE_DELAY_MS * 1000);

    /* Read 6 bytes: pressure(2) + temperature(2) + crc(2) */
    if (i2c_read_block(fd, raw, 6) < 0) return -1;

    /* CRC covers the 4 data bytes; verify */
    if (!crc_ok(raw, 4, raw[5])) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }

    /* Assemble 16-bit big-endian values */
    uint16_t p_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t t_raw = ((uint16_t)raw[2] << 8) | raw[3];

    /* Parse calibration coefficients (4 signed 16-bit values) */
    int16_t c0 = (int16_t)(((uint16_t)cal[0] << 8) | cal[1]);
    int16_t c1 = (int16_t)(((uint16_t)cal[2] << 8) | cal[3]);
    int16_t c2 = (int16_t)(((uint16_t)cal[4] << 8) | cal[5]);
    int16_t c3 = (int16_t)(((uint16_t)cal[6] << 8) | cal[7]);

    /* Official InvenSense conversion formulas */
    float t = (float)t_raw / 65535.0f;
    float p = (float)p_raw / 65535.0f;

    float t_comp = c0 * 0.5f + c1 * t;
    float p_comp = c2 * t + c3 * t * t;

    out->temperature = t_comp;
    out->pressure = p * 100000.0f + p_comp;
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    /* Open GPIO chip and request LED line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        sensor_data_t d;
        if (read_sensor(fd, &d) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in 1 s...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa  Temperature: %.2f °C\n", d.pressure, d.temperature);

        /* Blink frequency: 1 Hz when above threshold, 5 Hz when below */
        int period_ms = (d.pressure < HIGH_ALT_THRESHOLD) ? 100 : 500;
        int on_ms = period_ms / 2;
        int off_ms = period_ms - on_ms;

        gpiod_line_set_value(led, 1);
        usleep(on_ms * 1000);
        gpiod_line_set_value(led, 0);
        usleep(off_ms * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    if (fd >= 0) close(fd);
    return ret;
}

