#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define MEASURE_DELAY_US 10000
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = MEASURE_CMD;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        unsigned int raw_t = ((unsigned int)(buf[0] << 8)) | (unsigned char)buf[1];
        unsigned int raw_h = ((unsigned int)(buf[3] << 8)) | (unsigned char)buf[4];

        *temperature = -45.0f + 175.0f * ((float)raw_t / 65535.0f);
        *humidity = -6.0f + 125.0f * ((float)raw_h / 65535.0f);

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "SHT40 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void handle_client(int client_fd, float temp, float hum) {
    char response[512];
    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Connection: close\r\n"
        "\r\n"
        "<!DOCTYPE html><html><head><title>SHT40 Data</title></head>"
        "<body><h1>SHT40 Sensor Data</h1>"
        "<p>Temperature: %.2f &deg;C</p>"
        "<p>Humidity: %.2f %%</p>"
        "</body></html>",
        temp, hum);

    if (len > 0) {
        send(client_fd, response, len, 0);
    }
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT40_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HTTP server listening on port %d\n", HTTP_PORT);

    while (running) {
        float temperature = 0.0f, humidity = 0.0f;

        if (read_sht40(i2c_handle, &temperature, &humidity) != 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(1000000);
            continue;
        }

        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (running) perror("accept");
            continue;
        }

        handle_client(client_fd, temperature, humidity);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

