#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_out) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | (buf[1] & 0xFF));
    raw >>= 4;
    *temp_out = raw * 0.0625f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[20];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Smart Greenhouse Climate Monitoring System\n");
    printf("TMP102 at I2C bus %d, address 0x%02X. Logging to %s every %d seconds.\n",
           I2C_BUS, TMP102_ADDR, LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature reading.\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read temperature from sensor.\n");
        }

        if (running) {
            gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

