#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define TEMP_LOW_REG 0x00
#define TEMP_HIGH_REG 0x01
#define HUMID_LOW_REG 0x02
#define HUMID_HIGH_REG 0x03
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F

#define I2C_BUS 1
#define POLL_TIMEOUT_MS 500
#define POLL_INTERVAL_US 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t temp_low, temp_high;
    int16_t raw_temp;

    if (read_register(handle, TEMP_LOW_REG, &temp_low) < 0) return -1;
    if (read_register(handle, TEMP_HIGH_REG, &temp_high) < 0) return -1;

    raw_temp = (int16_t)((temp_high << 8) | temp_low);
    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint8_t humid_low, humid_high;
    int16_t raw_humid;

    if (read_register(handle, HUMID_LOW_REG, &humid_low) < 0) return -1;
    if (read_register(handle, HUMID_HIGH_REG, &humid_high) < 0) return -1;

    raw_humid = (int16_t)((humid_high << 8) | humid_low);
