#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_LINE 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    float kp, ki, kd;
    float integral, prev_error;
} PIDController;

float pid_calculate(PIDController *pid, float setpoint, float actual) {
    float error = setpoint - actual;
    pid->integral += error;
    float derivative = error - pid->prev_error;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

int read_max6675(int spi_fd, float *temp) {
    unsigned char tx[2] = {0, 0};
    unsigned char rx[2] = {0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    if (rx[1] & 0x04) {
        fprintf(stderr, "MAX6675 open circuit fault\n");
        return -2;
    }
    int raw = ((rx[0] << 8) | rx[1]) >> 3;
    *temp = raw * 0.25f;
    return 0;
}

int read_profile(const char *filename, float *times, float *temps, int *count) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open profile %s: %s\n", filename, strerror(errno));
        return -1;
    }
    int c = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && c < 100) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        if (sscanf(line, "%f,%f", &times[c], &temps[c]) == 2) {
            c++;
        } else {
            fprintf(stderr, "Parse error in profile line %d\n", c + 1);
            fclose(fp);
            return -1;
        }
    }
    fclose(fp);
    *count = c;
    return 0;
}

int log_data(FILE *fp, float temp, float setpoint, float duty) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, setpoint, duty) < 0) {
        fprintf(stderr, "Log write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open SPI %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }
    unsigned char mode = SPI_MODE;
    unsigned char bits = SPI_BITS;
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI config failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", RELAY_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay, "reflow", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open log %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(relay);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    fprintf(log, "Timestamp,Temperature,Setpoint,DutyCycle\n");

    float times[100], temps[100];
    int profile_count = 0;
    if (read_profile(PROFILE_FILE, times, temps, &profile_count) != 0) {
        fclose(log);
        gpiod_line_release(relay);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (profile_count == 0) {
        fprintf(stderr, "Profile empty\n");
        fclose(log);
        gpiod_line_release(relay);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    PIDController pid = {0.1f, 0.01f, 0.001f, 0.0f, 0.0f};
    int profile_idx = 0;
    float setpoint = temps[0];
    float current_time = 0.0f;

    while (program_running) {
        float temp;
        int ret = read_max6675(spi_fd, &temp);
        if (ret == -1) {
            sleep(1);
            continue;
        }
        if (ret == -2) {
            fprintf(stderr, "Sensor absent, skipping cycle\n");
            sleep(1);
            continue;
        }

        float duty = pid_calculate(&pid, setpoint, temp);
        gpiod_line_set_value(relay, duty > 0.5f ? 1 : 0);

        if (log_data(log, temp, setpoint, duty) != 0) {
            fprintf(stderr, "Logging error, continuing\n");
        }

        current_time += 1.0f;
        if (profile_idx < profile_count && current_time >= times[profile_idx]) {
            profile_idx++;
            if (profile_idx < profile_count) {
                setpoint = temps[profile_idx];
            } else {
                setpoint = temps[profile_count - 1];
            }
        }
        sleep(1);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(log);
    return 0;
}

