#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <dirent.h>
#include <fcntl.h>
#include <gpiod.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define GPIO_CHIP_NAME "gpiochip0"
#define HEATER_RELAY_LINE 17
#define PWM_LINE 18
#define PWM_PERIOD_NS 10000000  /* 10 ms => 100 Hz */
#define MAX_SENSORS 10
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static float setpoint = 25.0f;
static float Kp = 1.0f, Ki = 0.1f, Kd = 0.01f;
static float integral = 0.0f, previous_error = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_w1_sensor(const char *id, float *temp) {
    char path[256];
    char buf[256];
    int fd, n;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DEVICES_DIR, id);
    fd = open(path, O_RDONLY);
    if (fd < 0) return -1;

    n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n <= 0) return -1;
    buf[n] = '\0';

    /* Validate CRC: line must contain "YES" */
    if (!strstr(buf, "YES")) return -2;

    /* Find t= value */
    char *t = strstr(buf, "t=");
    if (!t) return -3;

    long raw = strtol(t + 2, NULL, 10);
    if (raw == 0 && errno == EINVAL) return -4;
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, HEATER_RELAY_LINE);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", HEATER_RELAY_LINE, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Failed to request relay output: %s\n", strerror(errno));
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_LINE);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line %d: %s\n", PWM_LINE, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Failed to request PWM output: %s\n", strerror(errno));
        return -1;
    }

    /* Software PWM: start with 0 duty */
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Failed to set PWM initial value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void set_pwm_duty(float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 100.0f) duty = 100.0f;
    int on_ns = (int)((duty / 100.0f) * PWM_PERIOD_NS);
    int off_ns = PWM_PERIOD_NS - on_ns;

    /* Simple software PWM: toggle line with usleep */
    if (on_ns > 0) {
        if (gpiod_line_set_value(pwm_line, 1) < 0) return;
        usleep(on_ns / 1000);
    }
    if (off_ns > 0) {
        if (gpiod_line_set_value(pwm_line, 0) < 0) return;
        usleep(off_ns / 1000);
    }
}

static float calculate_pid(float current) {
    float error = setpoint - current;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static void log_data(float avg_temp, float pid_out, float duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", ts, avg_temp, setpoint, pid_out, duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc > 1) setpoint = atof(argv[1]);
    if (argc > 2) Kp = atof(argv[2]);
    if (argc > 3) Ki = atof(argv[3]);
    if (argc > 4) Kd = atof(argv[4]);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char sensor_ids[MAX_SENSORS][32];
    int num_sensors = 0;
    DIR *dir = opendir(W1_DEVICES_DIR);
    if (dir) {
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strncmp(ent->d_name, "28-", 3) == 0 && num_sensors < MAX_SENSORS) {
                strncpy(sensor_ids[num_sensors], ent->d_name, 31);
                sensor_ids[num_sensors][31] = '\0';
                num_sensors++;
            }
        }
        closedir(dir);
    } else {
        fprintf(stderr, "Warning: cannot open %s: %s\n", W1_DEVICES_DIR, strerror(errno));
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Check w1-gpio module and sensor wiring.\n");
        cleanup();
        return 1;
    }

    printf("Greenhouse PID controller started. Sensors: %d\n", num_sensors);

    while (running) {
        float temps[MAX_SENSORS];
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            float t;
            int rc = read_w1_sensor(sensor_ids[i], &t);
            if (rc == 0) {
                temps[valid++] = t;
            } else if (rc == -2) {
                fprintf(stderr, "CRC error on sensor %s\n", sensor_ids[i]);
            } else {
                fprintf(stderr, "Read error on sensor %s (rc=%d)\n", sensor_ids[i], rc);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid temperature readings. Skipping cycle.\n");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        float avg = 0.0f;
        for (int i = 0; i < valid; i++) avg += temps[i];
        avg /= valid;

        float pid_out = calculate_pid(avg);
        float duty = pid_out;
        if (duty < 0.0f) duty = 0.0f;
        if (duty > 100.0f) duty = 100.0f;

        set_pwm_duty(duty);
        log_data(avg, pid_out, duty);

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

