#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", i + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", i + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[3] = { 0xBE, 0x08, 0x00 };
    if (i2c_write(fd, init_cmd, 3) != 0) return -1;
    sleep_ms(20);
    return 0;
}

static int aht20_read(int fd, float *humidity) {
    uint8_t trigger[3] = { 0xAC, 0x33, 0x00 };
    if (i2c_write(fd, trigger, 3) != 0) return -1;
    sleep_ms(80);

    uint8_t data[6];
    if (i2c_read(fd, data, 6) != 0) return -1;

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy or not calibrated\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    *humidity = ((float)raw / 1048576.0f) * 100.0f;
    return 0;
}

static void log_reading(float humidity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

