#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define API_ENDPOINT "http://api.example.com/humidity"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 80
#define MEASURE_HUMIDITY_CMD 0xE5
#define MEASUREMENT_DELAY_US 50000
#define POLL_INTERVAL_S 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t buf[3];

    if (i2c_write_cmd(fd, MEASURE_HUMIDITY_CMD) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_US);

    if (i2c_read_bytes(fd, buf, 3) < 0) {
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0xFFFC;

    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;

    if (*humidity < 0.0f || *humidity > 100.0f) {
        syslog(LOG_ERR, "Humidity out of range: %.2f", *humidity);
        return -1;
    }

    return 0;
}

static int send_http_post(const char *json_data) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", SERVER_IP);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        API_ENDPOINT, SERVER_IP, strlen(json_data), json_data);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request formatting failed");
        close(sockfd);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < req_len) {
        ssize_t n = send(sockfd, request + sent, req_len - sent, 0);
        if (n < 0) {
            syslog(LOG_ERR, "Send failed: %s", strerror(errno));
            close(sockfd);
            return -1;
        }
        sent += n;
    }

    char response[1024];
    ssize_t n = recv(sockfd, response, sizeof(response) - 1, 0);
    if (n < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[n] = '\0';

    if (strstr(response, "HTTP/1.1 200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP request failed: %s", response);
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D humidity monitor started on %s (addr 0x%02X)", I2C_BUS, HTU21D_ADDR);

    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            char json_data[64];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

            if (send_http_post(json_data) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from HTU21D");
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

