#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO_LINE 17
#define GPIO_CHIP "gpiochip4"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_fp = NULL;
static char current_date[16];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_write_cmd2(int fd, unsigned char cmd, unsigned char arg) {
    unsigned char buf[2] = {cmd, arg};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_temperature(float *temp) {
    unsigned char buf[2];
    for (int r = 0; r < MAX_RETRIES; r++) {
        if (i2c_write_cmd(i2c_fd, 0x00) < 0) { msleep(RETRY_DELAY_MS); continue; }
        msleep(6);
        if (i2c_read_bytes(i2c_fd, buf, 2) < 0) { msleep(RETRY_DELAY_MS); continue; }
        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temp = raw * 0.0078125f;
        return 0;
    }
    return -1;
}

static int read_humidity(float *hum, float *temp) {
    unsigned char init[3] = {0xBE, 0x08, 0x00};
    unsigned char measure[3] = {0xAC, 0x33, 0x00};
    unsigned char data[7];
