#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static void stop_motor(struct gpiod_line *in1, struct gpiod_line *in2,
                        struct gpiod_line *ena)
{
    if (in1) gpiod_line_set_value(in1, 0);
    if (in2) gpiod_line_set_value(in2, 0);
    if (ena) gpiod_line_set_value(ena, 0);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        fprintf(stderr, "Failed to acquire one or more GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain-monitor") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto cleanup;
    }
    if (gpiod_line_request_output(ena_line, "motor-ena", 0) < 0) {
        perror("gpiod_line_request_output(ena)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor-in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor-in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        goto cleanup;
    }

    log_event("Program started: monitoring rain sensor on GPIO17.");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            perror("gpiod_line_get_value(rain)");
            break;
        }

        if (val == 0) {
            log_event("Rain detected! Closing window.");

            if (gpiod_line_set_value(in1_line, 1) < 0 ||
                gpiod_line_set_value(in2_line, 0) < 0 ||
                gpiod_line_set_value(ena_line, 1) < 0) {
                perror("Failed to start motor");
                break;
            }

            for (int i = 0; i < MOTOR_RUN_SEC && program_running; i++)
                sleep(1);

            stop_motor(in1_line, in2_line, ena_line);
            log_event("Window closed. Motor stopped.");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++)
            sleep(1);
    }

    stop_motor(in1_line, in2_line, ena_line);
    log_event("Program exiting.");
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line) gpiod_line_release(rain_line);
    if (ena_line)  gpiod_line_release(ena_line);
    if (in1_line)  gpiod_line_release(in1_line);
    if (in2_line)  gpiod_line_release(in2_line);
    if (chip)     gpiod_chip_close(chip);
    return ret;
}

