#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read /proc/stat and return the number of jiffies spent in user+sys. */
static int64_t read_cpu_jiffies(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(/proc/stat)");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets(/proc/stat)");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    int64_t user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "cpu  %lld %lld %lld %lld %lld %lld %lld %lld %lld %lld",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "sscanf failed to parse /proc/stat\n");
        return -1;
    }
    return user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
}

/* Map CPU load (0.0 .. 1.0) to a common-anode RGB color. */
static void load_to_color(float load, int *r, int *g, int *b)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 1.0f) load = 1.0f;

    /* Common-anode: 0 = full brightness, 255 = off. */
    *r = (int)(255.0f * load);
    *g = (int)(255.0f * (1.0f - load));
    *b = 0;
}

static void clamp_pwm(int *v)
{
    if (*v < 0)   *v = 0;
    if (*v > 255) *v = 255;
}

static void set_led_color(int r, int g, int b)
{
    clamp_pwm(&r);
    clamp_pwm(&g);
    clamp_pwm(&b);
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

static void led_off(void)
{
    /* Common-anode: drive all channels high (255) to turn the LED off. */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int64_t prev = read_cpu_jiffies();
    if (prev < 0) {
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        gpioDelay(SAMPLE_US);

        int64_t now = read_cpu_jiffies();
        if (now < 0) {
            led_off();
            break;
        }

        int64_t elapsed = now - prev;
        if (elapsed <= 0) {
            prev = now;
            continue;
        }

        int64_t user = now;
        float load = (float)user / (float)elapsed;

        int r, g, b;
        load_to_color(load, &r, &g, &b);
        set_led_color(r, g, b);

        prev = now;
    }

    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

