#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define I2C_BUS 1
#define SAMPLE_INTERVAL_SEC 5

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != (int)len) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) return -1;
    return 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *cal) {
    uint8_t buf[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, buf, sizeof(buf)) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int handle, bmp280_calib_data *cal) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_REG_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle, cal) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read(int handle, const bmp280_calib_data *cal, float *temperature, float *pressure) {
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(10000);
    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
