#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FAN_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

#define MAX31855_FAULT_BIT  16
#define MAX31855_OC_BIT     0
#define MAX31855_SCG_BIT    1
#define MAX31855_SCV_BIT    2

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & (1 << MAX31855_FAULT_BIT)) {
        if (raw & (1 << MAX31855_OC_BIT))
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (raw & (1 << MAX31855_SCG_BIT))
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (raw & (1 << MAX31855_SCV_BIT))
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -1;
    }

    int16_t thermocouple_data = (int16_t)(raw >> 18);
    *temperature = thermocouple_data * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < 25.0f) return 0;
    if (temperature < 40.0f) return (int)((temperature - 25.0f) / 15.0f * 50.0f);
    if (temperature < 60.0f) return (int)((temperature - 40.0f) / 20.0f * 150.0f) + 50;
    return 255;
}

static void log_data(float temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
        }
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FAN_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            if (gpioPWM(FAN_PIN, pwm_duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty\n");
            }
            log_data(temperature, pwm_duty);
            printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping fan update\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_PIN, 0);
    spiClose(spi_handle);
    print_log_buffer();
    gpioTerminate();
    return 0;
}

