        fprintf(stderr, "SPI init failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_rtd_registers(uint8_t *rtd_lsb, uint8_t *rtd_msb, uint8_t *fault) {
    uint8_t tx[4] = {0x01, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    if (spi_transfer(tx, rx, 4) < 0) {
        return -1;
    }
    *rtd_lsb = rx[1];
    *rtd_msb = rx[2];
    *fault = rx[3];
    return 0;
}

int read_fault_status(uint8_t *fault) {
    uint8_t tx[2] = {0x09, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *fault = rx[1];
    return 0;
}

void clear_fault_status(void) {
    uint8_t tx[2] = {0x82, 0x00};
    uint8_t rx[2] = {0};
    spi_transfer(tx, rx, 2);
}

double calculate_temperature(uint16_t rtd_value) {
    double rtd_resistance = (double)rtd_value * R0 / 32768.0;
    double Z = rtd_resistance / R0;
    double temp = -RTD_A;
    temp += RTD_B * Z;
    temp += RTD_C * Z * Z * Z;
    return temp;
}

void log_data(double temperature, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%s\n", timestamp, temperature, status);
    fflush(log_file);
}

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE_1;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 init failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        uint8_t rtd_lsb = 0, rtd_msb = 0, fault = 0;
        gpiod_line_set_value(cs_line, 0);
        if (read_rtd_registers(&rtd_lsb, &rtd_msb, &fault) < 0) {
            fprintf(stderr, "SPI read error: %s\n", strerror(errno));
            log_data(0.0, "SPI_ERROR");
        } else {
            gpiod_line_set_value(cs_line, 1);
            uint16_t rtd_value = ((uint16_t)rtd_msb << 8) | rtd_lsb;
            if (fault & 0x01) {
                fprintf(stderr, "Fault detected\n");
                log_data(0.0, "FAULT");
                if (read_fault_status(&fault) == 0) {
                    clear_fault_status();
                }
            } else {
                double temperature = calculate_temperature(rtd_value);
                if (temperature > FAULT_THRESHOLD) {
                    fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                    log_data(temperature, "OUT_OF_RANGE");
                } else {
                    log_data(temperature, "OK");
                }
            }
        }
        sleep(5);
    }

    cleanup();
    return 0;
}

