#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 1200
#define OSS 0
#define ALERT_THRESHOLD 5.0

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

static PressureData pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    ac1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 1));
    ac2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 2) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 3));
    ac3 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 4) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 5));
    ac4 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 6) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 7));
    ac5 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 8) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 9));
    ac6 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 10) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 11));
    b1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 12) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 13));
    b2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 14) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 15));
    mb = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 16) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 17));
    mc = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 18) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 19));
    md = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 20) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 21));
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(5000 + (3000 << OSS));
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error: Failed to read temperature from BMP180.\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error: Failed to read pressure from BMP180.\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    time_t now = time(NULL);
    pressure_buffer[buffer_index].timestamp = now;
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    float avg = calculate_average_pressure();
    if (buffer_count >= 600 && fabs(pressure - avg) > ALERT_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", pressure, avg);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X.\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error: Could not read calibration data from BMP180.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up timer.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, 50, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

