#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    char buf[16];
    if (!fgets(buf, sizeof(buf), fp)) {
        perror("fgets temperature");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    long millideg = strtol(buf, NULL, 10);
    if (millideg <= 0) {
        fprintf(stderr, "Invalid temperature value: %ld\n", millideg);
        return -1;
    }
    *temp_out = (float)millideg / 1000.0f;
    return 0;
}

static int set_fan_speed(float temp) {
    float duty;
    if (temp <= TEMP_MIN) {
        duty = 0.0f;
    } else if (temp >= TEMP_MAX) {
        duty = 100.0f;
    } else {
        duty = (temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * 100.0f;
    }
    int pwm = (int)(duty * (PWM_RANGE / 100.0f));
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, pwm) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", pwm);
        return -1;
    }
    return pwm;
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    if (!tm) {
        perror("localtime");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(log_fp, "%s, Temperature: %.2f C, Duty: %d\n", ts, temp, duty) < 0) {
        perror("fprintf log");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        perror("fflush log");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. GPIO%d, %d Hz, range %d. Ctrl+C to exit.\n",
           FAN_GPIO, PWM_FREQ, PWM_RANGE);

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle.\n");
        } else {
            int duty = set_fan_speed(temp);
            if (duty < 0) {
                fprintf(stderr, "Failed to set fan speed.\n");
            } else {
                if (log_data(temp, duty) != 0) {
                    fprintf(stderr, "Logging failed.\n");
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (log_fp) {
        fclose(log_fp);
    }
    gpioTerminate();
    return 0;
}

