#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define CONFIG_FILE "config.json"
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775
#define MAX_TEMP 80.0
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config file %s; using defaults\n", filename);
        *target_temp = DEFAULT_TARGET_TEMP;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        return 0;
    }
    char buffer[512];
    size_t n = fread(buffer, 1, sizeof(buffer) - 1, fp);
    buffer[n] = '\0';
    fclose(fp);
    if (strstr(buffer, "target_temperature") && strstr(buffer, "Kp") &&
        strstr(buffer, "Ki") && strstr(buffer, "Kd")) {
        *target_temp = DEFAULT_TARGET_TEMP;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        if (sscanf(buffer, "{\"target_temperature\": %lf, \"Kp\": %lf, \"Ki\": %lf, \"Kd\": %lf}",
                   target_temp, kp, ki, kd) != 4) {
            fprintf(stderr, "Warning: config format invalid; using defaults\n");
            *target_temp = DEFAULT_TARGET_TEMP;
            *kp = DEFAULT_KP;
            *ki = DEFAULT_KI;
            *kd = DEFAULT_KD;
        }
    } else {
        fprintf(stderr, "Warning: config missing required fields; using defaults\n");
        *target_temp = DEFAULT_TARGET_TEMP;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
    }
    return 0;
}

static int max31865_init(void) {
    char tx[2] = {MAX31865_CONFIG_REG, 0xC1};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI write to config register failed\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd_code(int *rtd_code) {
    char tx[3] = {MAX31865_RTD_MSB_REG | 0x80, 0x00, 0x00};
    char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI read of RTD registers failed\n");
        return -1;
    }
    if (rx[1] & 0x01) {
        char ftx[2] = {MAX31865_FAULT_REG | 0x80, 0x00};
        char frx[2] = {0, 0};
        if (spiXfer(spi_handle, ftx, frx, 2) == 2) {
            if (frx[1] & 0x01) fprintf(stderr, "Fault: open circuit\n");
            if (frx[1] & 0x02) fprintf(stderr, "Fault: over-voltage\n");
            if (frx[1] & 0x04) fprintf(stderr, "Fault: under-voltage\n");
        }
        return -1;
    }
    *rtd_code = ((rx[1] & 0xFF) << 8) | (rx[2] & 0xFF);
    *rtd_code >>= 1;
    return 0;
}

static double rtd_code_to_resistance(int rtd_code) {
    return ((double)rtd_code / 32768.0) * R_REF;
}

static double resistance_to_temperature(double r) {
    if (r <= 0.0) return -273.15;
    double t = (r / R0 - 1.0) / A;
    if (t < 0.0) {
        t = (r / R0 - 1.0 - B * t * t) / (A + 2.0 * B * t);
    }
    return t;
}

static double pid_calculate(double target, double current, double *integral, double *prev_error, double kp, double ki, double kd) {
    double error = target - current;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static void set_heater_pwm(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 100.0) duty = 100.0;
    gpioPWM(HEATER_GPIO, (int)(duty * (PWM_RANGE / 100.0)));
}

static void heater_off(void) {
    gpioPWM(HEATER_GPIO, 0);
}

int main(void) {
    double target_temp = DEFAULT_TARGET_TEMP;
    double kp = DEFAULT_KP, ki = DEFAULT_KI, kd = DEFAULT_KD;
    double integral = 0.0, prev_error = 0.0;
    int rtd_code;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialization failed\n");
        return 1;
    }

    if (read_config(CONFIG_FILE, &target_temp, &kp, &ki, &kd) != 0) {
        fprintf(stderr, "Fatal: config read failed\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Fatal: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (max31865_init() != 0) {
        fprintf(stderr, "Fatal: MAX31865 init failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    heater_off();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Heater control started. Target: %.2f°C, Kp: %.3f, Ki: %.3f, Kd: %.3f\n",
           target_temp, kp, ki, kd);

    while (running) {
        if (read_rtd_code(&rtd_code) != 0) {
            fprintf(stderr, "Error: RTD read failed, shutting down\n");
            heater_off();
            break;
        }
        double r = rtd_code_to_resistance(rtd_code);
        double current_temp = resistance_to_temperature(r);
        if (current_temp < -200.0) {
            fprintf(stderr, "Error: invalid temperature (%.2f°C), shutting down\n", current_temp);
            heater_off();
            break;
        }
        if (current_temp > MAX_TEMP) {
            fprintf(stderr, "Error: temperature %.2f°C exceeds max %.1f°C, shutting down\n",
                    current_temp, MAX_TEMP);
            heater_off();
            break;
        }
        double pid_out = pid_calculate(target_temp, current_temp, &integral, &prev_error, kp, ki, kd);
        set_heater_pwm(pid_out);
        printf("Temp: %.2f°C, PID: %.2f, PWM: %.1f%%\n", current_temp, pid_out, pid_out);
        gpioDelay(LOOP_DELAY_US);
    }

    heater_off();
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

