        printf("Temp: %.2f°C, PID: %.2f, PWM: %.1f%%\n", current_temp, pid_out, pid_out);
        gpioDelay(LOOP_DELAY_US);
    }

    heater_off();
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
