#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR        0x77
#define BMP180_REG_CAL     0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA    0xF6
#define BMP180_CMD_TEMP    0x2E
#define BMP180_CMD_PRESS   0x34
#define FAN_GPIO           18
#define BUFFER_SIZE        60
#define SAMPLE_PERIOD_US   500000  /* 500 ms */
#define TEMP_THRESHOLD     30.0f

/* ---- Calibration coefficients (signed/unsigned 16-bit) ---- */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

/* ---- Circular buffer ---- */
typedef struct {
    time_t   timestamp;
    float    temperature;
    float    pressure;
} sensor_data_t;

static sensor_data_t  buffer[BUFFER_SIZE];
static int            buf_head = 0;
static int            buf_count = 0;
static int            i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static bmp180_cal_t   cal;
static int            cal_valid = 0;

/* ---- Prototypes ---- */
static int  read_calibration(void);
static int  read_raw_temp(int16_t *raw);
static int  read_raw_press(int32_t *raw);
static float calc_temperature(int16_t ut);
static float calc_pressure(int32_t up, int16_t ut);
static void add_reading(float temp, float pres);
static void check_threshold(float temp);
static void timer_cb(void *user);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/* Read 22 bytes of calibration data from register 0xAA (11 words).    */
/* ------------------------------------------------------------------ */
static int read_calibration(void)
{
    char reg = BMP180_REG_CAL;
    char data[22];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set calibration register pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }

    cal.ac1 = (int16_t)((data[0]  << 8) | data[1]);
    cal.ac2 = (int16_t)((data[2]  << 8) | data[3]);
    cal.ac3 = (int16_t)((data[4]  << 8) | data[5]);
    cal.ac4 = (uint16_t)((data[6]  << 8) | data[7]);
    cal.ac5 = (uint16_t)((data[8]  << 8) | data[9]);
    cal.ac6 = (uint16_t)((data[10] << 8) | data[11]);
    cal.b1  = (int16_t)((data[12] << 8) | data[13]);
    cal.b2  = (int16_t)((data[14] << 8) | data[15]);
    cal.mb  = (int16_t)((data[16] << 8) | data[17]);
    cal.mc  = (int16_t)((data[18] << 8) | data[19]);
    cal.md  = (int16_t)((data[20] << 8) | data[21]);

    /* Sanity-check: AC1 should not be 0 or 0xFFFF on a real BMP180. */
    if (cal.ac1 == 0 || cal.ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Error: calibration data invalid (AC1=%d)\n", cal.ac1);
        return -1;
    }
    cal_valid = 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a temperature conversion and read the 16-bit raw value.     */
/* ------------------------------------------------------------------ */
static int read_raw_temp(int16_t *raw)
{
    char cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_TEMP };
    char reg = BMP180_REG_DATA;
    char data[2];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set temperature data pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a pressure conversion (OSS=0) and read the 16-bit raw value.*/
/* ------------------------------------------------------------------ */
static int read_raw_press(int32_t *raw)
{
    char cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_PRESS };
    char reg = BMP180_REG_DATA;
    char data[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max for OSS=0 */

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set pressure data pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    *raw = ((int32_t)(data[0] << 16) | (data[1] << 8) | data[2]) >> 8;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 true temperature (°C) — integer math, returns float.         */
/* ------------------------------------------------------------------ */
static float calc_temperature(int16_t ut)
{
    int32_t x1 = ((int32_t)ut - (int32_t)cal.ac6) * (int32_t)cal.ac5 >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    int32_t t  = (b5 + 8) >> 4;
    return (float)t / 10.0f;
}

/* ------------------------------------------------------------------ */
/* BMP180 true pressure (Pa) — integer math, returns float.            */
/* ------------------------------------------------------------------ */
static float calc_pressure(int32_t up, int16_t ut)
{
    int32_t x1 = ((int32_t)ut - (int32_t)cal.ac6) * (int32_t)cal.ac5 >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t b3 = (((int32_t)cal.ac1 * 4 + x3 + x4) + 2) >> 2;

    uint32_t x1p = ((uint32_t)cal.ac3 * b6) >> 13;
    uint32_t x2p = ((uint32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3p = ((x1p + x2p) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (x3p + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1p = (p >> 8) * (p >> 8);
    x1p = (x1p * 3038) >> 16;
    x2p = (-7357 * p) >> 16;
    p += (x1p + x2p + 3791) >> 4;

    return (float)p;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the circular buffer.                            */
/* ------------------------------------------------------------------ */
static void add_reading(float temp, float pres)
{
    buffer[buf_head].timestamp  = time(NULL);
    buffer[buf_head].temperature = temp;
    buffer[buf_head].pressure    = pres;
    buf_head = (buf_head + 1) % BUFFER_SIZE;
    if (buf_count < BUFFER_SIZE) buf_count++;
}

/* ------------------------------------------------------------------ */
/* Fan control based on temperature threshold.                          */
/* ------------------------------------------------------------------ */
static void check_threshold(float temp)
{
    if (temp > TEMP_THRESHOLD) {
        if (gpioRead(FAN_GPIO) == 0) {
            gpioWrite(FAN_GPIO, 1);
            printf("Fan ON  (T=%.2f C)\n", temp);
        }
    } else {
        if (gpioRead(FAN_GPIO) == 1) {
            gpioWrite(FAN_GPIO, 0);
            printf("Fan OFF (T=%.2f C)\n", temp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* pigpio timer callback — runs in a dedicated thread.                  */
/* Keep it short: do I2C and printf in the main thread.                 */
/* ------------------------------------------------------------------ */
static void timer_cb(void *user)
{
    (void)user;
    /* Just set a flag; do heavy work in the main loop. */
}

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: set flag only.                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        fprintf(stderr, "Error: BMP180 calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_cb, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 monitoring started (500 ms period). Ctrl+C to exit.\n");

    while (running) {
        if (gpioReadTimerFuncEx(0) == 0) {  /* timer tick occurred */
            int16_t  ut;
            int32_t  up;

            if (read_raw_temp(&ut) != 0 || read_raw_press(&up) != 0) {
                fprintf(stderr, "Warning: I2C read error, skipping sample\n");
            } else {
                float temp = calc_temperature(ut);
                float pres = calc_pressure(up, ut);
                add_reading(temp, pres);
                check_threshold(temp);
                printf("T=%.2f C  P=%.2f Pa\n", temp, pres);
            }
        }
        gpioDelay(10000);  /* 10 ms sleep to avoid busy-wait */
    }

    /* ---- Cleanup ---- */
    gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, NULL, NULL);  /* stop timer */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

