#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 0
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34
#define TOGGLE_PIN 27
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_US 2000000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_edge_tick = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_handle = -1;
static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        return -1;
    }
    cal.ac1 = (buf[0] << 8) | buf[1];
    cal.ac2 = (buf[2] << 8) | buf[3];
    cal.ac3 = (buf[4] << 8) | buf[5];
    cal.ac4 = (buf[6] << 8) | buf[7];
    cal.ac5 = (buf[8] << 8) | buf[9];
    cal.ac6 = (buf[10] << 8) | buf[11];
    cal.b1 = (buf[12] << 8) | buf[13];
    cal.b2 = (buf[14] << 8) | buf[15];
    cal.mb = (buf[16] << 8) | buf[17];
    cal.mc = (buf[18] << 8) | buf[19];
    cal.md = (buf[20] << 8) | buf[21];
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) return -1;
    *ut = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd = BMP180_CMD_PRESSURE + (BMP180_OSS << 6);
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) return -1;
    *up = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    return x1 + x2;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f Pa\n", ts, pressure);
    fclose(fp);
}

static void toggle_logging(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_edge_tick > DEBOUNCE_US) {
        last_edge_tick = tick;
        logging_enabled = !logging_enabled;
        printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(TOGGLE_PIN, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_PIN, PI_PUD_UP);
    if (gpioSetAlertFuncEx(TOGGLE_PIN, toggle_logging, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO%d\n", TOGGLE_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP180 pressure logger started. Press button on GPIO%d to toggle logging.\n", TOGGLE_PIN);
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                double pressure = calculate_pressure(up, ut);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Warning: I2C read error, skipping log entry\n");
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(TOGGLE_PIN, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

