#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define LOG_FILE "heater_log.csv"
#define MAX_DUTY_CYCLE 80.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static int read_max31855(int handle, double *temperature) {
    char buffer[4] = {0};
    int result = spiRead(handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & 0x00000004) fprintf(stderr, "Open circuit");
        if (raw & 0x00000002) fprintf(stderr, "Short to GND");
        if (raw & 0x00000001) fprintf(stderr, "Short to VCC");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t thermocouple_data = (int16_t)(raw >> 18);
    *temperature = thermocouple_data * 0.25;
    return 0;
}

static double calculate_pid(double setpoint, double actual, double *integral, double *last_error, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;

    if (*integral > MAX_DUTY_CYCLE) *integral = MAX_DUTY_CYCLE;
    if (*integral < 0.0) *integral = 0.0;

    double output = (0.1 * error) + (0.01 * (*integral));
    *last_error = error;
    return output;
}

static void set_heater_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 255.0 / 100.0);
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", HEATER_GPIO);
    }
}

int main(int argc, char *argv[]) {
    double target_temperature = 25.0;

    if (argc > 1) {
        target_temperature = atof(argv[1]);
        if (target_temperature <= 0.0 || target_temperature > 1000.0) {
            fprintf(stderr, "Invalid target temperature. Using default 25.0C.\n");
            target_temperature = 25.0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0;
    double last_error = 0.0;
    double temperature = 0.0;
    double duty_cycle = 0.0;
    time_t last_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);
        double dt = difftime(current_time, last_time);
        last_time = current_time;

        if (read_max31855(spi_handle, &temperature) != 0) {
            fprintf(stderr, "Error reading temperature. Setting duty cycle to 0.\n");
            set_heater_duty_cycle(0.0);
            log_data(0.0, 0.0);
            continue;
        }

        duty_cycle = calculate_pid(target_temperature, temperature, &integral, &last_error, dt);
        set_heater_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_heater_duty_cycle(0.0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

