#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define POLL_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU temperature in millidegrees Celsius. Returns -1 on error. */
static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("fopen temperature file");
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        if (ferror(fp))
            perror("fscanf temperature");
        else
            fprintf(stderr, "fscanf: unexpected format in temperature file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0)
        perror("fclose temperature file");

    return temp;
}

/* Common-anode: duty 255 = fully off, duty 0 = fully on. */
static void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN,   PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN,  PWM_RANGE - blue);
}

static void set_led_off(void)
{
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM on each cathode line. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with all channels off (common-anode: duty 255 = off). */
    set_led_off();

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed; skipping update cycle.\n");
            usleep(POLL_US);
            continue;
        }

        int red, green, blue;
        if (temp < 40000) {
            red   = 0;
            green = 0;
            blue  = 255;   /* Blue */
        } else if (temp < 60000) {
            red   = 0;
            green = 255;   /* Green */
            blue  = 0;
        } else {
            red   = 255;   /* Red */
            green = 0;
            blue  = 0;
        }

        set_led_color(red, green, blue);
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
               temp, red, green, blue);
        fflush(stdout);

        usleep(POLL_US);
    }

    /* Clean shutdown: turn off all channels and release pigpio. */
    set_led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

