#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3
#define DEBOUNCE_US 200000
#define SAMPLE_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_tick = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_tick = tick;
    }
}

static int read_s16(int handle, uint8_t reg, int16_t *out) {
    int v = i2cReadWordData(handle, reg);
    if (v < 0) return -1;
    *out = (int16_t)((v >> 8) | (v << 8));
    return 0;
}

static int read_u16(int handle, uint8_t reg, uint16_t *out) {
    int v = i2cReadWordData(handle, reg);
    if (v < 0) return -1;
    *out = (uint16_t)((v >> 8) | (v << 8));
    return 0;
}

static int read_calibration(int handle) {
    if (read_s16(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_u16(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_s16(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) return -1;
    return 0;
}

static int read_raw_temp(int handle, int32_t *raw) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadWordData(handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    *raw = (int32_t)((v >> 8) | (v << 8));
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(26000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *raw = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << OSS) + 2) >> 2);
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, pressure / 100.0);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    int handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(handle) < 0) {
        fprintf(stderr, "BMP180 calibration read failed (sensor absent or invalid)\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "ISR setup failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 ready. Press button on GPIO4 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(handle, &ut) < 0 || read_raw_pressure(handle, &up) < 0) {
                fprintf(stderr, "I2C read error\n");
            } else {
                int32_t b5 = compute_b5(ut);
                int32_t p = compute_pressure(up, b5);
                log_pressure(p);
                printf("Pressure: %.2f hPa\n", p / 100.0);
            }
        }
        gpioDelay(SAMPLE_US);
    }
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

