#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = PI_HIGH;
    int bit_count = 0;
    int i;

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, PI_LOW);
    gpioDelay(2000);
    gpioWrite(DHT22_PIN, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(DHT22_PIN, PI_INPUT);

    uint32_t start = gpioTick();
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT_US) return -1;
    }
    start = gpioTick();
    while (gpioRead(DHT22_PIN) == PI_LOW) {
        if (gpioTick() - start > DHT22_TIMEOUT_US) return -1;
    }
    start = gpioTick();
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT_US) return -1;
    }

    for (i = 0; i < 40; i++) {
        start = gpioTick();
        while (gpioRead(DHT22_PIN) == PI_LOW) {
            if (gpioTick() - start > DHT22_TIMEOUT_US) return -1;
        }
        uint32_t high_start = gpioTick();
        while (gpioRead(DHT22_PIN) == PI_HIGH) {
            if (gpioTick() - high_start > DHT22_TIMEOUT_US) return -1;
        }
        uint32_t high_time = gpioTick() - high_start;
        data[i / 8] <<= 1;
        if (high_time > 50) {
            data[i / 8] |= 1;
        }
        bit_count++;
    }

    if (bit_count != 40) return -1;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)(((data[0] << 8) | data[1]) / 10.0);
    return 0;
}

static int post_humidity(float humidity, const char *url) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            syslog(LOG_INFO, "Humidity %.1f%% posted to %s", humidity, url);
            ret = 0;
        } else {
            syslog(LOG_ERR, "HTTP POST returned status %ld", http_code);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "libcurl global init failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "DHT22 humidity monitor started on GPIO %d, posting to %s", DHT22_PIN, server_url);

    while (running) {
        float humidity = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(&humidity) == 0) {
                success = 1;
                break;
            }
            syslog(LOG_WARNING, "DHT22 read failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) sleep(RETRY_DELAY_SEC);
        }

        if (success) {
            for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
                if (post_humidity(humidity, server_url) == 0) break;
                syslog(LOG_WARNING, "HTTP POST failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
                if (attempt < MAX_RETRIES - 1) sleep(RETRY_DELAY_SEC);
            }
        } else {
            syslog(LOG_ERR, "DHT22 sensor absent or unresponsive after %d attempts", MAX_RETRIES);
        }

        if (running) sleep(READ_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    curl_global_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

