#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

#define TEMP_THRESHOLD_1 45000
#define TEMP_THRESHOLD_2 55000
#define TEMP_THRESHOLD_3 65000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sysfs_int(const char *path, int *out) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    int val;
    if (fscanf(fp, "%d", &val) != 1) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *out = val;
    return 0;
}

static int write_sysfs_int(const char *path, int val) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for write: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", val) < 0) {
        fprintf(stderr, "Error writing %d to %s: %s\n", val, path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s after write: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_fan_speed(int temp, int max_state) {
    int state;
    if (temp < TEMP_THRESHOLD_1) {
        state = 0;
    } else if (temp < TEMP_THRESHOLD_2) {
        state = 1;
    } else if (temp < TEMP_THRESHOLD_3) {
        state = 2;
    } else {
        state = 3;
    }
    if (state > max_state) state = max_state;
    return state;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int max_state = 0;
    if (read_sysfs_int(MAX_STATE_FILE, &max_state) != 0) {
        fprintf(stderr, "Failed to read cooling device max_state. Exiting.\n");
        return EXIT_FAILURE;
    }
    if (max_state < 0 || max_state > 3) {
        fprintf(stderr, "Invalid max_state (%d) from %s. Exiting.\n", max_state, MAX_STATE_FILE);
        return EXIT_FAILURE;
    }

    int current_fan_state = -1;
    int exit_code = EXIT_SUCCESS;

    while (running) {
        int cpu_temp = 0;
        if (read_sysfs_int(CPU_TEMP_FILE, &cpu_temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_state = set_fan_speed(cpu_temp, max_state);

        if (desired_state != current_fan_state) {
            if (write_sysfs_int(FAN_STATE_FILE, desired_state) != 0) {
                fprintf(stderr, "Failed to set fan state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
                sleep(POLL_INTERVAL_SEC);
                continue;
            }
            current_fan_state = desired_state;
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Fan speed set to state %d (temp=%d mC)", desired_state, cpu_temp);
            log_message(log_buf);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_sysfs_int(FAN_STATE_FILE, 0) != 0) {
        fprintf(stderr, "Warning: failed to stop fan on shutdown.\n");
        exit_code = EXIT_FAILURE;
    } else {
        log_message("Fan stopped on shutdown.");
    }

    return exit_code;
}

