#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temp, int duty, float pid_out, const char *err) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2f, Duty: %d, PID: %.2f, Err: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, duty, pid_out, err ? err : "None");
    fclose(fp);
}

static int read_max31855(float *temp) {
    char buf[4] = {0};
    int ret = spiRead(spi_handle, buf, 4);
    if (ret != 4) return -1;
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000004) return -2;
        if (raw & 0x00000002) return -3;
        if (raw & 0x00000001) return -4;
        return -5;
    }
    int16_t therm = (int16_t)(raw >> 18);
    *temp = therm * 0.25;
    return 0;
}

static float pid_control(float setpoint, float actual, float *integral, float *prev_error, float Kp, float Ki, float Kd) {
    float error = setpoint - actual;
    *integral += error;
    float deriv = error - *prev_error;
    float out = Kp * error + Ki * (*integral) + Kd * deriv;
    *prev_error = error;
    return out;
}

static void set_heater_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty);
}

int main(void) {
    float Kp = 1.0f, Ki = 0.1f, Kd = 0.01f, setpoint = 50.0f;
    float integral = 0.0f, prev_error = 0.0f;
    int duty = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioPWM(HEATER_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("PID heater started. Ctrl+C to exit.\n");

    while (running) {
        float temp;
        int rc = read_max31855(&temp);
        const char *err = NULL;

        if (rc == 0) {
            if (temp > MAX_TEMP || temp < MIN_TEMP) {
                err = "Failsafe: temp out of range";
                set_heater_duty(0);
                integral = 0;
                prev_error = 0;
            } else {
                float pid_out = pid_control(setpoint, temp, &integral, &prev_error, Kp, Ki, Kd);
                duty = (int)(pid_out + 0.5f);
                if (duty < 0) duty = 0;
                if (duty > PWM_RANGE) duty = PWM_RANGE;
                set_heater_duty(duty);
            }
        } else {
            err = "SPI read error";
            set_heater_duty(0);
            integral = 0;
            prev_error = 0;
            switch (rc) {
                case -2: err = "Thermocouple open"; break;
                case -3: err = "Thermocouple short to GND"; break;
                case -4: err = "Thermocouple short to VCC"; break;
                default: err = "Unknown SPI fault"; break;
            }
        }

        log_data(rc == 0 ? temp : -999.0f, duty, rc == 0 ? (float)duty : 0.0f, err);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_heater_duty(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

