#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQ 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int set_fan_speed(int temp_milli) {
    float temp_c = temp_milli / 1000.0f;
    int duty;
    if (temp_c <= MIN_TEMP) {
        duty = 0;
    } else if (temp_c >= MAX_TEMP) {
        duty = 100;
    } else {
        duty = (int)(((temp_c - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0f);
    }
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
        return -1;
    }
    return duty;
}

static int log_data(int temp_milli, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    float temp_c = temp_milli / 1000.0f;
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty);
    fclose(fp);
    return 0;
}

static int write_csv_header(void) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("fopen log file for header");
            return -1;
        }
        fprintf(fp, "Timestamp,Temperature(C),PWM_Duty(%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }

    if (write_csv_header() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }
        int duty = set_fan_speed(temp);
        if (duty < 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }
        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return 0;
}

