#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define FLOW_LOG_FILE "flow_log.txt"
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x08
#define FLOW_SCALE 0.01f
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on handle %d\n", handle);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *flow_rate = (float)raw * FLOW_SCALE;
        return 0;
    }
    return -1;
}

static void log_flow_rates(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open sensor 1 at 0x%02X\n", SENSOR1_ADDR);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open sensor 2 at 0x%02X\n", SENSOR2_ADDR);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(i2c_handle1, &flow1) == 0);
        int ok2 = (read_flow_rate(i2c_handle2, &flow2) == 0);

        if (ok1 && ok2) {
            log_flow_rates(flow1, flow2);
        } else {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d)\n", ok1, ok2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

