#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int a, int b, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - A: %d, B: %d, Angle: %.2f\n", timestamp, a, b, angle);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    int last_a, last_b;
    int current_a, current_b;
    int state = 0;
    float angle = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    last_a = gpioRead(SENSOR_A_PIN);
    last_b = gpioRead(SENSOR_B_PIN);

    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Error reading initial sensor values\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_a = gpioRead(SENSOR_A_PIN);
        current_b = gpioRead(SENSOR_B_PIN);

        if (current_a < 0 || current_b < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            break;
        }

        if (current_a != last_a || current_b != last_b) {
            int new_state = (current_a << 1) | current_b;
            int diff = new_state ^ state;

            if (diff == 1 || diff == 2) {
                angle += 360.0f / PULSES_PER_REVOLUTION;
            } else if (diff == 3 || diff == 6) {
                angle -= 360.0f / PULSES_PER_REVOLUTION;
            }

            if (angle < 0.0f) angle += 360.0f;
            if (angle >= 360.0f) angle -= 360.0f;

            log_data(current_a, current_b, angle);
            state = new_state;
            last_a = current_a;
            last_b = current_b;
        }

        gpioDelay(1000);
    }

    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

