/*
 * ADPD144RI Red/IR photometric sensor reader for Raspberry Pi 3 Model B+
 * Uses libgpiod for GPIO and the Linux I2C character-device interface.
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode   -> GPIO 17 (1 kΩ series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri_reader adpd144ri_reader.c \
 *       -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Constants ----------------------------- */
#define I2C_BUS_NAME      "/dev/i2c-1"
#define ADPD144RI_ADDR    0x39          /* ADPD144RI default 7-bit I2C address */
#define LED_GPIO_LINE     17            /* GPIO 17 (BCM) */
#define IR_THRESHOLD      2000          /* IR ADC count threshold */
#define SAMPLE_PERIOD_MS  100           /* Sampling period */
#define LOG_FILE_NAME     "adpd144ri_log.txt"

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_DEVID         0x00          /* Device ID register */
#define REG_FIFO_DATA     0x60          /* FIFO data register (16-bit red + 16-bit IR) */
#define EXPECTED_DEVID    0x144         /* Expected device ID for ADPD144RI */

/* ----------------------------- Globals ------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* --------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ----------------------------- */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);   /* MSB first */
    buf[2] = (uint8_t)(value & 0xFF); /* LSB second */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- Sensor init ----------------------------- */
static int sensor_init(int fd)
{
    uint16_t devid = 0;

    if (i2c_read_reg16(fd, REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }

    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "Unexpected DEVID: 0x%04X (expected 0x%04X).\n",
                devid, EXPECTED_DEVID);
        return -1;
    }

    printf("ADPD144RI detected (DEVID=0x%04X).\n", devid);

    /* Reset FIFO and configure sampling rate / mode as needed */
    if (i2c_write_reg16(fd, 0x01, 0x0001) < 0) return -1; /* Example reset */
    if (i2c_write_reg16(fd, 0x02, 0x0002) < 0) return -1; /* Example config */

    return 0;
}

/* --------------------------- Read data ------------------------------- */
static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir)
{
    uint16_t raw;

    if (i2c_read_reg16(fd, REG_FIFO_DATA, &raw) < 0)
        return -1;

    /* ADPD144RI FIFO data: 16-bit red in upper 16 bits, IR in lower 16 bits */
    *red = (uint16_t)(raw >> 8);
    *ir  = (uint16_t)(raw & 0xFF);
    return 0;
}

/* --------------------------- Logging --------------------------------- */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* --------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main ------------------------------------ */
int main(void)
{
    struct sigaction sa;
    uint16_t red = 0, ir = 0;

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (sensor_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request LED line --- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring ADPD144RI (IR threshold: %d). Press Ctrl+C to exit.\n",
           IR_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        if (read_sensor_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            log_data(g_log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(g_led, 1);
            } else {
                gpiod_line_set_value(g_led, 0);
            }
        }

        /* Sleep SAMPLE_PERIOD_MS milliseconds */
        struct timespec ts = {
            .tv_sec  = SAMPLE_PERIOD_MS / 1000,
            .tv_nsec = (long)(SAMPLE_PERIOD_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

