    if (i2c_write_reg16(fd, 0x01, 0x0001) < 0) return -1; /* Example reset */
    if (i2c_write_reg16(fd, 0x02, 0x0002) < 0) return -1; /* Example config */

    return 0;
}

/* --------------------------- Read data ------------------------------- */
static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir)
{
    uint16_t raw;

    if (i2c_read_reg16(fd, REG_FIFO_DATA, &raw) < 0)
        return -1;

    /* ADPD144RI FIFO data: 16-bit red in upper 16 bits, IR in lower 16 bits */
    *red = (uint16_t)(raw >> 8);
    *ir  = (uint16_t)(raw & 0xFF);
    return 0;
}

/* --------------------------- Logging --------------------------------- */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* --------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main ------------------------------------ */
int main(void)
{
    struct sigaction sa;
    uint16_t red = 0, ir = 0;

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (sensor_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request LED line --- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring ADPD144RI (IR threshold: %d). Press Ctrl+C to exit.\n",
           IR_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        if (read_sensor_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            log_data(g_log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(g_led, 1);
            } else {
                gpiod_line_set_value(g_led, 0);
            }
        }

        /* Sleep SAMPLE_PERIOD_MS milliseconds */
        struct timespec ts = {
            .tv_sec  = SAMPLE_PERIOD_MS / 1000,
            .tv_nsec = (long)(SAMPLE_PERIOD_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

