#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_audio_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *audio_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_PIN);
    if (!audio_line) {
        perror("gpiod_chip_get_line AUDIO_PIN");
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        perror("gpiod_chip_get_line GAIN_PIN");
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "max9814_gain", 0) < 0) {
        perror("gpiod_line_request_output GAIN_PIN");
        goto cleanup;
    }

    if (gpiod_line_request_input(audio_line, "max9814_audio") < 0) {
        perror("gpiod_line_request_input AUDIO_PIN");
        goto cleanup;
    }

    printf("Audio monitoring started on GPIO %d. Press Ctrl+C to exit.\n", AUDIO_PIN);

    int prev_val = gpiod_line_get_value(audio_line);
    if (prev_val < 0) {
        perror("gpiod_line_get_value initial");
        goto cleanup;
    }

    while (program_running) {
        int val = gpiod_line_get_value(audio_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        if (val == 1 && prev_val == 0) {
            if (log_audio_event(1) < 0) {
                fprintf(stderr, "Failed to log audio event\n");
            }
        }
        prev_val = val;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (audio_line) gpiod_line_release(audio_line);
    if (gain_line) gpiod_line_release(gain_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

