/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SLF3S_ADDR, i2c_handle);
        return -1;
    }

    /* Send start-measurement command: 0x3608 */
    uint8_t cmd[2] = { (uint8_t)(START_MEAS_CMD >> 8), (uint8_t)(START_MEAS_CMD & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing start-measurement command: %d\n", rc);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Allow sensor to settle after issuing the start command */
    gpioDelay(10000);  /* 10 ms */
    return 0;
