    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading flow data (rc=%d)\n", rc);
        return -1;
    }

    /* Validate CRC-8 over the first 2 bytes */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Assemble 16-bit signed raw value (MSB first) */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 1000.0f;
    return 0;
