#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define SENSOR_REG 0x00
#define SENSOR_DATA_LEN 7

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf, int len) {
    int rc = i2cWriteByte(handle, SENSOR_REG);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select) failed: %d\n", rc);
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

static int calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0f - ((float)tvoc / 10.0f) - ((float)(eco2 - 400) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return (int)iaq;
}

static void log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%u,%u\n", ts, iaq, tvoc, eco2);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,iaq,TVOC_ppb,eCO2_ppm\n");
        fflush(log_file);
    }

    uint8_t buf[SENSOR_DATA_LEN];
    while (running) {
        if (read_sensor_data(i2c_handle, buf, SENSOR_DATA_LEN) == 0) {
            uint16_t tvoc = ((uint16_t)buf[1] << 8) | buf[2];
            uint16_t eco2 = ((uint16_t)buf[5] << 8) | buf[6];
            int iaq = calculate_iaq(tvoc, eco2);
            log_data(log_file, iaq, tvoc, eco2);
            printf("IAQ: %d, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc, eco2);
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle.\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

