#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define CONSUMER_LABEL  "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec last_touch_ts;
    int ret;
    int prev_touched = 0;
    int first_touch = 1;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip by name */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for the sensor */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with the consumer label */
    ret = gpiod_line_request_input(line, CONSUMER_LABEL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s)...\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    printf("Intrusion alert after %d seconds of continuous touch.\n",
           INTRUSION_THRESHOLD_S);
    fflush(stdout);

    clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        int touched = (value == 1);

        if (touched) {
            if (first_touch) {
                first_touch = 0;
                prev_touched = 1;
                clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);
            } else if (!prev_touched) {
                /* Just transitioned from released to touched */
                prev_touched = 1;
                clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);
            }

            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - last_touch_ts.tv_sec)
                           + (now.tv_nsec - last_touch_ts.tv_nsec) / 1e9;

            if (elapsed >= INTRUSION_THRESHOLD_S) {
                printf("INTRUSION DETECTED: Sensor touched for %.1f seconds.\n",
                       elapsed);
                fflush(stdout);
            }
        } else {
            if (prev_touched) {
                first_touch = 1;
                prev_touched = 0;
            }
        }

        /* Sleep for the poll interval (interruptible by signals) */
        struct timespec sleep_ts = {
            .tv_sec = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&sleep_ts, NULL);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

