#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 48000
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 24
#define FRAMES_PER_BUFFER 1024
#define FILENAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pcm_format(int fd) {
    int format = AFMT_S32_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        perror("ioctl SNDCTL_DSP_SETFMT");
        return -1;
    }
    if (format != AFMT_S32_LE) {
        fprintf(stderr, "Error: 32-bit LE format not supported by device.\n");
        return -1;
    }
    return 0;
}

static int set_pcm_channels(int fd, int channels) {
    int ch = channels;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &ch) == -1) {
        perror("ioctl SNDCTL_DSP_CHANNELS");
        return -1;
    }
    if (ch != channels) {
        fprintf(stderr, "Error: Could not set %d channels (got %d).\n", channels, ch);
        return -1;
    }
    return 0;
}

static int set_pcm_speed(int fd, int speed) {
    int sp = speed;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &sp) == -1) {
        perror("ioctl SNDCTL_DSP_SPEED");
        return -1;
    }
    if (sp != speed) {
        fprintf(stderr, "Warning: Could not set exact sample rate %d (got %d).\n", speed, sp);
    }
    return 0;
}

static int16_t extract_16bit_sample(uint32_t raw) {
    uint32_t sample = raw >> 8;  // Remove the 8-bit padding on the right
    return (int16_t)sample;
}

int main(void) {
    int pcm_fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "inmp441_lr_select", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    pcm_fd = open(PCM_DEVICE, O_RDONLY);
    if (pcm_fd == -1) {
        perror("open PCM device");
        goto cleanup;
    }

    if (set_pcm_format(pcm_fd) == -1) goto cleanup;
    if (set_pcm_channels(pcm_fd, NUM_CHANNELS) == -1) goto cleanup;
    if (set_pcm_speed(pcm_fd, SAMPLE_RATE) == -1) goto cleanup;

    fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    size_t frame_size = NUM_CHANNELS * (BITS_PER_SAMPLE / 8);
    size_t buffer_size = FRAMES_PER_BUFFER * frame_size;
    uint8_t *buffer = malloc(buffer_size);
    if (!buffer) {
        perror("malloc");
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        ssize_t bytes_read = read(pcm_fd, buffer, buffer_size);
        if (bytes_read == -1) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "End of stream.\n");
            break;
        }

        size_t num_frames = bytes_read / frame_size;
        for (size_t i = 0; i < num_frames; i++) {
            uint32_t raw_sample = 0;
            memcpy(&raw_sample, buffer + i * frame_size, frame_size);
            int16_t pcm_sample = extract_16bit_sample(raw_sample);
            if (fwrite(&pcm_sample, sizeof(int16_t), 1, fp) != 1) {
                perror("fwrite");
                goto cleanup;
            }
        }
    }

    ret = 0;

cleanup:
    if (buffer) free(buffer);
    if (fp) fclose(fp);
    if (pcm_fd != -1) close(pcm_fd);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);

    if (ret == 0) {
        printf("Audio capture stopped.\n");
    }
    return ret;
}

