#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_DELAY_US 50000
#define FLAME_TIMEOUT_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int read_flame_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        log_event("Error: gpioRead failed on flame sensor pin");
        return -1;
    }
    return v;
}

static void control_fan(int pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(pin, duty_cycle) < 0) {
        log_event("Error: gpioPWM failed");
    }
}

static int calculate_duty_cycle(int flame_duration_seconds) {
    double duty = 80.0 * (1.0 - exp(-0.1 * flame_duration_seconds));
    if (duty < 0) duty = 0;
    if (duty > 80) duty = 80;
    return (int)(duty * 10);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("Error: gpioSetMode failed for flame sensor pin");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        log_event("Error: gpioSetPullUpDown failed for flame sensor pin");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        log_event("Error: gpioSetMode failed for fan pin");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        log_event("Error: gpioSetPWMfrequency failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        log_event("Error: gpioSetPWMrange failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_fan(FAN_PIN, 0);

    log_event("System started");

    int flame_active = 0;
    time_t flame_start_time = 0;
    int last_flame_state = 1;
    int timeout_counter = 0;

    while (running) {
        int sensor_value = read_flame_sensor(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value == 0 && last_flame_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = read_flame_sensor(FLAME_SENSOR_PIN);
            if (sensor_value < 0) continue;
            if (sensor_value == 0) {
                flame_active = 1;
                flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else if (sensor_value == 1 && last_flame_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = read_flame_sensor(FLAME_SENSOR_PIN);
            if (sensor_value < 0) continue;
            if (sensor_value == 1) {
                if (flame_active) {
                    time_t now = time(NULL);
                    int duration = (int)difftime(now, flame_start_time);
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Flame ended, duration: %d seconds", duration);
                    log_event(msg);
                    control_fan(FAN_PIN, 0);
                    flame_active = 0;
                }
            }
        }

        last_flame_state = sensor_value;

        if (flame_active) {
            time_t now = time(NULL);
            int duration = (int)difftime(now, flame_start_time);
            int duty = calculate_duty_cycle(duration);
            control_fan(FAN_PIN, duty);
            timeout_counter = 0;
        } else {
            control_fan(FAN_PIN, 0);
            timeout_counter++;
            if (timeout_counter >= (FLAME_TIMEOUT_S * 10)) {
                log_event("Warning: No flame detected for 5 seconds (sensor absent?)");
                timeout_counter = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down");
    control_fan(FAN_PIN, 0);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_OFF);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioTerminate();
    return EXIT_SUCCESS;
}

