        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(READY_PIN, PI_INPUT);
    gpioSetPullUpDown(READY_PIN, PI_PUD_DOWN);
