    if (!log_file) {
        perror("fopen");
        return -1;
    }
    return 0;
}

static int write_config(ConfigData *cfg) {
    if (fwrite(cfg, sizeof(*cfg), 1, log_file) != 1) {
        perror("fwrite config");
        return -1;
    }
    return 0;
}

static int read_radar_data(uint8_t *data, int len) {
    char tx_buf[DATA_SIZE];
    if (len > DATA_SIZE) {
        fprintf(stderr, "read_radar_data: len %d exceeds buffer\n", len);
        return -1;
    }
    memset(tx_buf, 0, len);
    int bytes = spiXfer(spi_handle, tx_buf, (char *)data, len);
    if (bytes != len) {
