        if (!ready) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue;
        }

        if (read_radar_data(data, DATA_SIZE) != 0) {
            fprintf(stderr, "Failed to read radar data\n");
            continue;
        }

        time_t ts = time(NULL);
        if (fwrite(&ts, sizeof(ts), 1, log_file) != 1) {
            perror("fwrite timestamp");
            break;
        }
        if (fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1) {
            perror("fwrite frame_number");
            break;
        }
        if (fwrite(data, 1, DATA_SIZE, log_file) != DATA_SIZE) {
            perror("fwrite data");
            break;
        }
        fflush(log_file);

        frame_number++;
    }

    free(data);
    cleanup();
    return 0;
}

