#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int opt3001_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *raw) {
    char reg = REG_RESULT;
    char data[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *raw = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
    return 0;
}

static float opt3001_raw_to_lux(uint16_t raw) {
    uint8_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return 0.01f * (float)(1 << exponent) * (float)mantissa;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, lux);
    }
    fclose(fp);
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (opt3001_write_config(i2c_handle, CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "Failed to write OPT3001 config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint32_t next_tick = gpioTick();
    while (running) {
        uint16_t raw = 0;
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (opt3001_read_result(i2c_handle, &raw) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);
        }
        if (ok) {
            float lux = opt3001_raw_to_lux(raw);
            log_data(lux);
        } else {
            log_error("I2C read failed after retries");
        }
        next_tick += SAMPLE_INTERVAL_US;
        uint32_t now = gpioTick();
        if (next_tick > now) {
            gpioDelay(next_tick - now);
        } else {
            next_tick = now;
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

