/*
 * SainSmart IR Flame Detection Sensor Module reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod v2.x (libgpiod-dev)
 * Sensor:  SainSmart IR Flame Detection Module
 *          DOUT -> GPIO17 (BCM 17, physical pin 11)
 *          VCC  -> 3.3 V (physical pin 1)
 *          GND  -> GND  (physical pin 9)
 *
 * The module's DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO controller on Pi 3B+ (libgpiod v2) */
#define GPIO_LINE_OFFSET 17            /* BCM 17 */
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Print a timestamped status line to stdout                           */
/* ------------------------------------------------------------------ */
static void log_status(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] Flame Detected: %s\n",
           timestamp, flame_detected ? "YES" : "NO");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *request = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure line settings: input, pull-up bias ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* ---- Build line config for offset 17 ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offset = GPIO_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1,
                                            settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request config: consumer label "flame_detect" ---- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* ---- Request the line ---- */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        /* DOUT is active-low: 0 => flame detected */
        log_status(value == 0);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL)
        gpiod_line_request_release(request);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

