/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio
 * Sensors: Two TMAG5110 digital OUT pins (open-drain, external pull-up)
 *   - Sensor 1 OUT -> BCM GPIO 4
 *   - Sensor 2 OUT -> BCM GPIO 5
 * Logic: HIGH = no magnet, LOW = magnet detected
 * Sample interval: 500 ms
 * Build: gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    int ret;

    /* Register signal handler for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler.\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups (external pull-ups assumed; this is a safety net) */
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO %d | Sensor 2: BCM GPIO %d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_US / 1000);

    /* Main sampling loop */
    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: GPIO read error (s1=%d, s2=%d).\n", s1, s2);
        } else {
            printf("Sensor 1: %s | Sensor 2: %s\n",
                   s1 == 0 ? "MAGNET DETECTED (LOW)" : "No Magnet (HIGH)",
                   s2 == 0 ? "MAGNET DETECTED (LOW)" : "No Magnet (HIGH)");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

