#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("%s", buffer);
    } else {
        printf("1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000L};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, gpio_pins, NUM_CHANNELS, NULL) != 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-reader");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!request) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("TTP226 Touch Sensor Reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int values[NUM_CHANNELS];

        if (gpiod_line_request_get_values(request, values) != 0) {
            perror("gpiod_line_request_get_values");
            break;
        }

        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf(",%d", values[i]);
        }
        printf("\n");
        fflush(stdout);

        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request) {
        gpiod_line_request_release(request);
    }
    if (req_cfg) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg) {
        gpiod_line_config_free(line_cfg);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

