    }

    printf("[%s] Tilt sensor state: %s\n",
           timestamp, state == 0 ? "Tilted" : "Not Tilted");
    fflush(stdout);
}

int main(void)
{
    int last_state = -1;
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with pull-up --- */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
