#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define SCALE_FACTOR   0.036f
#define LOG_FILE       "flow_log.txt"
#define READ_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion 8-bit CRC: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu: %s\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC for each 3-byte measurement */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement %d\n", i);
            return -1;
        }
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw_flow * SCALE_FACTOR;
    return 0;
}

static void log_flow_rate(FILE *fp, float avg_flow) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);
    fflush(fp);
}

int main(void) {
    int fd1 = -1, fd2 = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *alarm_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* Set slave addresses */
    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", SENSOR1_ADDR, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", SENSOR2_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensors: send start-measurement command 0x3608 */
    if (i2c_write_cmd(fd1, 0x36) < 0 || i2c_write_cmd(fd2, 0x36) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        goto cleanup;
    }
    usleep(100000); /* 100 ms for first measurement */

    /* Open GPIO chip and request alarm line */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }
    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", ALARM_GPIO, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", SENSOR1_ADDR, strerror(errno));
        } else if (read_flow_rate(fd1, &flow1) == 0) {
            ok1 = 1;
        } else {
            fprintf(stderr, "Sensor 1 read failed\n");
        }

        if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", SENSOR2_ADDR, strerror(errno));
        } else if (read_flow_rate(fd2, &flow2) == 0) {
            ok2 = 1;
        } else {
            fprintf(stderr, "Sensor 2 read failed\n");
        }

        float avg_flow = 0.0f;
        int count = 0;
        if (ok1) { avg_flow += flow1; count++; }
        if (ok2) { avg_flow += flow2; count++; }
        if (count > 0) avg_flow /= count;

        if (count > 0) {
            log_flow_rate(fp, avg_flow);
            int alarm = (avg_flow < FLOW_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(alarm_line, alarm) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "No valid sensor readings this cycle\n");
        }

        sleep(READ_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alarm_line) gpiod_line_release(alarm_line);
    if (chip) gpiod_chip_close(chip);
    if (fp) fclose(fp);
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    return ret;
}

