#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    int reading;
} sensor_data_t;

/* Global state */
static sensor_data_t buffer[BUFFER_SIZE];
static int head = 0;          /* next write slot */
static int count = 0;         /* number of valid entries */
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append one entry to the circular buffer                            */
/* ------------------------------------------------------------------ */
static void buffer_add(time_t ts, int reading)
{
    buffer[head].timestamp = ts;
    buffer[head].reading   = reading;
    head = (head + 1) % BUFFER_SIZE;
    if (count < BUFFER_SIZE)
        count++;
}

/* ------------------------------------------------------------------ */
/* Print all valid entries in chronological order                     */
/* ------------------------------------------------------------------ */
static void buffer_print(void)
{
    int start, i;

    if (count == 0) {
        printf("No obstacle detection events recorded.\n");
        return;
    }

    /* If buffer is full, start at head (oldest of current cycle) */
    if (count == BUFFER_SIZE)
        start = head;
    else
        start = 0;

    printf("\n--- Obstacle Detection Log (%d entries) ---\n", count);
    for (i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm tm_info;

        localtime_r(&buffer[idx].timestamp, &tm_info);
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] GPIO %d: %s\n",
               tbuf, SENSOR_PIN,
               buffer[idx].reading == 0 ? "OBSTACLE DETECTED" : "clear");
    }
    printf("--- End of log ---\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin --- */
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    /* --- Install signal handlers --- */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);

    /* --- Main polling loop --- */
    while (running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Warning: gpioRead failed on pin %d.\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (reading == 0) {
            /* Obstacle detected — record timestamp */
            time_t now = time(NULL);
            buffer_add(now, reading);
            printf("Obstacle detected on GPIO %d!\n", SENSOR_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    buffer_print();
    gpioTerminate();
    printf("pigpio terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

