#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (safe_set_mode(LED_PIN, PI_OUTPUT) != 0 ||
        safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle-avoidance monitor running.\n");
    printf("  Sensor 1: GPIO %d\n  Sensor 2: GPIO %d\n  LED:     GPIO %d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        /* KY-032 output is active-LOW: 0 = obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (safe_write(LED_PIN, obstacle) != 0) {
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean resource release on all exit paths */
    safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

