#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define LOG_FILE "stall_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Returns 1 if both sensors detect an object (LOW), 0 otherwise, -1 on error. */
static int check_stall(void) {
    int s1 = gpioRead(SENSOR_1_GPIO);
    int s2 = gpioRead(SENSOR_2_GPIO);

    if (s1 < 0 || s2 < 0) {
        fprintf(stderr, "Error reading sensor GPIOs (s1=%d, s2=%d)\n", s1, s2);
        return -1;
    }
    return (s1 == 0 && s2 == 0) ? 1 : 0;
}

/* Returns 1 if stall is confirmed, 0 otherwise, -1 on error. */
static int confirm_stall(int *stall_active, time_t *stall_start) {
    int stall = check_stall();
    if (stall < 0) return -1;

    if (stall) {
        if (!*stall_active) {
            *stall_active = 1;
            *stall_start = time(NULL);
        } else if (difftime(time(NULL), *stall_start) >= STALL_THRESHOLD_SEC) {
            return 1;
        }
    } else {
        *stall_active = 0;
    }
    return 0;
}

static int log_stall_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Stall detected on conveyor belt\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

