        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so sensors read HIGH when no object is present. */
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
