    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int stall_active = 0;
    time_t stall_start = 0;

    printf("Monitoring conveyor belt for stalls (threshold: %d s). Press Ctrl+C to exit.\n",
           STALL_THRESHOLD_SEC);

    while (running) {
        int confirmed = confirm_stall(&stall_active, &stall_start);
        if (confirmed < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else if (confirmed == 1) {
            printf("Stall confirmed! Logging event...\n");
            if (log_stall_event() != 0) {
                fprintf(stderr, "Failed to log stall event.\n");
