#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_X_CH_RESULT 0x01
#define REG_Y_CH_RESULT 0x02
#define REG_Z_CH_RESULT 0x03
#define REG_DEVICE_CONFIG 0x04
#define REG_SENSOR_CONFIG 0x05

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID 0x8D

/* LSB scale factor for 50 mT range: 1 LSB = 0.001 mT */
#define SCALE_FACTOR_MT 0.001f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement register pair from the sensor        */
/* ------------------------------------------------------------------ */
static int read_axis(int handle, uint8_t reg, int16_t *out)
{
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) {
        return -1;
    }
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) {
        return -1;
    }
    *out = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field readings in mT                          */
/* ------------------------------------------------------------------ */
static int read_magnetic_field(int handle, float *x_mt, float *y_mt, float *z_mt)
{
    int16_t x_raw, y_raw, z_raw;

    if (read_axis(handle, REG_X_CH_RESULT, &x_raw) != 0) {
        return -1;
    }
    if (read_axis(handle, REG_Y_CH_RESULT, &y_raw) != 0) {
        return -1;
    }
    if (read_axis(handle, REG_Z_CH_RESULT, &z_raw) != 0) {
        return -1;
    }

    *x_mt = (float)x_raw * SCALE_FACTOR_MT;
    *y_mt = (float)y_raw * SCALE_FACTOR_MT;
    *z_mt = (float)z_raw * SCALE_FACTOR_MT;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a data row to the CSV file                                      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x_mt, float y_mt, float z_mt)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, x_mt, y_mt, z_mt);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TMAG5170 address */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device ID */
    int dev_id = i2cReadByteData(g_i2c_handle, REG_DEVICE_ID);
    if (dev_id < 0) {
        fprintf(stderr, "Error: failed to read device ID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (dev_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0x%02X)\n",
                dev_id, TMAG5170_DEVICE_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous mode, all three axes enabled, 50 mT range */
    /* DEVICE_CONFIG (0x04): [7:6]=00 (range 50 mT), [5:4]=00 (mag_if), [3:2]=00 (mag_ch), [1:0]=00 (mag_en) */
    if (i2cWriteByteData(g_i2c_handle, REG_DEVICE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write DEVICE_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }
    /* SENSOR_CONFIG (0x05): [7:6]=00 (mag_if), [5:4]=00 (mag_ch), [3:2]=00 (mag_en), [1:0]=00 (mag_if) */
    if (i2cWriteByteData(g_i2c_handle, REG_SENSOR_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write SENSOR_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open magnetic_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x_mt, y_mt, z_mt;

        if (read_magnetic_field(g_i2c_handle, &x_mt, &y_mt, &z_mt) == 0) {
            log_data(g_log_file, x_mt, y_mt, z_mt);
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

