#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_GPIO 4          /* BCM 4, physical pin 7 */
#define LOG_FILE    "rpm_log.txt"
#define SAMPLE_US   1000000    /* 1 second in microseconds */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of SENSOR_GPIO          */
/* ------------------------------------------------------------------ */
static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                 /* rising edge => one revolution */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Append one timestamped RPM record to the log file and stdout        */
/* ------------------------------------------------------------------ */
static void log_rpm(uint32_t pulses)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    double rpm = (double)pulses * 60.0;   /* one pulse per revolution */

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm);
        fflush(g_log_fp);
    }
    printf("%s %.2f RPM\n", timestamp, rpm);
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all pigpio resources and close the log file       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable the 1-second timer and the alert callback */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback for rising/falling edges ---- */
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for GPIO %d.\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    /* ---- 1-second sampling timer ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_US, log_rpm, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- main loop — wait for signal ---- */
    while (g_running) {
        gpioDelay(500000);   /* 0.5 s — timer fires every 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

