#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    /* Get the touch sensor line */
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request the touch sensor line as input */
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request the LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Touch sensor and LED initialized. Monitoring touch events...");

    /* Main polling loop */
    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor value: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (touch_value == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch detected, LED turned ON");
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch released, LED turned OFF");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Ensure LED is off on exit */
    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn LED off during shutdown: %s", strerror(errno));
    }

    syslog(LOG_INFO, "Program terminated gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

