        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%u) failed\n", pin);
    }
    return v;
}

static void log_event(int sensor_pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp  = now;
    log_buffer[log_index].state      = state;

    log_index++;
    if (log_index >= LOG_SIZE) {
        log_index = 0;
        log_overflow++;
    }
}

static void print_log(void)
{
    printf("\n--- Log Buffer (%d entries, %d overflow) ---\n",
           LOG_SIZE, log_overflow);

    int start = log_overflow > 0 ? log_index : 0;
    for (int i = 0; i < LOG_SIZE; i++) {
        int idx = (start + i) % LOG_SIZE;
        printf("  [%3d] Sensor: GPIO %2d, Timestamp: %ld, State: %s\n",
               idx,
               log_buffer[idx].sensor_pin,
               (long)log_buffer[idx].timestamp,
               log_buffer[idx].state ? "Touched" : "Released");
    }
    printf("--- End of Log Buffer ---\n");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_1_PIN,    PI_OUTPUT) != 0 ||
        safe_set_mode(LED_2_PIN,    PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(LED_1_PIN, 0) != 0 || safe_write(LED_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        safe_write(LED_1_PIN, 0);
        safe_write(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor application started.\n");
    printf("  Sensor 1: GPIO %d -> LED: GPIO %d\n", SENSOR_1_PIN, LED_1_PIN);
    printf("  Sensor 2: GPIO %d -> LED: GPIO %d\n", SENSOR_2_PIN, LED_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    int prev1 = 0, prev2 = 0;

    while (running) {
        int s1 = safe_read(SENSOR_1_PIN);
        int s2 = safe_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 != prev1) {
            safe_write(LED_1_PIN, s1);
            log_event(SENSOR_1_PIN, s1);
            prev1 = s1;
        }

        if (s2 != prev2) {
            safe_write(LED_2_PIN, s2);
            log_event(SENSOR_2_PIN, s2);
            prev2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    safe_write(LED_1_PIN, 0);
    safe_write(LED_2_PIN, 0);
    print_log();
    gpioTerminate();
    printf("Application terminated.\n");
    return EXIT_SUCCESS;
}

