#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define PULSES_PER_REVOLUTION 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static volatile uint32_t last_sensor1_tick = 0;
static volatile uint32_t last_sensor2_tick = 0;
static volatile int last_sensor1_debounced = 0;
static volatile int last_sensor2_debounced = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, s1, s2);
    fclose(fp);
}

static void sensor1_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == last_sensor1_debounced) return;
    if (tick - last_sensor1_tick > DEBOUNCE_DELAY_US) {
        last_sensor1_debounced = level;
        last_sensor1_tick = tick;
        sensor1_state = level;
        log_data(level, sensor2_state);
    }
}

static void sensor2_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == last_sensor2_debounced) return;
    if (tick - last_sensor2_tick > DEBOUNCE_DELAY_US) {
        last_sensor2_debounced = level;
        last_sensor2_tick = tick;
        sensor2_state = level;
        log_data(sensor1_state, level);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    if (gpioSetISRFunc(SENSOR_1_GPIO, EITHER_EDGE, 0, sensor1_callback) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFunc(SENSOR_2_GPIO, EITHER_EDGE, 0, sensor2_callback) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 2\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t now = gpioTick();
        static uint32_t last_pulse_tick = 0;
        static int last_s1 = 0, last_s2 = 0;
        int s1 = sensor1_state;
        int s2 = sensor2_state;

        if (s1 != last_s1 || s2 != last_s2) {
            if (s1 == 1 && s2 == 1) {
                if (now - last_pulse_tick > 0) {
                    double time_diff = (now - last_pulse_tick) / 1000000.0;
                    double rpm = 60.0 / (time_diff * PULSES_PER_REVOLUTION);
                    printf("RPM: %.2f\n", rpm);
                }
                last_pulse_tick = now;
            }
            last_s1 = s1;
            last_s2 = s2;
        }
        gpioDelay(10000);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

