#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define POLL_DELAY_US  100000   /* 100 ms */
#define ALARM_THRESHOLD_S 2     /* 2 s */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper — returns 0 on success, -1 on failure             */
/* ------------------------------------------------------------------ */
static int get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (g_log == NULL) {
        return;
    }
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    }
    fprintf(g_log, "%s %s\n", ts, msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Alarm control                                                      */
/* ------------------------------------------------------------------ */
static int alarm_set(int state)
{
    if (gpioWrite(ALARM_PIN, state) != 0) {
        log_event("ERROR: gpioWrite(alarm) failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path                           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log != NULL) {
        log_event("Bridge integrity monitor shutting down");
        fclose(g_log);
        g_log = NULL;
    }
    /* Best-effort alarm deactivation */
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALARM_PIN,    PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Internal pull-down so sensors read LOW when idle */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure alarm starts OFF */
    if (alarm_set(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log = fopen("bridge_integrity.log", "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Bridge integrity monitor started");

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Monitoring state ---- */
    int s1_active = 0;          /* HIGH for > ALARM_THRESHOLD_S */
    int s2_active = 0;
    uint32_t s1_start_tick = 0; /* tick when sensor 1 went HIGH */
    uint32_t s2_start_tick = 0;
    int alarm_armed = 0;        /* alarm currently active */

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            log_event("ERROR: gpioRead failed");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t now = gpioTick();

        /* ---- Sensor 1 ---- */
        if (s1 == 1) {
            if (!s1_active) {
                s1_active = 1;
                s1_start_tick = now;
                log_event("Tilt sensor 1 triggered (HIGH)");
            } else if (!alarm_armed && (now - s1_start_tick) >=
                       (uint32_t)(ALARM_THRESHOLD_S * 1000000)) {
                alarm_armed = 1;
                if (alarm_set(1) == 0) {
                    log_event("ALARM: Tilt sensor 1 exceeded threshold");
                }
            }
        } else {
            if (s1_active) {
                s1_active = 0;
                log_event("Tilt sensor 1 reset (LOW)");
            }
            if (alarm_armed && s2 == 0) {
                alarm_armed = 0;
                alarm_set(0);
                log_event("ALARM deactivated (s1 & s2 LOW)");
            }
        }

        /* ---- Sensor 2 ---- */
        if (s2 == 1) {
            if (!s2_active) {
                s2_active = 1;
                s2_start_tick = now;
                log_event("Tilt sensor 2 triggered (HIGH)");
            } else if (!alarm_armed && (now - s2_start_tick) >=
                       (uint32_t)(ALARM_THRESHOLD_S * 1000000)) {
                alarm_armed = 1;
                if (alarm_set(1) == 0) {
                    log_event("ALARM: Tilt sensor 2 exceeded threshold");
                }
            }
        } else {
            if (s2_active) {
                s2_active = 0;
                log_event("Tilt sensor 2 reset (LOW)");
            }
            if (alarm_armed && s1 == 0) {
                alarm_armed = 0;
                alarm_set(0);
                log_event("ALARM deactivated (s1 & s2 LOW)");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

