/*
 * Omron D7S-A0011 Seismic Sensor Monitor (Raspberry Pi 3 Model B+)
 * Library: pigpio (I2C bus 1, address 0x1D)
 * LED: GPIO 17
 * Log: seismic_events.log
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define CTRL1_REG            0x1F          /* Control register 1 */
#define CTRL1_POWER_DOWN_BIT 0x01          /* Bit 0 = power-down */
#define CTRL1_ACTIVE_VAL     0x00          /* Clear bit 0 to active mode */
#define ACCEL_X_REG          0x28          /* X-axis acceleration (LSB) */
#define ACCEL_DATA_LEN       6             /* 2 bytes per axis, 3 axes */
#define VIBRATION_THRESHOLD  500           /* Units depend on sensor scale */
#define LED_GPIO             17
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_DURATION_US   1000000       /* 1 second */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* ------------------------------- Globals --------------------------------- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes -------------------------- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(int16_t *x, int16_t *y, int16_t *z);
static int  calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z);
static void trigger_led(void);
static void log_event(int vibration_magnitude);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor initialization ------------------------ */
static int init_sensor(void) {
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, CTRL1_REG);
    if (ctrl1 < 0) {
        fprintf(stderr, "Error reading CTRL1 (0x%02X): pigpio error %d\n",
                CTRL1_REG, ctrl1);
        return -1;
    }
    if (ctrl1 & CTRL1_POWER_DOWN_BIT) {
        fprintf(stderr, "Warning: sensor reports power-down (CTRL1=0x%02X). "
                        "Attempting to wake.\n", ctrl1);
    }

    /* Clear power-down bit to enter active mode */
    int status = i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_ACTIVE_VAL);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL1 (0x%02X): pigpio error %d\n",
                CTRL1_REG, status);
        return -1;
    }

    /* Allow sensor to settle after waking */
    gpioDelay(10000);  /* 10 ms */
    return 0;
}

/* ----------------------- Read 6-byte acceleration block ------------------- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[ACCEL_DATA_LEN];
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG,
                                             buffer, ACCEL_DATA_LEN);
        if (bytes_read == ACCEL_DATA_LEN) {
            /* D7S-A0011 outputs little-endian: LSB first, then MSB */
            *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
            return 0;
        }
        fprintf(stderr, "I2C block read failed (attempt %d/%d): got %d bytes\n",
                retries + 1, MAX_RETRIES, bytes_read);
        retries++;
        gpioDelay(1000);  /* 1 ms backoff */
    }
    return -1;
}

/* --------------------------- Vibration magnitude -------------------------- */
static int calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z) {
    return (int)sqrt((double)x * x + (double)y * y + (double)z * z);
}

/* ------------------------------- LED pulse -------------------------------- */
static void trigger_led(void) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_DURATION_US);
    gpioWrite(LED_GPIO, 0);
}

/* ------------------------------- Log event -------------------------------- */
static void log_event(int vibration_magnitude) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s - Vibration magnitude: %d\n", timestamp,
            vibration_magnitude);
    fflush(log_file);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* --------------------------------- main ----------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Check wiring and address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            int magnitude = calculate_vibration_magnitude(x, y, z);

