/*
 * flame_monitor.c - KY-026 flame sensor monitor using libgpiod (v1.6+)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (needs write access to /var/log/flame_events.log)
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: 5x Keyes KY-026 (digital out, active-low)
 *   BCM 2  -> physical pin 3
 *   BCM 3  -> physical pin 5
 *   BCM 4  -> physical pin 7
 *   BCM 17 -> physical pin 11
 *   BCM 27 -> physical pin 13
 *   VCC -> 3.3V, GND -> GND
 *
 * Log:  /var/log/flame_events.log  (append, line per event)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define CONSUMER_NAME    "flame_monitor"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    int fd = fileno(fp);
    if (fd == -1) {
        syslog(LOG_ERR, "fileno: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time: %s", strerror(errno));
        flock(fd, LOCK_UN);
        fclose(fp);
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed");
        flock(fd, LOCK_UN);
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        flock(fd, LOCK_UN);
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
    } else if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog(CONSUMER_NAME, LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitoring (%d sensors)",
           NUM_SENSORS);

    if (install_signal_handlers() == -1) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    int lines_requested = 0;
    int exit_code = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], CONSUMER_NAME) < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "Initial read GPIO %u: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = v;
    }

    syslog(LOG_INFO, "Monitoring started; polling every %d s",
           POLL_INTERVAL_S);

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                syslog(LOG_ERR, "read GPIO %u: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: HIGH -> flame detected (active-low sensor) */
            if (v == 1 && prev_state[i] == 0) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                int v2 = gpiod_line_get_value(lines[i]);
                if (v2 < 0) {
                    syslog(LOG_ERR, "debounce read GPIO %u: %s",
                           sensor_pins[i], strerror(errno));
                } else if (v2 == 1) {
                    log_event(i + 1, sensor_pins[i]);
                }
            }
            prev_state[i] = v;
        }

        sleep(POLL_INTERVAL_S);
    }

    exit_code = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < lines_requested; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();
    return exit_code;
}

