#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_config(int handle) {
    /* Config: ALS gain 1/8 (bits 11:10 = 00), ALS integration 100 ms (bits 9:6 = 0000) */
    uint16_t config = 0x0000;
    char buf[2] = { (char)(config & 0xFF), (char)((config >> 8) & 0xFF) };
    if (i2cWriteI2CBlockData(handle, VEML7700_REG_CONFIG, buf, 2) < 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, VEML7700_REG_ALS, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
            timestamp, lux, brightness, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_write_config(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure VEML7700: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int brightness = 0;
        int error_code = 0;

        if (veml7700_read_lux(i2c_handle, &lux) < 0) {
            error_code = -1;
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        } else {
            if (lux < 100.0f) {
                brightness = 100;
            } else if (lux < 500.0f) {
                brightness = 75;
            } else if (lux < 1000.0f) {
                brightness = 50;
            } else {
                brightness = 25;
            }

            if (set_led_brightness(LED_GPIO, brightness) < 0) {
                error_code = -2;
                fprintf(stderr, "PWM write error on GPIO %d: %s\n",
                        LED_GPIO, strerror(errno));
            }
        }

        log_data(log_file, lux, brightness, error_code);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_led_brightness(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

