                fprintf(stderr, "Error reading GPIO %d\n", channel_pins[i]);
                continue;
            }

            if (current == 1 && last_state[i] == 0) {
                /* Debounce: wait and re-read */
                gpioDelay(DEBOUNCE_DELAY_US);
                int confirm = gpioRead(channel_pins[i]);
                if (confirm == 1) {
                    if (log_touch_event(i + 1) != 0) {
                        fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                    }
                    any_touched = 1;
                }
            }
            last_state[i] = current;
        }

        if (any_touched && !led_on) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            } else {
                led_on = 1;
            }
        } else if (!any_touched && led_on) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            } else {
                led_on = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

