#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR          0x44
#define REG_RESULT            0x00
#define REG_CONFIG            0x01
#define CONFIG_CONTINUOUS     0xC810  /* RN=1100 (auto-range), CT=100ms, M=1100, FC=00, OVF=0, CR=1100 */
#define I2C_BUS               1
#define LOG_FILE              "light_data.txt"
#define SAMPLE_INTERVAL_US    1000000  /* 1 second */
#define CONVERSION_DELAY_US   150000   /* 150 ms (covers 100 ms conversion + margin) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Swap bytes: pigpio word data is little-endian, OPT3001 expects big-endian */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_opt3001(void)
{
    uint16_t config_be = swap16(CONFIG_CONTINUOUS);

    if (i2cWriteWordData(g_i2c_handle, REG_CONFIG, config_be) < 0) {
        fprintf(stderr, "Error: failed to write OPT3001 config register 0x%02X\n", REG_CONFIG);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int read_lux(float *lux_out)
{
    int raw = i2cReadWordData(g_i2c_handle, REG_RESULT);
    if (raw < 0) {
        fprintf(stderr, "Error: failed to read OPT3001 result register 0x%02X\n", REG_RESULT);
        return -1;
    }

    uint16_t result_be = swap16((uint16_t)raw);
    uint16_t exponent = (result_be >> 12) & 0x0F;
    uint16_t mantissa = result_be & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (handle=%d)\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_opt3001() != 0) {
        fprintf(stderr, "Error: OPT3001 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging to %s every 1 s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float lux;
        if (read_lux(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping this sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

