           GPIO_LINE_OFFSET);

    int last_state = -1;

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        if (val != last_state) {
            if (log_event(fp, val) != 0) {
                break;
            }
            last_state = val;
            usleep(DEBOUNCE_MS * 1000);
        } else {
            usleep(10000);
        }
