    if (fp != NULL) {
        fclose(fp);
    }

cleanup_line:
    gpiod_line_release(line);

cleanup_chip:
    gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }

    return ret;
}

