#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define FLOW_SCALE     90.0f
#define SAMPLE_US      1000000  /* 1 second */
#define MEASURE_DELAY  2000     /* 2 ms after start command */
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        return -1;
    }
    /* Start continuous measurement: 0x3608 */
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Failed to send start-measurement command\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(MEASURE_DELAY);
    return 0;
}

static int read_flow_rate(float *flow_rate, int *raw_flags)
{
    uint8_t buf[3];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read returned %d bytes (expected 3)\n", n);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -2;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_flags = (raw & 0x8000) ? 1 : 0;
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static void log_data(float flow_rate, int raw_flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("cooling_log.csv", "a");
    if (!g_log_file) {
        perror("fopen cooling_log.csv");
        cleanup();
        return 1;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    fflush(g_log_file);

    while (g_running) {
        float flow_rate = 0.0f;
        int   raw_flags = 0;
        int   rc = read_flow_rate(&flow_rate, &raw_flags);

        if (rc == 0) {
            if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX) {
                log_data(flow_rate, raw_flags, "OK");
            } else {
                log_data(flow_rate, raw_flags, "INVALID");
            }
        } else if (rc == -1) {
            log_data(0.0f, 0, "ERROR");
            if (init_i2c() != 0)
                fprintf(stderr, "Re-init failed; will retry next cycle\n");
        } else {
            log_data(0.0f, 0, "CRC_ERROR");
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

