/*
 * Flame-detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 * Buzzer : Active buzzer (driven HIGH = on)
 *
 * Wiring
 *   KY-026 D0  -> GPIO17 (physical pin 11)
 *   Buzzer +   -> GPIO18 (physical pin 12)
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *   Buzzer GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */
#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN       18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define LOG_FILE         "alert_log.txt"
#define CHIP_NAME        "gpiochip0"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log_file, const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;
    int prev_flame = 1;   /* assume no flame at startup (HIGH) */
    int first_read = 1;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* --- Get lines --- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request lines --- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        fprintf(stderr, "gpiod_line_request_input(flame) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Log startup --- */
    log_event(log_file, "System started");
    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int flame_value = gpiod_line_get_value(flame_line);
        if (flame_value < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame) failed: %s\n",
                    strerror(errno));
            log_event(log_file, "Error reading flame sensor");
            break;
        }

        /* Detect HIGH -> LOW transition (flame newly detected) */
        if (first_read) {
            prev_flame = flame_value;
            first_read = 0;
        } else if (prev_flame == 1 && flame_value == 0) {
            log_event(log_file, "Flame detected!");
            printf("Flame detected! Activating buzzer for %d ms.\n",
                   BUZZER_DURATION_MS);

            if (gpiod_line_set_value(buzzer_line, 1) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer ON) failed: %s\n",
                        strerror(errno));
                log_event(log_file, "Error activating buzzer");
                break;
            }

            /* Break buzzer activation into 100 ms slices for responsiveness */
            for (int elapsed = 0; elapsed < BUZZER_DURATION_MS && g_running;
                 elapsed += 100) {
                usleep(100 * 1000);
            }

            if (gpiod_line_set_value(buzzer_line, 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer OFF) failed: %s\n",
                        strerror(errno));
                log_event(log_file, "Error deactivating buzzer");
                break;
            }
        }

        prev_flame = flame_value;

        /* Break poll interval into 100 ms slices */
        for (int elapsed = 0; elapsed < POLL_INTERVAL_MS && g_running;
             elapsed += 100) {
            usleep(100 * 1000);
        }
    }

    /* --- Graceful shutdown --- */
    log_event(log_file, "System stopped");
    printf("Shutting down...\n");

    if (buzzer_line != NULL) {
        if (gpiod_line_set_value(buzzer_line, 0) != 0) {
            fprintf(stderr, "gpiod_line_set_value(buzzer OFF) failed: %s\n",
                    strerror(errno));
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line != NULL) {
        gpiod_line_release(buzzer_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }

    return ret;
}

