#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
    }
    return value;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
    }
    return result;
}

static int initialize_sensor(int handle) {
    int part_id = read_register(handle, PART_ID_REG);
    if (part_id < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Sensor not present or wrong device.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    int hw_rev = read_register(handle, HW_REV_REG);
    if (hw_rev < 0) return -1;
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X).\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_register(handle, LED_CURRENT_REG, 0x0F) < 0) return -1;
    if (write_register(handle, AVERAGING_REG, 0x04) < 0) return -1;
    if (write_register(handle, ENABLE_REG, 0x01) < 0) return -1;

    return 0;
}

static float read_heart_rate(int handle) {
    int raw = i2cReadWordData(handle, HEART_RATE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart rate register: %d\n", raw);
        return -1.0f;
    }
    return (float)raw * 0.5f;
}

static float moving_average(float new_value, float *buffer, int size, int *index, float *sum) {
    *sum -= buffer[*index];
    buffer[*index] = new_value;
    *sum += new_value;
    *index = (*index + 1) % size;
    return *sum / size;
}

static int log_data(FILE *fp, float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float hr_buffer[MOVING_AVG_SIZE] = {0};
    int hr_index = 0;
    float hr_sum = 0.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (!terminate) {
        float raw_bpm = read_heart_rate(i2c_handle);
        if (raw_bpm < 0) {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
            sleep(1);
            continue;
        }

        float filtered_bpm = moving_average(raw_bpm, hr_buffer, MOVING_AVG_SIZE, &hr_index, &hr_sum);

        if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
            if (log_data(log_file, filtered_bpm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM reading: %.2f\n", filtered_bpm);
        }

        sleep(1);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

