/*
 * TTP226 8-channel capacitive touch sensor -> 8-bit counter on GPIOs.
 * Board: Raspberry Pi Zero W (BCM numbering).
 * Sensor OUT1..OUT8 -> GPIO5..GPIO12 (active-high, 3.3 V touched).
 * Counter bits 0..7 -> GPIO17..GPIO24.
 * Log: touch_log.txt (append), format: YYYY-MM-DDTHH:MM:SSZ, Channel: <1-8>, Counter: <0-255>
 * Build: gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 10000          /* 10 ms */
#define STABILIZE_DELAY_US 200000        /* 200 ms after line-request */
#define LOG_FILE "touch_log.txt"

/* BCM pin numbers */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Write an 8-bit value to the 8 output GPIOs. Returns 0 on success, -1 on error. */
static int write_outputs(struct gpiod_line_request *req, unsigned int value)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int bit = (value >> i) & 1;
        if (gpiod_line_request_set_value(req, output_pins[i], bit) < 0) {
            fprintf(stderr, "Error writing output GPIO %u: %s\n",
                    output_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* Log a touch event to file and stdout. Returns 0 on success, -1 on file error. */
static int log_touch_event(int channel, unsigned int counter)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        /* Continue with stdout-only output */
    } else {
        fprintf(fp, "%s, Channel: %d, Counter: %u\n", timestamp, channel, counter);
        if (fclose(fp) != 0)
            fprintf(stderr, "Warning: fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }

    printf("Touch on channel %d | Counter: %u\n", channel, counter);
    fflush(stdout);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *output_req = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the gpiochip (gpiochip0 on Pi Zero W) --- */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open /dev/gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure sensor lines as inputs --- */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new (sensor) failed\n");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new (sensor) failed\n");
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(line_cfg, sensor_pins,
                                             NUM_CHANNELS, line_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (sensor) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new (sensor) failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch");

    sensor_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (sensor_req == NULL) {
        fprintf(stderr, "Failed to request sensor lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure output lines as outputs, initial value 0 --- */
    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(line_settings, GPIOD_LINE_VALUE_INACTIVE);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new (output) failed\n");
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(line_cfg, output_pins,
                                             NUM_CHANNELS, line_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (output) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_request_config_set_consumer(req_cfg, "ttp226-output");

    output_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (output_req == NULL) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Stabilize --- */
    usleep(STABILIZE_DELAY_US);

    /* --- Main loop --- */
    unsigned int counter = 0;
    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
        if (v < 0) {
            fprintf(stderr, "Initial read of sensor GPIO %u failed: %s\n",
                    sensor_pins[i], strerror(errno));
            prev_state[i] = 0;
        } else {
            prev_state[i] = v;
        }
    }

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (v < 0) {
                fprintf(stderr, "Error reading sensor GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }
            if (v == 1 && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (write_outputs(output_req, counter) < 0) {
                    fprintf(stderr, "Warning: output write failed, continuing\n");
                }
                if (log_touch_event(i + 1, counter) < 0) {
                    fprintf(stderr, "Warning: log write failed, continuing\n");
                }
            }
            prev_state[i] = v;
        }
        usleep(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    if (write_outputs(output_req, 0) < 0) {
        fprintf(stderr, "Warning: failed to reset outputs during shutdown\n");
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (sensor_req)
        gpiod_line_request_release(sensor_req);
    if (output_req)
        gpiod_line_request_release(output_req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (line_settings)
        gpiod_line_settings_free(line_settings);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

