#define DEBOUNCE_MS    50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_file, int sensor_number) {
    time_t rawtime;
