        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Error reading GPIO lines: %s\n", strerror(errno));
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

