        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1_line, "tcrt5000_s1") < 0) {
        fprintf(stderr, "Failed to request sensor1 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(s2_line, "tcrt5000_s2") < 0) {
        fprintf(stderr, "Failed to request sensor2 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "tcrt5000_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1 = gpiod_line_get_value(s1_line);
        int s2 = gpiod_line_get_value(s2_line);
        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int led_val = (s1 == 0 && s2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            fprintf(stderr, "LED write error: %s\n", strerror(errno));
        }

        if (log_data(log_fp, s1, s2, led_val) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (s1_line) gpiod_line_release(s1_line);
    if (s2_line) gpiod_line_release(s2_line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

