#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Set up signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_line) {
        perror("Failed to get left sensor line");
        goto cleanup;
    }

    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    if (!center_line) {
        perror("Failed to get center sensor line");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        perror("Failed to get right sensor line");
        goto cleanup;
    }

    /* Request the lines as inputs with pull-up enabled.
     * The SunFounder 3-Way Tracing Sensor is active-low: a black line
     * reflects IR and the output is pulled high; white reflects less
     * and the output is pulled low. */
    if (gpiod_line_request_input_flags(left_line, "tracing_sensor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request left sensor line as input with pull-up");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(center_line, "tracing_sensor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request center sensor line as input with pull-up");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(right_line, "tracing_sensor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request right sensor line as input with pull-up");
        goto cleanup;
    }

    printf("Tracing sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values.\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program finished.\n");
    return ret;
}

