#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define SI1175_ALS_VIS_DATA0 0x24
#define SI1175_ALS_VIS_DATA1 0x25
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access to 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 ALS visible data reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t lsb = 0, msb = 0;

        if (i2c_read_reg8(fd, SI1175_ALS_VIS_DATA0, &lsb) < 0) {
            fprintf(stderr, "Error: Failed to read ALS_VIS_DATA0: %s\n", strerror(errno));
            break;
        }

        if (i2c_read_reg8(fd, SI1175_ALS_VIS_DATA1, &msb) < 0) {
            fprintf(stderr, "Error: Failed to read ALS_VIS_DATA1: %s\n", strerror(errno));
            break;
        }

        uint16_t als_value = ((uint16_t)msb << 8) | lsb;
        printf("ALS Visible: %u\n", als_value);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");
    return ret;
}

