#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000
#define FADE_STEPS 50
#define FADE_DELAY_US (5000000 / FADE_STEPS)
#define HUE_MAX 360

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int clamp_int(int v, int lo, int hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static int set_rgb(int r, int g, int b) {
    if (gpioPWM(RED_PIN,   PWM_RANGE - clamp_int(r, 0, PWM_RANGE)) < 0) return -1;
    if (gpioPWM(GREEN_PIN, PWM_RANGE - clamp_int(g, 0, PWM_RANGE)) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - clamp_int(b, 0, PWM_RANGE)) < 0) return -1;
    return 0;
}

static void hsv_to_rgb(int h, int s, int v, int *r, int *g, int *b) {
    if (s == 0) {
        *r = *g = *b = v;
        return;
    }
    int c = v * s / 100;
    int x = c * (100 - abs((h % 60) - 30)) / 100;
    int m = v - c;
    if (h < 60)  { *r = c; *g = x; *b = 0; }
    else if (h < 120) { *r = x; *g = c; *b = 0; }
    else if (h < 180) { *r = 0; *g = c; *b = x; }
    else if (h < 240) { *r = 0; *g = x; *b = c; }
    else if (h < 300) { *r = x; *g = 0; *b = c; }
    else             { *r = c; *g = 0; *b = x; }
    *r += m; *g += m; *b += m;
}

static int fade_to_hsv(int h, int s, int v) {
    int r0, g0, b0, r1, g1, b1;
    hsv_to_rgb(h, s, v, &r1, &g1, &b1);
    if (set_rgb(r1, g1, b1) < 0) return -1;
    return 0;
}

static int fade_to_hsv_smooth(int h, int s, int v) {
    int r0, g0, b0, r1, g1, b1;
    if (gpioGetPWMdutycycle(RED_PIN,   &r0) < 0) r0 = 0;
    if (gpioGetPWMdutycycle(GREEN_PIN, &g0) < 0) g0 = 0;
    if (gpioGetPWMdutycycle(BLUE_PIN,  &b0) < 0) b0 = 0;
    r0 = PWM_RANGE - r0; g0 = PWM_RANGE - g0; b0 = PWM_RANGE - b0;
    hsv_to_rgb(h, s, v, &r1, &g1, &b1);
    int dr = r1 - r0, dg = g1 - g0, db = b1 - b0;
    for (int i = 0; i <= FADE_STEPS && running; i++) {
        int r = r0 + (dr * i) / FADE_STEPS;
        int g = g0 + (dg * i) / FADE_STEPS;
        int b = b0 + (db * i) / FADE_STEPS;
        if (set_rgb(r, g, b) < 0) return -1;
        usleep(FADE_DELAY_US);
    }
    return 0;
}

static int random_hue(void) {
    FILE *fp = fopen("/dev/urandom", "rb");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %m");
        return rand() % HUE_MAX;
    }
    unsigned char buf[2];
    size_t n = fread(buf, 1, 2, fp);
    fclose(fp);
    if (n < 2) {
        syslog(LOG_ERR, "Short read from /dev/urandom");
        return rand() % HUE_MAX;
    }
    return ((int)buf[0] << 8 | buf[1]) % HUE_MAX;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return -1;
    }
    int pins[] = {RED_PIN, GREEN_PIN, BLUE_PIN};
    for (size_t i = 0; i < sizeof(pins)/sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            syslog(LOG_ERR, "gpioSetPWMrange failed for GPIO%d", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            syslog(LOG_ERR, "gpioSetPWMfrequency failed for GPIO%d", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);
    srand((unsigned)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return 1;
    }

    if (init_gpio() < 0) {
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Mood lamp started (RGB: R%d G%d B%d, PWM %d Hz, %d-step fade)",
           RED_PIN, GREEN_PIN, BLUE_PIN, PWM_FREQ, FADE_STEPS);

    while (running) {
        int hue = random_hue();
        if (fade_to_hsv_smooth(hue, 100, 100) < 0) {
            syslog(LOG_ERR, "Fade failed during transition");
            break;
        }
        for (int i = 0; i < 50 && running; i++) usleep(100000);
    }

    syslog(LOG_INFO, "Shutting down");
    set_rgb(0, 0, 0);
    gpioTerminate();
    closelog();
    return 0;
}

