           RED_PIN, GREEN_PIN, BLUE_PIN, PWM_FREQ, FADE_STEPS);

    while (running) {
        int hue = random_hue();
        if (fade_to_hsv_smooth(hue, 100, 100) < 0) {
            syslog(LOG_ERR, "Fade failed during transition");
            break;
        }
        for (int i = 0; i < 50 && running; i++) usleep(100000);
    }

    syslog(LOG_INFO, "Shutting down");
    set_rgb(0, 0, 0);
    gpioTerminate();
    closelog();
    return 0;
}

