#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A

#define LED_PIN         17
#define RED_THRESHOLD   200
#define POLL_MS         200

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint16_t id;
    if (i2c_read16(fd, TCS34725_ID, &id) < 0) return -1;
    if ((id & 0xFF) != 0x44) {
        fprintf(stderr, "TCS34725 ID mismatch: 0x%02X (expected 0x44)\n", id & 0xFF);
        return -1;
    }
    if (i2c_write(fd, TCS34725_ENABLE, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    if (i2c_write(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    usleep(3000);
    return 0;
}

static void calibrate(uint16_t r, uint16_t g, uint16_t b, uint16_t c,
                      uint16_t *cr, uint16_t *cg, uint16_t *cb, uint16_t *cc) {
    *cr = (uint16_t)((r * 0.8) + 10);
    *cg = (uint16_t)((g * 0.9) + 5);
    *cb = (uint16_t)((b * 0.7) + 15);
    *cc = (uint16_t)((c * 0.85) + 8);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (i2c_read16(fd, TCS34725_RDATAL, &r) < 0 ||
            i2c_read16(fd, TCS34725_GDATAL, &g) < 0 ||
            i2c_read16(fd, TCS34725_BDATAL, &b) < 0 ||
            i2c_read16(fd, TCS34725_CDATAL, &c) < 0) {
            fprintf(stderr, "Read error, re-initializing sensor...\n");
            i2c_write(fd, TCS34725_ENABLE, 0x00);
            usleep(3000);
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed, retrying next cycle...\n");
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        uint16_t cr, cg, cb, cc;
        calibrate(r, g, b, c, &cr, &cg, &cb, &cc);
        printf("R: %u, G: %u, B: %u, C: %u\n", cr, cg, cb, cc);

        if (cr > RED_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    i2c_write(fd, TCS34725_ENABLE, 0x00);
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

