#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEAS_DELAY_US 180000
#define MAX_LUX 1000.0
#define PWM_RANGE 255
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_color(uint8_t r, uint8_t g, uint8_t b) {
    uint8_t *buf = malloc(NUM_LEDS * 3);
    if (!buf) return;
    for (int i = 0; i < NUM_LEDS; i++) {
        buf[i * 3] = g;
        buf[i * 3 + 1] = r;
        buf[i * 3 + 2] = b;
    }
    gpioWaveAddNew();
    gpioWaveAddGeneric(1, buf);
    int wid = gpioWaveCreate();
    if (wid >= 0) {
        gpioWaveTxSend(wid, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) gpioDelay(100);
        gpioWaveDelete(wid);
    }
    free(buf);
}

static float read_light_level(void) {
    int handle = i2cOpen(1, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1.0f;
    }
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) != 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        i2cClose(handle);
        return -1.0f;
    }
    gpioDelay(BH1750_MEAS_DELAY_US);
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        i2cClose(handle);
        return -1.0f;
    }
    i2cClose(handle);
    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return (float)raw / 1.2f;
}

static uint8_t map_light_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float norm = log10f(lux + 1.0f) / log10f(MAX_LUX + 1.0f);
    if (norm < 0.0f) norm = 0.0f;
    if (norm > 1.0f) norm = 1.0f;
    return (uint8_t)(norm * PWM_RANGE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LED_PIN, 800000);
    gpioPWM(LED_PIN, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (running) {
        float lux = read_light_level();
        if (lux < 0.0f) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }
        uint8_t brightness = map_light_to_brightness(lux);
        set_led_color(brightness, brightness, brightness);
        gpioDelay(LOOP_DELAY_US);
    }
    set_led_color(0, 0, 0);
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

