#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define NUM_LEDS 10
#define LUX_MIN 10.0f
#define LUX_MAX 300.0f
#define SPI_SPEED_HZ 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, 0x20) < 0) return -1;
    usleep(120000);
    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < LUX_MIN) lux = LUX_MIN;
    if (lux > LUX_MAX) lux = LUX_MAX;
    float norm = (lux - LUX_MIN) / (LUX_MAX - LUX_MIN);
    return (int)(norm * 31.0f);
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_led_brightness(int fd, int brightness) {
    int total_len = 4 + (4 * NUM_LEDS) + 4;
    uint8_t *tx = malloc(total_len);
    if (!tx) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    memset(tx, 0x00, 4);
    for (int i = 0; i < NUM_LEDS; i++) {
        int idx = 4 + (i * 4);
        tx[idx] = 0xE0 | (brightness & 0x1F);
        tx[idx + 1] = 0x00;
        tx[idx + 2] = 0x00;
        tx[idx + 3] = 0x00;
    }
    memset(tx + 4 + (NUM_LEDS * 4), 0xFF, 4);
    uint8_t *rx = malloc(total_len);
    if (!rx) {
        free(tx);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    int ret = spi_transfer(fd, tx, rx, total_len);
    free(tx);
    free(rx);
    return ret;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        set_led_brightness(spi_fd, 0);
        close(spi_fd);
        spi_fd = -1;
