#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define MAX_BRIGHTNESS 31
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define BH1750_CONV_TIME_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle_low = -1;
static int i2c_handle_high = -1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    if (handle < 0) {
        return -1;
    }
    if (i2cWriteByte(handle, 0x21) != 0) {
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_apa102_brightness(int handle, int brightness) {
    if (handle < 0) return;
    char buf[4 * NUM_LEDS + 4];
    for (int i = 0; i < 4; i++) buf[i] = 0x00;
    for (int i = 0; i < NUM_LEDS; i++) {
        buf[4 + i * 4] = 0xE0 | (brightness & 0x1F);
        buf[5 + i * 4] = 0x00;
        buf[6 + i * 4] = 0x00;
        buf[7 + i * 4] = 0x00;
    }
    for (int i = 0; i < 4; i++) buf[4 * NUM_LEDS + 4 + i] = 0xFF;
    spiWrite(handle, buf, sizeof(buf));
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(spi_handle, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle_low >= 0) {
        i2cClose(i2c_handle_low);
        i2c_handle_low = -1;
    }
    if (i2c_handle_high >= 0) {
        i2cClose(i2c_handle_high);
        i2c_handle_high = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle_low = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x23 not found\n");
    }

    i2c_handle_high = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x5C not found\n");
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int current_brightness = 0;
    int target_brightness = 0;

    while (running) {
        float lux_low = 0.0f, lux_high = 0.0f;
        int ok_low = (i2c_handle_low >= 0) ? read_bh1750(i2c_handle_low, &lux_low) : -1;
        int ok_high = (i2c_handle_high >= 0) ? read_bh1750(i2c_handle_high, &lux_high) : -1;

        float avg_lux = 0.0f;
        int count = 0;
        if (ok_low == 0) { avg_lux += lux_low; count++; }
        if (ok_high == 0) { avg_lux += lux_high; count++; }

        if (count > 0) {
            avg_lux /= count;
            target_brightness = (int)(MAX_BRIGHTNESS * (1.0f - (avg_lux / 1000.0f)));
            if (target_brightness < 0) target_brightness = 0;
            if (target_brightness > MAX_BRIGHTNESS) target_brightness = MAX_BRIGHTNESS;
        } else {
            target_brightness = MAX_BRIGHTNESS;
        }

        int fade_steps = FADE_DURATION_MS / 10;
        int step_size = (target_brightness > current_brightness) ? 1 : -1;
        for (int i = 0; i < fade_steps && running; i++) {
            current_brightness += step_size;
            if (step_size > 0 && current_brightness > target_brightness) current_brightness = target_brightness;
            if (step_size < 0 && current_brightness < target_brightness) current_brightness = target_brightness;
            set_apa102_brightness(spi_handle, current_brightness);
            gpioDelay(10000);
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

