#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define MAX_LUX 120000.0
#define GAMMA 2.2

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value & 0xFF), (uint8_t)((value >> 8) & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int init_veml7700(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

int read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_REG, &raw) < 0) {
        fprintf(stderr, "Error reading ALS: %s\n", strerror(errno));
        return -1;
    }
    *lux = (float)raw * 0.0288f;
    return 0;
}

void set_led_brightness(int brightness) {
    if (led_line) {
        gpiod_line_set_value(led_line, (brightness > 0) ? 1 : 0);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("VEML7700 initialized. Starting loop...\n");

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
            lux = 0.0f;
        }

        float brightness = 255.0f * powf(lux / MAX_LUX, 1.0f / GAMMA);
        if (brightness < 0.0f) brightness = 0.0f;
        if (brightness > 255.0f) brightness = 255.0f;

        set_led_brightness((int)brightness);
        printf("Lux: %.2f, Brightness: %.0f\n", lux, brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    set_led_brightness(0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

