#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define POLL_INTERVAL_MS 50
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_MS 100
#define SELF_TEST_FAIL_THRESHOLD 0

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Failed to get flame sensor line");
        cleanup();
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("Failed to request flame sensor line as input");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        cleanup();
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int val = gpiod_line_get_value(flame_line);
    if (val < 0) {
        perror("Failed to read flame sensor");
        return -1;
    }
    return val;
}

static void activate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Failed to activate buzzer");
    }
}

static void deactivate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Failed to deactivate buzzer");
    }
}

static void activate_led(void) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Failed to activate LED");
    }
}

static void deactivate_led(void) {
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to deactivate LED");
    }
}

static void self_test(void) {
    log_event("Starting self-test...");

    log_event("Blinking LED twice...");
    activate_led();
    usleep(500000);
    deactivate_led();
    usleep(500000);
    activate_led();
    usleep(500000);
    deactivate_led();
    usleep(500000);

    log_event("Reading flame sensor 5 times...");
    int fail_count = 0;
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int val = read_flame_sensor();
        if (val < 0) {
            fail_count++;
        } else if (val == 0) {
            fail_count++;
        }
        usleep(SELF_TEST_INTERVAL_MS * 1000);
    }

    if (fail_count > SELF_TEST_FAIL_THRESHOLD) {
        log_event("Self-test failed: flame sensor fault detected.");
        log_event("Error pattern: LED rapid blink, buzzer short-short-long-short.");
        for (int i = 0; i < 5; i++) {
            activate_led();
            usleep(100000);
            deactivate_led();
            usleep(100000);
        }
        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            usleep(200000);
            deactivate_buzzer();
            usleep(200000);
            activate_buzzer();
            usleep(600000);
            deactivate_buzzer();
            usleep(200000);
            activate_buzzer();
            usleep(200000);
            deactivate_buzzer();
            usleep(200000);
        }
        exit(1);
    } else {
        log_event("Self-test passed.");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    self_test();

    log_event("Entering main loop...");

    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor.");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val == 0) {
            log_event("Flame detected!");
            activate_buzzer();
            activate_led();

            int flame_active = 1;
            while (flame_active && program_running) {
                int new_val = read_flame_sensor();
                if (new_val < 0) {
                    log_event("Error reading flame sensor during active state.");
                    flame_active = 0;
                } else if (new_val == 1) {
                    log_event("Flame gone.");
                    flame_active = 0;
                }
                usleep(POLL_INTERVAL_MS * 1000);
            }

            deactivate_buzzer();
            deactivate_led();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Exiting gracefully...");
    cleanup();
    return 0;
}

