#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 1000000
#define BLINK_DUTY_CYCLE 0.5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    // Power on, then set continuous high-resolution mode
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    usleep(10000); // 10 ms power-on delay
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(180000); // 180 ms first measurement
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open export: %s\n", strerror(errno));
        return;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
    }
    close(fd);
    usleep(100000); // 100 ms settle
}

static void gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open unexport: %s\n", strerror(errno));
        return;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
    }
    close(fd);
}

static void gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open direction: %s\n", strerror(errno));
        return;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
    }
    close(fd);
}

static void gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open value: %s\n", strerror(errno));
        return;
    }
    char buf[2] = {value ? '1' : '0'};
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to write value: %s\n", strerror(errno));
    }
    close(fd);
}

static float calculate_average_lux(const float *buffer, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / (float)size;
}

static float map_lux_to_rate(float lux) {
