#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        if (gpiod_line_set_value(data_line, bit) < 0) {
            fprintf(stderr, "Error setting data line\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            fprintf(stderr, "Error setting clock high\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            fprintf(stderr, "Error setting clock low\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        usleep(1);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "74hc595", 0) < 0 ||
        gpiod_line_request_output(clock_line, "74hc595", 0) < 0 ||
        gpiod_line_request_output(latch_line, "74hc595", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Digit '5' pattern for common-cathode display: segments a,b,c,d,f,g on
    // Segments: a,b,c,d,e,f,g,dp (dp unused)
    // Bit order: Q0=a, Q1=b, Q2=c, Q3=d, Q4=e, Q5=f, Q6=g, Q7=dp
    // Pattern: 11011010 (MSB first: dp=0, g=1, f=1, e=0, d=1, c=1, b=0, a=1)
    unsigned char digit5 = 0xDB;

    while (keep_running) {
        // Display digit 5
        if (gpiod_line_set_value(latch_line, 0) < 0) {
            fprintf(stderr, "Error setting latch low\n");
            cleanup();
            return EXIT_FAILURE;
        }
        shift_out(digit5);
        if (gpiod_line_set_value(latch_line, 1) < 0) {
            fprintf(stderr, "Error setting latch high\n");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(500000);

        // Turn off
        if (gpiod_line_set_value(latch_line, 0) < 0) {
            fprintf(stderr, "Error setting latch low\n");
            cleanup();
            return EXIT_FAILURE;
        }
        shift_out(0x00);
        if (gpiod_line_set_value(latch_line, 1) < 0) {
            fprintf(stderr, "Error setting latch high\n");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

