#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_MS 1000
#define EVENT_TIMEOUT_SEC 1

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    // Request LED line as output, initially low
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    // Request button line as input with pull-up and falling-edge events
    struct gpiod_line_request_config button_config = {
        .consumer = "blink_button",
        .request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };
    if (gpiod_line_request(button_line, &button_config, 0) < 0) {
        perror("gpiod_line_request (button)");
        goto cleanup;
    }

    int led_state = 0;
    struct timespec ts = {EVENT_TIMEOUT_SEC, 0};

    while (keep_running) {
        // Toggle LED
        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        // Wait for button event with timeout
        int event_ret = gpiod_line_event_wait(button_line, &ts);
        if (event_ret < 0) {
            perror("gpiod_line_event_wait");
            goto cleanup;
        } else if (event_ret > 0) {
            // Button pressed: stop blinking, turn off LED, exit
            printf("Button pressed! Stopping blinking.\n");
            gpiod_line_set_value(led_line, 0);
            ret = EXIT_SUCCESS;
            break;
        }

        // Sleep for the remaining interval (minus event wait time)
        // Since event wait has a timeout, we just continue the loop
        // The loop naturally delays due to the blink interval
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

