    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line (GPIO22) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(button)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "led-blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    /* Request button line as input with internal pull-down */
    ret = gpiod_line_request_input_flags(button_line, "button-input",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(button)");
        goto cleanup;
    }

    printf("LED on GPIO%d, button on GPIO%d. Press Ctrl+C to exit.\n", LED_PIN, BUTTON_PIN);

    while (running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("gpiod_line_get_value(button)");
            break;
        }

        if (button_val == 1) {
            /* Button pressed: blink LED 500 ms on, 500 ms off */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led, 1)");
                break;
            }
            usleep(500000);
            if (!running) break;
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, 0)");
                break;
            }
            usleep(500000);
        } else {
            /* Button released: ensure LED is off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, 0)");
                break;
            }
            usleep(10000); /* small poll delay to avoid busy-loop */
        }
    }

cleanup:
    /* Turn LED off before releasing */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

