#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_MS 10
#define PWM_STEPS     100
#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) == EINTR) {
        if (!keep_running) break;
    }
}

static void set_pwm(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int on_ms = (PWM_PERIOD_MS * duty_percent) / 100;
    int off_ms = PWM_PERIOD_MS - on_ms;
    if (on_ms > 0) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
            return;
        }
        sleep_ms(on_ms);
    }
    if (off_ms > 0) {
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
            return;
        }
        sleep_ms(off_ms);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = 1;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    while (keep_running) {
        int red_val = rand() % (PWM_STEPS + 1);
        int green_val = rand() % (PWM_STEPS + 1);
        int blue_val = rand() % (PWM_STEPS + 1);

        set_pwm(red_line, red_val);
        set_pwm(green_line, green_val);
        set_pwm(blue_line, blue_val);

        sleep_ms(COLOR_CHANGE_MS);
    }

    ret = 0;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

