#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LSM303_ADDRESS 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SENSITIVITY 16384.0
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static double g_threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LSM303_ADDRESS, i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4_A\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_accelerometer(double *x, double *y, double *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (double)raw_x / SENSITIVITY;
    *y = (double)raw_y / SENSITIVITY;
    *z = (double)raw_z / SENSITIVITY;
    return 0;
}

static double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

static void log_impact(double x, double y, double z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.3f G, Y: %.3f G, Z: %.3f G\n", s, x, y, z);
    fclose(fp);
}

static void trigger_gpio(void) {
    gpioWrite(GPIO_PIN, 1);
    gpioDelay(50000);
    gpioWrite(GPIO_PIN, 0);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                if (g_threshold <= 0) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n", g_threshold);

    while (!terminate) {
        double x, y, z;
        if (read_accelerometer(&x, &y, &z) == 0) {
            double magnitude = calculate_magnitude(x, y, z);
            if (magnitude > g_threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                log_impact(x, y, z);
                trigger_gpio();
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

