    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                if (g_threshold <= 0) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n", g_threshold);

    while (!terminate) {
        double x, y, z;
        if (read_accelerometer(&x, &y, &z) == 0) {
            double magnitude = calculate_magnitude(x, y, z);
            if (magnitude > g_threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                log_impact(x, y, z);
                trigger_gpio();
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

