#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADPD188BI I2C address (7-bit)
#define ADPD188BI_ADDR 0x39

// ADPD188BI register addresses
#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED 0x66
#define REG_GREEN 0x68
#define REG_BLUE 0x6A

// GPIO pin for LED control (hardware PWM)
#define LED_GPIO 18

// I2C bus
#define I2C_BUS 1

// Sampling interval in microseconds
#define SAMPLE_INTERVAL_US 500000

// Retry delay in microseconds
#define RETRY_DELAY_US 100000

// Global variables for cleanup
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c(void);
int configure_sensor(void);
int read_sensor_data(sensor_data_t *data);
void log_data(const sensor_data_t *data);
void control_led(uint16_t als_value);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                ADPD188BI_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

// Configure the ADPD188BI sensor
int configure_sensor(void) {
    // Write 0x01 to MODE register to enter normal operation mode
    if (i2cWriteByteData(i2c_handle, REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Error writing to MODE register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data from ADPD188BI
int read_sensor_data(sensor_data_t *data) {
    int als_lsb, als_msb, red, green, blue;

    als_lsb = i2cReadByteData(i2c_handle, REG_ALS_LSB);
    if (als_lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %s\n", strerror(errno));
        return -1;
    }

    als_msb = i2cReadByteData(i2c_handle, REG_ALS_MSB);
    if (als_msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %s\n", strerror(errno));
        return -1;
    }

    red = i2cReadByteData(i2c_handle, REG_RED);
    if (red < 0) {
        fprintf(stderr, "Error reading Red channel: %s\n", strerror(errno));
        return -1;
    }

    green = i2cReadByteData(i2c_handle, REG_GREEN);
    if (green < 0) {
        fprintf(stderr, "Error reading Green channel: %s\n", strerror(errno));
        return -1;
    }

    blue = i2cReadByteData(i2c_handle, REG_BLUE);
    if (blue < 0) {
        fprintf(stderr, "Error reading Blue channel: %s\n", strerror(errno));
        return -1;
    }

    data->als = (uint16_t)((als_msb << 8) | als_lsb);
    data->red = (uint16_t)red;
    data->green = (uint16_t)green;
    data->blue = (uint16_t)blue;

    return 0;
}

// Log data to CSV file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data->als, data->red, data->green, data->blue);
    fflush(log_file);
}

// Control LED brightness based on ALS value
void control_led(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)((als_value / 65535.0) * 255.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output and configure PWM
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(LED_GPIO, 255);      // Range 0-255

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    return 0;
}

