        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }
    printf("FXOS8700CQ verified (WHO_AM_I = 0x%02X)\n", who);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure FXOS8700CQ: standby, ±2g, then active mode                */
/* ------------------------------------------------------------------ */
static int configure_sensor(void)
{
    /* 1. Place in standby (clear bit 0 of CTRL_REG1) */
    if (i2cWriteByteData(g_i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return -1;
    }

    /* 2. Set ±2g range (0x00 = ±2g, 0x01 = ±4g, 0x02 = ±8g) */
    if (i2cWriteByteData(g_i2c_handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set XYZ_DATA_CFG\n");
        return -1;
    }

    /* 3. Activate: bit 0 = active, bits 3-5 = ODR (010 = 200 Hz) */
    if (i2cWriteByteData(g_i2c_handle, FXOS8700_REG_CTRL_REG1, 0x0D) < 0) {
        fprintf(stderr, "Error: failed to set active mode\n");
        return -1;
    }

    printf("FXOS8700CQ configured: ±2g range, 200 Hz ODR, active mode\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (14-bit left-justified)          */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at OUT_X_MSB (0x01) */
    int bytes_read = i2cReadI2CBlockData(g_i2c_handle, FXOS8700_REG_OUT_X_MSB,
                                         buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes, expected 6)\n",
                bytes_read);
        return -1;
    }

    /* Data is 14-bit left-justified; shift right by 2 to get signed 14-bit */
    raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to g: raw / 4096 counts/g */
    *x = (float)raw_x / SENSITIVITY_2G;
    *y = (float)raw_y / SENSITIVITY_2G;
    *z = (float)raw_z / SENSITIVITY_2G;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude in m/s^2                            */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z) * 9.81f;
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                            */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open impact_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    } else {
        fprintf(fp, "UNKNOWN,%.3f,%.3f,%.3f,%.3f\n", x, y, z, magnitude);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1F */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) < 0) {
            /* I2C read error: log and continue rather than crash */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x, y, z, magnitude);
            printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

