#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define NUM_CAL_SAMPLES 100
#define CALIBRATION_TIME 1000
#define SAMPLE_PERIOD_US 50000
#define DPS_PER_LSB   0.00875f
#define ALERT_THRESHOLD 50.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst read(%zu bytes) failed: %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", GYRO_ADDR, strerror(errno));
        return -1;
    }

    uint8_t whoami = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &whoami) < 0) {
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, CTRL_REG4, 0x00) < 0) return -1;

    return 0;
}

static int read_gyro_raw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(i2c_fd, OUT_X_L | 0x80, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate_gyro(float *x_off, float *y_off, float *z_off) {
    int16_t x, y, z;
    long sx = 0, sy = 0, sz = 0;

    printf("Calibrating gyroscope (keep sensor stationary)...\n");
    for (int i = 0; i < NUM_CAL_SAMPLES; i++) {
        if (read_gyro_raw(&x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return;
        }
        sx += x; sy += y; sz += z;
        usleep(CALIBRATION_TIME / NUM_CAL_SAMPLES * 1000);
    }
    *x_off = (float)sx / NUM_CAL_SAMPLES * DPS_PER_LSB;
    *y_off = (float)sy / NUM_CAL_SAMPLES * DPS_PER_LSB;
    *z_off = (float)sz / NUM_CAL_SAMPLES * DPS_PER_LSB;
    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f dps\n", *x_off, *y_off, *z_off);
}

static void log_data(float x, float y, float z, float x_off, float y_off, float z_off) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, x - x_off, y - y_off, z - z_off);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        if (i2c_fd >= 0) close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "fopen(gyro_log.txt) failed: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    float x_off = 0, y_off = 0, z_off = 0;
    calibrate_gyro(&x_off, &y_off, &z_off);

    int16_t x, y, z;
    while (running) {
        if (read_gyro_raw(&x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float rx = (float)x * DPS_PER_LSB - x_off;
        float ry = (float)y * DPS_PER_LSB - y_off;
        float rz = (float)z * DPS_PER_LSB - z_off;

        log_data(rx, ry, rz, x_off, y_off, z_off);

        if (fabsf(rx) > ALERT_THRESHOLD || fabsf(ry) > ALERT_THRESHOLD || fabsf(rz) > ALERT_THRESHOLD) {
            fprintf(stderr, "WARNING: Angular velocity threshold exceeded! X=%.2f, Y=%.2f, Z=%.2f dps\n", rx, ry, rz);
            fprintf(log_file, "%s,WARNING,%.2f,%.2f,%.2f\n", "", rx, ry, rz);
            fflush(log_file);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

