#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_EXPECTED_DEVID 0xE5

#define LED_GPIO 17
#define ACCEL_THRESHOLD_G 2.0f
#define SAMPLE_PERIOD_US 100000
#define SCALE_FACTOR 0.0039f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (pigpio error %d)\n", devid);
        return -1;
    }
    if (devid != ADXL345_EXPECTED_DEVID) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n", devid, ADXL345_EXPECTED_DEVID);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL standby\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL measure\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char raw[6];
    int rc = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
