        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open accel_log.txt\n");
        cleanup();
        return 1;
    }

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
