#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

#define ACCEL_SENSITIVITY 0.000061f
#define MAG_SENSITIVITY   0.0001f

static volatile sig_atomic_t running = 1;
static int i2c_handle_accel = -1;
static int i2c_handle_mag   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm303(void) {
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | buffer[5]);
    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cos_roll  = cosf(roll);
    float sin_roll  = sinf(roll);
    float cos_pitch = cosf(pitch);
    float heading = atan2f(my * cos_roll - mz * sin_roll, mx * cos_pitch + my * sin_roll * cos_pitch - mz * sin_roll * sin_pitch);
    if (heading < 0) heading += 2.0f * M_PI;
    return heading * 180.0f / M_PI;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle_accel = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }
    i2c_handle_mag = i2cOpen(I2C_BUS, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }
    if (init_lsm303() < 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float ax, ay, az, mx, my, mz, heading;
    while (running) {
        if (read_accelerometer(&ax, &ay, &az) == 0 && read_magnetometer(&mx, &my, &mz) == 0) {
            heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        gpioDelay(100000);
    }
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();
    return 0;
}

