#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG     0x01
#define CTRL_REG     0x00
#define CTRL_VAL     0x80
#define SAMPLE_US    10000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VAL) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *out) {
    int hi = i2cReadByteData(handle, DATA_REG);
    if (hi < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }
    int lo = i2cReadByteData(handle, DATA_REG + 1);
    if (lo < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }
    *out = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, int16_t tdoa) {
    fprintf(fp, "%ld,%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            break;
        }

        int16_t s1 = 0, s2 = 0;
        int r1 = read_sensor_data(i2c_handle1, &s1);
        int r2 = read_sensor_data(i2c_handle2, &s2);

        if (r1 == 0 && r2 == 0) {
