#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG     0x01
#define CTRL_REG     0x00
#define CTRL_VAL     0x80
#define SAMPLE_US    10000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VAL) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *out) {
    int hi = i2cReadByteData(handle, DATA_REG);
    if (hi < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }
    int lo = i2cReadByteData(handle, DATA_REG + 1);
    if (lo < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }
    *out = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, int16_t tdoa) {
    fprintf(fp, "%ld,%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

