#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* Sensitivities */
#define GYRO_SENS   0.005f   /* deg/sec/LSB */
#define ACCEL_SENS  0.00025f /* g/LSB */

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0b11000000000 /* CPHA=1, CPOL=1, aux SPI off */

/* Timing */
#define SAMPLE_PERIOD_US  100000   /* 100 ms */
#define SPI_STALL_US      40       /* >40 us stall between request and data read */

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, close file, terminate pigpio                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                          */
/* Returns 0 on success (value stored in *out), -1 on SPI error.       */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    /* Request: MSB=0, bits[6:0]=register address */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    /* Stall for the ADIS16488A conversion / data-valid window */
    gpioDelay(SPI_STALL_US);

    /* Data read: send dummy 0x00 */
    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample row to the CSV file                                  */
/* ------------------------------------------------------------------ */
static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%ld.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ms, gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI: mode 3 (CPOL=1, CPHA=1), 16-bit words, 1 MHz */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, flags 0x%X)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        perror("fopen(\"imu_data.csv\")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(fp);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Register cleanup so every exit path releases resources */
    atexit(cleanup);

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t gx_raw, gy_raw, gz_raw;
        int16_t ax_raw, ay_raw, az_raw;

        int err = 0;
        err |= read_register(REG_X_GYRO,  &gx_raw);
        err |= read_register(REG_Y_GYRO,  &gy_raw);
        err |= read_register(REG_Z_GYRO,  &gz_raw);
        err |= read_register(REG_X_ACCEL, &ax_raw);
        err |= read_register(REG_Y_ACCEL, &ay_raw);
        err |= read_register(REG_Z_ACCEL, &az_raw);

        if (err) {
            fprintf(stderr, "SPI error — skipping sample\n");
        } else {
            float gx = gx_raw * GYRO_SENS;
            float gy = gy_raw * GYRO_SENS;
            float gz = gz_raw * GYRO_SENS;
            float ax = ax_raw * ACCEL_SENS;
            float ay = ay_raw * ACCEL_SENS;
            float az = az_raw * ACCEL_SENS;
            log_data(gx, gy, gz, ax, ay, az);
        }

        /* Non-blocking delay: sleep in 10 ms chunks so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    return EXIT_SUCCESS;
}

