#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8

#define REG_XGYRO_OUT   0x04
#define REG_YGYRO_OUT   0x06
#define REG_ZGYRO_OUT   0x08
#define REG_XACCL_OUT   0x0A
#define REG_YACCL_OUT   0x0C
#define REG_ZACCL_OUT   0x0E

#define GYRO_SCALE      0.02f
#define ACCL_SCALE      0.00025f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis_read_reg(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2], rx[2];

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    tx[0] = (uint8_t)(reg | 0x80);
    tx[1] = 0x00;
    if (spi_xfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (adis_read_reg(spi_fd, cs, REG_XGYRO_OUT, &gx) < 0 ||
            adis_read_reg(spi_fd, cs, REG_YGYRO_OUT, &gy) < 0 ||
            adis_read_reg(spi_fd, cs, REG_ZGYRO_OUT, &gz) < 0 ||
            adis_read_reg(spi_fd, cs, REG_XACCL_OUT, &ax) < 0 ||
            adis_read_reg(spi_fd, cs, REG_YACCL_OUT, &ay) < 0 ||
            adis_read_reg(spi_fd, cs, REG_ZACCL_OUT, &az) < 0) {
            fprintf(stderr, "SPI read error, continuing...\n");
            usleep(100000);
            continue;
        }

        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gx * GYRO_SCALE, gy * GYRO_SCALE, gz * GYRO_SCALE,
               ax * ACCL_SCALE, ay * ACCL_SCALE, az * ACCL_SCALE);
        fflush(stdout);

        usleep(100000);
    }

    ret = 0;

cleanup:
    if (cs) gpiod_line_release(cs);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

