#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

/* Scaling factors */
#define GYRO_SCALE 0.05f   /* deg/sec/LSB */
#define ACCL_SCALE 0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_MODE 0

/* ADIS16448 SPI read command: bit 15 = 1, bits 14:0 = register address */
#define READ_CMD(reg) ((uint16_t)((reg) | 0x8000))

/* Stall time between read command and dummy transfer (>= 40 us per datasheet) */
#define STALL_TIME_US 40

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from the ADIS16448 via two-cycle SPI.
 * Returns 0 on success, -1 on error. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_dummy[2];
    char rx_data[2];

    /* First transfer: send read command, clock out null data */
    tx_cmd[0] = (char)((READ_CMD(reg) >> 8) & 0xFF);
    tx_cmd[1] = (char)(READ_CMD(reg) & 0xFF);
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI command transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Stall time between command and dummy transfer */
    gpioDelay(STALL_TIME_US);

    /* Second transfer: send dummy, clock out 16-bit data */
    tx_dummy[0] = 0x00;
    tx_dummy[1] = 0x00;
    if (spiXfer(spi_handle, tx_dummy, rx_data, 2) != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

int main(void) {
    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: mode 0, active-low CE, 8 bits/word */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 2) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU Reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
        int16_t accl_x_raw, accl_y_raw, accl_z_raw;

        int err = 0;
        err |= read_register(X_GYRO_OUT, &gyro_x_raw);
        err |= read_register(Y_GYRO_OUT, &gyro_y_raw);
        err |= read_register(Z_GYRO_OUT, &gyro_z_raw);
        err |= read_register(X_ACCL_OUT, &accl_x_raw);
        err |= read_register(Y_ACCL_OUT, &accl_y_raw);
        err |= read_register(Z_ACCL_OUT, &accl_z_raw);

        if (err) {
            fprintf(stderr, "Error reading IMU data, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        float gyro_x = gyro_x_raw * GYRO_SCALE;
        float gyro_y = gyro_y_raw * GYRO_SCALE;
        float gyro_z = gyro_z_raw * GYRO_SCALE;
        float accl_x = accl_x_raw * ACCL_SCALE;
        float accl_y = accl_y_raw * ACCL_SCALE;
        float accl_z = accl_z_raw * ACCL_SCALE;

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
               gyro_x, gyro_y, gyro_z);
        printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n\n",
               accl_x, accl_y, accl_z);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

