#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68
#define WHO_AM_I       0x75
#define WHO_AM_I_VAL   0x86
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43
#define SAMPLE_DELAY_US 50000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who;
    if (i2c_read_burst(fd, WHO_AM_I, &who, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I - sensor absent or bus error\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    printf("MPU-6886 detected (WHO_AM_I = 0x%02X)\n", who);

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) return -1;
    usleep(100000);

    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) != 0) return -1;

    printf("MPU-6886 initialized: accel +/-2g, gyro +/-250 dps\n");
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) == 0) {
            *ax = (int16_t)((buf[0] << 8) | buf[1]);
            *ay = (int16_t)((buf[2] << 8) | buf[3]);
            *az = (int16_t)((buf[4] << 8) | buf[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) == 0) {
            *gx = (int16_t)((buf[0] << 8) | buf[1]);
            *gy = (int16_t)((buf[2] << 8) | buf[3]);
            *gz = (int16_t)((buf[4] << 8) | buf[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6886_init(fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("Reading IMU data every 50 ms (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_accel(fd, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Failed to read accelerometer after %d retries\n", MAX_RETRIES);
        } else if (read_gyro(fd, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Failed to read gyroscope after %d retries\n", MAX_RETRIES);
        } else {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting cleanly...\n");
    close(fd);
    return 0;
}

