#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_EXPECTED 0xE5

/* Impact threshold in g */
#define IMPACT_THRESHOLD 2.5f

/* GPIO pin for the red LED */
#define LED_PIN 17

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Full-resolution, +/-2g range (0x08 = FULL_RES | 0g) */
#define DATA_FORMAT_FULL_RES_2G 0x08

/* Scale factor for +/-2g full-resolution mode: 256 LSB/g */
#define SCALE_FACTOR 256.0f

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold accelerometer data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to initialize the ADXL345 */
static int init_adxl345(int handle) {
    /* Verify device identity */
    int devid = i2cReadByteData(handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Set data format: full resolution, +/-2g range */
    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT,
                         DATA_FORMAT_FULL_RES_2G) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        return -1;
    }

    /* Enable measurement mode (clear standby bit) */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer_data(int handle, accelerometer_data_t *data) {
    char raw_data[6];

    /* Read 6 bytes starting from DATAX0 (0x32) */
    int bytes_read = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0,
                                        raw_data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", bytes_read);
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    data->x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data->y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data->z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return 0;
}

/* Function to calculate the magnitude of acceleration */
static float calculate_magnitude(accelerometer_data_t data) {
    float x = (float)data.x / SCALE_FACTOR;
    float y = (float)data.y / SCALE_FACTOR;
    float z = (float)data.z / SCALE_FACTOR;
    return sqrtf(x * x + y * y + z * z);
}

/* Function to log impact data to a file */
static void log_impact_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n",
            timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file);
}

/* Function to handle an impact */
static void handle_impact(accelerometer_data_t data, float magnitude) {
    printf("Impact detected! Magnitude: %.2f g\n", magnitude);
    log_impact_data(data, magnitude);

    /* Turn on the LED */
    gpioWrite(LED_PIN, 1);
    gpioDelay(500000); /* 500 ms in microseconds */
    gpioWrite(LED_PIN, 0);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection on bus 1 */
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADXL345 */
    if (init_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file */
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        accelerometer_data_t data;

        if (read_accelerometer_data(i2c_handle, &data) == 0) {
            float magnitude = calculate_magnitude(data);

            if (magnitude > IMPACT_THRESHOLD) {
                handle_impact(data, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data in main loop\n");
        }

        gpioDelay(10000); /* 10 ms in microseconds */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

