        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to read gyroscope data */
static int read_gyroscope(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to log data to a CSV file */
static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
    fprintf(fp, "%.6f,%d,%d,%d,%d,%d,%d\n", timestamp, ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection on bus 1 */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who_am_i, ICM20602_WHO_AM_I);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the ICM-20602 */
    if (init_icm20602(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open the log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header */
    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    /* Main loop */
    int16_t ax, ay, az, gx, gy, gz;
    while (program_running) {
        if (read_accelerometer(i2c_handle, &ax, &ay, &az) == 0 &&
            read_gyroscope(i2c_handle, &gx, &gy, &gz) == 0) {
            log_data(log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
        }
        gpioDelay(100000); /* 100 ms delay (10 Hz) */
    }

    /* Cleanup */
    fprintf(stderr, "\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

