#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451_ADDR   0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define CTRL_REG1      0x2A
#define XYZ_DATA_CFG   0x0E
#define OUT_X_MSB      0x01
#define LED_PIN        17
#define IMPACT_THRESH  2.0f
#define SCALE_FACTOR   1024.0f
#define POLL_MS        100
#define LED_ON_MS      500

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8451_init(int fd) {
    uint8_t who;
    if (i2c_read(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write(fd, XYZ_DATA_CFG, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static bool impact_detected(float x, float y, float z) {
    return fabsf(x) > IMPACT_THRESH || fabsf(y) > IMPACT_THRESH || fabsf(z) > IMPACT_THRESH;
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %.2f, Y: %.2f, Z: %.2f\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MMA8451_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (mma8451_init(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "mma8451-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8451Q impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (impact_detected(x, y, z)) {
            printf("Impact detected! X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
            gpiod_line_set_value(led, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

