#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TMAG5273_ADDR 0x35
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetic_field_log.csv"
#define SAMPLE_INTERVAL_US 1000000

#define REG_X_RESULT 0x10
#define REG_Y_RESULT 0x11
#define REG_Z_RESULT 0x12

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int file_exists = (access(LOG_FILE, F_OK) == 0);
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    printf("TMAG5273 magnetic field logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        int err = 0;

        if (i2c_read_reg16(i2c_fd, REG_X_RESULT, &x) != 0) {
            fprintf(stderr, "Error reading X: %s\n", strerror(errno));
            err = 1;
        }
        if (i2c_read_reg16(i2c_fd, REG_Y_RESULT, &y) != 0) {
            fprintf(stderr, "Error reading Y: %s\n", strerror(errno));
            err = 1;
        }
        if (i2c_read_reg16(i2c_fd, REG_Z_RESULT, &z) != 0) {
            fprintf(stderr, "Error reading Z: %s\n", strerror(errno));
            err = 1;
        }

        if (!err) {
            if (log_data(log_fp, x, y, z) != 0) {
                fprintf(stderr, "Error writing to log: %s\n", strerror(errno));
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

