#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define ADXL345_DATAX0 0x32
#define ADXL345_DEVID_VAL 0xE5

#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define LOG_FILE "freefall_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x1E) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x04) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_INT_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_ff") < 0) {
        fprintf(stderr, "Cannot request falling-edge events on GPIO%d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts = {1, 0};
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
            continue;
        }

        uint8_t src;
        if (i2c_read_reg8(i2c_fd, ADXL345_INT_SOURCE, &src) < 0) continue;
        if (!(src & 0x04)) continue;

        uint8_t raw[6];
        if (i2c_read_block(i2c_fd, ADXL345_DATAX0, raw, 6) < 0) continue;

        int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
        int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
        int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

        struct timespec ts_now;
        clock_gettime(CLOCK_REALTIME, &ts_now);
        struct tm tm_info;
        localtime_r(&ts_now.tv_sec, &tm_info);
        char ts_str[32];
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(log_fp, "%s.%03ld,%d,%d,%d\n", ts_str, ts_now.tv_nsec / 1000000, x, y, z);
        fflush(log_fp);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

