#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 4.375f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FALL_WINDOW 1.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    float x, y, z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_regs(WHO_AM_I, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent?\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(CTRL1_XL, 0x80) != 0) return -1;
    if (i2c_write_reg(CTRL2_G, 0x80) != 0) return -1;
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_regs(OUTX_L_G, buf, 6) != 6) return -1;
    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);
    if (i2c_read_regs(OUTX_L_XL, buf, 6) != 6) return -1;
    int16_t ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t az = (int16_t)((buf[5] << 8) | buf[4]);
    data->x = ax * ACCEL_SENSITIVITY;
    data->y = ay * ACCEL_SENSITIVITY;
    data->z = az * ACCEL_SENSITIVITY;
    data->x = gx * GYRO_SENSITIVITY;
    data->y = gy * GYRO_SENSITIVITY;
    data->z = gz * GYRO_SENSITIVITY;
    return 0;
}

static float calc_magnitude(const sensor_data_t *d) {
    return sqrtf(d->x * d->x + d->y * d->y + d->z * d->z);
