            }
        } else if (state == 1) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            double elapsed = (now.tv_sec - fall_start.tv_sec) + (now.tv_nsec - fall_start.tv_nsec) / 1e9;
            if (elapsed > FALL_WINDOW) {
