#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_XGYRO_OUT 0x14
#define ADIS16266_SMPL_PRD  0x36
#define ADIS16266_AVG_CNT   0x38
#define ADIS16266_GLOB_CMD  0x68
#define ADIS16266_MSC_CTRL  0x60
#define ADIS16266_PROD_ID   0x5D

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* ADIS16266 Scaling Factor (degrees/sec/LSB) */
#define GYRO_SCALE 0.0305f

/* Global variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to read a 16-bit register from the ADIS16266 */
static int read_register(uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    /* SPI read: send register address with bit 7 set (read command) */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00; /* Dummy byte for clocking out data */

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X (returned %d)\n", reg_addr, result);
        return -1;
    }

    /* Data is returned in the next transaction */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read data transfer failed for register 0x%02X (returned %d)\n", reg_addr, result);
        return -1;
    }

    /* Combine the two bytes into a 16-bit value (MSB first) */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Function to write a 16-bit value to an ADIS16266 register */
static int write_register(uint8_t reg_addr, uint16_t value) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    /* SPI write: send register address with bit 7 clear (write command) */
    tx_buf[0] = (char)(reg_addr & 0x7F);
    tx_buf[1] = (char)(value & 0xFF); /* Low byte first */

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X (returned %d)\n", reg_addr, result);
        return -1;
    }

    return 0;
}

/* Function to initialize the ADIS16266 */
static int initialize_adis16266(void) {
    int16_t prod_id;

    /* Verify device identity */
    if (read_register(ADIS16266_PROD_ID, &prod_id) != 0) {
        fprintf(stderr, "Failed to read PROD_ID register\n");
        return -1;
    }

    /* ADIS16266 PROD_ID is 0x3F5A (datasheet) */
    if ((uint16_t)prod_id != 0x3F5A) {
        fprintf(stderr, "Unexpected PROD_ID: 0x%04X (expected 0x3F5A)\n", (uint16_t)prod_id);
        return -1;
    }

    /* Set sample period to 10 ms (0x000A) */
    if (write_register(ADIS16266_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to write SMPL_PRD register\n");
        return -1;
    }

    /* Set averaging count to 4 (0x0004) */
    if (write_register(ADIS16266_AVG_CNT, 0x0004) != 0) {
        fprintf(stderr, "Failed to write AVG_CNT register\n");
        return -1;
    }

    /* Reset device via GLOB_CMD */
    if (write_register(ADIS16266_GLOB_CMD, 0x0004) != 0) {
        fprintf(stderr, "Failed to write GLOB_CMD register\n");
        return -1;
    }
    gpioDelay(100000); /* Wait 100 ms for reset to complete */

    return 0;
}

/* Function to log data to a CSV file */
static void log_data(float gyro_x) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.6f,%.6f\n", timestamp, gyro_x);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel: mode 3, 1 MHz */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 2) | (1 << 3)); /* mode 3 */
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADIS16266 */
    if (initialize_adis16266() != 0) {
        fprintf(stderr, "ADIS16266 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header */
    fprintf(log_file, "timestamp,gyro_x\n");
    fflush(log_file);

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        int16_t gyro_x_raw;

        /* Read X-axis gyroscope data */
        if (read_register(ADIS16266_XGYRO_OUT, &gyro_x_raw) == 0) {
            /* Convert raw data to degrees/sec */
            float gyro_x = (float)gyro_x_raw * GYRO_SCALE;

            /* Log the data */
            log_data(gyro_x);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        /* Delay for 10 ms */
        gpioDelay(10000);
    }

    /* Clean up */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

