#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to VCC on GY-50) */
#define GYRO_ADDRESS 0x69

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28

/* Expected device ID */
#define WHO_AM_I_EXPECTED 0xD3

/* Sensitivity for +/- 250 dps: 8.75 mdps/LSB = 1/114.285714286 */
#define GYRO_SENSITIVITY 114.285714286

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum retries for I2C writes */
#define MAX_RETRIES 3

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register with retry logic */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d), rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        gpioDelay(1000); /* 1 ms backoff */
    }
    fprintf(stderr, "Error: Failed to write reg 0x%02X after %d attempts\n", reg, MAX_RETRIES);
    return -1;
}

/* Read a byte from a register */
static int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed, rc=%d\n", reg, value);
    }
    return value;
}

/* Read 6 bytes of gyro data starting at OUT_X_L */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: I2C block read failed, rc=%d\n", result);
        return -1;
    }
    /* L3G4200D outputs are left-justified; shift right 4 bits to get 12-bit value */
