#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_I2C_ADDR   0x53
#define CSV_FILENAME   "vibration_log.csv"
#define SAMPLE_MS      100
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int read_axis(int fd, uint8_t lsb_reg, int16_t *out) {
    uint8_t lsb = 0, msb = 0;
    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, lsb_reg + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z) {
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        perror("fopen " CSV_FILENAME);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "Timestamp,X,Y,Z\n");
        fflush(g_csv);
    }

    printf("Monitoring vibration on D7S-0001 at 0x%02X every %d ms. Ctrl+C to stop.\n",
           D7S_I2C_ADDR, SAMPLE_MS);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 1;

        if (read_axis(g_i2c_fd, REG_X_LSB, &x) < 0) ok = 0;
        if (ok && read_axis(g_i2c_fd, REG_Y_LSB, &y) < 0) ok = 0;
        if (ok && read_axis(g_i2c_fd, REG_Z_LSB, &z) < 0) ok = 0;

        if (!ok) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            log_data(g_csv, ts, x, y, z);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

