#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define CHIP_NAME "gpiochip4"
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, int s1, int s2) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, ts.tv_nsec / 1000000, s1, s2) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "conveyor-safety",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(SENSOR_1_PIN)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(line2, "conveyor-safety",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(SENSOR_2_PIN)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(LOG_FILE)");
        goto cleanup;
    }

    printf("Conveyor safety system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1 = gpiod_line_get_value(line1);
        if (s1 < 0) {
            perror("gpiod_line_get_value(SENSOR_1_PIN)");
            break;
        }
        int s2 = gpiod_line_get_value(line2);
        if (s2 < 0) {
            perror("gpiod_line_get_value(SENSOR_2_PIN)");
            break;
        }

        if (log_event(log_fp, s1, s2) != 0) {
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("Conveyor belt halted! (Sensor1=1, Sensor2=1)\n");
        }

        struct timespec delay = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Conveyor safety system stopped.\n");
    return ret;
}

