#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MMA8452Q I2C address when SA0 tied high */
#define MMA8452Q_ADDR 0x1D

/* Register addresses */
#define MMA8452Q_STATUS   0x00
#define MMA8452Q_OUT_X_MSB 0x01
#define MMA8452Q_OUT_X_LSB 0x02
#define MMA8452Q_OUT_Y_MSB 0x03
#define MMA8452Q_OUT_Y_LSB 0x04
#define MMA8452Q_OUT_Z_MSB 0x05
#define MMA8452Q_OUT_Z_LSB 0x06
#define MMA8452Q_WHO_AM_I  0x0D
#define MMA8452Q_CTRL_REG1 0x2A

/* Expected device ID */
#define MMA8452Q_ID 0x2A

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8452q_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &id) != 0)
        return -1;
    if (id != MMA8452Q_ID) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, MMA8452Q_ID);
        return -1;
    }

    /* Standby: clear ACTIVE bit (bit 0) */
    if (i2c_read_reg8(fd, MMA8452Q_CTRL_REG1, &id) != 0)
        return -1;
    id &= ~0x01;
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, id) != 0)
        return -1;

    /* Set data rate to 100 Hz (ODR = 0b010, bits 3-5) */
    id = (id & 0xE7) | (0x02 << 3);

    /* Active mode: set ACTIVE bit (bit 0) */
    id |= 0x01;

    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, id) != 0)
        return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* 12-bit left-justified: shift right 4 to get signed 12-bit value */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z)
{
    double x_d = (double)x;
    double y_d = (double)y;
    double z_d = (double)z;
    return atan2(x_d, sqrt(y_d * y_d + z_d * z_d)) * 180.0 / M_PI;
}

static void log_fall_event(int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[64];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (mma8452q_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen("fall_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(fall_log.txt) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("MMA8452Q initialized. Monitoring tilt (threshold %.1f deg)...\n",
           TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "read_accel failed, continuing...\n");
            usleep(10000);
            continue;
        }

        double tilt = calculate_tilt_angle(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_fall_event(x, y, z);
            printf("Tilt %.2f deg exceeds threshold -> logged\n", tilt);
        }

        usleep(10000); /* 10 ms ~ 100 Hz */
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

