#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_PARTID      0x01
#define ADXL354B_REG_STATUS      0x04
#define ADXL354B_REG_XDATA_H     0x08
#define ADXL354B_REG_YDATA_H     0x0B
#define ADXL354B_REG_ZDATA_H     0x0E
#define ADXL354B_REG_POWER_CTL   0x2D
#define ADXL354B_REG_RESET       0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// ADXL354B Sensitivity for +/- 2g range (3.9 microg/LSB)
#define ADXL354B_SENSITIVITY 0.0000039f

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_init(int handle);
int adxl354b_read_data(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// SPI Read Function (Multi-byte read)
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[32];
    char rx_buf[32];
    if (len > 31) return -1; // Limit to 31 bytes for safety

    tx_buf[0] = reg | 0x80; // Set bit 7 for read
    tx_buf[1] = 0x00;       // Dummy byte for first read
    memset(&tx_buf[2], 0x00, len - 1);

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != (len + 1)) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, &rx_buf[1], len);
    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];
    tx_buf[0] = reg & 0x7F; // Set bit 7 to 0 for write
    tx_buf[1] = value;

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }
    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t partid;
    int retries = 3;

    // Check Part ID
    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_PARTID, &partid, 1) == 0) {
            if (partid == 0x1D) {
                break;
            } else {
                fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x1D)\n", partid);
            }
        } else {
            fprintf(stderr, "Failed to read Part ID\n");
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "ADXL354B not detected\n");
        return -1;
    }

    // Reset the device
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay for reset

    // Set measurement mode (clear RUN bit, then set RUN bit)
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Wait for STABLE bit to be set
    uint8_t status;
    retries = 10;
    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_STATUS, &status, 1) == 0) {
            if (status & 0x01) {
                break;
            }
        } else {
            fprintf(stderr, "Failed to read status\n");
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "ADXL354B not stable\n");
        return -1;
    }

    // Start measurement (set RUN bit)
