            if (status & 0x01) {
                break;
            }
        } else {
            fprintf(stderr, "Failed to read status\n");
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "ADXL354B not stable\n");
        return -1;
    }

    // Start measurement (set RUN bit)
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    return 0;
}

