    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    // Convert to g's (20-bit signed, shift right 4 bits for 16-bit equivalent)
    *x = (float)raw_x * ADXL354B_SENSITIVITY;
    *y = (float)raw_y * ADXL354B_SENSITIVITY;
    *z = (float)raw_z * ADXL354B_SENSITIVITY;

    return 0;
}

// Data Logging Function
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
