#include <errno.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_X_GYRO_OUT  0x04
#define ADIS16362_Y_GYRO_OUT  0x06
#define ADIS16362_Z_GYRO_OUT  0x08
#define ADIS16362_X_ACCL_OUT  0x0A
#define ADIS16362_Y_ACCL_OUT  0x0C
#define ADIS16362_Z_ACCL_OUT  0x0E

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCEL_SCALE 0.0025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x0003  /* Mode 3: active-high clock, sampled on trailing edge */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x_gyro, y_gyro, z_gyro;
    float x_accel, y_accel, z_accel;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16362.
 * The ADIS16362 read protocol requires sending the register address
 * with the MSB set (read command) followed by a dummy byte, then
 * performing a second 16-bit transfer to retrieve the data.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(uint8_t address, int16_t *data) {
    char tx[2], rx[2];
    int ret;

    /* Phase 1: send read command for the register */
    tx[0] = (char)(address | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write error for address 0x%02X: ret=%d, errno=%d\n",
                address, ret, errno);
        return -1;
    }

    /* Small delay to allow the device to prepare the response */
    gpioDelay(20); /* 20 microseconds */

    /* Phase 2: read the 16-bit data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read error for address 0x%02X: ret=%d, errno=%d\n",
                address, ret, errno);
        return -1;
    }

    *data = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    int16_t raw;

    if (read_register(ADIS16362_X_GYRO_OUT, &raw) != 0) return -1;
    data->x_gyro = (float)raw * GYRO_SCALE;
    if (read_register(ADIS16362_Y_GYRO_OUT, &raw) != 0) return -1;
    data->y_gyro = (float)raw * GYRO_SCALE;
    if (read_register(ADIS16362_Z_GYRO_OUT, &raw) != 0) return -1;
    data->z_gyro = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16362_X_ACCL_OUT, &raw) != 0) return -1;
    data->x_accel = (float)raw * ACCEL_SCALE;
    if (read_register(ADIS16362_Y_ACCL_OUT, &raw) != 0) return -1;
    data->y_accel = (float)raw * ACCEL_SCALE;
    if (read_register(ADIS16362_Z_ACCL_OUT, &raw) != 0) return -1;
    data->z_accel = (float)raw * ACCEL_SCALE;

    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            data->x_gyro, data->y_gyro, data->z_gyro,
            data->x_accel, data->y_accel, data->z_accel);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    imu_data_t imu_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            log_data(&imu_data);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping logging.\n");
        }
        gpioDelay(10000); /* 10 ms delay (~100 Hz) */
    }

    cleanup();
    return EXIT_SUCCESS;
}

