#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS 8

#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL 0x24

#define SCALE_FACTOR 0.02f
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, struct gpiod_line *cs, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }
    int ret = spi_transfer(fd, tx, rx, 2);
    gpiod_line_set_value(cs, 1);
    return ret;
}

static int adis16266_read_reg(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    gpiod_line_set_value(cs, 1);

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (adis16266_write_reg(spi_fd, cs_line, ADIS16266_MSC_CTRL, 0x00) < 0) {
        fprintf(stderr, "Failed to write MSC_CTRL register\n");
        goto cleanup;
    }
    usleep(10000);

    printf("ADIS16266 initialized. Reading data every %d ms...\n", SAMPLE_DELAY_MS);

    while (running) {
        int16_t x_raw, y_raw, z_raw;

        if (adis16266_read_reg(spi_fd, cs_line, ADIS16266_XGYRO_OUT, &x_raw) < 0 ||
            adis16266_read_reg(spi_fd, cs_line, ADIS16266_YGYRO_OUT, &y_raw) < 0 ||
            adis16266_read_reg(spi_fd, cs_line, ADIS16266_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "SPI read error, continuing...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        float x_rate = x_raw * SCALE_FACTOR;
        float y_rate = y_raw * SCALE_FACTOR;
        float z_rate = z_raw * SCALE_FACTOR;

        printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x_rate, y_rate, z_rate);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

