#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied high on Adafruit breakout) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I    0x0F
#define CTRL1_XL    0x10
#define CTRL2_G     0x11
#define OUTX_L_G    0x22
#define OUTX_H_G    0x23
#define OUTY_L_G    0x24
#define OUTY_H_G    0x25
#define OUTZ_L_G    0x26
#define OUTZ_H_G    0x27
#define OUTX_L_XL   0x28
#define OUTX_H_XL   0x29
#define OUTY_L_XL   0x2A
#define OUTY_H_XL   0x2B
#define OUTZ_L_XL   0x2C
#define OUTZ_H_XL   0x2D

/* Expected chip ID */
#define WHO_AM_I_EXPECTED 0x6B

/* Sensitivities for default full-scale ranges */
#define ACCEL_SENSITIVITY 0.000061f  /* 0.061 mg/LSB  -> g/LSB */
#define GYRO_SENSITIVITY  0.00875f   /* 8.75 mdps/LSB -> dps/LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_checked(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_block_checked(int handle, uint8_t reg,
                                  uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed: reg=0x%02X len=%u rc=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int16_t combine_le(uint8_t lo, uint8_t hi)
{
    return (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the LSM6DSR address --- */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=1 addr=0x%02X): %d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    int who = i2cReadByteData(g_i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who);
        goto cleanup_fail;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_EXPECTED);
        goto cleanup_fail;
    }

    /* --- Configure accelerometer: +-2g, 104 Hz --- */
    if (i2c_write_checked(g_i2c_handle, CTRL1_XL, 0x42) != 0)
        goto cleanup_fail;

    /* --- Configure gyroscope: +-250 dps, 104 Hz --- */
    if (i2c_write_checked(g_i2c_handle, CTRL2_G, 0x42) != 0)
        goto cleanup_fail;

    /* --- Allow sensors to settle --- */
    gpioDelay(20000); /* 20 ms */

    /* --- Main sampling loop --- */
    while (g_running) {
        uint8_t buf[12];

        /* Burst-read 6 gyro bytes + 6 accel bytes starting at OUTX_L_G */
        if (i2c_read_block_checked(g_i2c_handle, OUTX_L_G, buf, 12) != 0) {
            fprintf(stderr, "Sensor read error; continuing\n");
            gpioDelay(100000);
            continue;
        }

        int16_t gx = combine_le(buf[0], buf[1]);
        int16_t gy = combine_le(buf[2], buf[3]);
        int16_t gz = combine_le(buf[4], buf[5]);
        int16_t ax = combine_le(buf[6], buf[7]);
        int16_t ay = combine_le(buf[8], buf[9]);
        int16_t az = combine_le(buf[10], buf[11]);

        float gx_dps = gx * GYRO_SENSITIVITY;
        float gy_dps = gy * GYRO_SENSITIVITY;
        float gz_dps = gz * GYRO_SENSITIVITY;
        float ax_g   = ax * ACCEL_SENSITIVITY;
        float ay_g   = ay * ACCEL_SENSITIVITY;
        float az_g   = az * ACCEL_SENSITIVITY;

        printf("Gyro:  X=%.2f Y=%.2f Z=%.2f dps | "
               "Accel: X=%.2f Y=%.2f Z=%.2f g\n",
               gx_dps, gy_dps, gz_dps,
               ax_g, ay_g, az_g);
        fflush(stdout);

        gpioDelay(100000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    i2cClose(g_i2c_handle);
    g_i2c_handle = -1;
    gpioTerminate();
    return EXIT_SUCCESS;

cleanup_fail:
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_FAILURE;
}

