    if (fxos8700_write_register(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Configure magnetometer: OS=1, M_ODR=100 Hz */
    if (fxos8700_write_register(handle, FXOS8700_REG_M_CTRL_REG1, M_CTRL_REG1_VAL) != 0)
        return -1;

    /* Configure magnetometer: hybrid mode, auto-increment */
    if (fxos8700_write_register(handle, FXOS8700_REG_M_CTRL_REG2, M_CTRL_REG2_VAL) != 0)
        return -1;

    /* Configure accelerometer range: +/-2g (0x00) */
    if (fxos8700_write_register(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode, 100 Hz ODR, hybrid mode */
    if (fxos8700_write_register(handle, FXOS8700_REG_CTRL_REG1, CTRL_REG1_VAL) != 0)
        return -1;

    /* Hybrid mode control */
    if (fxos8700_write_register(handle, FXOS8700_REG_CTRL_REG2, CTRL_REG2_VAL) != 0)
        return -1;

    return 0;
}

static int fxos8700_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    char buffer[12];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buffer, 12);
    if (rc != 12) {
        fprintf(stderr, "I2C block read error: expected 12 bytes, got %d\n", rc);
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 */
    *ax = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    *ay = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    *az = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Magnetometer: 16-bit */
    *mx = (int16_t)(((uint16_t)buffer[6] << 8) | (uint8_t)buffer[7]);
    *my = (int16_t)(((uint16_t)buffer[8] << 8) | (uint8_t)buffer[9]);
    *mz = (int16_t)(((uint16_t)buffer[10] << 8) | (uint8_t)buffer[11]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, mx, my, mz;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n",
                FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fxos8700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 hybrid mode logging started (Ctrl+C to stop)\n");

    while (g_running) {
        if (fxos8700_read_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting\n");
                break;
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

