#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int adxl345_init(int fd) {
    if (i2c_write_byte(fd, POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, DATA_FORMAT, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, DATAX0, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *x_angle, float *y_angle) {
    *x_angle = atan2((float)x, (float)z) * 180.0 / M_PI;
    *y_angle = atan2((float)y, (float)z) * 180.0 / M_PI;
}

void log_tilt_event(float x_angle, float y_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt Event: X=%.2f, Y=%.2f\n", timestamp, x_angle, y_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized successfully. Monitoring tilt...\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration data\n");
            usleep(100000);
            continue;
        }

        float x_angle, y_angle;
        calculate_tilt_angles(x, y, z, &x_angle, &y_angle);

        if (fabs(x_angle) > TILT_THRESHOLD || fabs(y_angle) > TILT_THRESHOLD) {
            log_tilt_event(x_angle, y_angle);
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

