#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define WINDOW_MS 5000
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_SAMPLES (WINDOW_MS / (SAMPLE_INTERVAL_US / 1000))
#define PAUSE_BETWEEN_WINDOWS_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int parse_threshold(const char *arg, int *out) {
    char *endptr = NULL;
    long val = strtol(arg, &endptr, 10);
    if (endptr == arg || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be a valid integer.\n");
        return -1;
    }
    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return -1;
    }
    *out = (int)val;
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high-readings per 5-second window to trigger alert\n");
        return EXIT_FAILURE;
    }

    int threshold;
    if (parse_threshold(argv[1], &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound levels on GPIO%d. Threshold: %d high-readings in %d ms.\n",
           SOUND_SENSOR_GPIO, threshold, WINDOW_MS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int high_count = 0;
        int sample_count = 0;

        for (int i = 0; i < WINDOW_SAMPLES && program_running; i++) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                program_running = 0;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            sample_count++;
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!program_running) {
            break;
        }

        if (sample_count == 0) {
            fprintf(stderr, "Error: no samples taken during monitoring window.\n");
            break;
        }

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (high_count > threshold) {
            printf("[%s] ALERT: Sound level exceeded threshold (%d > %d)\n",
                   timestamp, high_count, threshold);
        } else {
            printf("[%s] Sound level normal (%d <= %d)\n",
                   timestamp, high_count, threshold);
        }
        fflush(stdout);

        if (program_running) {
            gpioDelay(PAUSE_BETWEEN_WINDOWS_US);
        }
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

