static int mpr121_read_touch(int handle) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

static int map_touch_to_frequency(int touch_value) {
    if (touch_value < 0) return 220;
    if (touch_value > 1000) touch_value = 1000;
    float log_min = log10f(220.0f);
    float log_max = log10f(880.0f);
    float t = (float)touch_value / 1000.0f;
    float freq = powf(10.0f, log_min + t * (log_max - log_min));
    return (int)(freq + 0.5f);
}

static void play_tone(int frequency) {
    if (frequency < 20) frequency = 20;
    if (frequency > 20000) frequency = 20000;
    int duty = (int)((float)frequency / 1000.0f * 50000.0f);
    if (duty > 500000) duty = 500000;
    if (duty < 0) duty = 0;
    gpioHardwarePWM(PWM_GPIO, frequency, duty);
}

static void stop_tone(void) {
    gpioHardwarePWM(PWM_GPIO, 0, 0);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %d Hz\n", ts, frequency);
    fclose(fp);
}

static void cleanup(void) {
    stop_tone();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 init failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    stop_tone();

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (running) perror("accept");
            continue;
        }

        char buffer[1024];
        ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (n <= 0) {
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[n] = '\0';

        char *motion_prefix = strstr(buffer, "MOTION_DETECTED:");
        if (motion_prefix) {
            char *key_pos = strstr(motion_prefix, SECRET_KEY);
            if (key_pos) {
                printf("Motion detected! Playing theremin for %d seconds...\n", PLAYBACK_DURATION_S);
                time_t start = time(NULL);
                while (running && (time(NULL) - start) < PLAYBACK_DURATION_S) {
                    int touch = mpr121_read_touch(i2c_handle);
                    if (touch < 0) {
                        stop_tone();
                        break;
                    }
                    int freq = map_touch_to_frequency(touch);
                    play_tone(freq);
                    log_frequency(freq);
                    gpioDelay(SAMPLE_INTERVAL_US);
                }
                stop_tone();
            } else {
                printf("Invalid secret key.\n");
            }
        } else {
            printf("Invalid message format.\n");
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

