#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_PIN 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000  // 10ms period for 100Hz PWM

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *pwm_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_lsm303(int fd) {
    if (i2c_write_byte(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC\n");
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt((double)x * x + (double)y * y + (double)z * z);
}

int set_led_brightness(struct gpiod_line *line, double magnitude) {
    int duty_cycle = (int)((magnitude / 1000.0) * 1000000);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;
    if (gpiod_line_set_value(line, duty_cycle > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void cleanup() {
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_lsm303(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, 18); // GPIO18 supports hardware PWM
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "lsm303_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request PWM line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) == 0) {
            double magnitude = calculate_magnitude(x, y, z);
            set_led_brightness(pwm_line, magnitude);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

