#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error reading block from reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    if (write_reg(HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(HMC5883L_DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_offsets(int16_t *x_off, int16_t *y_off, int16_t *z_off,
                              const int16_t *x_buf, const int16_t *y_buf,
                              const int16_t *z_buf, int count) {
    long sx = 0, sy = 0, sz = 0;
    for (int i = 0; i < count; i++) {
        sx += x_buf[i];
        sy += y_buf[i];
        sz += z_buf[i];
    }
    *x_off = (int16_t)(sx / count);
    *y_off = (int16_t)(sy / count);
    *z_off = (int16_t)(sz / count);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x_buf[SAMPLE_WINDOW], y_buf[SAMPLE_WINDOW], z_buf[SAMPLE_WINDOW];
    int idx = 0, filled = 0;
    int16_t x_off = 0, y_off = 0, z_off = 0;

    while (running) {
        int16_t x, y, z;
        if (read_raw_data(&x, &y, &z) < 0) {
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        x_buf[idx] = x;
        y_buf[idx] = y;
        z_buf[idx] = z;
        idx = (idx + 1) % SAMPLE_WINDOW;
        if (idx == 0) filled = 1;

        if (filled) {
            calculate_offsets(&x_off, &y_off, &z_off, x_buf, y_buf, z_buf, SAMPLE_WINDOW);
        }

        int16_t cx = x - x_off;
        int16_t cy = y - y_off;
        int16_t cz = z - z_off;

        printf("X: %6d, Y: %6d, Z: %6d\n", cx, cy, cz);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

