 * Build  : gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run    : sudo ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants (accelerometer) ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_THS    0x32
#define LSM303D_INT1_DUR    0x33
#define LSM303D_OUT_X_L_A   0x28

#define ACCEL_SENSITIVITY   0.061f   /* mg/LSB at +/-2g */
#define ACCEL_THRESHOLD_MG  2000.0f
#define ACCEL_THRESHOLD_REG (int)(ACCEL_THRESHOLD_MG / 16.0f)  /* 0x7D */

#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"
#define GPIO_LINE           23       /* BCM 23 */
#define BUFFER_SIZE         64
#define SAMPLES_TO_PRINT    10
#define POLL_DELAY_US       10000    /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_int_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x[BUFFER_SIZE];
    int16_t y[BUFFER_SIZE];
    int16_t z[BUFFER_SIZE];
    int     head;
    int     count;
} AccelBuffer;

static AccelBuffer g_buf;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write 0x%02X <- 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    int r = i2c_smbus_read_byte_data(fd, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) != len) {
        fprintf(stderr, "I2C block read 0x%02X (%d bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

