static int accel_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, XYZ axes enabled -> 0x57 */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: +/-2g full-scale, high-resolution off -> 0x00 */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1_CFG: any-axis-high event, LIR (latch) off -> 0x2A */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x2A) < 0)
        return -1;

    /* INT1_THS: threshold = 2000 mg / 16 = 125 -> 0x7D */
    if (i2c_write_reg8(fd, LSM303D_INT1_THS, ACCEL_THRESHOLD_REG) < 0)
        return -1;

    /* INT1_DUR: 0 -> interrupt generated on threshold crossing */
    if (i2c_write_reg8(fd, LSM303D_INT1_DUR, 0x00) < 0)
        return -1;

