    if (i2c_read_block(fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buf_push(AccelBuffer *b, int16_t x, int16_t y, int16_t z)
{
    b->x[b->head] = x;
    b->y[b->head] = y;
    b->z[b->head] = z;
    b->head = (b->head + 1) % BUFFER_SIZE;
    if (b->count < BUFFER_SIZE)
        b->count++;
}

static void buf_dump_last(const AccelBuffer *b, int n)
{
    if (n > b->count)
        n = b->count;
    if (n == 0) {
        printf("  (no samples in buffer)\n");
        return;
    }
    int start = (b->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] X=%6d  Y=%6d  Z=%6d\n",
               b->count - n + i, b->x[idx], b->y[idx], b->z[idx]);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int_line) {
        gpiod_line_release(g_int_line);
        g_int_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

