int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (accel_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Accelerometer init failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_int_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_int_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_int_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D accelerometer monitor started.\n");
    printf("  I2C bus : %s @ 0x%02X\n", I2C_BUS, LSM303D_ADDR);
    printf("  INT1    : GPIO%d (BCM)\n", GPIO_LINE);
    printf("  Threshold: %.0f mg  (%d LSB)\n", ACCEL_THRESHOLD_MG, ACCEL_THRESHOLD_REG);
    printf("  Press Ctrl-C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        if (accel_read(g_i2c_fd, &x, &y, &z) == 0) {
            buf_push(&g_buf, x, y, z);
        } else {
            fprintf(stderr, "Warning: accel read failed, skipping sample.\n");
        }

        /* Check for GPIO interrupt event */
        struct timespec ts = { 0, 0 };  /* non-blocking */
        int ev = gpiod_line_event_wait(g_int_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_int_line, &event) < 0) {
                fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                time_t now = time(NULL);
                char tsbuf[32];
                strftime(tsbuf, sizeof(tsbuf), "%Y-%m-%d %H:%M:%S",
                         localtime(&now));
                printf("\n--- INT1 rising edge at %s ---\n", tsbuf);
                buf_dump_last(&g_buf, SAMPLES_TO_PRINT);
                printf("--- end dump ---\n\n");
            }
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

