#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_GPIO      17
#define LOCK2_GPIO      27
#define EXPECTED_CODE   "123456"
#define CODE_LENGTH     6
#define UNLOCK_DURATION 2
#define POLL_TIMEOUT_S  5
#define BAUD_RATE       9600
#define SERIAL0_DEV     "/dev/serial0"
#define SERIAL1_DEV     "/dev/serial1"

static volatile sig_atomic_t g_running = 1;
static int g_serial0 = -1;
static int g_serial1 = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Ensure both locks are locked (LOW) on every exit path */
    if (gpioInitialise() >= 0) {
        gpioWrite(LOCK1_GPIO, 0);
        gpioWrite(LOCK2_GPIO, 0);
        gpioTerminate();
    }
    if (g_serial0 >= 0) {
        serClose(g_serial0);
        g_serial0 = -1;
    }
    if (g_serial1 >= 0) {
        serClose(g_serial1);
        g_serial1 = -1;
    }
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        return -1;
    }
    /* Default: both locks locked (LOW) */
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW.\n", LOCK2_GPIO);
        return -1;
    }
    return 0;
}

static int init_serial(const char *device)
{
    int handle = serOpen((char *)device, BAUD_RATE, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open %s (pigpio error %d).\n", device, handle);
        return -1;
    }
    return handle;
}

/*
 * Constant-time comparison of two fixed-length strings to avoid
 * timing side-channels.
 */
static int codes_match(const char *a, const char *b)
{
    int diff = 0;
    for (int i = 0; i < CODE_LENGTH; i++) {
        diff |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return (diff == 0);
}

static int unlock_doors(void)
{
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to unlock lock 1 (GPIO%d).\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to unlock lock 2 (GPIO%d).\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Both doors unlocked for %d seconds.\n", UNLOCK_DURATION);
    sleep(UNLOCK_DURATION);
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to lock lock 1 (GPIO%d).\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to lock lock 2 (GPIO%d).\n", LOCK2_GPIO);
        return -1;
    }
    printf("Both doors locked.\n");
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    g_serial0 = init_serial(SERIAL0_DEV);
    if (g_serial0 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_serial1 = init_serial(SERIAL1_DEV);
    if (g_serial1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Dual-factor authentication system started.\n");
    printf("Expected code: %s\n", EXPECTED_CODE);
    printf("Listening on %s and %s at %d baud.\n", SERIAL0_DEV, SERIAL1_DEV, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");

    char code0[CODE_LENGTH + 1] = "";
    char code1[CODE_LENGTH + 1] = "";
    int  idx0 = 0, idx1 = 0;
    time_t start = time(NULL);

    while (g_running) {
        time_t now = time(NULL);
        if (now - start >= POLL_TIMEOUT_S) {
            /* Timeout: reset buffers and restart window */
            idx0 = 0;
            idx1 = 0;
            code0[0] = '\0';
            code1[0] = '\0';
            start = now;
            printf("Timeout: waiting for codes on both UARTs...\n");
            continue;
        }

        /* Non-blocking read from serial0 */
        if (g_serial0 >= 0) {
            char ch;
            int n = serRead(g_serial0, &ch, 1);
            if (n > 0) {
                if (ch >= '0' && ch <= '9') {
                    if (idx0 < CODE_LENGTH) {
                        code0[idx0++] = ch;
                        code0[idx0] = '\0';
                    } else {
                        /* Overflow: reset */
                        idx0 = 0;
                        code0[0] = '\0';
                    }
                } else {
                    /* Non-digit: reset */
                    idx0 = 0;
                    code0[0] = '\0';
                }
            } else if (n < 0) {
                fprintf(stderr, "Warning: error reading %s (pigpio error %d).\n",
                        SERIAL0_DEV, n);
            }
        }

        /* Non-blocking read from serial1 */
        if (g_serial1 >= 0) {
            char ch;
            int n = serRead(g_serial1, &ch, 1);
            if (n > 0) {
                if (ch >= '0' && ch <= '9') {
                    if (idx1 < CODE_LENGTH) {
                        code1[idx1++] = ch;
                        code1[idx1] = '\0';
                    } else {
                        /* Overflow: reset */
                        idx1 = 0;
                        code1[0] = '\0';
                    }
                } else {
                    /* Non-digit: reset */
                    idx1 = 0;
                    code1[0] = '\0';
                }
            } else if (n < 0) {
                fprintf(stderr, "Warning: error reading %s (pigpio error %d).\n",
                        SERIAL1_DEV, n);
            }
        }

        /* Check if both codes are fully received and match */
        if (idx0 == CODE_LENGTH && idx1 == CODE_LENGTH) {
            if (codes_match(code0, code1)) {
                printf("Codes match: %s == %s\n", code0, code1);
                if (codes_match(code0, EXPECTED_CODE)) {
                    printf("Codes match expected code. Unlocking doors.\n");
                    if (unlock_doors() < 0) {
                        fprintf(stderr, "Error: failed to unlock doors.\n");
                    }
                } else {
                    printf("Codes do not match expected code. Access denied.\n");
                }
            } else {
                printf("Codes do not match: %s != %s\n", code0, code1);
            }
            /* Reset buffers for next round */
            idx0 = 0;
            idx1 = 0;
            code0[0] = '\0';
            code1[0] = '\0';
            start = time(NULL);
        }

        usleep(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

