#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static void log_message_with_errno(int priority, const char *message) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s: %s", message, strerror(errno));
    closelog();
}

static void sleep_ms(int milliseconds) {
    struct timespec ts;
    ts.tv_sec = milliseconds / 1000;
    ts.tv_nsec = (milliseconds % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_message_with_errno(LOG_ERR, "Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message_with_errno(LOG_ERR, "Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_message_with_errno(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message_with_errno(LOG_ERR, "Failed to get PIR line");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_message_with_errno(LOG_ERR, "Failed to get relay line");
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_message_with_errno(LOG_ERR, "Failed to request PIR line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_message_with_errno(LOG_ERR, "Failed to request relay line as output");
        goto cleanup;
    }

    log_message(LOG_INFO, "Door strike system started");

    time_t last_motion_time = 0;
    int relay_energized = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_message_with_errno(LOG_ERR, "Failed to read PIR sensor");
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        if (pir_value == 1) {
            time_t current_time = time(NULL);
            if (current_time == (time_t)-1) {
                log_message_with_errno(LOG_ERR, "Failed to get current time");
            } else {
                if (last_motion_time == 0) {
                    last_motion_time = current_time;
                }

                if (!relay_energized) {
                    if (gpiod_line_set_value(relay_line, 1) < 0) {
                        log_message_with_errno(LOG_ERR, "Failed to energize relay");
                    } else {
                        relay_energized = 1;
                        log_message(LOG_INFO, "Motion detected, energizing relay");
                    }
                }

                if (difftime(current_time, last_motion_time) >= FAILSAFE_TIMEOUT_S) {
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        log_message_with_errno(LOG_ERR, "Failed to de-energize relay in failsafe");
                    } else {
                        relay_energized = 0;
                        log_message(LOG_WARNING, "Failsafe triggered: PIR sensor stuck HIGH for too long");
                    }
                    last_motion_time = current_time;
                }
            }

            sleep_ms(STRIKE_DURATION_MS);
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_message_with_errno(LOG_ERR, "Failed to de-energize relay");
            } else {
                relay_energized = 0;
                log_message(LOG_INFO, "Relay de-energized");
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    log_message(LOG_INFO, "Shutting down door strike system");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

