#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON  0   /* active-LOW: LOW = ON  */
#define RELAY_OFF 1   /* active-LOW: HIGH = OFF */

#define ACTIVATION_DURATION 300  /* seconds (5 minutes) */
#define PAUSE_DURATION      60   /* seconds (1 minute)   */

#define TIMER_ID 0
#define TIMER_INTERVAL_MS 60000 /* 60 seconds */

static volatile sig_atomic_t g_running = 1;

/* Internal state machine */
typedef enum {
    STATE_IDLE,
    STATE_ACTIVATING,
    STATE_DEACTIVATING,
    STATE_PAUSING
} State;

static State g_state = STATE_IDLE;
static int   g_current_relay = 0; /* 0..3 */
static time_t g_action_start = 0;

static const int relay_gpios[4] = { RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO };

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: set a relay ON (LOW) or OFF (HIGH)                           */
/* ------------------------------------------------------------------ */
static int set_relay(int gpio, int state)
{
    int rc = gpioWrite(gpio, state);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed: %s", gpio, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helper: deactivate (OFF = HIGH) all relays                           */
/* ------------------------------------------------------------------ */
static void deactivate_all_relays(void)
{
    for (int i = 0; i < 4; i++) {
        set_relay(relay_gpios[i], RELAY_OFF);
    }
}

/* ------------------------------------------------------------------ */
/* Timer callback (fires every 60 seconds)                              */
/* ------------------------------------------------------------------ */
static void timer_callback(void *user_data)
{
    (void)user_data;

    time_t now = time(NULL);

    switch (g_state) {
    case STATE_IDLE:
        /* Start first activation */
        g_current_relay = 0;
        g_state = STATE_ACTIVATING;
        g_action_start = now;
        set_relay(relay_gpios[g_current_relay], RELAY_ON);
        syslog(LOG_INFO, "Relay %d activated (GPIO %d)",
               g_current_relay + 1, relay_gpios[g_current_relay]);
        break;

    case STATE_ACTIVATING:
        /* Check if activation duration elapsed */
        if (difftime(now, g_action_start) >= ACTIVATION_DURATION) {
            g_state = STATE_DEACTIVATING;
            g_action_start = now;
            set_relay(relay_gpios[g_current_relay], RELAY_OFF);
            syslog(LOG_INFO, "Relay %d deactivated (GPIO %d)",
                   g_current_relay + 1, relay_gpios[g_current_relay]);
        }
        break;

    case STATE_DEACTIVATING:
        /* Deactivation is instantaneous; now pause */
        g_state = STATE_PAUSING;
        g_action_start = now;
        syslog(LOG_INFO, "Pausing for %d seconds", PAUSE_DURATION);
        break;

    case STATE_PAUSING:
        /* Check if pause duration elapsed */
        if (difftime(now, g_action_start) >= PAUSE_DURATION) {
            /* Advance to next relay, loop back to 0 after 3 */
            g_current_relay = (g_current_relay + 1) % 4;
            g_state = STATE_ACTIVATING;
            g_action_start = now;
            set_relay(relay_gpios[g_current_relay], RELAY_ON);
            syslog(LOG_INFO, "Relay %d activated (GPIO %d)",
                   g_current_relay + 1, relay_gpios[g_current_relay]);
        }
        break;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    deactivate_all_relays();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIOs as outputs */
    for (int i = 0; i < 4; i++) {
        int gpio = relay_gpios[i];
        if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", gpio);
            cleanup();
            return EXIT_FAILURE;
        }
        /* Ensure all relays start OFF (HIGH) */
        if (set_relay(gpio, RELAY_OFF) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start 60-second timer */
    if (gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL_MS, timer_callback, NULL) < 0) {
        syslog(LOG_ERR, "gpioSetTimerFuncEx failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started (4 relays, 5 min activation, 1 min pause)");

    /* Main loop: sleep until signal received */
    while (g_running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

