#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR        0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_CONFIG 0x1C

#define I2C_BUS "/dev/i2c-1"
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L  /* 100 Hz */

typedef struct {
    float x, y, z;
} accel_data_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *sysfs_fp = NULL;
static accel_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static timer_t timer_id;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
