        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

