#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long elapsed_seconds(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec last_activation[NUM_RELAYS];
    int states[NUM_RELAYS] = {0};
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
        clock_gettime(CLOCK_MONOTONIC, &last_activation[i]);
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (elapsed_seconds(&last_activation[i], &now) >= prime_intervals[i]) {
                states[i] = !states[i];
                if (gpiod_line_set_value(lines[i], states[i]) < 0) {
                    fprintf(stderr, "Failed to set GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                printf("Relay %d (GPIO %u) toggled to %s\n", i + 1, relay_pins[i], states[i] ? "ON" : "OFF");
                clock_gettime(CLOCK_MONOTONIC, &last_activation[i]);
            }
        }

        struct timespec sleep_time = {0, 100000000}; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    printf("\nShutting down and turning off all relays...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

