#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity (LSB/deg/s) for default +/- 250 dps range
#define GYRO_SENSITIVITY 131.0f

// Threshold for angular velocity (degrees/second)
#define THRESHOLD 50.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(const char *device, int addr);
int read_register(int fd, uint8_t reg, uint8_t *value);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, gyro_data_t *data);
float calculate_angular_velocity(gyro_data_t data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(gyro_data_t data, float threshold);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int init_i2c(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a single register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    uint8_t reg = GYRO_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to calculate angular velocity magnitude
float calculate_angular_velocity(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check if the angular velocity exceeds the threshold
void check_threshold(gyro_data_t data, float threshold) {
    float angular_velocity = calculate_angular_velocity(data);
    if (angular_velocity > threshold) {
        printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", angular_velocity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c("/dev/i2c-1", MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify sensor identity
    uint8_t who_am_i = 0;
    if (read_register(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        cleanup();
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned 0x%02X (expected 0x68)\n", who_am_i);
        cleanup();
        return 1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        cleanup();
        return 1;
    }

    // Allow sensor to stabilize
    usleep(100000); // 100ms

    // Main loop
    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            add_to_buffer(&gyro_buffer, gyro_data);
            check_threshold(gyro_data, THRESHOLD);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");

    return 0;
}

