/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (GPIO14 TXD, GPIO15 RXD), 9600 baud
 * Logs JSON to co2_log.json every 5 s and prints to stdout.
 * Errors are logged to co2_error.log.
 * Compile: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_INTERVAL_S  5
#define READ_TIMEOUT_US  1000000   /* 1 s */
#define READ_RETRY_US    10000     /* 10 ms between retries */
#define RESPONSE_LEN     9
#define MHZ19B_CMD_LEN   9

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof tbuf, "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_err_fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes from the UART, with a timeout.                 */
/* Returns 0 on success, -1 on timeout or error.                       */
/* ------------------------------------------------------------------ */
static int read_response(uint8_t *buf, int n)
{
    int total = 0;
    uint32_t deadline = gpioTick() + READ_TIMEOUT_US;

    while (total < n) {
        if (!g_running) return -1;

        int avail = serDataAvailable(g_uart_fd);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail == 0) {
            if (gpioTick() >= deadline) {
                log_error("Timeout waiting for UART data");
                return -1;
            }
            gpioDelay(READ_RETRY_US);
            continue;
        }

        int to_read = (avail < (n - total)) ? avail : (n - total);
        int got = serRead(g_uart_fd, (char *)(buf + total), to_read);
        if (got < 0) {
            log_error("serRead failed");
            return -1;
        }
        total += got;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send the 9-byte MH-Z19B read command.                               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int send_read_command(void)
{
    /* 0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79 */
    uint8_t cmd[MHZ19B_CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00,
                                   0x00, 0x00, 0x00, 0x79};
    int rc = serWrite(g_uart_fd, (char *)cmd, MHZ19B_CMD_LEN);
    if (rc != MHZ19B_CMD_LEN) {
        log_error("serWrite failed for read command");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read CO2 from the MH-Z19B.                                          */
/* Returns 0 on success (ppm stored in *out), -1 on error.            */
/* ------------------------------------------------------------------ */
static int read_co2(int *out)
{
    if (send_read_command() != 0)
        return -1;

    /* MH-Z19B needs ~40 ms after the command before the response is
       valid; 100 ms is a safe margin. */
    gpioDelay(100000);

    uint8_t resp[RESPONSE_LEN];
    if (read_response(resp, RESPONSE_LEN) != 0)
        return -1;

    /* Validate checksum: sum of bytes 1..7, inverted + 1 == byte 8 */
    uint8_t sum = 0;
    for (int i = 1; i < RESPONSE_LEN - 1; i++)
        sum += resp[i];
    sum = (uint8_t)~sum + 1;
    if (sum != resp[RESPONSE_LEN - 1]) {
        log_error("MH-Z19B checksum mismatch");
        return -1;
    }

    *out = (resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(int co2_ppm, int error_flag)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof tbuf, "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s.%03ld\",\"co2_ppm\":%d,\"error\":%d}\n",
            tbuf, ts.tv_nsec / 1000000L, co2_ppm, error_flag);
    fflush(g_log_fp);

    printf("{\"timestamp\":\"%s.%03ld\",\"co2_ppm\":%d,\"error\":%d}\n",
           tbuf, ts.tv_nsec / 1000000L, co2_ppm, error_flag);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        serClose(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp)  { fclose(g_log_fp);  g_log_fp  = NULL; }
    if (g_err_fp)  { fclose(g_err_fp);  g_err_fp  = NULL; }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log files --------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open UART -------------------------------------------------- */
    g_uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_fd < 0) {
        log_error("serOpen failed");
        fprintf(stderr, "serOpen failed (fd=%d)\n", g_uart_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitor started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL_S);
    fflush(stdout);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int co2_ppm = 0;
        int error_flag = 0;

        if (read_co2(&co2_ppm) != 0) {
            error_flag = 1;
            co2_ppm = 0;
        }

        log_data(co2_ppm, error_flag);

        /* Sleep READ_INTERVAL_S, but wake early on signal. */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

