#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES 0x10
#define BH1750_CONV_MS 120

#define LUX_THRESHOLD_1 50
#define LUX_THRESHOLD_2 150
#define LUX_THRESHOLD_3 300

#define LOG_FILE "lighting_log.txt"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_read(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CONT_HRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relays(struct gpiod_line *r, struct gpiod_line *g, struct gpiod_line *b, float lux) {
    int r_val = 0, g_val = 0, b_val = 0;
    if (lux < LUX_THRESHOLD_1) {
        r_val = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        g_val = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        b_val = 1;
    } else {
        r_val = g_val = b_val = 1;
    }
    gpiod_line_set_value(r, r_val);
    gpiod_line_set_value(g, g_val);
    gpiod_line_set_value(b, b_val);
}

static void log_data(FILE *fp, float lux, int r, int g, int b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, R: %d, G: %d, B: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, r, g, b);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *r = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *g = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *b = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!r || !g || !b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(r, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(g, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(b, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        gpiod_line_release(r);
        gpiod_line_release(g);
        gpiod_line_release(b);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpiod_line_release(r);
        gpiod_line_release(g);
        gpiod_line_release(b);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        gpiod_line_release(r);
        gpiod_line_release(g);
        gpiod_line_release(b);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        if (bh1750_read(i2c_fd, &lux) == 0) {
            int r_val = gpiod_line_get_value(r);
            int g_val = gpiod_line_get_value(g);
            int b_val = gpiod_line_get_value(b);
            control_relays(r, g, b, lux);
            log_data(log_fp, lux, r_val, g_val, b_val);
        } else {
            fprintf(stderr, "Sensor read error; relays unchanged.\n");
        }
        sleep(1);
    }

    gpiod_line_set_value(r, 0);
    gpiod_line_set_value(g, 0);
    gpiod_line_set_value(b, 0);
    gpiod_line_release(r);
    gpiod_line_release(g);
    gpiod_line_release(b);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_fp);
    return 0;
}

