#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQ 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int check_gpio(int rc, const char *what) {
    if (rc < 0) {
        fprintf(stderr, "pigpio error: %s failed (rc=%d)\n", what, rc);
        return -1;
    }
    return 0;
}

static int set_motor_pwm(int in1, int in2, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (check_gpio(gpioPWM(in2, duty), "gpioPWM") < 0) return -1;
    return 0;
}

static int motor_stop(int in1, int in2) {
    if (check_gpio(gpioWrite(in1, 0), "gpioWrite in1") < 0) return -1;
    if (check_gpio(gpioWrite(in2, 0), "gpioWrite in2") < 0) return -1;
    return 0;
}

static int motor_forward(int in1, int in2, int duty) {
    if (check_gpio(gpioWrite(in1, 1), "gpioWrite in1") < 0) return -1;
    return set_motor_pwm(in1, in2, duty);
}

static int motor_backward(int in1, int in2, int duty) {
    if (check_gpio(gpioWrite(in1, 0), "gpioWrite in1") < 0) return -1;
    return set_motor_pwm(in1, in2, duty);
}

static int control_motor(int in1, int in2, int distance) {
    int duty = 255 - (distance - 10) * 2;
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (distance < 50) {
        return motor_forward(in1, in2, duty);
    } else {
        return motor_backward(in1, in2, duty);
    }
}

static void cleanup(void) {
    motor_stop(MOTOR_A_IN1, MOTOR_A_IN2);
    motor_stop(MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    if (check_gpio(gpioSetMode(MOTOR_A_IN1, PI_OUTPUT), "gpioSetMode A_IN1") < 0 ||
        check_gpio(gpioSetMode(MOTOR_A_IN2, PI_OUTPUT), "gpioSetMode A_IN2") < 0 ||
        check_gpio(gpioSetMode(MOTOR_B_IN3, PI_OUTPUT), "gpioSetMode B_IN3") < 0 ||
        check_gpio(gpioSetMode(MOTOR_B_IN4, PI_OUTPUT), "gpioSetMode B_IN4") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (check_gpio(gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQ), "gpioSetPWMfrequency A") < 0 ||
        check_gpio(gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQ), "gpioSetPWMfrequency B") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (check_gpio(gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE), "gpioSetPWMrange A") < 0 ||
        check_gpio(gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE), "gpioSetPWMrange B") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int dist_a = rand() % 91 + 10;
        int dist_b = rand() % 91 + 10;

        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, dist_a) < 0 ||
            control_motor(MOTOR_B_IN3, MOTOR_B_IN4, dist_b) < 0) {
            fprintf(stderr, "Motor control error, stopping\n");
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

