#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_SCALE 16384.0
#define GYRO_SCALE 131.0
#define PWM_CHIP "/sys/class/pwm/pwmchip2"
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_sensor_data(int fd, float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    int16_t raw_ax, raw_ay, raw_az, raw_gx, raw_gy, raw_gz;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, &raw_ax) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 2, &raw_ay) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 4, &raw_az) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_XOUT_H, &raw_gx) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_XOUT_H + 2, &raw_gy) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_XOUT_H + 4, &raw_gz) < 0) return -1;
    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;
    return 0;
}

static void calculate_tilt(float ax, float ay, float az, float *pitch, float *roll) {
    *pitch = atan2f(ax, sqrtf(ay * ay + az * az)) * 180.0 / M_PI;
    *roll = atan2f(-ay, az) * 180.0 / M_PI;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty_ns = (int)((float)angle / 180.0 * PWM_PERIOD_NS);
    char path[128];
    snprintf(path, sizeof(path), "%s/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", duty_ns);
    fclose(fp);
    return 0;
}

