    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); fclose(log_fp); return 1; }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE failed: %s\n", strerror(errno));
            retries++;
            usleep(100000 << retries);
            continue;
        }
        if (init_mpu6050(i2c_fd) == 0) break;
        retries++;
        usleep(100000 << retries);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to init MPU6050 after %d retries.\n", MAX_RETRIES);
        close(i2c_fd); fclose(log_fp); return 1;
    }

    snprintf(PWM_CHIP, sizeof(PWM_CHIP), "%s/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *en = fopen(PWM_CHIP, "w");
    if (!en) { perror("fopen pwm enable"); close(i2c_fd); fclose(log_fp); return 1; }
    fprintf(en, "1");
    fclose(en);

    snprintf(PWM_CHIP, sizeof(PWM_CHIP), "%s/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *per = fopen(PWM_CHIP, "w");
    if (!per) { perror("fopen pwm period"); close(i2c_fd); fclose(log_fp); return 1; }
    fprintf(per, "%d", PWM_PERIOD_NS);
    fclose(per);

    while (running) {
        float ax, ay, az, gx, gy, gz;
