#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t file_changed = 0;

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to initialise GPIO %d to LOW\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_schedule(const char *filename, ScheduleEntry *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &schedule[count].hour, &schedule[count].minute, &schedule[count].second,
                   &schedule[count].relay_number, &schedule[count].state) == 5) {
            if (schedule[count].relay_number < 1 || schedule[count].relay_number > NUM_RELAYS ||
                schedule[count].state < 0 || schedule[count].state > 1) {
                fprintf(stderr, "Invalid schedule entry (relay or state out of range): %s", line);
                fclose(fp);
                return -1;
            }
            count++;
        } else {
            fprintf(stderr, "Invalid schedule format: %s", line);
        }
    }
    fclose(fp);
    return count;
}

static void set_relay(int relay_number, int state) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
    }
}

static void fade_lamp(int relay_number, int target_brightness) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pin);
        return;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pin);
        return;
    }
    int current_brightness = gpioGetPWMdutycycle(pin);
    if (current_brightness < 0) current_brightness = 0;
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int steps = abs(target_brightness - current_brightness);
    int delay_us = (FADE_DURATION * 1000000) / (steps * PWM_RANGE);
    if (delay_us < 1000) delay_us = 1000;
    for (int i = 0; i < steps; i++) {
        if (!running) break;
        current_brightness += step;
        if (gpioPWM(pin, current_brightness) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", pin);
            break;
        }
        usleep(delay_us);
    }
    if (running) {
        gpioPWM(pin, target_brightness);
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }
    if (initialize_gpio() < 0) {
        return 1;
    }
    ScheduleEntry schedule[100];
    int num_entries = read_schedule(SCHEDULE_FILE, schedule, 100);
    if (num_entries < 0) {
        cleanup();
        return 1;
    }
    time_t last_check = 0;
    while (running) {
        time_t now = time(NULL);
        if (now != last_check) {
            last_check = now;
            struct tm *tm_info = localtime(&now);
            if (!tm_info) {
                fprintf(stderr, "localtime failed\n");
                continue;
            }
            int current_hour = tm_info->tm_hour;
            int current_minute = tm_info->tm_min;
            int current_second = tm_info->tm_sec;
            for (int i = 0; i < num_entries; i++) {
                if (current_hour == schedule[i].hour &&
                    current_minute == schedule[i].minute &&
                    current_second == schedule[i].second) {
                    set_relay(schedule[i].relay_number, schedule[i].state);
                    if (schedule[i].state == 1) {
                        fade_lamp(schedule[i].relay_number, 100);
                    } else {
                        fade_lamp(schedule[i].relay_number, 0);
                    }
                }
            }
        }
        usleep(100000);
    }
    cleanup();
    return 0;
}

