#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(float r, float g, float b) {
    if (r < 0.0f) r = 0.0f; if (r > 1.0f) r = 1.0f;
    if (g < 0.0f) g = 0.0f; if (g > 1.0f) g = 1.0f;
    if (b < 0.0f) b = 0.0f; if (b > 1.0f) b = 1.0f;

    int rp = (int)(r * PWM_RANGE);
    int gp = (int)(g * PWM_RANGE);
    int bp = (int)(b * PWM_RANGE);

    if (gpioPWM(RED_PIN,   rp) < 0) return -1;
    if (gpioPWM(GREEN_PIN, gp) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  bp) < 0) return -1;
    return 0;
}

static void led_off(void) {
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Color-based proximity alert simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        double t = (double)clock() / CLOCKS_PER_SEC;
        float proximity = (float)(sin(t) * 0.5 + 0.5);

        float r, g, b;
        if (proximity < 0.33f) {
            r = 1.0f; g = proximity / 0.33f; b = 0.0f;
        } else if (proximity < 0.66f) {
            r = (0.66f - proximity) / 0.33f; g = 1.0f; b = 0.0f;
        } else {
            r = 0.0f; g = 0.0f; b = (proximity - 0.66f) / 0.33f;
        }

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Error: failed to set LED color.\n");
            break;
        }

        time_sleep(0.05);
    }

    led_off();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

