    *gx = (float)raw_x / GYRO_SENS_LSB;
    *gy = (float)raw_y / GYRO_SENS_LSB;
    *gz = (float)raw_z / GYRO_SENS_LSB;
    return 0;
}

static void log_data(float gx, float gy, float gz) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, gx, gy, gz);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.3f,%.3f,%.3f\n", gx, gy, gz);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        close(fd);
        return 1;
    }

    printf("MPU-6050 initialized. Logging to %s every 100 ms. Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro(fd, &gx, &gy, &gz) == 0) {
            log_data(gx, gy, gz);
        } else {
            fprintf(stderr, "Gyro read failed; continuing.\n");
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

