#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define PWM_DUTY_50 500000  /* 50% of 1,000,000 */

/* Musical note frequencies (Hz) */
#define NOTE_C4 262
#define NOTE_D4 294
#define NOTE_E4 330
#define NOTE_F4 349
#define NOTE_G4 392
#define NOTE_A4 440
#define NOTE_B4 494
#define NOTE_C5 523

/* Melody: note frequency, duration in milliseconds */
typedef struct {
    int frequency;
    int duration_ms;
} Note;

static const Note melody[] = {
    {NOTE_C4, 500}, {NOTE_D4, 500}, {NOTE_E4, 500}, {NOTE_F4, 500},
    {NOTE_G4, 500}, {NOTE_A4, 500}, {NOTE_B4, 500}, {NOTE_C5, 500}
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_press_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) {  /* Only act on falling edge (button press) */
        uint32_t elapsed = tick - last_press_tick;
        if (elapsed >= DEBOUNCE_US) {
            button_pressed = 1;
            last_press_tick = tick;
        }
    }
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) {
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioDelay(duration_ms * 1000);
        return 0;
    }

    if (gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_50) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for %d Hz\n", frequency);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM stop failed\n");
        return -1;
    }

    return 0;
}

static void play_melody(void) {
    for (int i = 0; i < melody_length; i++) {
        if (!running) break;
        if (play_tone(melody[i].frequency, melody[i].duration_ms) != 0) {
            fprintf(stderr, "Melody playback interrupted at note %d\n", i);
            break;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pin as input with internal pull-up */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin for hardware PWM */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR for button press (falling edge) */
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical Doorbell ready. Press the button (GPIO17) to play the melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            play_melody();
            printf("Melody finished.\n");
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

