#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define THRESHOLD 3
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    return 0;
}

static int log_event(FILE *log_file, const char *timestamp, int value) {
    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void check_earthquake(int value, int *window, int *idx, int *count) {
    window[*idx] = value;
    *idx = (*idx + 1) % WINDOW_SIZE;
    if (value == 1) {
        (*count)++;
    } else {
        (*count)--;
    }
    if (*count >= THRESHOLD) {
        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) == 0) {
            printf("EARTHQUAKE ALERT! Timestamp: %s\n", ts);
            fflush(stdout);
        }
        *count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) window[i] = 0;
        *idx = 0;
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    if (argc > 1) {
        long t = strtol(argv[1], NULL, 10);
        if (t > 0 && t <= 10000) {
            timeout_ms = (int)t;
        } else {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "sw420-vibration") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int window_idx = 0;
    int high_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout %d ms)...\n",
           GPIO_LINE_OFFSET, timeout_ms);
    fflush(stdout);

    while (program_running) {
        struct timespec ts = { timeout_ms / 1000, (timeout_ms % 1000) * 1000000L };
        int ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        int value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;

        char timestamp[32];
        if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
            if (log_event(log_file, timestamp, value) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        check_earthquake(value, window, &window_idx, &high_count);
    }

    printf("\nExiting gracefully...\n");
    if (fclose(log_file) != 0) {
        perror("fclose log");
    }
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

