#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* LSM303DLHC Magnetometer I2C address (7-bit) */
#define LSM303_ADDRESS 0x1E

/* LSM303DLHC Magnetometer register addresses */
#define CRA_REG_M 0x00
#define MR_REG_M  0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

/* Hard-iron calibration offsets (example values) */
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

/* Global file descriptors for cleanup */
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Write a single byte to an 8-bit register using SMBus ioctl */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE failed: %s\n", strerror(errno));
        return -1;
    }
