        fprintf(stderr, "Error: I2C_SMBUS write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register using SMBus ioctl */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE failed: %s\n", strerror(errno));
        return -1;
    }
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args = {
