/*
 * Automated Plant Watering System - Raspberry Pi Zero W
 * Library: pigpio (libpigpio)
 *
 * Hardware:
 *   - SG90 servo for water valve on GPIO17 (physical pin 11)
 *   - SG90 servo for directional nozzle on GPIO18 (physical pin 12)
 *
 * Servo pulse-width range (SG90): ~500 us (0 deg) .. ~2500 us (180 deg)
 *   Valve:   0 deg = closed, 90 deg = open
 *   Nozzle:  0, 45, 90, 135, 180 deg
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO        17
#define NOZZLE_GPIO       18

#define MOISTURE_THRESHOLD 50
#define NUM_MOISTURE_READINGS 5
#define NUM_NOZZLE_ANGLES   5

#define VALVE_CLOSED_US   500   /* 0 deg  */
#define VALVE_OPEN_US     1500  /* 90 deg */
#define NOZZLE_ANGLES_US  {500, 1000, 1500, 2000, 2500}

#define WATERING_HOLD_US  5000000   /* 5 s  */
#define CYCLE_DELAY_US    5000000   /* 5 s  */
#define NOZZLE_STEP_US    2000000   /* 2 s  */
#define SERVO_RETRY_COUNT 3
#define SERVO_RETRY_DELAY_US 100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Set a servo pulse width with retries. Returns 0 on success, -1 on failure.
 * gpioServo returns 0 on success, non-zero on error.
 */
static int set_servo_retry(int gpio, int pulsewidth)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        int rc = gpioServo(gpio, pulsewidth);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "Warning: gpioServo(gpio=%d, pw=%d) failed (rc=%d), attempt %d/%d\n",
                gpio, pulsewidth, rc, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1)
            gpioDelay(SERVO_RETRY_DELAY_US);
    }
    return -1;
}

static void stop_servos(void)
{
    /* gpioServo with pulsewidth 0 stops PWM on the pin */
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
}

static void cleanup(void)
{
    stop_servos();
    gpioTerminate();
}

/*
 * Watering cycle: open valve, sweep nozzle, hold, close valve.
 * Returns 0 on success, -1 if valve open failed (abort cycle).
 */
static int water_plant(void)
{
    int nozzle_angles_us[NUM_NOZZLE_ANGLES] = NOZZLE_ANGLES_US;

    printf("Watering plant...\n");

    /* Open valve */
    if (set_servo_retry(VALVE_GPIO, VALVE_OPEN_US) != 0) {
        fprintf(stderr, "Critical: failed to open valve on GPIO%d\n", VALVE_GPIO);
        return -1;
    }
    printf("Valve opened (90 deg)\n");

    /* Sweep nozzle */
    for (int i = 0; i < NUM_NOZZLE_ANGLES && g_running; i++) {
        int angle_us = nozzle_angles_us[i];
        printf("Setting nozzle to %d us (%.0f deg)\n",
               angle_us, (angle_us - 500.0) / 10.0);

        if (set_servo_retry(NOZZLE_GPIO, angle_us) != 0) {
            fprintf(stderr,
                    "Error: failed to set nozzle to %d us, skipping angle\n",
                    angle_us);
            continue;
        }

        /* Hold at this angle for 2 s (interruptible) */
        for (int elapsed = 0; elapsed < NOZZLE_STEP_US && g_running;
             elapsed += 100000) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Hold water for 5 s (interruptible) */
    for (int elapsed = 0; elapsed < WATERING_HOLD_US && g_running;
         elapsed += 100000) {
        gpioDelay(100000);
    }

    /* Close valve */
    if (set_servo_retry(VALVE_GPIO, VALVE_CLOSED_US) != 0) {
        fprintf(stderr, "Warning: failed to close valve on GPIO%d\n", VALVE_GPIO);
    } else {
        printf("Valve closed (0 deg)\n");
    }

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servos are stopped at start */
    stop_servos();

    /* Simulated moisture readings */
    int moisture_readings[NUM_MOISTURE_READINGS] = {20, 40, 60, 80, 100};
    int reading_index = 0;

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = moisture_readings[reading_index];
        reading_index = (reading_index + 1) % NUM_MOISTURE_READINGS;

        printf("Moisture reading: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d%% < %d%%). Watering...\n",
                   moisture, MOISTURE_THRESHOLD);
            if (water_plant() != 0) {
                fprintf(stderr, "Watering cycle aborted due to valve failure.\n");
            }
        } else {
            printf("Moisture above threshold (%d%% >= %d%%). Skipping watering.\n",
                   moisture, MOISTURE_THRESHOLD);
        }

        /* Wait 5 s between cycles (interruptible) */
        for (int elapsed = 0; elapsed < CYCLE_DELAY_US && g_running;
             elapsed += 100000) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

