#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000
#define MIN_GUARD_US 60000
#define TRIGGER_PULSE_US 10
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (trig_line) {
        gpiod_line_release(trig_line);
        trig_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input_flags(echo_line, "hcsr04-echo",
            GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void trigger_pulse(void) {
    gpiod_line_set_value(trig_line, 1);
    usleep(TRIGGER_PULSE_US);
    gpiod_line_set_value(trig_line, 0);
}

static long measure_pulse_us(void) {
    struct timespec t0, t1;
    long elapsed;

    clock_gettime(CLOCK_MONOTONIC, &t0);

    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed = (t1.tv_sec - t0.tv_sec) * 1000000L + (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed > TIMEOUT_US) return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed = (t1.tv_sec - t0.tv_sec) * 1000000L + (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed > TIMEOUT_US) return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &t1);
    return (t1.tv_sec - t0.tv_sec) * 1000000L + (t1.tv_nsec - t0.tv_nsec) / 1000L;
}

