#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define DIST_THRESHOLD 50   /* cm */
#define POLL_MS        100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET          0x0000
#define REG_SYSTEM_MODE_START   0x0080
#define REG_GPIO_HV_MUX_CTRL    0x0030
#define REG_INT_STATUS          0x0044
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE_MSB 0x0096
#define REG_RESULT_DISTANCE_LSB 0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single data byte. */
static int vl53l1x_write8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Write a 16-bit register address, then read `len` bytes. */
static int vl53l1x_read(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (vl53l1x_write8(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start continuous ranging (bit 0 = 1) */
    if (vl53l1x_write8(handle, REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    /* Check data-ready interrupt status (bit 0) */
    if (vl53l1x_read(handle, REG_INT_STATUS, &status, 1) != 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* not ready yet */
    }

    /* Read 16-bit distance (big-endian) */
    if (vl53l1x_read(handle, REG_RESULT_DISTANCE_MSB, data, 2) != 0) {
        fprintf(stderr, "Error: failed to read distance registers\n");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt by writing 0x01 to interrupt status */
    if (vl53l1x_write8(handle, REG_INT_STATUS, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt status\n");
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) - sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            printf("Distance: %u cm\n", distance);
            if (distance <= DIST_THRESHOLD) {
                gpioWrite(RELAY_PIN, 1);
                printf("Door OPEN\n");
            } else {
                gpioWrite(RELAY_PIN, 0);
                printf("Door CLOSED\n");
            }
        } else if (rc < 0) {
            /* Bus error: ensure relay is off for safety */
            gpioWrite(RELAY_PIN, 0);
        }

        gpioDelay(POLL_MS * 1000);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

