#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) == -1) {
        fprintf(stderr, "Failed to wake up MPU-6050 (sensor may be absent or bus error)\n");
        goto cleanup;
    }
    usleep(100000);

    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) == -1) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        goto cleanup;
    }

    printf("MPU-6050 initialized. Reading gyroscope data...\n");

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) == -1) {
            fprintf(stderr, "Failed to read gyroscope data, retrying...\n");
            usleep(100000);
            continue;
        }

        int16_t gyro_x = combine_bytes(buf[0], buf[1]);
        int16_t gyro_y = combine_bytes(buf[2], buf[3]);
        int16_t gyro_z = combine_bytes(buf[4], buf[5]);

        float gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
        float gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
        float gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;

        printf("Gyro X: %7.2f dps | Gyro Y: %7.2f dps | Gyro Z: %7.2f dps\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps);

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

