#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_DURATION 5
#define WATERING_INTERVAL 86400
#define POLL_INTERVAL 60
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static const char *relay_names[NUM_RELAYS] = {"Relay 1", "Relay 2", "Relay 3", "Relay 4"};

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_watering_cycle(const char *relay_name) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Watered %s\n", timestamp, relay_name) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int set_all_relays(int value) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], value) < 0) {
            perror("gpiod_line_set_value");
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    if (chip) {
        set_all_relays(1);
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
                lines[i] = NULL;
            }
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    time_t last_watering_time = 0;
    if (time(&last_watering_time) == (time_t)-1) {
        perror("time");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Automated Plant Watering System started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t current_time;
        if (time(&current_time) == (time_t)-1) {
            perror("time");
            break;
        }

        if (difftime(current_time, last_watering_time) >= WATERING_INTERVAL) {
            for (int i = 0; i < NUM_RELAYS && running; i++) {
                printf("Activating %s (pin %u)...\n", relay_names[i], relay_pins[i]);
                if (gpiod_line_set_value(lines[i], 0) < 0) {
                    perror("gpiod_line_set_value");
                    continue;
                }
                if (log_watering_cycle(relay_names[i]) < 0) {
                    fprintf(stderr, "Failed to log watering cycle for %s\n", relay_names[i]);
                }
                for (int s = 0; s < WATERING_DURATION && running; s++) {
                    sleep(1);
                }
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    perror("gpiod_line_set_value");
                }
                printf("%s deactivated.\n", relay_names[i]);
            }
            if (time(&last_watering_time) == (time_t)-1) {
                perror("time");
                break;
            }
        }

        for (int s = 0; s < POLL_INTERVAL && running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

