#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_ID 0x68
#define PWR_MGMT_1          0x6B
#define SMPLRT_DIV          0x19
#define GYRO_CONFIG         0x1B
#define GYRO_XOUT_H         0x43

#define I2C_BUS             1
#define LED_GPIO            17
#define THRESHOLD_DPS       250.0f
#define SAMPLE_PERIOD_US    50000   /* 50 ms -> 20 Hz */
#define MAX_REINIT_ATTEMPTS 3
#define BUFFER_SIZE         100

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float           x;
    float           y;
    float           z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int            i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  init_mpu6050(int handle);
static int  read_gyro_data(int handle, float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buf, gyro_data_t d);
static void check_threshold(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- MPU-6050 initialisation ---- */
static int init_mpu6050(int handle)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate = 1 kHz / (1 + SMPLRT_DIV) -> 100 Hz with 9 */
    if (i2cWriteByteData(handle, SMPLRT_DIV, 0x09) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Gyro full-scale range: ±250 deg/s (FS_SEL=0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I\n");
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_ID) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_ID);
        return -1;
    }

    return 0;
}

/* ---- Read 6-byte gyro block ---- */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* ±250 deg/s -> 131 LSB per deg/s */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(circular_buffer_t *buf, gyro_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

/* ---- Threshold check ---- */
static void check_threshold(float x, float y, float z)
{
    if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS ||
        fabsf(z) > THRESHOLD_DPS) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    int reinit_attempts = 0;
    gyro_data_t sample;

    while (!terminate) {
        if (read_gyro_data(i2c_handle, &sample.x, &sample.y, &sample.z) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &sample.timestamp);
            add_to_buffer(&gyro_buffer, sample);
            check_threshold(sample.x, sample.y, sample.z);
            reinit_attempts = 0;
        } else {
