                    reinit_attempts, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: max reinit attempts reached, exiting\n");
                break;
            }
            /* Attempt re-initialisation */
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
