#define GYRO_Z_REG      0x47
#define GYRO_SENSITIVITY 131.0f
#define GYRO_THRESHOLD   200.0f

#define BUFFER_SIZE     64

typedef struct {
    time_t timestamp;
    float  x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static volatile sig_atomic_t program_running = 1;

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
