    if (spi_transfer(tx, rx, 2) < 0)
        return -1;

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_gyro_axis(GYRO_X_REG, &raw_x) < 0) return -1;
