    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus 1 at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int16_t ax, ay, az;
        if (read_accel(&ax, &ay, &az) == 0) {
            double roll = atan2((double)ay, (double)az) * 180.0 / M_PI;
            double pitch = atan2(-(double)ax, sqrt((double)ay * ay + (double)az * az)) * 180.0 / M_PI;
            log_tilt(roll, pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
            if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

