#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

#define REG_X_RATE  0x02
#define REG_Y_RATE  0x04
#define READ_BIT    0x80
#define SENSITIVITY 200.0f   /* LSB per deg/s */
#define SAMPLE_US  10000     /* 10 ms -> ~100 Hz */
#define MAX_REINIT  3

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read one 16-bit register: send address|0x80 + dummy, response is second byte. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2] = { (char)(reg | READ_BIT), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)((uint8_t)rx[1]);
    return 0;
}

static int init_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    fp = fopen("gyro_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(fp, "timestamp_s,X_raw,Y_raw\n");

    int reinit_count = 0;

    while (!terminate) {
        int16_t x_raw = 0, y_raw = 0;
        int err = 0;

        if (read_register(REG_X_RATE, &x_raw) != 0) err = 1;
        if (!err && read_register(REG_Y_RATE, &y_raw) != 0) err = 1;

        if (err) {
            fprintf(stderr, "Read error, reinit attempt %d/%d\n", reinit_count + 1, MAX_REINIT);
            if (reinit_count < MAX_REINIT) {
                if (init_spi() == 0) {
                    reinit_count = 0;
                } else {
                    reinit_count++;
                }
            } else {
                fprintf(stderr, "Max reinit reached, exiting\n");
                break;
            }
            gpioDelay(SAMPLE_US);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            break;
        }

        fprintf(fp, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000, x_raw, y_raw);
        fflush(fp);

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

