#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_MODE 0

/* GPIO Pins */
#define LED_PIN 17

/* Gyroscope Sensitivity (LSB/deg/s) */
#define GYRO_SENSITIVITY 200.0

/* Angular Velocity Threshold (deg/s) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0

/* Circular Buffer Configuration */
#define BUFFER_SIZE 100

/* Data Structure for Circular Buffer */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

/* Circular Buffer Structure */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* Global Variables */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* Function Prototypes */
static int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
static int read_gyro_data(int handle, float *angular_velocity);
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/* SPI Read Register Function */
static int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[32];
    char rx_buf[32];

    if (len > (int)sizeof(tx_buf) - 1) {
        fprintf(stderr, "Error: SPI read length exceeds buffer size.\n");
        return -1;
    }

    /* Set MSB for read operation */
    tx_buf[0] = reg | 0x80;
    memset(&tx_buf[1], 0x00, len);

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "Error: SPI read failed (expected %d bytes, got %d).\n", len + 1, result);
        return -1;
    }

    memcpy(data, &rx_buf[1], len);
    return 0;
}

/* Read Gyro Data Function */
static int read_gyro_data(int handle, float *angular_velocity) {
    uint8_t xl, xh;
    int16_t raw_data;

    if (spi_read_register(handle, ADXRS290_REG_RATE_XL, &xl, 1) != 0) {
        return -1;
    }
    if (spi_read_register(handle, ADXRS290_REG_RATE_XH, &xh, 1) != 0) {
        return -1;
    }

    raw_data = (int16_t)((xh << 8) | xl);
    *angular_velocity = (float)raw_data / GYRO_SENSITIVITY;

    return 0;
}

/* Add Data to Circular Buffer Function */
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data) {
    pthread_mutex_lock(&cb->mutex);

    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;

    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }

    pthread_mutex_unlock(&cb->mutex);
}

/* Signal Handler Function */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup Function */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize Circular Buffer */
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float angular_velocity;

        if (read_gyro_data(spi_handle, &angular_velocity) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);

            gyro_data_t data;
            data.timestamp = ts;
            data.angular_velocity = angular_velocity;

            add_to_buffer(&gyro_buffer, data);

            /* Check threshold and control LED */
            if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }

            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data.\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    pthread_mutex_destroy(&gyro_buffer.mutex);
    cleanup();

    printf("Gyroscope monitoring stopped.\n");
    return EXIT_SUCCESS;
}

