#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQ 100

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int set_lamp_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d (brightness=%d)\n", gpio, brightness);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_seconds) {
    if (duration_seconds <= 0) {
        fprintf(stderr, "Error: fade duration must be positive\n");
        return -1;
    }

    int steps = duration_seconds * 10;
    int delay_us = (duration_seconds * 1000000) / steps;

    for (int brightness = PWM_RANGE; brightness >= 0; brightness--) {
        if (g_terminate) {
            fprintf(stderr, "Interrupted: turning off lamp on GPIO %d\n", gpio);
            set_lamp_brightness(gpio, 0);
            return -1;
        }
        if (set_lamp_brightness(gpio, brightness) != 0) {
            return -1;
        }
        usleep(delay_us);
    }

    return 0;
}

static void cleanup(void) {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: fade duration must be between 1 and 3600 seconds\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Sunset Simulator started. Fading duration: %d seconds\n", duration);
    printf("Lamp 1 on GPIO %d, Lamp 2 on GPIO %d, Lamp 3 on GPIO %d\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    printf("Press Ctrl+C to interrupt.\n");

    if (fade_lamp(LAMP1_GPIO, duration) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (g_terminate) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (fade_lamp(LAMP2_GPIO, duration) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (g_terminate) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (fade_lamp(LAMP3_GPIO, duration) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("All lamps faded out. Goodnight!\n");
    cleanup();
    return EXIT_SUCCESS;
}

