#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY_MS 100
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X", reg, value);
        log_message(msg);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, 0x80, 0x63) != 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(handle, 0x5E, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, 0x5D, 0x01) != 0) return -1;
    if (mpr121_write_reg(handle, 0x41, TOUCH_THRESHOLD) != 0) return -1;
    if (mpr121_write_reg(handle, 0x42, RELEASE_THRESHOLD) != 0) return -1;
    if (mpr121_write_reg(handle, 0x5B, 0x21) != 0) return -1;
    if (mpr121_write_reg(handle, 0x5C, 0x0D) != 0) return -1;
    if (mpr121_write_reg(handle, 0x5E, 0x0D) != 0) return -1;
    return 0;
}

static int read_touch_status(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("I2C read failed for touch status");
        return -1;
    }
    return ((buf[1] << 8) | buf[0]) & 0x01;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set relay GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_handle) != 0) {
        log_message("MPR121 initialisation failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (touch && !last_touch) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            touch = read_touch_status(i2c_handle);
            if (touch < 0) continue;
            if (touch) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[64];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                log_message(msg);
            }
        }
        last_touch = touch;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

