#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* Motor A */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
/* L298N enable pins */
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define MAX_SPEED 255
#define OBSTACLE_THRESHOLD 20.0
#define REVERSE_SPEED 128
#define LOG_FILE "balance_log.txt"
#define LOOP_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    } else {
        fprintf(stderr, "Error: Invalid motor identifier: %c\n", motor);
        if (log_file) {
            fprintf(log_file, "Error: Invalid motor identifier: %c\n", motor);
            fflush(log_file);
        }
        return;
    }

    if (speed > 0) {
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

static void stop_motors(void) {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

static float simulate_tilt_error(void) {
    return (float)(rand() % 20001) / 1000.0 - 10.0;
}

static float simulate_distance(void) {
    return (float)(rand() % 39801) / 100.0 + 2.0;
}

static int pid_control(float tilt_error, float *integral, float *previous_error,
                       float Kp, float Ki, float Kd) {
    float proportional = Kp * tilt_error;
    *integral += Ki * tilt_error;
    float derivative = Kd * (tilt_error - *previous_error);
    float output = proportional + *integral + derivative;

    *previous_error = tilt_error;

    if (output > MAX_SPEED) output = MAX_SPEED;
    if (output < -MAX_SPEED) output = -MAX_SPEED;

    return (int)output;
}

static void cleanup(void) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float Kp = 1.0, Ki = 0.01, Kd = 0.1;
    float integral = 0.0, previous_error = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Self-balancing robot simulation started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        int motor_a_speed = pid_control(tilt_error, &integral, &previous_error, Kp, Ki, Kd);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -REVERSE_SPEED;
            set_motor_speed('B', -REVERSE_SPEED);
        } else {
            set_motor_speed('B', motor_a_speed);
        }

        set_motor_speed('A', motor_a_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_a_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

