/*
 * mood_light.c — Ambient noise-driven RGB mood light for Raspberry Pi 3 B+
 *
 * Build:
 *   ALSA available:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lm
 *   ALSA unavailable: gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lm
 *
 * Run:
 *   ./mood_light [sensitivity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

/* ---- Hardware / ALSA configuration ---- */
#define RED_PIN        17
#define GREEN_PIN      18
#define BLUE_PIN       27

#define PWM_RANGE      255
#define PWM_FREQ_HZ    1000

#define SAMPLE_RATE    8000
#define PERIOD_SIZE    1024
#define NUM_CHANNELS   1

#define UPDATE_DELAY_US 10000   /* 10 ms between updates */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;

static int g_pigpio_initialized = 0;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_pcm_handle = NULL;
#endif

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- pigpio helpers ---- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_initialized = 1;

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set RGB pin modes.\n");
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }

    /* Start with LED off */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (red   < 0) red   = 0; if (red   > PWM_RANGE) red   = PWM_RANGE;
    if (green < 0) green = 0; if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue  < 0) blue  = 0; if (blue  > PWM_RANGE) blue  = PWM_RANGE;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void cleanup_gpio(void)
{
    if (g_pigpio_initialized) {
        /* Turn LED off before terminating */
        gpioPWM(RED_PIN, 0);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ---- ALSA helpers (when available) ---- */
#ifdef ALSA_AVAILABLE
static int init_alsa(void)
{
    int err;
    snd_pcm_hw_params_t *hw_params;

    err = snd_pcm_open(&g_pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: cannot open default ALSA device (%s).\n",
                snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    err = snd_pcm_hw_params_any(g_pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: cannot initialize hw_params (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_access(g_pcm_handle, hw_params,
                                       SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set access type (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_format(g_pcm_handle, hw_params,
                                       SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set sample format (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(g_pcm_handle, hw_params,
                                          &SAMPLE_RATE, NULL);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set sample rate (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(g_pcm_handle, hw_params,
                                         NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set channel count (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params(g_pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: cannot apply hw_params (%s).\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_prepare(g_pcm_handle);
    if (err < 0) {
        fprintf(stderr, "Error: cannot prepare PCM device (%s).\n",
                snd_strerror(err));
        return -1;
    }

    return 0;
}

static int read_audio(int16_t *buffer, int frames)
{
    int err = snd_pcm_readi(g_pcm_handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "Warning: ALSA buffer overrun — recovering.\n");
        snd_pcm_prepare(g_pcm_handle);
        return -1;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "Warning: ALSA device suspended — resuming.\n");
        if (snd_pcm_resume(g_pcm_handle) == 0) {
            return -1;  /* retry next iteration */
        }
        snd_pcm_prepare(g_pcm_handle);
        return -1;
    }
    if (err < 0) {
        fprintf(stderr, "Error: ALSA read failed (%s).\n",
                snd_strerror(err));
        return -1;
    }
    if (err != frames) {
        fprintf(stderr, "Warning: short read (%d of %d frames).\n",
                err, frames);
        return -1;
    }
    return 0;
}

static void close_alsa(void)
{
    if (g_pcm_handle) {
        snd_pcm_drain(g_pcm_handle);
        snd_pcm_close(g_pcm_handle);
        g_pcm_handle = NULL;
    }
}
#endif

/* ---- Simulated audio (when ALSA is unavailable) ---- */
static int init_simulated(void)
{
    /* Nothing to do */
    return 0;
}

static int read_simulated(int16_t *buffer, int frames)
{
    static double phase = 0.0;
    const double freq = 440.0;   /* A4 */
    const double two_pi = 2.0 * M_PI;

    for (int i = 0; i < frames; i++) {
        double sample = 0.5 * sin(phase);
        buffer[i] = (int16_t)(sample * 32767.0);
        phase += two_pi * freq / SAMPLE_RATE;
        if (phase >= two_pi) phase -= two_pi;
    }
    return 0;
}

static void close_simulated(void)
{
    /* Nothing to do */
}

/* ---- Audio abstraction layer ---- */
typedef struct {
#ifdef ALSA_AVAILABLE
    snd_pcm_t *handle;
#endif
    int initialized;
} audio_context_t;

static int audio_init(audio_context_t *ctx)
{
#ifdef ALSA_AVAILABLE
    if (init_alsa() == 0) {
        ctx->handle = g_pcm_handle;
        ctx->initialized = 1;
        return 0;
    }
    fprintf(stderr, "Warning: ALSA initialization failed; falling back to simulation.\n");
#endif
    if (init_simulated() == 0) {
        ctx->initialized = 1;
        return 0;
    }
    fprintf(stderr, "Error: neither ALSA nor simulation available.\n");
    return -1;
}

static int audio_read(audio_context_t *ctx, int16_t *buffer, int frames)
{
#ifdef ALSA_AVAILABLE
    if (ctx->initialized && ctx->handle) {
        return read_audio(buffer, frames);
    }
#endif
    return read_simulated(buffer, frames);
}

static void audio_close(audio_context_t *ctx)
{
#ifdef ALSA_AVAILABLE
    close_alsa();
#endif
    close_simulated();
    ctx->initialized = 0;
}

/* ---- Audio processing ---- */
static double calculate_rms(const int16_t *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / (double)frames);
}

/* ---- Color mapping ---- */
static void map_rms_to_color(double rms, double sensitivity,
                             int *red, int *green, int *blue)
{
    /* Normalize RMS to [0, 1] */
    double norm = rms / 32767.0;
    double scaled = norm * sensitivity;

    if (scaled < 0.0) scaled = 0.0;
    if (scaled > 1.0) scaled = 1.0;

    /* Non-linear transition: cool (blue) at low amplitude, warm (red) at high */
    double r = 0.0, g = 0.0, b = 0.0;

    if (scaled < 0.5) {
        /* Cool colors (blue) */
        b = scaled * 2.0;
        g = scaled * 2.0;
    } else {
        /* Warm colors (red) */
        r = (scaled - 0.5) * 2.0;
        g = (0.5 - (scaled - 0.5)) * 2.0;
        b = 0.0;
    }

    *red   = (int)(r * PWM_RANGE);
    *green = (int)(g * PWM_RANGE);
    *blue  = (int)(b * PWM_RANGE);
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    double sensitivity = 1.0;
    int16_t *audio_buffer = NULL;
    audio_context_t audio_ctx;
    memset(&audio_ctx, 0, sizeof(audio_ctx));

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: sensitivity must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 ||
        sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize audio */
    if (audio_init(&audio_ctx) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /* Allocate audio buffer */
    audio_buffer = (int16_t *)malloc(PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error: cannot allocate audio buffer.\n");
        audio_close(&audio_ctx);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Mood light running. Sensitivity: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (audio_read(&audio_ctx, audio_buffer, PERIOD_SIZE) != 0) {
            /* Non-fatal: continue with previous color or black */
            gpioDelay(UPDATE_DELAY_US);
            continue;
        }

        double rms = calculate_rms(audio_buffer, PERIOD_SIZE);
        int red, green, blue;
        map_rms_to_color(rms, sensitivity, &red, &green, &blue);
        set_led_color(red, green, blue);

        gpioDelay(UPDATE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);
    free(audio_buffer);
    audio_close(&audio_ctx);
    cleanup_gpio();

    return EXIT_SUCCESS;
}

