}

/* ---- Audio abstraction layer ---- */
typedef struct {
#ifdef ALSA_AVAILABLE
    snd_pcm_t *handle;
#endif
    int initialized;
} audio_context_t;

static int audio_init(audio_context_t *ctx)
{
#ifdef ALSA_AVAILABLE
    if (init_alsa() == 0) {
        ctx->handle = g_pcm_handle;
        ctx->initialized = 1;
        return 0;
    }
    fprintf(stderr, "Warning: ALSA initialization failed; falling back to simulation.\n");
#endif
    if (init_simulated() == 0) {
        ctx->initialized = 1;
        return 0;
    }
    fprintf(stderr, "Error: neither ALSA nor simulation available.\n");
    return -1;
}

static int audio_read(audio_context_t *ctx, int16_t *buffer, int frames)
{
#ifdef ALSA_AVAILABLE
    if (ctx->initialized && ctx->handle) {
        return read_audio(buffer, frames);
    }
#endif
    return read_simulated(buffer, frames);
}

static void audio_close(audio_context_t *ctx)
{
#ifdef ALSA_AVAILABLE
    close_alsa();
#endif
    close_simulated();
    ctx->initialized = 0;
}

/* ---- Audio processing ---- */
static double calculate_rms(const int16_t *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / (double)frames);
}

/* ---- Color mapping ---- */
static void map_rms_to_color(double rms, double sensitivity,
                             int *red, int *green, int *blue)
{
    /* Normalize RMS to [0, 1] */
    double norm = rms / 32767.0;
    double scaled = norm * sensitivity;

    if (scaled < 0.0) scaled = 0.0;
    if (scaled > 1.0) scaled = 1.0;

    /* Non-linear transition: cool (blue) at low amplitude, warm (red) at high */
    double r = 0.0, g = 0.0, b = 0.0;

    if (scaled < 0.5) {
        /* Cool colors (blue) */
        b = scaled * 2.0;
        g = scaled * 2.0;
    } else {
        /* Warm colors (red) */
        r = (scaled - 0.5) * 2.0;
        g = (0.5 - (scaled - 0.5)) * 2.0;
        b = 0.0;
    }

    *red   = (int)(r * PWM_RANGE);
    *green = (int)(g * PWM_RANGE);
    *blue  = (int)(b * PWM_RANGE);
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    double sensitivity = 1.0;
    int16_t *audio_buffer = NULL;
    audio_context_t audio_ctx;
    memset(&audio_ctx, 0, sizeof(audio_ctx));

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: sensitivity must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 ||
        sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize audio */
    if (audio_init(&audio_ctx) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /* Allocate audio buffer */
    audio_buffer = (int16_t *)malloc(PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error: cannot allocate audio buffer.\n");
        audio_close(&audio_ctx);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Mood light running. Sensitivity: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (audio_read(&audio_ctx, audio_buffer, PERIOD_SIZE) != 0) {
            /* Non-fatal: continue with previous color or black */
            gpioDelay(UPDATE_DELAY_US);
            continue;
        }

        double rms = calculate_rms(audio_buffer, PERIOD_SIZE);
        int red, green, blue;
        map_rms_to_color(rms, sensitivity, &red, &green, &blue);
        set_led_color(red, green, blue);

        gpioDelay(UPDATE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);
    free(audio_buffer);
    audio_close(&audio_ctx);
    cleanup_gpio();

    return EXIT_SUCCESS;
}

