#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, wbuf, 1) != 0) {
        fprintf(stderr, "Error selecting reg 0x%02X\n", reg);
        return -1;
    }
    char rbuf[1];
    if (i2cReadDevice(i2c_handle, rbuf, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)rbuf[0];
    return 0;
}

static int read_word(uint8_t reg, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg, &lo) != 0) return -1;
    if (read_reg(reg + 1, &hi) != 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(void) {
    if (write_reg(TCS34725_ENABLE, 0x03) != 0) return -1;
    if (write_reg(TCS34725_ATIME, 0xD5) != 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (read_word(TCS34725_CDATAL, c) != 0) return -1;
    if (read_word(TCS34725_RDATAL, r) != 0) return -1;
    if (read_word(TCS34725_GDATAL, g) != 0) return -1;
    if (read_word(TCS34725_BDATAL, b) != 0) return -1;
    return 0;
}

static void log_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t c, r, g, b;
        if (read_sensor_data(&c, &r, &g, &b) == 0) {
            log_data(c, r, g, b);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            c = r = g = b = 0;
        }
        gpioDelay(500000);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

