#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 52080

static const unsigned int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LAMPS] = {NULL};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_line_get(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for BCM GPIO%u\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "lamp_sim", 1) < 0) {
            fprintf(stderr, "Failed to request output for BCM GPIO%u\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
    }
    return 0;
}

static void set_all_lamps(int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpiod_line_set_value(lines[i], value) < 0) {
            perror("Failed to set relay value");
        }
    }
}

static void simulate_sunrise(void) {
    printf("Sunrise phase started\n");
    for (int i = 0; i <= 100 && program_running; i++) {
        set_all_lamps(0);
        usleep(SUNRISE_DURATION * 1000000 / 100);
        set_all_lamps(1);
        usleep(SUNRISE_DURATION * 1000000 / 100);
    }
    set_all_lamps(1);
    printf("Sunrise phase ended\n");
}

static void simulate_daytime(void) {
    printf("Daytime phase started\n");
    set_all_lamps(1);
    sleep(DAYTIME_DURATION);
    printf("Daytime phase ended\n");
}

static void simulate_sunset(void) {
    printf("Sunset phase started\n");
    for (int i = 100; i >= 0 && program_running; i--) {
        set_all_lamps(0);
        usleep(SUNSET_DURATION * 1000000 / 100);
        set_all_lamps(1);
        usleep(SUNSET_DURATION * 1000000 / 100);
    }
    set_all_lamps(0);
    printf("Sunset phase ended\n");
}

static void simulate_nighttime(void) {
    printf("Nighttime phase started\n");
    set_all_lamps(0);
    sleep(NIGHTTIME_DURATION);
    printf("Nighttime phase ended\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (program_running) {
        simulate_sunrise();
        if (!program_running) break;
        simulate_daytime();
        if (!program_running) break;
        simulate_sunset();
        if (!program_running) break;
        simulate_nighttime();
    }

    cleanup();
    printf("Program terminated gracefully\n");
    return EXIT_SUCCESS;
}

