#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_MS 200
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) return -1;
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) return -1;
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int record_video(const char *timestamp) {
    char command[512];
    char filename[128];
    int ret;

    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    ret = snprintf(command, sizeof(command),
                   "raspivid -o %s -t %d000 -w 640 -h 480 -fps 30",
                   filename, VIDEO_DURATION_SEC);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small.\n");
        return -1;
    }

    printf("Recording video to %s...\n", filename);
