#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Active-low relays: HIGH = off, LOW = on */
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static void control_relay(int pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d.\n", pin);
    }
}

static void log_data(int moisture_level, int relay_state, int pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Warning: localtime failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Zone (GPIO %d): Moisture = %d, Relay = %s\n",
                timestamp, pin, moisture_level,
                relay_state == 0 ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed.\n");
    }
    fflush(log_file);
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            int moisture_level = read_moisture_sensor();
            control_relay(relay_pins[i], moisture_level);
            int relay_state = gpioRead(relay_pins[i]);
            log_data(moisture_level, relay_state, relay_pins[i]);
        }
        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    deactivate_all_relays();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

