#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION_MS 500
#define ALARM_GPIO 27
#define LOG_FILE "freefall.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(void) {
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not reset ADXL345 (POWER_CTL write failed)\n");
        return -1;
    }
    gpioDelay(1000);
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Could not set DATA_FORMAT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not enable measurement mode\n");
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);
    data->x = (float)x / 256.0;
    data->y = (float)y / 256.0;
    data->z = (float)z / 256.0;
    return 0;
}

static int is_freefall(const accelerometer_data_t *data) {
    return (fabs(data->x) < FREEFALL_THRESHOLD &&
            fabs(data->y) < FREEFALL_THRESHOLD &&
            fabs(data->z) < FREEFALL_THRESHOLD);
}

static void trigger_alarm(void) {
    gpioWrite(ALARM_GPIO, 1);
    gpioDelay(5000000);
    gpioWrite(ALARM_GPIO, 0);
}

static void log_freefall_event(const accelerometer_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Freefall detection started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        accelerometer_data_t data;
        if (read_accelerometer_data(&data) == 0) {
            if (is_freefall(&data)) {
                gpioDelay(FREEFALL_DURATION_MS * 1000);
                if (read_accelerometer_data(&data) == 0 && is_freefall(&data)) {
                    printf("Freefall detected!\n");
                    trigger_alarm();
                    log_freefall_event(&data);
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(ALARM_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

