#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_US 23200
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile int echo_received = 0;
static volatile int measurement_pending = 0;
static pthread_mutex_t data_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_rising_edge(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    pulse_start = tick;
    measurement_pending = 1;
}

static void echo_falling_edge(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (!measurement_pending) return;
    pulse_end = tick;
    echo_received = 1;
    measurement_pending = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10000);
    return 0;
}

static int initialize_logging(void) {
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
    if (fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

static void cleanup(void) {
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&data_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (pthread_mutex_init(&data_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        pthread_mutex_destroy(&data_mutex);
        return 1;
    }

    if (initialize_logging() != 0) {
        gpioTerminate();
        pthread_mutex_destroy(&data_mutex);
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL) != 0) {
        fprintf(stderr, "Failed to set rising-edge callback\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL) != 0) {
        fprintf(stderr, "Failed to set falling-edge callback\n");
        cleanup();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        measurement_pending = 0;
        pulse_start = 0;
        pulse_end = 0;

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        uint32_t elapsed = 0;
        while (!echo_received && elapsed < ECHO_TIMEOUT_US && running) {
            gpioDelay(100);
            uint32_t now = gpioTick();
            elapsed = now - start_tick;
        }

        if (!running) break;

        if (!echo_received) {
            fprintf(stderr, "Warning: Echo timeout (no object detected or sensor error)\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        uint32_t pulse_width = pulse_end - pulse_start;
        if (pulse_width > MAX_DISTANCE_US) {
            fprintf(stderr, "Warning: Pulse width %u us exceeds max range (%d us)\n",
                    pulse_width, MAX_DISTANCE_US);
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        double distance_cm = (double)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;

        pthread_mutex_lock(&data_mutex);
        log_distance(distance_cm);
        pthread_mutex_unlock(&data_mutex);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

