#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define SENSITIVITY 16384.0f
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = I2C_RETRIES;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (bytes_read == 6) break;
        fprintf(stderr, "I2C read error (got %d bytes, expected 6): %d. Retrying...\n", bytes_read, bytes_read);
        retries--;
        gpioDelay(1000);
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read acceleration data after %d retries.\n", I2C_RETRIES);
        return -1;
    }

