#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SCALE_FACTOR 0.0009765625f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", rc);
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)(((uint16_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint16_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint16_t)buffer[5] << 8) | (uint8_t)buffer[4]);
    *x = (float)(raw_x >> 4) * SCALE_FACTOR;
    *y = (float)(raw_y >> 4) * SCALE_FACTOR;
    *z = (float)(raw_z >> 4) * SCALE_FACTOR;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - High acceleration: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        fprintf(stderr, "Error executing shutdown command\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x08-0x77)\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold: %.2f (must be > 0)\n", threshold);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0x57) != 0) {
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, CTRL_REG4, 0x88) != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration on LIS3DH at 0x%02X (threshold=%.2f g)...\n", i2c_address, threshold);

    while (program_running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

