#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define ALERT_THRESHOLD    5
#define POLL_DELAY_MS      10
#define ALERT_DURATION_MS  2000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static void init_motor(void)  { printf("Motor initialized.\n"); }
static void move_forward(void) { printf("Moving forward.\n"); }
static void turn_left(void)    { printf("Turning left.\n"); }
static void turn_right(void)   { printf("Turning right.\n"); }
static void stop_motor(void)   { printf("Stopping.\n"); }

static void trigger_alert(struct gpiod_line *alert_line) {
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
        return;
    }
    printf("Alert triggered!\n");
    usleep(ALERT_DURATION_MS * 1000);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
    }
}

static void follow_line(sensor_data_t data) {
    if (data.center == 0) {
        move_forward();
    } else if (data.left == 0) {
        turn_left();
    } else if (data.right == 0) {
        turn_right();
    } else {
        stop_motor();
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL, *center_line = NULL, *right_line = NULL;
    struct gpiod_line *alert_line = NULL;
    sensor_data_t sensor_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int center_no_line_count = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    init_motor();

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        sensor_data_t current_data = { left_val, center_val, right_val };
        sensor_buffer[buffer_index] = current_data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (center_val == 1) {
            center_no_line_count++;
        } else {
            center_no_line_count = 0;
        }

        if (center_no_line_count >= ALERT_THRESHOLD) {
            trigger_alert(alert_line);
            center_no_line_count = 0;
        }

        follow_line(current_data);
        usleep(POLL_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert_line) gpiod_line_release(alert_line);
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

