#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define RELAY_GPIO     17
#define THRESHOLD_MT   5.0f
#define POLL_MAX       50
#define SAMPLE_US      100000

#define REG_FIELD_LSB  0xC0
#define REG_FIELD_MSB  0xC1
#define REG_CTRL       0xC1
#define CTRL_START     0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void log_event(const char *msg) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_field_raw(int16_t *out) {
    if (i2cWriteByteData(i2c_handle, REG_CTRL, CTRL_START) < 0) {
        log_event("Error: failed to start conversion");
        return -1;
    }
    for (int i = 0; i < POLL_MAX; i++) {
        int status = i2cReadByteData(i2c_handle, REG_CTRL);
        if (status < 0) {
            log_event("Error: failed to poll conversion status");
            return -1;
        }
        if (status == 0) break;
        gpioDelay(1000);
        if (i == POLL_MAX - 1) {
            log_event("Error: conversion timeout");
            return -1;
        }
    }
    int lsb = i2cReadByteData(i2c_handle, REG_FIELD_LSB);
    if (lsb < 0) {
        log_event("Error: failed to read field LSB");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, REG_FIELD_MSB);
    if (msb < 0) {
        log_event("Error: failed to read field MSB");
        return -1;
    }
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static void control_relay(int activate) {
    if (gpioWrite(RELAY_GPIO, activate ? 1 : 0) < 0) {
        log_event("Error: failed to write relay GPIO");
    } else {
        char msg[64];
        snprintf(msg, sizeof(msg), "Relay %s", activate ? "activated" : "deactivated");
        log_event(msg);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_event("Program started");

    while (running) {
        int16_t raw;
        if (read_field_raw(&raw) == 0) {
            int field_x100 = (raw * 25) / 1000;
            float field_mt = field_x100 / 100.0f;
            char msg[128];
            snprintf(msg, sizeof(msg), "Field: %.2f mT (raw=%d)", field_mt, raw);
            log_event(msg);

            if (field_mt > THRESHOLD_MT) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        } else {
            control_relay(0);
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

