            snprintf(log_msg, sizeof(log_msg), "Invalid command received: %s", command);
            log_event(log_msg);
            printf("Invalid command received: %s\n", command);
        }
    }

    if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else if (bytes_received < 0) {
        perror("recv failed");
