#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x08
#define SENSOR2_ADDR   0x09
#define RELAY_PIN      18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR   1500.0f
#define LOG_FILE       "flow_log.txt"
#define POLL_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_sensor(int handle) {
    uint8_t cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed on handle %d (rc=%d)\n", handle, rc);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Warning: i2cReadDevice returned %d (expected 3) on handle %d\n", rc, handle);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Warning: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / SCALE_FACTOR;
    return 0;
}

static void log_flow_rates(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void cleanup(void) {
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(f1, f2);
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                gpioWrite(RELAY_PIN, 1);
            } else {
                gpioWrite(RELAY_PIN, 0);
            }
        } else {
            fprintf(stderr, "Warning: sensor read error, skipping relay update\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

