#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24

#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_TIME_US 5000000 /* 5 s   */
#define DRY_CONFIRM_COUNT 3       /* 3 consecutive dry polls = ~600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_WARNING, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

static void motor_stop(void)
{
    safe_write(MOTOR_ENABLE_PIN, 0);
    safe_write(MOTOR_INPUT_1_PIN, 0);
    safe_write(MOTOR_INPUT_2_PIN, 0);
}

static void motor_run(void)
{
    syslog(LOG_INFO, "Closing window: motor running for 5 s");
    if (safe_write(MOTOR_ENABLE_PIN, 1) < 0) return;
    if (safe_write(MOTOR_INPUT_1_PIN, 1) < 0) return;
    if (safe_write(MOTOR_INPUT_2_PIN, 0) < 0) return;

    /* gpioDelay is a busy-wait; break it into 100 ms slices so signals are
       noticed promptly. */
    for (int elapsed = 0; elapsed < MOTOR_RUN_TIME_US && g_running; elapsed += 100000)
        gpioDelay(100000);

    motor_stop();
    syslog(LOG_INFO, "Window closed");
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        goto fail_init;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        goto fail_init;
    }

    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pin) failed");
