#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000   /* 2000 µs = 2 ms  -> locked position  */
#define UNLOCK_PULSE_US 1000  /* 1000 µs = 1 ms  -> unlocked position */
#define DEBOUNCE_US    500000 /* 500 ms debounce after a press        */
#define POLL_US        10000  /* 10 ms poll interval                   */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed\n", pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release the pin */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins with internal pull-ups --- */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Set servo pin to output (gpioServo also sets mode, but explicit
           setMode ensures the pin is in the right state before any pulse). --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start with the door locked --- */
    if (set_servo(LOCK_PULSE_US) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Door lock system started. Door is LOCKED.\n");
    printf("Press button on GPIO %d to unlock, GPIO %d to lock.\n",
           UNLOCK_BUTTON, LOCK_BUTTON);
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        /* Lock button pressed (active-low: pin reads 0) */
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Lock button pressed. Locking door...\n");
            fflush(stdout);
            if (set_servo(LOCK_PULSE_US) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Door is LOCKED.\n");
            fflush(stdout);

            /* Debounce: wait for release, then wait DEBOUNCE_US */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        /* Unlock button pressed */
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlock button pressed. Unlocking door...\n");
            fflush(stdout);
            if (set_servo(UNLOCK_PULSE_US) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Door is UNLOCKED.\n");
            fflush(stdout);

            /* Debounce: wait for release, then wait DEBOUNCE_US */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock system stopped.\n");
    return EXIT_SUCCESS;
}

