#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(int duration_s)
{
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn floodlight ON\n");
        return -1;
    }

    if (log_event("Floodlight activated") != 0) {
        gpioWrite(FLOODLIGHT_PIN, 0);
        return -1;
    }

    time_t start = time(NULL);
    if (start == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        return -1;
    }

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            break;
        }
        if (difftime(now, start) >= (double)duration_s) {
            break;
        }
        gpioDelay(POLL_DELAY_US);
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn floodlight OFF\n");
        return -1;
    }

    time_t end = time(NULL);
    if (end == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    double elapsed = difftime(end, start);
    char msg[128];
    snprintf(msg, sizeof(msg), "Floodlight deactivated after %.2f seconds",
             elapsed);
    if (log_event(msg) != 0) {
        return -1;
    }

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin %d as output\n",
                FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise floodlight OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started.\n");
    printf("PIR sensor: GPIO %d | Floodlight: GPIO %d | Duration: %d s\n",
           PIR_PIN, FLOODLIGHT_PIN, FLOODLIGHT_DURATION_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(PIR_PIN) == 1) {
            if (activate_floodlight(FLOODLIGHT_DURATION_S) != 0) {
                fprintf(stderr, "Floodlight activation error; continuing.\n");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();
    printf("Smart Security Light System stopped.\n");
    return EXIT_SUCCESS;
}

