#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define DEBOUNCE_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write(0x80, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Baseline filtering – rising */
    if (mpr121_write(0x2B, 0x01) < 0) return -1; /* MHD */
    if (mpr121_write(0x2C, 0x01) < 0) return -1; /* NHD */
    if (mpr121_write(0x2D, 0x00) < 0) return -1; /* NCL */
    if (mpr121_write(0x2E, 0x00) < 0) return -1; /* FDL */

    /* Baseline filtering – falling */
    if (mpr121_write(0x2F, 0x01) < 0) return -1; /* MHD */
    if (mpr121_write(0x30, 0x01) < 0) return -1; /* NHD */
    if (mpr121_write(0x31, 0x00) < 0) return -1; /* NCL */
    if (mpr121_write(0x32, 0x00) < 0) return -1; /* FDL */

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(0x41 + 2 * i, 0x0F) < 0) return -1; /* touch */
        if (mpr121_write(0x42 + 2 * i, 0x0A) < 0) return -1; /* release */
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(0x5B, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, CDT=0.5 us */
    if (mpr121_write(0x2C, 0x24) < 0) return -1;

    /* Auto-config: enable, retries=2, FFI=6, SFI=4 */
    if (mpr121_write(0x7B, 0x0B) < 0) return -1;
    if (mpr121_write(0x7C, 0x00) < 0) return -1;
    if (mpr121_write(0x7D, 0x00) < 0) return -1;

    /* Enable 12 electrodes */
    if (mpr121_write(0x5E, 0x0C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch(uint16_t *touch) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    *touch = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed – sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 ready. Touch electrode 0 to toggle relay on GPIO%d. Ctrl+C to exit.\n", RELAY_GPIO);

    uint16_t prev_touch = 0;
    int relay_state = 0;

    while (running) {
        uint16_t touch = 0;
        if (mpr121_read_touch(&touch) < 0) {
            gpioDelay(DEBOUNCE_MS * 1000);
            continue;
        }

        /* Rising-edge detection on electrode 0 */
        if ((touch & 0x0001) && !(prev_touch & 0x0001)) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Failed to write relay GPIO\n");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        prev_touch = touch;
        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

