        log_message("Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message("Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "security_servo", 0) < 0) {
        log_message("Failed to request servo line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message("Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "security_pir") < 0) {
        log_message("Failed to request PIR line as input: %s", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        pir_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Socket creation failed: %s", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("Setsockopt failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;
    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char *newline = strpbrk(buffer, "\r\n");
        if (newline) *newline = '\0';
        char *command = strtok(buffer, " \t");
        if (command) {
            if (strcmp(command, "SERVO") == 0) {
                char *angle_str = strtok(NULL, " \t");
                if (angle_str) {
                    int angle = atoi(angle_str);
                    if (angle >= 0 && angle <= 180) {
                        servo_angle = angle;
                        servo_active = 1;
                        char response[64];
                        snprintf(response, sizeof(response), "OK SERVO %d", angle);
                        send(client_socket, response, strlen(response), 0);
                        log_message("Servo angle set to %d", angle);
                    } else {
                        send(client_socket, "ERROR Invalid angle", 18, 0);
                        log_message("Invalid servo angle: %s", angle_str);
                    }
                } else {
                    send(client_socket, "ERROR Missing angle", 17, 0);
                    log_message("Missing angle parameter");
                }
            } else if (strcmp(command, "PIR") == 0) {
                int pir_value = gpiod_line_get_value(pir_line);
                if (pir_value < 0) {
                    send(client_socket, "ERROR PIR read failed", 20, 0);
                    log_message("Failed to read PIR sensor: %s", strerror(errno));
                } else {
                    char response[32];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    send(client_socket, response, strlen(response), 0);
                    log_message("PIR sensor value: %d", pir_value);
                }
            } else {
                send(client_socket, "ERROR Unknown command", 20, 0);
                log_message("Unknown command: %s", command);
            }
        } else {
            send(client_socket, "ERROR Invalid command format", 26, 0);
            log_message("Invalid command format");
        }
    }
    if (bytes_received == 0) {
        log_message("Client disconnected");
    } else if (bytes_received < 0) {
        log_message("Recv failed: %s", strerror(errno));
    }
    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }
    if (init_gpio() < 0) {
        fclose(log_file);
        return 1;
    }
    if (init_socket() < 0) {
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }
    if (pthread_create(&servo_thread, NULL, servo_control, NULL) != 0) {
        log_message("Failed to create servo thread: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }
    log_message("Security system started on port %d", PORT);
    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            log_message("Accept failed: %s", strerror(errno));
            break;
        }
        log_message("Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_socket);
    }
    running = 0;
    pthread_join(servo_thread, NULL);
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    log_message("Security system stopped");
    return 0;
}

