#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"
#define I2C_BUS 1
#define BH1750_CMD_OT_HIGH_RES 0x20
#define BH1750_CONV_TIME_US 120000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HIGH_RES) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command to BH1750.\n");
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_US);

    char buf[2] = {0};
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 (got %d).\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handlers.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light controller started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            log_data(log_file, lux);
            if (lux < LUX_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Lux %.2f below threshold %.1f — grow light ON\n", lux, LUX_THRESHOLD);
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("Lux %.2f at or above threshold %.1f — grow light OFF\n", lux, LUX_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

