#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define DOUT_PIN 23
#define SCK_PIN  24
#define LOCK_PIN 25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE     1.0f
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define POLL_INTERVAL_MS  500
#define DOUT_TIMEOUT_MS   1000
#define MAX_RETRIES       3

static volatile sig_atomic_t running = 1;
static float threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION;
static long tare_offset = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *dout_line = NULL;
static struct gpiod_line *sck_line = NULL;
static struct gpiod_line *lock_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (lock_line) {
        gpiod_line_set_value(lock_line, 0);
        gpiod_line_release(lock_line);
        lock_line = NULL;
    }
    if (sck_line) {
        gpiod_line_set_value(sck_line, 0);
        gpiod_line_release(sck_line);
        sck_line = NULL;
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
        dout_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    closelog();
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line %d: %s", DOUT_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line %d: %s", SCK_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        syslog(LOG_ERR, "Failed to get LOCK line %d: %s", LOCK_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(lock_line, "solenoid_lock", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LOCK as output: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static int wait_dout_low(int timeout_ms) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (gpiod_line_get_value(dout_line) == 0) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L +
                          (now.tv_nsec - start.tv_nsec) / 1000000L;
        if (elapsed_ms >= timeout_ms) return -1;
        usleep(100);
    }
}

static long read_hx711(void) {
    if (wait_dout_low(DOUT_TIMEOUT_MS) < 0) {
        syslog(LOG_ERR, "HX711 DOUT did not go LOW within %d ms", DOUT_TIMEOUT_MS);
        return -1;
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        value <<= 1;
        if (gpiod_line_get_value(dout_line) == 1) {
            value |= 1;
        }
        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }
    return value;
}

static long average_readings(int num_readings) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < num_readings; i++) {
        long v = read_hx711();
        if (v < 0) {
            syslog(LOG_ERR, "HX711 read failed on attempt %d", i + 1);
            continue;
        }
        sum += v;
        valid++;
        usleep(1000);
    }
    if (valid == 0) return -1;
    return sum / valid;
}

static void tare_sensor(void) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < TARE_READINGS; i++) {
        long v = read_hx711();
        if (v < 0) {
            syslog(LOG_ERR, "Tare read failed on attempt %d", i + 1);
            continue;
        }
        sum += v;
        valid++;
        usleep(1000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return;
    }
    tare_offset = sum / valid;
    syslog(LOG_INFO, "Tare offset: %ld", tare_offset);
}

static void activate_lock(int duration_ms) {
    if (gpiod_line_set_value(lock_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to activate solenoid: %s", strerror(errno));
        return;
    }
    syslog(LOG_INFO, "Solenoid activated for %d ms", duration_ms);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(lock_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to deactivate solenoid: %s", strerror(errno));
    }
    syslog(LOG_INFO, "Solenoid deactivated");
}

static void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atof(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration_ms = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }
    syslog(LOG_INFO, "Threshold: %.2f g, Scale: %.2f, Duration: %d ms", threshold, scale, duration_ms);
}

int main(int argc, char *argv[]) {
    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 solenoid control");

    parse_arguments(argc, argv);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    tare_sensor();

    int retry_count = 0;
    while (running) {
        long raw = average_readings(NUM_READINGS);
        if (raw < 0) {
            retry_count++;
            syslog(LOG_ERR, "HX711 read failed (attempt %d/%d)", retry_count, MAX_RETRIES);
            if (retry_count >= MAX_RETRIES) {
                syslog(LOG_ERR, "Max retries reached, exiting");
                break;
            }
            usleep(100000);
            continue;
        }
        retry_count = 0;

        float weight = (float)(raw - tare_offset) / scale;
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            activate_lock(duration_ms);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

