/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control on localhost:1883 and drives a relay
 * on GPIO17 (BCM) according to the payload ("ON" or "OFF").
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *            -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "relay_controller_1"
#define MQTT_TOPIC       "home/lights/control"
#define MQTT_KEEPALIVE   60
#define GPIO_PIN         17
#define RETRY_DELAY_SEC  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO%d configured as output, relay OFF", GPIO_PIN);
    return 0;
}

static void relay_set(int on)
{
    int level = on ? 1 : 0;
    if (gpioWrite(GPIO_PIN, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, level);
    } else {
        syslog(LOG_INFO, "Relay on GPIO%d set to %s",
               GPIO_PIN, on ? "ON" : "OFF");
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker %s:%d",
               MQTT_HOST, MQTT_PORT);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe failed: %s",
                   mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s",
               mosquitto_connack_string(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                          int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s",
               mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Received empty message on %s", MQTT_TOPIC);
        return;
    }

    /* Ensure NUL-termination for safe string handling */
    char payload[64];
    int len = message->payloadlen;
    if (len >= (int)sizeof(payload))
        len = (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received on %s: %s", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        relay_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        relay_set(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' — relay unchanged", payload);
    }
}

static void on_subscribe(struct mosquitto *mosq, void *userdata,
                         int mid, int qos_count,
                         const int *granted_qos)
{
    (void)mosq;
    (void)userdata;
    (void)mid;
    (void)qos_count;
    (void)granted_qos;
    syslog(LOG_INFO, "Subscription to %s acknowledged", MQTT_TOPIC);
}

static void on_log(struct mosquitto *mosq, void *userdata,
                   int level, const char *str)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_DEBUG, "MQTT log: %s", str);
}

/* ------------------------------------------------------------------ */
/* MQTT client setup                                                   */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    int rc;

    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_subscribe_callback_set(g_mosq, on_subscribe);
    mosquitto_log_callback_set(g_mosq, on_log);

    rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect(%s:%d) failed: %s",
               MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d, MQTT %s:%d)",
           GPIO_PIN, MQTT_HOST, MQTT_PORT);

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 1000, 1);
        if (rc == MOSQ_ERR_SUCCESS) {
            continue;
        }

        syslog(LOG_ERR, "mosquitto_loop error: %s — reconnecting in %d s",
               mosquitto_strerror(rc), RETRY_DELAY_SEC);

        mqtt_cleanup();

        for (int i = 0; i < RETRY_DELAY_SEC && g_running; i++)
            sleep(1);

        if (!g_running)
            break;

        if (mqtt_init() != 0) {
            syslog(LOG_ERR, "Reconnect failed — will retry");
        }
    }

    /* Graceful shutdown */
    relay_set(0);
    gpioTerminate();
    mqtt_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

