#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define NUM_SERVOS 5
#define SERVO_FREQ 50          /* 50 Hz -> 20 ms period */
#define SERVO_RANGE 20000      /* 20000 steps = 1 us resolution at 50 Hz */
#define HOLD_US 3000000        /* 3 seconds */

static const int servo_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
static const int pulse_widths[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        int pin = servo_pins[i];
        int pw  = pulse_widths[i];

        /* Set PWM frequency to 50 Hz (20 ms period) */
        if (gpioSetPWMfrequency(pin, SERVO_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* Set range to 20000 so each step = 1 us at 50 Hz */
        if (gpioSetPWMrange(pin, SERVO_RANGE) < 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* Write pulse width in microseconds (pigpio accepts 0-1000000 range) */
        if (gpioServo(pin, pw) < 0) {
            fprintf(stderr, "Error: failed to set servo pulse on GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo on GPIO %d set to %d us\n", pin, pw);
    }

    /* Hold the positions for 3 seconds so servos can reach their targets */
    gpioDelay(HOLD_US);

    /* Stop PWM on each pin and release pigpio resources */
    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioServo(servo_pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

