#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <math.h>

/* DRV8833 H-bridge motor driver pins */
#define MOTOR_A_PWM_PIN  17
#define MOTOR_A_DIR_PIN  18
#define MOTOR_B_PWM_PIN  22
#define MOTOR_B_DIR_PIN  23

/* Quadrature encoder pins */
#define ENCODER_A_A_PIN  4
#define ENCODER_A_B_PIN  5
#define ENCODER_B_A_PIN  6
#define ENCODER_B_B_PIN  12

/* Encoder parameters */
#define ENCODER_TICKS_PER_REV  64
#define ENCODER_GEAR_RATIO     1.0

/* PI controller parameters */
#define KP  0.5
#define KI  0.05

/* Control loop period (seconds) */
#define CONTROL_PERIOD  0.1

/* Stall detection timeout (seconds) */
#define STALL_TIMEOUT  2.0

/* PWM frequency (Hz) */
#define PWM_FREQUENCY  10000

/* Global state */
static volatile sig_atomic_t g_running = 1;
static atomic_int g_encoder_a_count = 0;
static atomic_int g_encoder_b_count = 0;

/* Motor state */
typedef struct {
    int pwm_pin;
    int dir_pin;
    double integral;
    double last_error;
    int last_pwm;
    double last_time;
    int stall_warning;
} MotorState;

static MotorState g_motor_a;
static MotorState g_motor_b;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Encoder ISR helpers                                                 */
/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick;
    int b = gpioRead(ENCODER_A_B_PIN);
    if (b == 1) {
        atomic_fetch_add(&g_encoder_a_count, 1);
    } else {
        atomic_fetch_sub(&g_encoder_a_count, 1);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick;
    int b = gpioRead(ENCODER_B_B_PIN);
    if (b == 1) {
        atomic_fetch_add(&g_encoder_b_count, 1);
    } else {
        atomic_fetch_sub(&g_encoder_b_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static void motor_set_speed(MotorState *m, int pwm)
{
    if (pwm > 255) pwm = 255;
    if (pwm < 0)   pwm = 0;

    if (pwm > 0) {
        gpioWrite(m->dir_pin, 1);
        gpioPWM(m->pwm_pin, pwm);
    } else {
        gpioWrite(m->dir_pin, 0);
        gpioPWM(m->pwm_pin, 0);
    }
    m->last_pwm = pwm;
}

static void motor_stop(MotorState *m)
{
    gpioWrite(m->dir_pin, 0);
    gpioPWM(m->pwm_pin, 0);
}

/* ------------------------------------------------------------------ */
/* PI controller                                                       */
/* ------------------------------------------------------------------ */
static int pi_controller(MotorState *m, double target_rpm, double current_rpm,
                         double dt)
{
    double error = target_rpm - current_rpm;

    m->integral += error * dt;
    if (m->integral > 255.0)  m->integral = 255.0;
    if (m->integral < -255.0) m->integral = -255.0;

    double output = KP * error + KI * m->integral;
    if (output > 255.0)  output = 255.0;
    if (output < -255.0) output = -255.0;

    return (int)output;
}

/* ------------------------------------------------------------------ */
/* Stall detection                                                     */
/* ------------------------------------------------------------------ */
static void check_stall(MotorState *m, double now)
{
    int count = (m == &g_motor_a)
                ? atomic_load(&g_encoder_a_count)
                : atomic_load(&g_encoder_b_count);

    if (count == 0) {
        if (!m->stall_warning) {
            m->stall_warning = 1;
            printf("Warning: %s stall detected (no encoder ticks for > %.1f s)\n",
                   (m == &g_motor_a) ? "Motor A" : "Motor B", STALL_TIMEOUT);
        }
    } else {
        m->stall_warning = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop(&g_motor_a);
    motor_stop(&g_motor_b);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Set PWM frequency */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n",
                MOTOR_A_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n",
                MOTOR_B_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor direction pins as outputs */
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n",
                MOTOR_A_DIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n",
                MOTOR_B_DIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins as inputs */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder GPIOs as inputs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize motor state */
    g_motor_a.pwm_pin     = MOTOR_A_PWM_PIN;
    g_motor_a.dir_pin     = MOTOR_A_DIR_PIN;
    g_motor_a.integral    = 0.0;
    g_motor_a.last_error  = 0.0;
    g_motor_a.last_pwm    = 0;
    g_motor_a.last_time   = time_time();
    g_motor_a.stall_warning = 0;

    g_motor_b.pwm_pin     = MOTOR_B_PWM_PIN;
    g_motor_b.dir_pin     = MOTOR_B_DIR_PIN;
    g_motor_b.integral    = 0.0;
    g_motor_b.last_error  = 0.0;
    g_motor_b.last_pwm    = 0;
    g_motor_b.last_time   = time_time();
    g_motor_b.stall_warning = 0;

    /* Register encoder ISRs on rising edge */
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Closed-loop speed control started. Press Ctrl+C to exit.\n");

    double target_rpm = 50.0;
    double last_time  = time_time();

    while (g_running) {
        double now = time_time();
        double dt  = now - last_time;
        last_time  = now;

        if (dt <= 0.0) {
            usleep(10000);
            continue;
        }

        /* Read and reset encoder counts */
        int enc_a = atomic_exchange(&g_encoder_a_count, 0);
        int enc_b = atomic_exchange(&g_encoder_b_count, 0);

        /* Convert ticks to RPM (assumes 1:1 gear ratio) */
        double rpm_a = (double)enc_a / ENCODER_TICKS_PER_REV * (60.0 / dt);
        double rpm_b = (double)enc_b / ENCODER_TICKS_PER_REV * (60.0 / dt);

        /* PI control */
        int pwm_a = pi_controller(&g_motor_a, target_rpm, rpm_a, dt);
        int pwm_b = pi_controller(&g_motor_b, target_rpm, rpm_b, dt);

        motor_set_speed(&g_motor_a, pwm_a);
        motor_set_speed(&g_motor_b, pwm_b);

        /* Stall detection */
        check_stall(&g_motor_a, now);
        check_stall(&g_motor_b, now);

        printf("Motor A: RPM=%.2f, PWM=%d | Motor B: RPM=%.2f, PWM=%d\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        usleep((useconds_t)(CONTROL_PERIOD * 1e6));
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

