#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES2 0x21
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DARK 50.0
#define LUX_THRESHOLD_LIGHT 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_MEAS_DELAY_US 180000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    char cmd = BH1750_CMD_OT_HRES2;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_MEAS_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read returned %d bytes, expected 2\n", rc);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_event(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n",
                ts, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    }
    printf("%s: Lux = %.2f, Relay = %s\n",
           ts, lux, relay_state ? "ON" : "OFF");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float lux = 0.0f;
    int relay_state = 0;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Chicken coop lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_lux(&lux) == 0) {
            consecutive_errors = 0;

            if (lux < LUX_THRESHOLD_DARK && !relay_state) {
                if (set_relay(1) == 0) {
                    relay_state = 1;
                    printf("Dusk: Lux %.2f below %.1f, turning relay ON\n",
                           lux, LUX_THRESHOLD_DARK);
                }
            } else if (lux > LUX_THRESHOLD_LIGHT && relay_state) {
                if (set_relay(0) == 0) {
                    relay_state = 0;
                    printf("Dawn: Lux %.2f above %.1f, turning relay OFF\n",
                           lux, LUX_THRESHOLD_LIGHT);
                }
            }
            log_event(lux, relay_state);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read error #%d\n", consecutive_errors);
            log_event(-1.0f, relay_state);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, shutting down safely.\n");
                set_relay(0);
                break;
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    set_relay(0);
    cleanup();
    printf("Chicken coop lighting system stopped.\n");
    return 0;
}

