#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int ret;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input (code %d)\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output */
    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (code %d)\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d (code %d)\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_state = 0;
    log_relay_state(relay_state);

    printf("Touch-controlled relay ready. Touch GPIO %d to toggle relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        /* Read touch sensor */
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Warning: failed to read GPIO %d (code %d)\n", TOUCH_SENSOR_PIN, touch_value);
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        if (touch_value == 1) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            touch_value = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_value < 0) {
                fprintf(stderr, "Warning: failed to read GPIO %d after debounce (code %d)\n",
                        TOUCH_SENSOR_PIN, touch_value);
                gpioDelay(LOOP_DELAY_MS * 1000);
                continue;
            }

            if (touch_value == 1) {
                /* Valid touch detected: toggle relay */
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d (code %d)\n", RELAY_PIN, ret);
                } else {
                    log_relay_state(relay_state);
                }

                /* Wait for touch release before next toggle */
                while (running) {
                    touch_value = gpioRead(TOUCH_SENSOR_PIN);
                    if (touch_value < 0) {
                        fprintf(stderr, "Warning: failed to read GPIO %d during release wait (code %d)\n",
                                TOUCH_SENSOR_PIN, touch_value);
                        break;
                    }
                    if (touch_value == 0) {
                        break;
                    }
                    gpioDelay(LOOP_DELAY_MS * 1000);
                }
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    /* Graceful shutdown: turn relay OFF and release pigpio */
    printf("\nShutting down...\n");
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during shutdown (code %d)\n", ret);
    }
    gpioTerminate();
    printf("Cleanup complete. Goodbye.\n");
    return EXIT_SUCCESS;
}

