#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27

#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD   5.0
#define HYSTERESIS       0.5
#define SAMPLE_INTERVAL  1.0
#define DEBOUNCE_US      1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static volatile unsigned int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void log_event(const char *msg)
{
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;  /* handles 32-bit wrap */
    if (diff > DEBOUNCE_US) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = tick;
    }
}

static double calculate_flow_rate(unsigned int pulses)
{
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

