#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define HX711_TIMEOUT_MAX 1000
#define HX711_SETTLE_US 100000
#define DISPENSE_STABILIZE_US 1000000

static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[20] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int server_fd = -1;
static int client_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = 0;
        char *key = line;
        char *val = eq + 1;
        while (*key == ' ') key++;
        char *end = key + strlen(key) - 1;
        while (end > key && *end == ' ') { *end = 0; end--; }
        while (*val == ' ') val++;
        end = val + strlen(val) - 1;
        while (end > val && *end == ' ') { *end = 0; end--; }
        if (strcmp(key, "calibration_factor") == 0) calibration_factor = atof(val);
        else if (strcmp(key, "server_ip") == 0) { strncpy(server_ip, val, sizeof(server_ip) - 1); server_ip[sizeof(server_ip) - 1] = 0; }
        else if (strcmp(key, "server_port") == 0) server_port = atoi(val);
    }
    fclose(fp);
    return 1;
}

static int read_hx711(void) {
    int data = 0;
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN)) {
        if (++timeout > HX711_TIMEOUT_MAX) return -1;
        gpioDelay(1);
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) data |= ~0xFFFFFF;
    return data;
}

static double read_weight(void) {
    int raw = read_hx711();
    if (raw == -1) return -1.0;
    gpioDelay(HX711_SETTLE_US);
    return (double)raw / calibration_factor;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pw = SERVO_MIN_PULSE_WIDTH + (int)((double)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    if (gpioServo(SERVO_PIN, pw) < 0) return -1;
    return 0;
}

static int log_dispensing(double target, double actual, const char *err) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error\":\"%s\"}\n",
            ts, target, actual, err ? err : "");
    fclose(fp);
    return 0;
}

static int handle_client(int cfd) {
    char buf[256];
    ssize_t n = recv(cfd, buf, sizeof(buf) - 1, 0);
    if (n <= 0) { perror("recv"); return -1; }
    buf[n] = 0;
    char *endp = NULL;
    double target = strtod(buf, &endp);
    if (endp == buf) { fprintf(stderr, "Invalid target: %s\n", buf); return -1; }
    if (target <= 0) { fprintf(stderr, "Target must be positive\n"); return -1; }
    if (set_servo_angle(180) != 0) { perror("set_servo_angle open"); return -1; }
    gpioDelay(DISPENSE_STABILIZE_US);
    double actual = read_weight();
    if (actual < 0) { fprintf(stderr, "HX711 timeout\n"); log_dispensing(target, 0, "HX711 timeout"); return -1; }
    char resp[128];
    snprintf(resp, sizeof(resp), "%.2f", actual);
    if (send(cfd, resp, strlen(resp), 0) < 0) { perror("send"); return -1; }
    if (set_servo_angle(0) != 0) { perror("set_servo_angle close"); return -1; }
    log_dispensing(target, actual, NULL);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    read_config(CONFIG_FILE);
    if (gpioInitialise() < 0) { fprintf(stderr, "pigpio init failed\n"); return 1; }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) { fprintf(stderr, "setMode servo failed\n"); cleanup(); return 1; }
    gpioServo(SERVO_PIN, 0);
    int sfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sfd < 0) { perror("socket"); cleanup(); return 1; }
    int opt = 1;
    setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(server_ip);
    addr.sin_port = htons(server_port);
    if (bind(sfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) { perror("bind"); close(sfd); cleanup(); return 1; }
    if (listen(sfd, 5) < 0) { perror("listen"); close(sfd); cleanup(); return 1; }
    server_fd = sfd;
    printf("Server listening on %s:%d\n", server_ip, server_port);
    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        int cfd = accept(sfd, (struct sockaddr *)&caddr, &clen);
        if (cfd < 0) { if (errno == EINTR) continue; perror("accept"); break; }
        client_fd = cfd;
        handle_client(cfd);
        close(cfd);
        client_fd = -1;
    }
    cleanup();
    return 0;
}

