#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define ANGLE_STEP 10
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define INITIAL_ANGLE 90

static volatile sig_atomic_t running = 1;
static struct termios orig_termios;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_terminal_raw(void) {
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    raw = orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) != 0) {
        perror("tcsetattr restore");
    }
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US)) / MAX_ANGLE;
}

int main(void) {
    int angle = INITIAL_ANGLE;
    int pulse_us;
    char ch;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pulse_us = angle_to_pulse_us(angle);
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "gpioServo failed for pin %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control. + or - to change angle, q to quit.\n");
    printf("Angle: %d degrees\n", angle);

    while (running) {
        ch = getchar();
        if (ch == 'q') {
            break;
        } else if (ch == '+') {
            angle += ANGLE_STEP;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (gpioServo(SERVO_PIN, pulse_us) != 0) {
                fprintf(stderr, "gpioServo failed\n");
            }
            printf("Angle: %d degrees\n", angle);
        } else if (ch == '-') {
            angle -= ANGLE_STEP;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (gpioServo(SERVO_PIN, pulse_us) != 0) {
                fprintf(stderr, "gpioServo failed\n");
            }
            printf("Angle: %d degrees\n", angle);
        }
        usleep(10000);
    }

    gpioServo(SERVO_PIN, 0);
    restore_terminal();
    gpioTerminate();
    printf("\nExiting.\n");
    return EXIT_SUCCESS;
}

