#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double elapsed_seconds(const struct timespec *start, const struct timespec *end) {
    return (double)(end->tv_sec - start->tv_sec) +
           (double)(end->tv_nsec - start->tv_nsec) / 1.0e9;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request rising-edge events with internal pull-up bias (A3144 open-collector needs pull-up). */
    if (gpiod_line_request_input_flags(line, "motor_rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Monitoring motor RPM on GPIO %d (A3144 Hall sensor, rising edge, pull-up). "
           "Logging to %s every %d s. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, LOG_FILE, SAMPLE_INTERVAL_S);

    struct timespec last_pulse_ts;
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_ts);
    unsigned long pulse_count = 0;
    struct timespec sample_start, sample_end;

    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &sample_start);

        while (program_running) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (elapsed_seconds(&sample_start, &now) >= SAMPLE_INTERVAL_S) {
                break;
            }

            struct timespec timeout_ts;
            timeout_ts.tv_sec = 0;
            timeout_ts.tv_nsec = 100 * 1000 * 1000; /* 100 ms */
            int ev = gpiod_line_event_wait(line, &timeout_ts);
            if (ev < 0) {
                if (errno == EINTR) continue;
                perror("gpiod_line_event_wait");
                goto cleanup;
            }
            if (ev == 0) {
                continue; /* timeout, loop back to check sample interval */
            }

            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) < 0) {
                if (errno == EINTR) continue;
                perror("gpiod_line_event_read");
                goto cleanup;
            }

            if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
                continue;
            }

            struct timespec current_ts = event.ts;
            if (elapsed_seconds(&last_pulse_ts, &current_ts) * 1000.0 >= DEBOUNCE_MS) {
                pulse_count++;
                last_pulse_ts = current_ts;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &sample_end);
        double elapsed = elapsed_seconds(&sample_start, &sample_end);
        if (elapsed < 1.0e-6) elapsed = SAMPLE_INTERVAL_S;

        double rpm = (double)pulse_count / elapsed * 60.0;

        time_t rawtime = time(NULL);
        struct tm timeinfo;
        char timestamp[32];
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        } else {
            strncpy(timestamp, "1970-01-01T00:00:00", sizeof(timestamp));
            timestamp[sizeof(timestamp) - 1] = '\0';
        }

        if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
            perror("fprintf(log_file)");
            goto cleanup;
        }
        if (fflush(log_file) == EOF) {
            perror("fflush(log_file)");
            goto cleanup;
        }

        printf("%s,%.2f RPM\n", timestamp, rpm);
        pulse_count = 0;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

