#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
    }
    return v;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure relay starts OFF --- */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int touch_active = 0;
    uint32_t touch_start_tick = 0;

    printf("Touch-controlled relay running. Touch GPIO%d to toggle GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            break;
        }

        if (touch == 1) {
            if (!touch_active) {
                touch_active = 1;
                touch_start_tick = gpioTick();
                printf("Touch detected (rising edge).\n");
            }

            /* Fail-safe: if HIGH for > FAILSAFE_TIMEOUT seconds, force OFF */
            uint32_t elapsed = (gpioTick() - touch_start_tick) / 1000000; /* seconds */
            if (elapsed > FAILSAFE_TIMEOUT) {
                printf("Fail-safe: touch held for %u s > %d s. Forcing relay OFF.\n",
                       elapsed, FAILSAFE_TIMEOUT);
                if (safe_write(RELAY_PIN, 0) != 0) {
                    break;
                }
                relay_state = 0;
                touch_active = 0; /* ignore further toggles until release */
                continue;
            }

            /* Normal toggle on rising edge */
            if (safe_write(RELAY_PIN, !relay_state) != 0) {
                break;
            }
            relay_state = !relay_state;
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        } else {
            if (touch_active) {
                touch_active = 0;
                printf("Touch released.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);   /* release relay */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

