#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO          18
#define VALVE_ENABLE_GPIO   23
#define FLOW_SENSOR_GPIO    24

#define PULSES_PER_LITER    450.0
#define SAMPLE_INTERVAL_US  100000  /* 100 ms */
#define PWM_RANGE           255
#define PWM_FREQ            1000     /* Hz */

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_GPIO);
        return -1;
    }
    if (gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_ENABLE_GPIO);
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        return -1;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", VALVE_GPIO);
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve (GPIO %d).\n", VALVE_ENABLE_GPIO);
        return -1;
    }
    if (gpioPWM(VALVE_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO %d.\n", VALVE_GPIO);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_GPIO);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioPWM(VALVE_GPIO, 0);
    gpioWrite(VALVE_ENABLE_GPIO, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

static double calculate_flow_rate(int pulses, double interval_s)
{
    return ((double)pulses / PULSES_PER_LITER) / interval_s * 60.0;
}

static int set_valve_position(double flow_error)
{
    double kp = 1.0;
    double valve_position = kp * flow_error;

    if (valve_position < 0.0) valve_position = 0.0;
    if (valve_position > (double)PWM_RANGE) valve_position = (double)PWM_RANGE;

    int pwm_value = (int)(valve_position + 0.5);
    if (gpioPWM(VALVE_GPIO, pwm_value) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed for value %d.\n", pwm_value);
        return -1;
    }
    return pwm_value;
}

static void log_data(FILE *fp, double flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
    fprintf(fp, "%lld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(fp);
}

int main(int argc, char *argv[])
{
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be a positive number.\n");
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening flow_log.csv");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");
    fflush(g_log_file);

    printf("Flow control started. Target: %.2f L/min. Logging to flow_log.csv\n", target_flow_rate);

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        double interval_s = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double flow_rate = calculate_flow_rate(pulses, interval_s);
        double flow_error = target_flow_rate - flow_rate;

        int valve_position = set_valve_position(flow_error);
        log_data(g_log_file, flow_rate, valve_position);

        printf("Flow: %.2f L/min | Target: %.2f L/min | Valve: %d\n",
               flow_rate, target_flow_rate, valve_position);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    fclose(g_log_file);
    g_log_file = NULL;
    cleanup_gpio();
    return EXIT_SUCCESS;
}

