#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define ENA 23
#define IN1 24
#define IN2 25
#define ENB 12
#define IN3 16
#define IN4 20
#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 19

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define PULSES_PER_REV 600
#define TARGET_RPM 60.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ena_line = NULL, *in1_line = NULL, *in2_line = NULL;
static struct gpiod_line *enb_line = NULL, *in3_line = NULL, *in4_line = NULL;
static struct gpiod_line *enc1a_line = NULL, *enc1b_line = NULL;
static struct gpiod_line *enc2a_line = NULL, *enc2b_line = NULL;

static double integral1 = 0.0, prev_error1 = 0.0;
static double integral2 = 0.0, prev_error2 = 0.0;
static int enc1_count = 0, enc2_count = 0;
static pthread_mutex_t enc1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (ena_line) gpiod_line_set_value(ena_line, 0);
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (enb_line) gpiod_line_set_value(enb_line, 0);
    if (in3_line) gpiod_line_set_value(in3_line, 0);
    if (in4_line) gpiod_line_set_value(in4_line, 0);
    if (enc1a_line) gpiod_line_release(enc1a_line);
    if (enc1b_line) gpiod_line_release(enc1b_line);
    if (enc2a_line) gpiod_line_release(enc2a_line);
    if (enc2b_line) gpiod_line_release(enc2b_line);
    if (ena_line) gpiod_line_release(ena_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (enb_line) gpiod_line_release(enb_line);
    if (in3_line) gpiod_line_release(in3_line);
    if (in4_line) gpiod_line_release(in4_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) { fclose(log_file); log_file = NULL; }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); return -1; }

    ena_line = gpiod_chip_get_line(chip, ENA);
    in1_line = gpiod_chip_get_line(chip, IN1);
    in2_line = gpiod_chip_get_line(chip, IN2);
    enb_line = gpiod_chip_get_line(chip, ENB);
    in3_line = gpiod_chip_get_line(chip, IN3);
    in4_line = gpiod_chip_get_line(chip, IN4);
    enc1a_line = gpiod_chip_get_line(chip, ENC1_A);
    enc1b_line = gpiod_chip_get_line(chip, ENC1_B);
    enc2a_line = gpiod_chip_get_line(chip, ENC2_A);
    enc2b_line = gpiod_chip_get_line(chip, ENC2_B);
    if (!ena_line || !in1_line || !in2_line || !enb_line || !in3_line || !in4_line ||
        !enc1a_line || !enc1b_line || !enc2a_line || !enc2b_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return -1;
    }

    if (gpiod_line_request_output(ena_line, "motor", 0) < 0 ||
        gpiod_line_request_output(in1_line, "motor", 0) < 0 ||
        gpiod_line_request_output(in2_line, "motor", 0) < 0 ||
        gpiod_line_request_output(enb_line, "motor", 0) < 0 ||
        gpiod_line_request_output(in3_line, "motor", 0) < 0 ||
        gpiod_line_request_output(in4_line, "motor", 0) < 0) {
        fprintf(stderr, "Failed to request motor lines as output\n");
        return -1;
    }

    if (gpiod_line_request_both_edges_events(enc1a_line, "encoder1") < 0 ||
        gpiod_line_request_both_edges_events(enc2a_line, "encoder2") < 0) {
        fprintf(stderr, "Failed to request encoder edge events\n");
        return -1;
    }
    return 0;
}

static void *encoder_thread(void *arg) {
    struct gpiod_line *a_line = (struct gpiod_line *)arg;
    struct gpiod_line *b_line = (a_line == enc1a_line) ? enc1b_line : enc2b_line;
    int *count = (a_line == enc1a_line) ? &enc1_count : &enc2_count;
    pthread_mutex_t *mutex = (a_line == enc1a_line) ? &enc1_mutex : &enc2_mutex;

    while (running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(a_line, &(struct timespec){0, 100000000});
        if (ret < 0) { if (errno == EINTR) continue; break; }
        if (ret == 0) continue;

        if (gpiod_line_event_read(a_line, &event) < 0) continue;
        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE &&
            event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        int b_val = gpiod_line_get_value(b_line);
        if (b_val < 0) continue;

        int dir = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? b_val : !b_val;
        pthread_mutex_lock(mutex);
        *count += (dir) ? 1 : -1;
        pthread_mutex_unlock(mutex);
    }
    return NULL;
}

static double calculate_pid(double target, double current, double *integral, double *prev_error) {
    double error = target - current;
    *integral += error * SAMPLE_TIME_MS / 1000.0;
    double derivative = (error - *prev_error) * SAMPLE_TIME_MS / 1000.0;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static void set_motor_speed(int motor, double speed) {
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;
    int duty_us = (int)((speed / 100.0) * PWM_PERIOD_US);
    int on = (duty_us > 0) ? 1 : 0;
    struct gpiod_line *en_line, *in1_line, *in2_line;
    if (motor == 1) { en_line = ena_line; in1_line = in1_line; in2_line = in2_line; }
    else { en_line = enb_line; in1_line = in3_line; in2_line = in4_line; }

    gpiod_line_set_value(in1_line, on);
    gpiod_line_set_value(in2_line, 0);
    gpiod_line_set_value(en_line, 1);
    usleep(duty_us);
    gpiod_line_set_value(en_line, 0);
    usleep(PWM_PERIOD_US - duty_us);
}

static void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double out1,
                     double p2, double i2, double d2, double out2) {
    pthread_mutex_lock(&enc1_mutex);
    int c1 = enc1_count;
    enc1_count = 0;
    pthread_mutex_unlock(&enc1_mutex);
    pthread_mutex_lock(&enc2_mutex);
    int c2 = enc2_count;
    enc2_count = 0;
    pthread_mutex_unlock(&enc2_mutex);

    double elapsed = SAMPLE_TIME_MS / 1000.0;
    double r1 = (c1 / (double)PULSES_PER_REV) / elapsed * 60.0;
    double r2 = (c2 / (double)PULSES_PER_REV) / elapsed * 60.0;

    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            rpm1, rpm2, p1, i1, d1, out1, p2, i2, d2, out2, r1, r2, c1, c2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio() != 0) { cleanup(); return 1; }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) { perror("fopen"); cleanup(); return 1; }
    fprintf(log_file, "TargetRPM1,TargetRPM2,P1,I1,D1,Out1,P2,I2,D2,Out2,ActualRPM1,ActualRPM2,Enc1Count,Enc2Count\n");

    pthread_t enc1_tid, enc2_tid;
    if (pthread_create(&enc1_tid, NULL, encoder_thread, enc1a_line) != 0 ||
        pthread_create(&enc2_tid, NULL, encoder_thread, enc2a_line) != 0) {
        perror("pthread_create"); cleanup(); return 1;
    }

    while (running) {
        double target1 = TARGET_RPM, target2 = TARGET_RPM;
        double p1 = KP * (target1 - target1);
        double i1 = KI * integral1;
        double d1 = KD * (target1 - target1 - prev_error1);
        double out1 = p1 + i1 + d1;
        double p2 = KP * (target2 - target2);
        double i2 = KI * integral2;
        double d2 = KD * (target2 - target2 - prev_error2);
        double out2 = p2 + i2 + d2;

        set_motor_speed(1, out1);
        set_motor_speed(2, out2);

        log_data(target1, target2, p1, i1, d1, out1, p2, i2, d2, out2);

        usleep(SAMPLE_TIME_MS * 1000);
    }

    pthread_join(enc1_tid, NULL);
    pthread_join(enc2_tid, NULL);
    cleanup();
    return 0;
}

