#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int relay_state = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, 0x80, 0x63) < 0) return -1; /* Soft reset */
    gpioDelay(10000);

    if (mpr121_write_reg(handle, 0x2B, 0x01) < 0) return -1; /* MHDR */
    if (mpr121_write_reg(handle, 0x2C, 0x01) < 0) return -1; /* NHDR */
    if (mpr121_write_reg(handle, 0x2D, 0x00) < 0) return -1; /* NCLR */
    if (mpr121_write_reg(handle, 0x2E, 0x00) < 0) return -1; /* FDLR */
    if (mpr121_write_reg(handle, 0x2F, 0x01) < 0) return -1; /* MHDF */
    if (mpr121_write_reg(handle, 0x30, 0x01) < 0) return -1; /* NHDF */
    if (mpr121_write_reg(handle, 0x31, 0x00) < 0) return -1; /* NCLF */
    if (mpr121_write_reg(handle, 0x32, 0x00) < 0) return -1; /* FDLF */
    if (mpr121_write_reg(handle, 0x33, 0x00) < 0) return -1; /* NHDT */
    if (mpr121_write_reg(handle, 0x34, 0x00) < 0) return -1; /* NCLT */
    if (mpr121_write_reg(handle, 0x35, 0x00) < 0) return -1; /* FDLT */

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, 0x41 + 2 * i, 0x0F) < 0) return -1; /* Touch threshold */
        if (mpr121_write_reg(handle, 0x42 + 2 * i, 0x0A) < 0) return -1; /* Release threshold */
    }

    if (mpr121_write_reg(handle, 0x5E, 0x0C) < 0) return -1; /* Debounce */
    if (mpr121_write_reg(handle, 0x5F, 0x0C) < 0) return -1; /* Debounce */
    if (mpr121_write_reg(handle, 0x7B, 0x01) < 0) return -1; /* Auto-config */
    if (mpr121_write_reg(handle, 0x7D, 0x00) < 0) return -1; /* FFI / CDC */
    if (mpr121_write_reg(handle, 0x7E, 0x00) < 0) return -1; /* CDT */
    if (mpr121_write_reg(handle, 0x5B, 0x01) < 0) return -1; /* Enable 12 electrodes */

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: %s\n", pigpio_error(rc));
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read short: got %d bytes\n", rc);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d Relay: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ON" : "OFF");
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (relay_state >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);
    relay_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int touched = (touch_status & 0x0FFF) != 0;
        if (touched != relay_state) {
            if (gpioWrite(RELAY_GPIO, touched ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to write GPIO %d\n", RELAY_GPIO);
            } else {
                relay_state = touched;
                log_relay_state(relay_state);
                printf("Relay %s\n", relay_state ? "ON" : "OFF");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

