#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE1_MS 5000
#define PAUSE2_MS 10000
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "greenhouse-valve1", 0) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "greenhouse-valve2", 0) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

static void activate_valve(struct gpiod_line *line, int duration_ms, const char *valve_name) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set %s HIGH: %s\n", valve_name, strerror(errno));
        log_event("Error: Failed to activate valve");
        return;
    }
    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Valve %s activated for %d ms", valve_name, duration_ms);
    log_event(log_msg);

    usleep(duration_ms * 1000);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set %s LOW: %s\n", valve_name, strerror(errno));
        log_event("Error: Failed to deactivate valve");
        return;
    }
    snprintf(log_msg, sizeof(log_msg), "Valve %s deactivated", valve_name);
    log_event(log_msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_event("Greenhouse irrigation system started");

    while (running) {
        activate_valve(valve1_line, VALVE1_DURATION_MS, "1");
        if (!running) break;
        usleep(PAUSE1_MS * 1000);

        activate_valve(valve2_line, VALVE2_DURATION_MS, "2");
        if (!running) break;
        usleep(PAUSE2_MS * 1000);
    }

    log_event("Greenhouse irrigation system stopped");
    cleanup();
    return 0;
}

