#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    // Stop mode
    if (mpr121_write(handle, 0x2B, 0x00) < 0) return -1;
    gpioDelay(1000);

    // Touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, 0x41 + 2 * i, 0x10) < 0) return -1; // touch
        if (mpr121_write(handle, 0x42 + 2 * i, 0x0A) < 0) return -1; // release
    }

    // Filter configuration (FFI=00, CDC=16, CDT=0.5us)
    if (mpr121_write(handle, 0x2B, 0x01) < 0) return -1;
    // Charge time (16uA, 0.5us)
    if (mpr121_write(handle, 0x5B, 0x01) < 0) return -1;
    // Electrode current (16uA)
    if (mpr121_write(handle, 0x5D, 0x01) < 0) return -1;

    // Enter run mode with 12 electrodes enabled
    if (mpr121_write(handle, 0x2B, 0x20) < 0) return -1;
    gpioDelay(100000); // 100 ms stabilization

    return 0;
}

static int read_touch_status(int handle) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: %d\n", rc);
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;

    while (running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);
            printf("Relay %s\n", relay_state ? "ON" : "OFF");
            fflush(stdout);
        }

        gpioDelay(100000); // 100 ms
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

