#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define THRESHOLD_KG 10.0
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    int i;
    long count = 0;
    uint32_t start_tick;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(clock_pin, 0) < 0) return -1;

    start_tick = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
    }

    for (i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) return -1;
        gpioDelay(1);
        count = count << 1;
        if (gpioWrite(clock_pin, 0) < 0) return -1;
        gpioDelay(1);
        if (gpioRead(data_pin)) {
            count++;
        }
    }

    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(clock_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (count & 0x800000) {
        count |= ~0xFFFFFF;
    }

    *raw_value = count;
    return 0;
}

static double convert_to_kg(long raw_value, double sf, double off) {
    return (double)(raw_value - off) / sf;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *sf, double *off) {
    long sum = 0;
    long raw;
    int i;

    printf("Calibrating HX711 (zero load)...\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        if (read_hx711(data_pin, clock_pin, &raw) != 0) {
            fprintf(stderr, "Calibration read failed at iteration %d\n", i);
            return -1;
        }
        sum += raw;
        gpioDelay(10000);
    }
    *off = (double)sum / NUM_CALIBRATION_READINGS;
    *sf = 1.0;
    printf("Calibration complete. Offset: %.2f\n", *off);
    return 0;
}

static int load_calibration_data(const char *filename, double *sf, double *off) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        return -1;
    }
    if (fscanf(fp, "%lf %lf", sf, off) != 2) {
        fprintf(stderr, "Invalid calibration file format, using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration data loaded: scale=%.2f, offset=%.2f\n", *sf, *off);
    return 0;
}

static int save_calibration_data(const char *filename, double sf, double off) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to save calibration data\n");
        return -1;
    }
    fprintf(fp, "%.2f %.2f\n", sf, off);
    fclose(fp);
    printf("Calibration data saved\n");
    return 0;
}

static int log_weight(double weight_kg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f kg\n", ts, weight_kg);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        scale_factor = 1.0;
        offset = 0.0;
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
        fprintf(stderr, "Calibration failed, continuing with defaults\n");
    }
    save_calibration_data(CALIBRATION_FILE, scale_factor, offset);

    printf("Starting weight monitoring (threshold: %.1f kg)\n", THRESHOLD_KG);

    while (running) {
        long raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "HX711 read error, skipping iteration\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = convert_to_kg(raw, scale_factor, offset);
        log_weight(weight);

        if (weight > THRESHOLD_KG) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold, locking\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg below threshold, unlocking\n", weight);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete\n");
    return 0;
}

