code:
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <string.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50
#define MOTOR_PWM_FREQUENCY 1000
#define MOTOR_PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME_SEC 5
#define CHECK_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_INTERVAL_MS * 1000);
        }
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to start PWM on motor enable");
        return;
    }
    syslog(LOG_INFO, "Window closing started (IN1=1, IN2=0, PWM=%d/255)",
           MOTOR_PWM_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME_SEC * 1000000);
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 low after run");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 low after run");
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop PWM on motor enable");
    }
    syslog(LOG_INFO, "Window closing stopped");
}

static void cleanup(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin %d as input", RAIN_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin %d as output", MOTOR_IN1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin %d as output", MOTOR_IN2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin %d as output", MOTOR_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on pin %d", MOTOR_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control service started");

    while (running) {
        int rain = read_rain_sensor();
        if (rain) {
            syslog(LOG_INFO, "Rain detected on GPIO%d", RAIN_SENSOR_PIN);
            close_window();
            for (int i = 0; i < CHECK_INTERVAL_SEC && running; i++) {
                gpioDelay(1000000);
            }
        } else {
            for (int i = 0; i < CHECK_INTERVAL_SEC && running; i++) {
                gpioDelay(1000000);
            }
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

