#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define SOLENOID_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }
    if (fclose(fp) != 0) {
        perror("fclose log");
        return -1;
    }
    return 0;
}

static int read_hx711_raw(int32_t *out) {
    if (gpioSetMode(HX711_DT, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_SCK, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DT) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) {
            log_event("HX711 timeout waiting for DT low");
            return -1;
        }
        gpioDelay(100);
    }

    int32_t count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK, 1) < 0) return -1;
        gpioDelay(1);
        count = count << 1;
        if (gpioWrite(HX711_SCK, 0) < 0) return -1;
        gpioDelay(1);
        if (gpioRead(HX711_DT)) {
            count++;
        }
    }

    if (gpioWrite(HX711_SCK, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK, 0) < 0) return -1;
    gpioDelay(1);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }

    *out = count;
    return 0;
}

static int read_weight(float *weight) {
    int32_t raw;
    if (read_hx711_raw(&raw) < 0) return -1;
    *weight = (float)raw / 100.0;
    return 0;
}

static int activate_solenoid(void) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set solenoid pin mode");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        log_event("Failed to activate solenoid");
        return -1;
    }
    log_event("Solenoid activated");
    for (int i = 0; i < SOLENOID_DURATION && running; i++) {
        gpioDelay(1000000);
    }
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        log_event("Failed to deactivate solenoid");
        return -1;
    }
    log_event("Solenoid deactivated");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Stock monitoring started");

    while (running) {
        float weight;
        if (read_weight(&weight) < 0) {
            log_event("Weight read failed, retrying");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            if (activate_solenoid() < 0) {
                log_event("Solenoid activation failed");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    log_event("Stock monitoring stopped");
    gpioTerminate();
    return EXIT_SUCCESS;
}

