#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define CLOCK_HIGH_DELAY_US 1
#define CLOCK_LOW_DELAY_US 1

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    int i;
    long value = 0;
    uint32_t start_tick;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    start_tick = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
        gpioDelay(100);
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(CLOCK_HIGH_DELAY_US);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(CLOCK_LOW_DELAY_US);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(CLOCK_HIGH_DELAY_US);
    gpioWrite(clock_pin, 0);
    gpioDelay(CLOCK_LOW_DELAY_US);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static double convert_to_kg(long raw_value, double factor) {
    return (double)raw_value / factor;
}

static int log_security_event(const char *filename, double weight) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[64];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening security log file");
        return -1;
    }

    if (fprintf(fp, "%s - Weight exceeded threshold: %.2f kg\n", timestamp, weight) < 0) {
        perror("Error writing to security log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing security log file");
        return -1;
    }

    return 0;
}

static int control_solenoid(int solenoid_pin, int duration_seconds) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid pin high\n");
        return -1;
    }
    printf("Solenoid lock activated for %d seconds.\n", duration_seconds);
    sleep(duration_seconds);
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Failed to set solenoid pin low\n");
        return -1;
    }
    printf("Solenoid lock deactivated.\n");
    return 0;
}

static int save_calibration_factor(const char *filename, double factor) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening calibration file for writing");
        return -1;
    }
    if (fprintf(fp, "%.10f\n", factor) < 0) {
        perror("Error writing calibration factor");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing calibration file");
        return -1;
    }
    printf("Calibration factor saved: %.10f\n", factor);
    return 0;
}

static int load_calibration_factor(const char *filename, double *factor) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return -1;
    }
    if (fscanf(fp, "%lf", factor) != 1) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration factor loaded: %.10f\n", *factor);
    return 0;
}

static int calibrate_load_cell(int data_pin, int clock_pin, double *factor) {
    double known_weight;
    long raw_value;

    printf("Calibration mode. Place a known weight on the load cell.\n");
    printf("Enter the known weight in kilograms: ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input for known weight.\n");
        return -1;
    }
    while (getchar() != '\n');

    printf("Reading raw value...\n");
    if (read_hx711(data_pin, clock_pin, &raw_value) != 0) {
        fprintf(stderr, "Failed to read raw value during calibration.\n");
        return -1;
    }
    printf("Raw value: %ld\n", raw_value);

    *factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.10f\n", *factor);

    if (save_calibration_factor(CALIBRATION_FILE, *factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor.\n");
        return -1;
    }

    return 0;
}

int main(void) {
    double weight;
    long raw_value;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize solenoid pin low\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to install SIGINT handler");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        return 1;
    }

    if (load_calibration_factor(CALIBRATION_FILE, &calibration_factor) != 0) {
        printf("Calibration file not found. Starting calibration.\n");
        if (calibrate_load_cell(HX711_DATA_PIN, HX711_CLOCK_PIN, &calibration_factor) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioWrite(SOLENOID_PIN, 0);
            gpioTerminate();
            return 1;
        }
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "HX711 read error. Retrying...\n");
            sleep(1);
            continue;
        }

        weight = convert_to_kg(raw_value, calibration_factor);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded!\n");
            if (log_security_event(SECURITY_LOG_FILE, weight) != 0) {
                fprintf(stderr, "Failed to log security event.\n");
            }
            if (control_solenoid(SOLENOID_PIN, 5) != 0) {
                fprintf(stderr, "Failed to control solenoid.\n");
            }
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

