    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize solenoid pin low\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to install SIGINT handler");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        return 1;
    }

    if (load_calibration_factor(CALIBRATION_FILE, &calibration_factor) != 0) {
        printf("Calibration file not found. Starting calibration.\n");
        if (calibrate_load_cell(HX711_DATA_PIN, HX711_CLOCK_PIN, &calibration_factor) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioWrite(SOLENOID_PIN, 0);
            gpioTerminate();
            return 1;
        }
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "HX711 read error. Retrying...\n");
            sleep(1);
            continue;
        }

        weight = convert_to_kg(raw_value, calibration_factor);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded!\n");
            if (log_security_event(SECURITY_LOG_FILE, weight) != 0) {
                fprintf(stderr, "Failed to log security event.\n");
            }
            if (control_solenoid(SOLENOID_PIN, 5) != 0) {
                fprintf(stderr, "Failed to control solenoid.\n");
            }
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

