#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments for a Raspberry Pi Zero W */
#define SENSOR_LEFT   4
#define SENSOR_CENTER 17
#define SENSOR_RIGHT  27

#define MOTOR_LEFT_FORWARD   22
#define MOTOR_LEFT_BACKWARD  23
#define MOTOR_RIGHT_FORWARD  24
#define MOTOR_RIGHT_BACKWARD 25

#define BASE_SPEED 150
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define LOOP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single IR sensor; returns 0 (line detected) or 1 (no line)   */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Drive one motor: speed in [-255, 255]                              */
/* ------------------------------------------------------------------ */
static int drive_motor(int forward, int backward, int speed)
{
    int f = 0, b = 0;

    if (speed > 0) {
        f = speed;
        b = 0;
    } else if (speed < 0) {
        f = 0;
        b = -speed;
    } else {
        f = 0;
        b = 0;
    }

    if (gpioPWM(forward, f) < 0) {
        fprintf(stderr, "gpioPWM(forward=%d, %d) failed\n", forward, f);
        return -1;
    }
    if (gpioPWM(backward, b) < 0) {
        fprintf(stderr, "gpioPWM(backward=%d, %d) failed\n", backward, b);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Stop both motors                                                   */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioPWM(MOTOR_LEFT_FORWARD, 0);
    gpioPWM(MOTOR_LEFT_BACKWARD, 0);
    gpioPWM(MOTOR_RIGHT_FORWARD, 0);
    gpioPWM(MOTOR_RIGHT_BACKWARD, 0);
}

/* ------------------------------------------------------------------ */
/* Log one control cycle with ISO 8601 timestamp                       */
/* ------------------------------------------------------------------ */
static void log_data(int sl, int sc, int sr, int lv, int rv)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, S_L=%d, S_C=%d, S_R=%d, M_L=%d, M_R=%d\n",
                ts, sl, sc, sr, lv, rv) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — stop motors, close log, terminate pigpio, release pins   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int sl, sc, sr;
    int lv = 0, rv = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO mode setup ---- */
    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_CENTER, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_LEFT_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_BACKWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- PWM frequency and range ---- */
    if (gpioSetPWMfrequency(MOTOR_LEFT_FORWARD, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_LEFT_BACKWARD, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_FORWARD, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_BACKWARD, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_LEFT_BACKWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_BACKWARD, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* ---- main control loop ---- */
    while (running) {
        sl = read_sensor(SENSOR_LEFT);
        sc = read_sensor(SENSOR_CENTER);
        sr = read_sensor(SENSOR_RIGHT);

        if (sl < 0 || sc < 0 || sr < 0) {
            fprintf(stderr, "Sensor read error — stopping motors\n");
            stop_motors();
            lv = 0;
            rv = 0;
            log_data(sl, sc, sr, lv, rv);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Active-low: 0 = line detected, 1 = no line */
        if (sc == 0) {
            /* Line directly under center — drive straight */
            lv = BASE_SPEED;
            rv = BASE_SPEED;
        } else if (sl == 0 && sr == 1) {
            /* Line to left — turn right */
            lv = BASE_SPEED / 2;
            rv = BASE_SPEED;
        } else if (sl == 1 && sr == 0) {
            /* Line to right — turn left */
            lv = BASE_SPEED;
            rv = BASE_SPEED / 2;
        } else {
            /* No line — stop */
            lv = 0;
            rv = 0;
        }

        if (drive_motor(MOTOR_LEFT_FORWARD, MOTOR_LEFT_BACKWARD, lv) < 0 ||
            drive_motor(MOTOR_RIGHT_FORWARD, MOTOR_RIGHT_BACKWARD, rv) < 0) {
            fprintf(stderr, "Motor drive error\n");
        }

        log_data(sl, sc, sr, lv, rv);
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

