#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_MEAS_DELAY_US    180000  /* 180 ms for high-res mode */
#define LUX_THRESHOLD           150.0f
#define RELAY_GPIO              23
#define LOG_FILE                "grow_log.txt"
#define POLL_INTERVAL_US        5000000 /* 5 s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Read illuminance from BH1750 in continuous high-resolution mode     */
/* Returns lux >= 0 on success, -1.0 on error                          */
/* ------------------------------------------------------------------ */
static float read_bh1750(int handle)
{
    /* Send continuous high-resolution mode command */
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) != 0) {
        log_event("BH1750: failed to send measurement command");
        return -1.0f;
    }

    /* Wait for conversion to complete */
