#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22

#define LOCKED_PW 1000
#define UNLOCKED_PW 2000
#define MIN_PW 500
#define MAX_PW 2500
#define DEBOUNCE_US 100000

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 || gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 || gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int current_pw = LOCKED_PW;
    if (gpioServo(SERVO_PIN, current_pw) != 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door lock initialized: locked\n");

    while (keep_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                if (current_pw != LOCKED_PW) {
                    if (gpioServo(SERVO_PIN, LOCKED_PW) == 0) {
                        current_pw = LOCKED_PW;
                        printf("Door locked\n");
                    } else {
                        fprintf(stderr, "Failed to set servo to locked position\n");
                    }
                }
                while (gpioRead(LOCK_BUTTON) == 0 && keep_running) {
                    gpioDelay(10000);
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                if (current_pw != UNLOCKED_PW) {
                    if (gpioServo(SERVO_PIN, UNLOCKED_PW) == 0) {
                        current_pw = UNLOCKED_PW;
                        printf("Door unlocked\n");
                    } else {
                        fprintf(stderr, "Failed to set servo to unlocked position\n");
                    }
                }
                while (gpioRead(UNLOCK_BUTTON) == 0 && keep_running) {
                    gpioDelay(10000);
                }
            }
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Door lock terminated\n");
    return EXIT_SUCCESS;
}

