#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "haptic-motor1", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "haptic-motor2", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            goto cleanup;
        }
        usleep(MOTOR1_PULSE_MS * 1000);
        if (!running) break;
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            goto cleanup;
        }
        usleep(MOTOR2_PULSE_MS * 1000);
        if (!running) break;
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

