#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_SUB_ADDRESS "tcp://localhost:5555"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

static int publish_alert(void *socket, const char *message) {
    int rc = zmq_send(socket, message, strlen(message), 0);
    if (rc == -1) {
        perror("zmq_send");
        return -1;
    }
    return 0;
}

static int sound_sensor_mode(void *context, struct gpiod_chip *chip) {
    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        return -1;
    }
    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        return -1;
    }

    void *socket = zmq_socket(context, ZMQ_PUB);
    if (!socket) {
        perror("zmq_socket(PUB)");
        return -1;
    }
    if (zmq_bind(socket, ZMQ_ADDRESS) == -1) {
        perror("zmq_bind");
        zmq_close(socket);
        return -1;
    }

    printf("Sound sensor node started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            perror("gpiod_line_get_value(sound)");
            break;
        }
        if (val == 0) {
            time_t now = time(NULL);
            char message[64];
            snprintf(message, sizeof(message), "SOUND_ALERTS %ld", (long)now);
            if (publish_alert(socket, message) != 0) {
                break;
            }
        }
        sleep_ms(POLL_INTERVAL_MS);
    }

    zmq_close(socket);
    gpiod_line_release(sound_line);
    return 0;
}

static int alarm_node_mode(void *context, struct gpiod_chip *chip) {
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        return -1;
    }
    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
