#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define NEC_HDR_MARK  9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK  560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define TOLERANCE 0.3

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;
static volatile int mqtt_connected = 0;

static uint32_t pulse_times[MAX_PULSES];
static int pulse_count = 0;
static volatile int ir_data_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int in_range(uint32_t val, uint32_t target) {
    return (val > target * (1.0 - TOLERANCE)) && (val < target * (1.0 + TOLERANCE));
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulse_times[pulse_count++] = tick;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow, resetting");
            pulse_count = 0;
        }
    }
}

static int decode_nec(uint32_t *address, uint32_t *command) {
    if (pulse_count < 67) return -1;
    if (!in_range(pulse_times[0], NEC_HDR_MARK)) return -1;
    if (!in_range(pulse_times[1], NEC_HDR_SPACE)) return -1;

    uint32_t addr = 0, cmd = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= pulse_count) return -1;
        if (!in_range(pulse_times[idx], NEC_BIT_MARK)) return -1;
        uint32_t space = pulse_times[idx + 1] - pulse_times[idx];
        if (in_range(space, NEC_ONE_SPACE)) {
            if (i < 16) addr |= (1UL << i);
            else cmd |= (1UL << (i - 16));
        } else if (!in_range(space, NEC_ZERO_SPACE)) {
            return -1;
        }
    }

    uint8_t addr_lo = addr & 0xFF;
    uint8_t addr_hi = (addr >> 8) & 0xFF;
    if ((uint8_t)(~addr_lo) != (addr >> 16) & 0xFF) return -1;
    if ((uint8_t)(~addr_hi) != (addr >> 24) & 0xFF) return -1;

    uint8_t cmd_lo = cmd & 0xFF;
    uint8_t cmd_hi = (cmd >> 8) & 0xFF;
    if ((uint8_t)(~cmd_lo) != (cmd >> 16) & 0xFF) return -1;
    if ((uint8_t)(~cmd_hi) != (cmd >> 24) & 0xFF) return -1;

    *address = addr & 0xFFFF;
    *command = cmd & 0xFFFF;
    return 0;
}

static void publish_mqtt(uint32_t address, uint32_t command) {
    if (!mqtt_connected) return;
    char payload[128];
    snprintf(payload, sizeof(payload),
             "{\"address\": %u, \"command\": %u}", address, command);
    MQTTClient_message msg = MQTTClient_message_initializer;
    msg.payload = payload;
    msg.payloadlen = (int)strlen(payload);
    msg.qos = 0;
    msg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &msg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    }
}

static int mqtt_connect(MQTTClient *client) {
    int rc = MQTTClient_create(client, MQTT_HOST, "ir_decoder",
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT create failed: %s", MQTTClient_strerror(rc));
        return -1;
    }
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    rc = MQTTClient_connect(*client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(client);
        return -1;
    }
    mqtt_connected = 1;
    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (ir_callback(IR_GPIO, 0, 0) != 0) {
        syslog(LOG_ERR, "Failed to register alert callback");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (mqtt_connect(&mqtt_client) != 0) {
        syslog(LOG_ERR, "MQTT init failed, continuing without MQTT");
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        if (ir_data_ready) {
            ir_data_ready = 0;
            uint32_t address, command;
            if (decode_nec(&address, &command) == 0) {
                syslog(LOG_INFO, "Decoded: address=0x%04X, command=0x%04X",
                       address, command);
                publish_mqtt(address, command);
            } else {
                syslog(LOG_WARNING, "NEC decode failed, %d pulses", pulse_count);
            }
            pulse_count = 0;
        }
        if (mqtt_connected) {
            MQTTClient_yield();
        }
        usleep(10000);
    }

    if (mqtt_connected) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }
    gpioTerminate();
    syslog(LOG_INFO, "IR decoder stopped");
    closelog();
    return 0;
}

