#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS     4
#define BH1750_ADDR_0   0x23
#define BH1750_ADDR_1   0x24
#define BH1750_ADDR_2   0x25
#define BH1750_ADDR_3   0x26
#define BH1750_CMD_OT_H  0x20   /* One-Time High-Resolution mode */
#define BH1750_CONV_MS  180    /* max conversion time */
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define SAMPLE_MS       1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Open /dev/i2c-1 once and return fd; caller closes. */
static int i2c_open_bus(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0)
        perror("open(" I2C_BUS ")");
    return fd;
}

/* Set slave address on an already-open I2C bus fd. */
static int i2c_set_slave(int fd, uint8_t addr)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x): %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a single command byte to the BH1750. */
static int bh1750_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write cmd 0x%02x: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read 2 bytes from the BH1750 (big-endian). */
static int bh1750_read_data(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "read: %s\n", strerror(errno));
