#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_read_flow(int fd, int16_t *flow_out)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Zero-length write acts as a start condition to select the
           register we want to read.  The AWM7300V returns 2 bytes of
           flow data on the next read. */
        if (write(fd, buf, 0) < 0) {
            retries++;
            msleep(RETRY_DELAY_MS);
            continue;
        }

        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == (ssize_t)sizeof(buf)) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            raw &= 0x3FFF;                 /* 14-bit data */
            *flow_out = (int16_t)raw;
            return 0;
        }

        retries++;
        msleep(RETRY_DELAY_MS);
    }

    return -1;
}

static float convert_to_slpm(int16_t raw)
{
    return ((float)raw - 3277.0f) * 0.1f;
}

static void log_flow_rate(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "unknown");
    }

    fprintf(fp, "%s, %.2f SLPM\n", ts, slpm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (i2c_read_flow(g_i2c_fd, &raw) == 0) {
            float slpm = convert_to_slpm(raw);
            log_flow_rate(g_log_fp, slpm);
            printf("Flow rate: %.2f SLPM\n", slpm);
        } else {
            fprintf(stderr, "I2C read failed after %d retries: %s\n",
                    MAX_RETRIES, strerror(errno));
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

