#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* AS7341 register addresses */
#define AS7341_ENABLE  0x80
#define AS7341_ATIME   0x01
#define AS7341_ID      0x24
#define AS7341_CFG6    0xAF
#define AS7341_F1DATAL 0x60
#define AS7341_F1DATAH 0x61
#define AS7341_F2DATAL 0x62
#define AS7341_F2DATAH 0x63
#define AS7341_F3DATAL 0x64
#define AS7341_F3DATAH 0x65
#define AS7341_F4DATAL 0x66
#define AS7341_F4DATAH 0x67
#define AS7341_F5DATAL 0x68
#define AS7341_F5DATAH 0x69
#define AS7341_F6DATAL 0x6A
#define AS7341_F6DATAH 0x6B
#define AS7341_F7DATAL 0x6C
#define AS7341_F7DATAH 0x6D
#define AS7341_F8DATAL 0x6E
#define AS7341_F8DATAH 0x6F
#define AS7341_CDATAL  0x70
#define AS7341_CDATAH  0x71
#define AS7341_NDATAL  0x72
#define AS7341_NDATAH  0x73

#define AS7341_ID_VALUE 0x19
#define AS7341_ENABLE_PON 0x01
#define AS7341_ENABLE_SP_EN 0x20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID, &id) != 0) {
        fprintf(stderr, "Cannot read ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X). Wrong sensor?\n", id, AS7341_ID_VALUE);
        return -1;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) != 0) {
        fprintf(stderr, "Failed to power on sensor.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_ATIME, 0xFF) != 0) {
        fprintf(stderr, "Failed to set ATIME.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CFG6.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0) {
        fprintf(stderr, "Failed to enable spectral measurement.\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_spectral_data(int fd, uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4,
                              uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8,
                              uint16_t *clear, uint16_t *nir) {
    if (i2c_read_reg16(fd, AS7341_F1DATAL, f1) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F2DATAL, f2) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F3DATAL, f3) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F4DATAL, f4) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F5DATAL, f5) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F6DATAL, f6) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_F7DATAL, f7) != 0) return -1;
