#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define D7S_DEFAULT_I2C_ADDRESS 0x37
#define D7S_ACCEL_REG 0x28
#define D7S_NUM_AXES_BYTES 6
#define D7S_SENSITIVITY 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define DEFAULT_INTERVAL 1

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t program_running = 1;
static int i2c_address = D7S_DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char filename[256] = "seismic_data.csv";

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_file) {
        fprintf(error_file, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
        fflush(error_file);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *x, float *y, float *z) {
    uint8_t buffer[D7S_NUM_AXES_BYTES];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, D7S_ACCEL_REG, buffer, D7S_NUM_AXES_BYTES) == 0) {
            int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
            *x = (float)raw_x * D7S_SENSITIVITY;
            *y = (float)raw_y * D7S_SENSITIVITY;
            *z = (float)raw_z * D7S_SENSITIVITY;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (data_file) {
        fclose(data_file);
        data_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (error_file) {
        fclose(error_file);
        error_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address < 0 || i2c_address > 0x7F) {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return 1;
                }
                break;
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval: %s\n", optarg);
                    return 1;
                }
                break;
            case 'f':
                strncpy(filename, optarg, sizeof(filename) - 1);
                filename[sizeof(filename) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        return 1;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        log_error("Failed to open data file");
        cleanup();
        return 1;
    }

    if (fprintf(data_file, "timestamp,x_g,y_g,z_g\n") < 0) {
        log_error("Failed to write CSV header");
        cleanup();
        return 1;
    }
    fflush(data_file);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers");
        cleanup();
        return 1;
    }

    printf("Seismic data logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float x, y, z;
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(data_file, x, y, z) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data after retries");
        }
        sleep(interval);
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

