#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) return -1;
    usleep(180000);
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Buffer formatting error\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sock_fd, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return 1;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(sock_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Read error, retrying in %d s...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }
        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Send error\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (sock_fd >= 0) close(sock_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

