#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <stdbool.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE   B115200
#define READ_TIMEOUT_SEC  2
#define READ_TIMEOUT_USEC 0
#define LINE_BUF_SIZE     256
#define MAX_RANGE_M       100.0f

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    /* Clear O_NONBLOCK so reads block per termios VMIN/VTIME */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NONBLOCK: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;  /* No parity */
    tty.c_cflag &= ~CSTOPB;  /* 1 stop bit */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;      /* 8 data bits */
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    /* VMIN=0, VTIME=50 => 0.5 s inter-byte timeout */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void cleanup_uart(int fd) {
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
}

static void parse_and_log(const char *line) {
    char *copy = strdup(line);
    if (!copy) {
        fprintf(stderr, "strdup failed: %s\n", strerror(errno));
        return;
    }

    char *saveptr = NULL;
    char *ts_str = strtok_r(copy, ",", &saveptr);
    char *range_str = strtok_r(NULL, ",", &saveptr);

    if (!ts_str || !range_str) {
        fprintf(stderr, "Malformed line (missing fields): %s\n", line);
        free(copy);
        return;
    }

    errno = 0;
    char *endptr = NULL;
    long ts_val = strtol(ts_str, &endptr, 10);
    if (errno != 0 || endptr == ts_str) {
        fprintf(stderr, "Invalid timestamp: %s\n", ts_str);
        free(copy);
        return;
    }

    errno = 0;
    float range = strtof(range_str, &endptr);
    if (errno != 0 || endptr == range_str) {
        fprintf(stderr, "Invalid range: %s\n", range_str);
        free(copy);
        return;
    }

    if (range < 0.0f || range > MAX_RANGE_M) {
        fprintf(stderr, "Range out of bounds: %.2f m\n", range);
        free(copy);
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        free(copy);
        return;
    }

    char time_buf[32];
    if (strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(copy);
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_buf, range);
    fflush(stdout);
    free(copy);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[256];

    printf("AWR1642 range reader started on %s @ 115200 8N1.\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec  = READ_TIMEOUT_SEC;
        tv.tv_usec = READ_TIMEOUT_USEC;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            /* Timeout — no data available. Check g_running for shutdown. */
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Should not happen on a tty, but handle defensively. */
            fprintf(stderr, "UART closed by peer.\n");
            break;
        }

        for (ssize_t i = 0; i < n; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    parse_and_log(line_buf);
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line too long (%d bytes), discarding.\n",
                            LINE_BUF_SIZE - 1);
                    line_len = 0;
                }
            }
        }
    }

    cleanup_uart(g_uart_fd);
    g_uart_fd = -1;

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

