#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR   4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR  27
#define SERIAL_PORT   "/dev/ttyAMA0"
#define BAUD_RATE     115200
#define LOOP_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(int fd) {
    const char *msg = "EMERGENCY STOP!\n";
    int len = (int)strlen(msg);
    int written = serWrite(fd, (char *)msg, len);
    if (written != len) {
        fprintf(stderr, "Error sending emergency stop: wrote %d of %d bytes\n", written, len);
        return -1;
    }
    return 0;
}

int main(void) {
    int left, middle, right;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure sensor pins as inputs with pull-up resistors */
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    /* Open serial port */
    g_serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT, pigpio_error(g_serial_fd));
        gpioTerminate();
        return 1;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register signal handlers\n");
    }

    printf("Program started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        left   = read_sensor(LEFT_SENSOR);
        middle = read_sensor(MIDDLE_SENSOR);
        right  = read_sensor(RIGHT_SENSOR);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                if (send_emergency_stop(g_serial_fd) != 0) {
                    fprintf(stderr, "Failed to send emergency stop\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

